    Mouse = Killaura:CreateToggle({Name = 'Require mouse down'})
	Attackable = Killaura:CreateToggle({Name = 'Attackable check'})
    Swing = Killaura:CreateToggle({Name = 'No Swing'})
    GUI = Killaura:CreateToggle({Name = 'GUI check'})
