run(function()
    local Prediction
    local AutoCharge
    local TargetPart
    local Targets
    local FOV
    local Sort
    local OtherProjectiles
    local Blacklist
    -- Ground search params for the trajectory solve, and nothing else. Exclude rather than
    -- Include-the-map: in this game a target is almost always standing on a block somebody
    -- placed, which is not part of the static map, so an Include list of the map alone casts
    -- straight past whatever they are stood on and reports the floor of the world far below -
    -- and the solve then leads them as though they were about to fall into it. Worse, the list
    -- was built at load time, so on any join where the map had not streamed in yet it held a
    -- single nil, and an EMPTY Include list makes every cast return nothing at all.
    local rayCheck = RaycastParams.new()
    rayCheck.FilterType = Enum.RaycastFilterType.Exclude
    rayCheck.RespectCanCollide = true
    local launchHook

    local function getMousePosition()
	if inputService.TouchEnabled then
		return gameCamera.ViewportSize / 2
	end
	return inputService.GetMouseLocation(inputService)
    end

    local function getPosition(ent, proj)
	if TargetPart.Value == 'Closest' then
		local localPosition, magnitude, part = getMousePosition(), 9e9, nil
		for _, v in ent:GetChildren() do
			if pcall(function() return v.Position; end) then
				local position, vis = gameCamera.WorldToViewportPoint(gameCamera, v.Position)

				if vis then
					local mag = (localPosition - Vector2.new(position.x, position.y)).Magnitude

					if mag < magnitude then
						magnitude = mag
						part = v
					end
				end
			end
		end
		return part and part.Position or ent.PrimaryPart.Position
	elseif TargetPart.Value == 'Dynamic' then
		local tool = store.hand.tool
		if tool and tool.Name:find('headhunter') then
			return ent.Head.Position
		end
		return ent.PrimaryPart.Position
	end
	return
    end

    local ProjectileAimbot
    ProjectileAimbot = vape.Categories.Blatant:CreateModule({
	Name = 'ProjectileAimbot',
	Disabled = not canDebug,
	Function = function(callback)
		if callback then
			oldd = bedwars.BlockKickerKitController.getKickBlockProjectileOriginPosition
			launchHook = bedwars.ProjectileLaunchHook:Add('ProjectileAimbot', 100, function(nextLaunch, ...)
				local self, projmeta, worldmeta, origin, shootpos = ...
				local plr = entitylib.EntityMouse({
					Part = 'RootPart',
					Range = FOV.Value,
					Players = Targets.Players.Enabled,
					NPCs = Targets.NPCs.Enabled,
					Wallcheck = Targets.Walls.Enabled,
					Sort = sortmethods[Sort.Value or 'Distance'],
					Origin = entitylib.isAlive and (shootpos or entitylib.character.RootPart.Position) or Vector3.zero,
				})

				if plr then
					local pos = shootpos or self:getLaunchPosition(origin)
					if not pos then
						return nextLaunch(...)
					end

					if (not OtherProjectiles.Enabled) and not projmeta.projectile:find('arrow') then
						return nextLaunch(...)
					end

					if table.find(Blacklist.ListEnabled or {}, ((projmeta.projectile == 'glue_trap' or projmeta.projectile == 'glue_projectile') and 'gloop' or projmeta.projectile)) then
						return nextLaunch(...)
					end

					local meta = projmeta:getProjectileMeta()
					local lifetime = (worldmeta and meta.predictionLifetimeSec or meta.lifetimeSec or 3)
					local gravity = (meta.gravitationalAcceleration or 196.2) * projmeta.gravityMultiplier
					local projSpeed = (meta.launchVelocity or 100)
					local offsetpos = pos + (projmeta.projectile == 'owl_projectile' and Vector3.zero or projmeta.fromPositionOffset)
					local balloons = plr.Character:GetAttribute('InflatedBalloons')
					local playerGravity = workspace.Gravity

					if balloons and balloons > 0 then
						playerGravity = (workspace.Gravity * (1 - (balloons >= 4 and 1.2 or balloons >= 3 and 1 or 0.975)))
					end

					if plr.Character.PrimaryPart:FindFirstChild('rbxassetid://8200754399') then
						playerGravity = 6
					end

					if plr.Player and plr.Player:GetAttribute('IsOwlTarget') then
						for _, owl in collectionService:GetTagged('Owl') do
							if owl:GetAttribute('Target') == plr.Player.UserId and owl:GetAttribute('Status') == 2 then
								playerGravity = 0
							end
						end
					end

					local targetPart = plr[TargetPart.Value] or plr.RootPart
					local targetpos = getPosition(plr.Character) or (targetPart and targetPart.Position)
					if not targetpos then return nextLaunch(...) end
					local newlook = CFrame.new(offsetpos, targetpos) * CFrame.new(projmeta.projectile == 'owl_projectile' and Vector3.zero or Vector3.new(bedwars.BowConstantsTable.RelX, bedwars.BowConstantsTable.RelY, bedwars.BowConstantsTable.RelZ))
					-- Solve and launch at the same speed. Previously prediction used the
					-- full metadata speed while a partially charged bow was launched at
					-- velocityMultiplier speed, so the arc looked redirected but landed
					-- short of the entity.
					local charge = AutoCharge.Enabled and 1 or (projmeta.velocityMultiplier or 1)
					local launchSpeed = projSpeed * charge
					rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera}
					local calc = prediction.SolveTrajectory(newlook.p, launchSpeed * Prediction.Value, gravity, targetpos, projmeta.projectile == 'telepearl' and Vector3.zero or plr.RootPart.AssemblyLinearVelocity, playerGravity, plr.HipHeight, plr.Jumping and 42.6 or nil, rayCheck, nil, lplr:GetNetworkPing())
					if calc then
						targetinfo.Targets[plr] = tick() + 1
						return {
						initialVelocity = CFrame.new(newlook.Position, calc).LookVector * launchSpeed,
							positionFrom = offsetpos,
							deltaT = lifetime,
							gravitationalAcceleration = gravity,
							drawDurationSeconds = AutoCharge.Enabled and 5 or projmeta.drawDurationSeconds,
						}
					end
				end

				return nextLaunch(...)
			end)
		else
			if launchHook then
				launchHook()
				launchHook = nil
			end
		end
	end,
	Tooltip = 'Silently adjusts your aim towards the enemy',
    })
    Targets = ProjectileAimbot:CreateTargets({
	Players = true,
	Walls = true,
    })
    TargetPart = ProjectileAimbot:CreateDropdown({
	Name = 'Part',
	List = {'RootPart', 'Head', 'Dynamic', 'Closest'},
    })
    local methods = {'Damage', 'Distance'}
    for i in sortmethods do
	if not table.find(methods, i) then
		table.insert(methods, i)
	end
    end
    Sort = ProjectileAimbot:CreateDropdown({
	Name = 'Target Mode',
	List = methods,
	Default = 'Distance',
    })
    Prediction = ProjectileAimbot:CreateSlider({
	Name = 'Prediction',
	Min = 0.1,
	Max = 2,
	Default = 1,
	Decimal = 10,
    })
    FOV = ProjectileAimbot:CreateSlider({
	Name = 'FOV',
	Min = 1,
	Max = 1000,
	Default = 1000,
    })
    AutoCharge = ProjectileAimbot:CreateToggle({
	Name = 'Auto Charge',
	Default = true,
	Tooltip = 'Fully charges your bow, Allowing your projectile to deal more damage',
    })
    OtherProjectiles = ProjectileAimbot:CreateToggle({
	Name = 'Other Projectiles',
	Default = true,
	Function = function(call)
		if Blacklist and Blacklist.Object then
			Blacklist.Object.Visible = call
		end
	end,
    })
    Blacklist = ProjectileAimbot:CreateTextList({
	Name = 'Blacklist',
	Default = {'gloop', 'telepearl'},
	Darker = true,
	Placeholder = 'projectile',
    })
end)

run(function()
	local SilentAim
	local Targets
	local TargetPart
	local Sort
	local Prediction
	local FOV
	local OtherProjectiles
	local Blacklist

	-- Ground search params for the arc solve. Exclude rather than Include-the-map,
	-- the same way ProjectileAimbot does it: targets stand on player-placed blocks
	-- far more often than on the static map, and an Include list built at load time
	-- is empty on any join where the map has not streamed in yet - which makes every
	-- cast miss and the solve lead the target into the floor of the world.
	local rayCheck = RaycastParams.new()
	rayCheck.FilterType = Enum.RaycastFilterType.Exclude
	rayCheck.RespectCanCollide = true

	local oldnamecall

	-- Which remote a projectile is fired down.
	--
	-- This is why SilentAim did nothing at all: the hook below matched the call by
	-- comparing the remote against the literal string 'ProjectileFire', but that is the
	-- name the game's own code uses, not the name of the instance. Every remote in this
	-- game is published under a randomised name that the loader dumps out of the
	-- controllers into remotes.FireProjectile, so tostring(remote) never once equalled
	-- 'ProjectileFire' and the hook fell through to the original call on every shot.
	--
	-- Resolved lazily and re-resolved if it goes away, the same as every other module
	-- that talks to this remote, and cached because the hook runs on every namecall the
	-- game makes.
	local firedRemote
	local function projectileRemote()
		if firedRemote and firedRemote.Parent then return firedRemote end
		local suc, res = pcall(function()
			return bedwars.Client:Get(remotes.FireProjectile).instance
		end)
		firedRemote = suc and typeof(res) == 'Instance' and res or nil
		return firedRemote
	end

	-- Identity first, name second: if the remote cannot be resolved (a build that moved
	-- it, an executor without debug.getconstants) the dumped name is still usually right.
	local function isProjectileCall(remote)
		if typeof(remote) ~= 'Instance' then return false end
		local resolved = projectileRemote()
		if resolved then return remote == resolved end
		return remotes.FireProjectile ~= '' and remote.Name == remotes.FireProjectile
	end

	local function getMousePosition()
		if inputService.TouchEnabled then
			return gameCamera.ViewportSize / 2
		end
		return inputService.GetMouseLocation(inputService)
	end

	local function getPosition(ent)
		if TargetPart.Value == 'Closest' then
			local localPosition, magnitude, part = getMousePosition(), 9e9, nil
			for _, v in ent:GetChildren() do
				if v:IsA('BasePart') then
					local position, vis = gameCamera.WorldToViewportPoint(gameCamera, v.Position)
					if vis then
						local mag = (localPosition - Vector2.new(position.x, position.y)).Magnitude
						if mag < magnitude then
							magnitude = mag
							part = v
						end
					end
				end
			end
			return part and part.Position or ent.PrimaryPart and ent.PrimaryPart.Position
		elseif TargetPart.Value == 'Dynamic' then
			local tool = store.hand.tool
			if tool and tool.Name:find('headhunter') and ent:FindFirstChild('Head') then
				return ent.Head.Position
			end
			return ent.PrimaryPart and ent.PrimaryPart.Position
		end
		return
	end

	local function solveSilent(args)
		local origin, velocity, projType = args[4], args[6], args[3]
		if typeof(origin) ~= 'Vector3' or typeof(velocity) ~= 'Vector3' or type(projType) ~= 'string' then
			return
		end

		if (not OtherProjectiles.Enabled) and not projType:find('arrow') then
			return
		end

		if table.find(Blacklist.ListEnabled or {}, ((projType == 'glue_trap' or projType == 'glue_projectile') and 'gloop' or projType)) then
			return
		end

		local meta = bedwars.ProjectileMeta[projType]
		if not meta then return end

		local speed = velocity.Magnitude
		if speed <= 0 then return end
		local gravity = meta.gravitationalAcceleration or 196.2

		local plr = entitylib.EntityMouse({
			Part = 'RootPart',
			Range = FOV.Value,
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs.Enabled,
			Wallcheck = Targets.Walls.Enabled,
			Sort = sortmethods[Sort.Value or 'Distance'],
			Origin = origin
		})
		if not plr then return end

		local targetpart = plr[TargetPart.Value]
		local targetpos = getPosition(plr.Character) or targetpart and targetpart.Position
		if not targetpos then return end
		local playerGravity = workspace.Gravity
		local balloons = plr.Character:GetAttribute('InflatedBalloons')
		if balloons and balloons > 0 then
			playerGravity = workspace.Gravity * (1 - (balloons >= 4 and 1.2 or balloons >= 3 and 1 or 0.975))
		end

		-- A pearl is thrown to land somewhere, not to hit somebody, so it is solved
		-- against where they are standing rather than where they are heading.
		local pearl = projType == 'telepearl'
		local targetVelocity = pearl and Vector3.zero or plr.RootPart.AssemblyLinearVelocity

		rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera}
		local calc, travelTime = prediction.SolveTrajectory(
			origin,
			speed * Prediction.Value,
			gravity,
			targetpos,
			targetVelocity,
			playerGravity,
			plr.HipHeight,
			plr.Jumping and 42.6 or nil,
			rayCheck,
			nil,
			lplr:GetNetworkPing()
		)
		if not calc or not travelTime or travelTime > (meta.lifetimeSec or 3) then return end

		targetinfo.Targets[plr] = tick() + 1
		return CFrame.lookAt(origin, calc).LookVector * speed
	end

	SilentAim = vape.Categories.Combat:CreateModule({
		Name = 'SilentAim',
		Function = function(callback)
			-- Installed once and left in place: a metamethod hook cannot be lifted
			-- cleanly, so it stays inert behind the Enabled check instead.
			if callback and not oldnamecall and hookmetamethod and newcclosure and checkcaller and getnamecallmethod then
				oldnamecall = hookmetamethod(game, '__namecall', newcclosure(function(...)
					if SilentAim.Enabled and not checkcaller() and getnamecallmethod() == 'InvokeServer' and isProjectileCall((...)) then
						local self = ...
						-- table.pack keeps the argument count, so a call that ends in a
						-- nil is passed on with the same arity it arrived with.
						local args = table.pack(select(2, ...))
						-- Guarded: anything thrown in here would come out of a __namecall
						-- the whole game runs through, not just ours.
						local ok, newVelocity = pcall(solveSilent, args)
						if ok and newVelocity then
							args[6] = newVelocity
						end
						return oldnamecall(self, table.unpack(args, 1, args.n))
					end
					return oldnamecall(...)
				end))
			end
		end,
		Tooltip = 'Shoot anywhere, the projectile is redirected onto the target'
	})
	Targets = SilentAim:CreateTargets({
		Players = true,
		Walls = true
	})
	TargetPart = SilentAim:CreateDropdown({
		Name = 'Part',
		List = {'RootPart', 'Head', 'Dynamic', 'Closest'}
	})
	local methods = {'Damage', 'Distance'}
	for i in sortmethods do
		if not table.find(methods, i) then
			table.insert(methods, i)
		end
	end
	Sort = SilentAim:CreateDropdown({
		Name = 'Target Mode',
		List = methods,
		Default = 'Distance'
	})
	Prediction = SilentAim:CreateSlider({
		Name = 'Prediction',
		Min = 0.1,
		Max = 2,
		Default = 1,
		Decimal = 10
	})
	FOV = SilentAim:CreateSlider({
		Name = 'FOV',
		Min = 1,
		Max = 1000,
		Default = 1000
	})
	OtherProjectiles = SilentAim:CreateToggle({
		Name = 'Other Projectiles',
		Function = function(call)
			if Blacklist and Blacklist.Object then
				Blacklist.Object.Visible = call
			end
		end,
		Default = true
	})
	Blacklist = SilentAim:CreateTextList({
		Name = 'Blacklist',
		Default = {'gloop', 'telepearl'},
		Darker = true,
		Placeholder = 'projectile'
	})
end)
	
run(function()
    local ProjectileAura
    local Targets
    local TargetMode
    local Range
    local List
    -- Ground search params for the trajectory solve, and nothing else. Exclude rather than
    -- Include-the-map: in this game a target is almost always standing on a block somebody
    -- placed, which is not part of the static map, so an Include list of the map alone casts
    -- straight past whatever they are stood on and reports the floor of the world far below -
    -- and the solve then leads them as though they were about to fall into it. Worse, the list
    -- was built at load time, so on any join where the map had not streamed in yet it held a
    -- single nil, and an EMPTY Include list makes every cast return nothing at all.
    local rayCheck = RaycastParams.new()
    rayCheck.FilterType = Enum.RaycastFilterType.Exclude
    rayCheck.RespectCanCollide = true
    local projectileRemote = {InvokeServer = function() end}
    local FireDelays = {}
    task.spawn(function()
        projectileRemote = bedwars.Client:Get(remotes.FireProjectile).instance
    end)

    local function getAmmo(check)
        for _, item in store.inventory.inventory.items do
            if check.ammoItemTypes and table.find(check.ammoItemTypes, item.itemType) then
                return item.itemType
            end
        end
    end

    local function getProjectiles()
        local items = {}
        for _, item in store.inventory.inventory.items do
            local itemMeta = bedwars.ItemMeta[item.itemType]
            local proj = itemMeta and itemMeta.projectileSource
            local ammo = proj and getAmmo(proj)
            if ammo then
                table.insert(items, {
                    item,
                    ammo,
                    proj.projectileType(ammo),
                    proj
                })
            end
        end
        return items
    end

    ProjectileAura = vape.Categories.Blatant:CreateModule({
        Name = 'ProjectileAura',
        Function = function(callback)
            if callback then
                repeat
                    if (workspace:GetServerTimeNow() - bedwars.SwordController.lastAttack) > 0.5 then
                        local ent = entitylib.EntityPosition({
                            Part = 'RootPart',
                            Range = Range.Value,
                            Players = Targets.Players.Enabled,
                            NPCs = Targets.NPCs.Enabled,
                            Wallcheck = Targets.Walls.Enabled,
                            -- Target selection mode. 'Distance' leaves Sort nil so entitylib uses its
                            -- default nearest-first ordering; anything else feeds the matching
                            -- comparator (Mouse/Damage/Threat/Health/Angle/Kit).
                            Sort = TargetMode.Value ~= 'Distance' and sortmethods[TargetMode.Value] or nil
                        })

                        if ent then
                            local pos = entitylib.character.RootPart.Position
                            for _, data in getProjectiles() do
                                local item, ammo, projectile, itemMeta = unpack(data)
                                if (FireDelays[item.itemType] or 0) < tick() then
                                    rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera}
                                    local meta = bedwars.ProjectileMeta[projectile]
                                    local projSpeed, gravity = meta.launchVelocity, meta.gravitationalAcceleration or 196.2
                                    local calc = prediction.SolveTrajectory(pos, projSpeed, gravity, ent.RootPart.Position, ent.RootPart.Velocity, workspace.Gravity, ent.HipHeight, ent.Jumping and 42.6 or nil, rayCheck, nil, lplr:GetNetworkPing())
                                    if calc then
                                        targetinfo.Targets[ent] = tick() + 1
                                        -- Publish that we are actively firing a projectile so Breaker (and
                                        -- anything else that swaps the held item) doesn't yank the bow out
                                        -- of our hand mid-shot, the same way it defers to a sword swing.
                                        store.lastProjectileFire = workspace:GetServerTimeNow()
                                        local switched = switchItem(item.tool)

                                        task.spawn(function()
                                            local dir, id = CFrame.lookAt(pos, calc).LookVector, httpService:GenerateGUID(true)
                                            local shootPosition = (CFrame.new(pos, calc) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ))).Position
                                            bedwars.ProjectileController:createLocalProjectile(meta, ammo, projectile, shootPosition, id, dir * projSpeed, {drawDurationSeconds = 1})
                                            local res = projectileRemote:InvokeServer(item.tool, ammo, projectile, shootPosition, pos, dir * projSpeed, id, {drawDurationSeconds = 1, shotId = httpService:GenerateGUID(false)}, workspace:GetServerTimeNow() - 0.045)
                                            if not res then
                                                FireDelays[item.itemType] = tick()
                                            else
                                                local shoot = itemMeta.launchSound
                                                shoot = shoot and shoot[math.random(1, #shoot)] or nil
                                                if shoot then
                                                    bedwars.SoundManager:playSound(shoot)
                                                end
                                            end
                                        end)

                                        FireDelays[item.itemType] = tick() + itemMeta.fireDelaySec
                                        if switched then
                                            task.wait(0.05)
                                        end
                                    end
                                end
                            end
                        end
                    end
                    task.wait(0.1)
                until not ProjectileAura.Enabled
            end
        end,
        Tooltip = 'Shoots people around you'
    })
    Targets = ProjectileAura:CreateTargets({
        Players = true,
        Walls = true
    })
    local targetModes = {'Distance'}
    for name in sortmethods do
        table.insert(targetModes, name)
    end
    TargetMode = ProjectileAura:CreateDropdown({
        Name = 'Target Mode',
        Tooltip = 'Who to shoot at: Distance (closest), Mouse (nearest crosshair), Damage (most recently hit), Threat, Health, Angle or Kit',
        List = targetModes,
        Default = 'Distance'
    })
    List = ProjectileAura:CreateTextList({
        Name = 'Projectiles',
        Default = {'arrow', 'snowball'}
    })
    Range = ProjectileAura:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 50,
        Default = 50,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
end)



run(function()
    local Mode
    local Value
    local WallCheck
    local AutoJump
    local AlwaysJump
    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true

    Speed = vape.Categories.Blatant:CreateModule({
        Name = 'Speed',
        Function = function(callback)
            frictionTable.Speed = callback or nil
            updateVelocity()
            pcall(function()
                debug.setconstant(bedwars.WindWalkerController.updateSpeed, 7, callback and 'constantSpeedMultiplier' or 'moveSpeedMultiplier')
            end)

            if callback then
                Speed:Clean(runService.PreSimulation:Connect(function(dt)
                    bedwars.StatefulEntityKnockbackController.lastImpulseTime = callback and math.huge or time()
                    if entitylib.isAlive then
                        if not (Fly and Fly.Enabled) and not (LongJump and LongJump.Enabled) then
                            bedwars.SprintController:setSpeed(Mode.Value == 'CFrame' and 20 or Value.Value)
                            if Mode.Value == 'CFrame' then
                                local state = entitylib.character.Humanoid:GetState()
                                if state == Enum.HumanoidStateType.Climbing then return end

                                local root, velo = entitylib.character.RootPart, getSpeed()
                                local moveDirection = AntiFallDirection or entitylib.character.Humanoid.MoveDirection
                                local destination = (moveDirection * math.max(Value.Value - velo, 0) * dt)

                                if WallCheck.Enabled and destination.Magnitude > 1e-4 then
                                    rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera}
                                    rayCheck.CollisionGroup = root.CollisionGroup
                                    -- The probe has to reach past the BODY, not just past the step.
                                    -- The step itself is only what the CFrame push adds on top of
                                    -- normal movement - a few hundredths of a stud at 60fps - so a
                                    -- ray that length, cast from the middle of the root, ended
                                    -- inside the player and never saw the wall a stud in front of
                                    -- them. Nothing was ever subtracted, the push went straight
                                    -- into the block every frame, and pressed against a surface
                                    -- while falling that is exactly the clip through it.
                                    local skin = (math.max(root.Size.X, root.Size.Z) / 2) + 0.4
                                    local half = root.Size.Y / 2
                                    -- Two passes: the first takes out the component into whatever
                                    -- we are pressed against, the second catches the corner that
                                    -- the resulting slide runs into.
                                    for _ = 1, 2 do
                                        local step = destination.Magnitude
                                        if step <= 1e-4 then break end
                                        local probe = destination.Unit * (step + skin)
                                        local ray
                                        -- Waist, then shoulders, then shins: a block edge level
                                        -- with only one of them still counts as a wall.
                                        for _, height in {0, half * 0.8, -half * 0.8} do
                                            ray = workspace:Raycast(root.Position + Vector3.new(0, height, 0), probe, rayCheck)
                                            if ray then break end
                                        end
                                        if not ray then break end
                                        -- Drop the part of the step that goes into the wall and keep
                                        -- the rest, so pressing into a surface slides along it rather
                                        -- than through it.
                                        local into = destination:Dot(ray.Normal)
                                        if into >= 0 then break end
                                        destination -= ray.Normal * into
                                    end
                                end

                                root.CFrame += destination
                                root.AssemblyLinearVelocity = (moveDirection * velo) + Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
                                if AutoJump.Enabled and (state == Enum.HumanoidStateType.Running or state == Enum.HumanoidStateType.Landed) and moveDirection ~= Vector3.zero and (Attacking or AlwaysJump.Enabled) then
                                    entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
                                end
                            end
                        end
                    end
                end))
            else
                bedwars.SprintController:setSpeed(bedwars.SprintController:isSprinting() and 20 or 14)
            end
        end,
        ExtraText = function()
            return 'Heatseeker'
        end,
        Tooltip = 'Increases your movement with various methods'
    })
    Mode = Speed:CreateDropdown({
        Name = 'Method',
        List = {'Bedwars', 'CFrame'},
        Default = 'CFrame'
    })
    Value = Speed:CreateSlider({
        Name = 'Speed',
        Min = 1,
        Max = 23,
        Default = 23,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
    WallCheck = Speed:CreateToggle({
        Name = 'Wall Check',
        Default = true
    })
    AutoJump = Speed:CreateToggle({
        Name = 'AutoJump',
        Function = function(callback)
            AlwaysJump.Object.Visible = callback
        end
    })
    AlwaysJump = Speed:CreateToggle({
        Name = 'Always Jump',
        Visible = false,
        Darker = true
    })
end)

run(function()
    local Mode
    local Animation
    local Value
    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true
    local Active, Truss, Loaded

    local climbAnimation = Instance.new('Animation')
    climbAnimation.AnimationId = 'rbxassetid://11344417710'

    Spider = vape.Categories.Blatant:CreateModule({
	Name = 'Spider',
	Function = function(callback)
		if callback then
			if Truss then
				Truss.Parent = gameCamera
			end

			Spider:Clean(runService.PreSimulation:Connect(function(dt)
				if entitylib.isAlive then
					local root = entitylib.character.RootPart
					local chars = { gameCamera, lplr.Character, Truss }
					for _, v in entitylib.List do
						table.insert(chars, v.Character)
					end
					SpiderShift = inputService:IsKeyDown(Enum.KeyCode.LeftShift)
					rayCheck.FilterDescendantsInstances = chars
					rayCheck.CollisionGroup = root.CollisionGroup

                        local dir, stop = entitylib.character.Humanoid.MoveDirection, false
                        if dir.Magnitude <= 0 then
                            dir, stop = root.CFrame.LookVector, true
                        end
                        local vec = dir * 2.5
                        local ray = workspace:Raycast(
                            root.Position - Vector3.new(0, entitylib.character.HipHeight - 0.5, 0),
                            vec,
                            rayCheck
                        )
                        if Active then
                            if not Loaded and Animation.Enabled then
                                Loaded = entitylib.character.Humanoid:LoadAnimation(climbAnimation)
                                Loaded:Play()
                            end
                            if Loaded then
                                Loaded:AdjustSpeed((not stop) and 2 or 0)
                            end
                            -- Only cancel downward velocity while actively climbing (to stop
                            -- overshoot once we reach the top). When there is no movement input
                            -- (stop) we must NOT zero the Y velocity, otherwise the player just
                            -- hovers/slides down the wall very slowly while stuck in the falling
                            -- animation. Letting gravity through makes idle descent feel normal.
                            if not ray and not stop then
                                root.Velocity = Vector3.new(root.Velocity.X, 0, root.Velocity.Z)
                            end
                        end

                        Active = ray
                        if Active and ray.Normal.Y == 0 and not stop then
                            if not (vape.Modules.Phase and vape.Modules.Phase.Enabled) or not SpiderShift then
                                if Animation.Enabled then
                                    entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Climbing)
                                end

                                root.Velocity *= Vector3.new(1, 0, 1)
                                if Mode.Value == 'CFrame' then
                                    root.CFrame += Vector3.new(0, Value.Value * dt, 0)
                                elseif Mode.Value == 'Impulse' then
                                    root:ApplyImpulse(Vector3.new(0, Value.Value, 0) * root.AssemblyMass)
                                else
                                    root.Velocity += Vector3.new(0, Value.Value, 0)
                                end
                            end
                        elseif not Active then
                            if Loaded then
                                Loaded:Stop()
                            end
                            Loaded = nil
                        end
                    else
                        if Loaded then
                            Loaded:Stop()
                        end
                        Loaded = nil
				end
			end))
		else
			if Truss then
				Truss.Parent = nil
			end
                if Loaded then
                    Loaded:Stop()
                end
                Loaded = nil
			SpiderShift = false
		end
	end,
	Tooltip = 'Lets you climb up walls. (Hold shift to use Phase over spider)',
    })
    Mode = Spider:CreateDropdown({
	Name = 'Mode',
	List = {'Velocity', 'Impulse', 'CFrame'},
	Function = function(val)
		Value.Object.Visible = val ~= 'Part'
            if Truss then
			Truss:Destroy()
			Truss = nil
		end
		if val == 'Part' then
			Truss = Instance.new('TrussPart')
			Truss.Size = Vector3.new(2, 2, 2)
			Truss.Transparency = 1
			Truss.Anchored = true
			Truss.Parent = Spider.Enabled and gameCamera or nil
		end
	end,
	Tooltip = 'Velocity - smooth boost up\nCFrame - moves you up\nPart - a climbable part in front of you',
    })
    Value = Spider:CreateSlider({
	Name = 'Speed',
	Min = 0,
	Max = 100,
	Default = 30,
	Darker = true,
	Suffix = function(val)
		return val == 1 and 'stud' or 'studs'
	end,
    })
    Animation = Spider:CreateToggle({
        Name = 'Use bedwars climbing',
        Tooltip = 'Makes you look like you are climbing with a kit (e.g. Yamini)'
    })
end)

run(function()
    local TerraAimbot
    local Range
    local Mode

    local old

    TerraAimbot = kits:CreateModule({
        Name = 'TerraAimbot',
        Category = 'Aim',
        Function = function(callback)
            if callback then
                old = bedwars.BlockKickerKitController.getKickBlockProjectileOriginPosition
                bedwars.BlockKickerKitController.getKickBlockProjectileOriginPosition = function(...)
                    local origin, dir = select(2, ...)
                    local plr = entitylib['Entity'.. Mode.Value]({
                        Part = 'RootPart',
                        Range = Range.Value,
                        Origin = origin,
                        Players = true,
                        Wallcheck = true
                    })

                    if plr then
                        local calc = prediction.SolveTrajectory(origin, 100, 20, plr.RootPart.Position, plr.RootPart.Velocity, workspace.Gravity, plr.HipHeight, plr.Jumping and 42.6 or nil)

                        if calc then
                            for i, v in debug.getstack(2) do
                                if v == dir then
                                    debug.setstack(2, i, CFrame.lookAt(origin, calc).LookVector)
                                end
                            end
                        end
                    end

                    return old(...)
                end
            end
        end,
        Tooltip = 'Silently adjusts where terra blocks are heading towards'
    })

    Mode = TerraAimbot:CreateDropdown({
        Name = 'Mode',
        List = {'Position', 'Mouse'},
        Default = 'Mouse'
    })
    Range = TerraAimbot:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 1000,
        Default = 1000,
        Suffix = function(val)
            return val <= 1 and 'studs' or 'stud'
        end
    })
end)

-- VulcanAssist (from idk; replaces Aether's VulcanAimbot, which did the same job).
-- Points the Vulcan turret camera at whoever is nearest the crosshair, leading the shot with
-- the trajectory solver and allowing for a target that is currently off the ground.
run(function()
    local VulcanAssist
    local Targets
    local Range
    local Sort

    VulcanAssist = kits:CreateModule({
        Name = 'VulcanAssist',
        Category = 'Aim',
        Function = function(callback)
            if not callback then return end
            repeat
                if entitylib.isAlive then
                    local turret = bedwars.Store:getState().Game.selectedTurret
                    if turret then
                        local origin = turret.Rotate.Position
                        local ent = entitylib.EntityMouse({
                            Range = Range.Value,
                            Origin = origin,
                            Wallcheck = Targets.Walls.Enabled or nil,
                            Part = 'RootPart',
                            Players = Targets.Players.Enabled,
                            NPCs = Targets.NPCs.Enabled,
                            Sort = sortmethods[Sort.Value]
                        })
                        if ent then
                            -- A target already in the air keeps falling for the whole flight, so
                            -- the solver is told to simulate the jump rather than assume they are
                            -- standing still on the ground.
                            local airborne = ent.Humanoid and ent.Humanoid.FloorMaterial == Enum.Material.Air
                            if not airborne then
                                airborne = math.abs(ent.RootPart.AssemblyLinearVelocity.Y) > 0.01
                            end
                            local pos = prediction.SolveTrajectory(
                                origin,
                                320,
                                10,
                                ent.RootPart.Position,
                                ent.RootPart.AssemblyLinearVelocity,
                                workspace.Gravity,
                                ent.HipHeight,
                                airborne and ent.RootPart.AssemblyLinearVelocity.Y or nil,
                                store.airRay
                            )
                            if pos then
                                local delta = pos - origin
                                bedwars.TurretCameraController.angleX = math.atan2(-delta.X, -delta.Z)
                                bedwars.TurretCameraController.angleY = math.clamp(math.atan2(delta.Y, math.sqrt(delta.X^2 + delta.Z^2)), -0.8, 0.8)
                            end
                        end
                    end
                end
                task.wait(0.1)
            until not VulcanAssist.Enabled
        end,
        Tooltip = 'Automatically aims the Vulcan turret camera toward opponents'
    })

    Targets = VulcanAssist:CreateTargets({Walls = true, Players = true})
    local methods = {'Distance', 'Damage'}
    for i in sortmethods do
        if not table.find(methods, i) then
            table.insert(methods, i)
        end
    end
    Sort = VulcanAssist:CreateDropdown({
        Name = 'Target mode',
        List = methods,
        Default = methods[1]
    })
    Range = VulcanAssist:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 1000,
        Default = 500
    })
end)

