run(function()
    local ViewmodelVisuals
    local StrokeColor
    local Color

    local Instances = {}

    ViewmodelVisuals = vape.Categories.Render:CreateModule({
        Name = 'ViewmodelVisuals',
        Function = function(call)
            if call then
                local viewmodel = gameCamera:WaitForChild('Viewmodel', 9e9)
                if not ViewmodelVisuals.Enabled then
                    return
                end

                for i,v in viewmodel:GetChildren() do
                    if v:IsA('Accessory') then
                        local highlight = v.Handle:FindFirstChildOfClass('Highlight') or Instance.new('Highlight', v.Handle)
                        highlight.FillColor = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
                        highlight.FillTransparency = Color.Opacity
                        highlight.OutlineTransparency = StrokeColor.Opacity
                        highlight.OutlineColor = Color3.fromHSV(StrokeColor.Hue, StrokeColor.Sat, StrokeColor.Value)

                        ViewmodelVisuals:Clean(highlight)
                        table.insert(Instances, highlight)

                        break
                    end
                end

                ViewmodelVisuals:Clean(viewmodel.ChildAdded:Connect(function(visual)
                    if visual:IsA('Accessory') then
                        local highlight = visual.Handle:FindFirstChildOfClass('Highlight') or Instance.new('Highlight', visual.Handle)
                        highlight.FillColor = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
                        highlight.FillTransparency = Color.Opacity
                        highlight.OutlineTransparency = StrokeColor.Opacity
                        highlight.OutlineColor = Color3.fromHSV(StrokeColor.Hue, StrokeColor.Sat, StrokeColor.Value)

                        ViewmodelVisuals:Clean(highlight)
                        table.insert(Instances, highlight)
                    end
                end))

                ViewmodelVisuals:Clean(gameCamera.ChildAdded:Connect(function(visual)
                    if visual.Name == 'Viewmodel' then
                        ViewmodelVisuals:Toggle()
                        ViewmodelVisuals:Toggle()
                    end
                end))
            end
        end
    })

    Color = ViewmodelVisuals:CreateColorSlider({
        Name = 'Color',
        Default = Color3.new(1, 1, 1),
        Function = function(hue, sat, val, opacity)
            for _, v in Instances do
                v.FillColor = Color3.fromHSV(hue, sat, val)
                v.FillTransparency = opacity
            end
        end
    })
    StrokeColor = ViewmodelVisuals:CreateColorSlider({
        Name = 'Stroke Color',
        Default = Color3.new(),
        Function = function(hue, sat, val, opacity)
            for _, v in Instances do
                v.OutlineColor = Color3.fromHSV(hue, sat, val)
                v.OutlineTransparency = opacity
            end
        end
    })
end)

--[[
    Utility
]]

-- MP3Player: plays your own .mp3 files out of the aetherv2/songs folder the loader creates.
--
-- The folder is scanned live, so songs added or deleted while you are in a game are picked up
-- without a reinject (Auto refresh, plus a Refresh button for right now). Anything the executor
-- can turn into an asset works - mp3, wav, ogg.
--
-- Spotify mode is best-effort and honest about it: Spotify hands out no audio at all without a
-- session, EXCEPT the 30-second preview its own web player uses. So a track link is resolved to
-- that preview, saved into songs/spotify and played. Full tracks are not possible from here.
run(function()
    local MP3Player
    local Volume
    local Speed
    local Shuffle
    local Loop
    local AutoRefresh
    local PlayField
    local Playlist
    local SpotifyMode
    local SpotifyLink
    local ShowHUD
    local HUDProgress
    local HUDTime
    local HUDColor

    local SONGS = 'aetherv2/songs'
    local SPOTIFY = 'aetherv2/songs/spotify'

    local sound
    local tracks, index = {}, 0
    local hudName, hudTime, hudBarFill, hudBackground
    local lastScan = 0
    local scanKey = ''
    -- When the current track was started, so the watchdog below can tell a song that has
    -- finished from one that has only just been asked to start.
    local lastPlay = 0

    -- Every filesystem call is optional: some executors ship none of them, and the module has to
    -- degrade to "no songs found" rather than erroring on load.
    local function fsList(path)
        local ok, res = pcall(function()
            if isfolder and not isfolder(path) then
                if makefolder then makefolder(path) end
                return {}
            end
            return listfiles and listfiles(path) or {}
        end)
        return ok and res or {}
    end

    local function isAudio(path)
        path = tostring(path):lower()
        return path:sub(-4) == '.mp3' or path:sub(-4) == '.wav' or path:sub(-4) == '.ogg'
    end

    local function fileName(path)
        local normalised = tostring(path):gsub('\\', '/')
        local name = normalised:match('([^/]+)$') or normalised
        return (name:gsub('%.[^%.]+$', ''))
    end

    local function scan(announce)
        local found = {}
        for _, file in fsList(SONGS) do
            if isAudio(file) then
                table.insert(found, {Name = fileName(file), Path = tostring(file):gsub('\\', '/')})
            end
        end
        for _, file in fsList(SPOTIFY) do
            if isAudio(file) then
                table.insert(found, {Name = fileName(file), Path = tostring(file):gsub('\\', '/')})
            end
        end
        table.sort(found, function(a, b)
            return a.Name:lower() < b.Name:lower()
        end)

        -- Playlist, when you have filled one in, is both the filter and the order.
        local wanted = Playlist and Playlist.ListEnabled or {}
        if #wanted > 0 then
            local ordered = {}
            for _, entry in wanted do
                local needle = entry:lower()
                for _, track in found do
                    if track.Name:lower():find(needle, 1, true) then
                        table.insert(ordered, track)
                        break
                    end
                end
            end
            if #ordered > 0 then
                found = ordered
            end
        end

        local key = ''
        for _, track in found do
            key = key .. track.Path .. ';'
        end
        local changed = key ~= scanKey
        scanKey = key
        tracks = found
        if changed and announce and MP3Player.Enabled then
            notif('MP3Player', #tracks > 0 and (#tracks .. ' song' .. (#tracks == 1 and '' or 's') .. ' loaded') or 'No songs in the songs folder yet', 3)
        end
        return changed
    end

    local function assetFor(path)
        local ok, asset = pcall(function()
            return getcustomasset(path)
        end)
        return ok and asset or nil
    end

    local function refreshHUD()
        if not hudName then return end
        local track = tracks[index]
        local colour = HUDColor and Color3.fromHSV(HUDColor.Hue, HUDColor.Sat, HUDColor.Value) or Color3.new(1, 1, 1)
        hudName.TextColor3 = colour
        hudName.Text = track and track.Name or 'No song loaded'
        if hudBackground then
            hudBackground.BackgroundTransparency = HUDColor and (1 - (HUDColor.Opacity * 0.65)) or 0.35
        end

        local length = sound and sound.TimeLength or 0
        local at = sound and sound.TimePosition or 0
        if hudTime then
            hudTime.Visible = HUDTime == nil or HUDTime.Enabled
            hudTime.TextColor3 = colour
            local function clock(t)
                t = math.max(math.floor(t), 0)
                return string.format('%d:%02d', t // 60, t % 60)
            end
            hudTime.Text = track and (clock(at) .. ' / ' .. clock(length)) or ''
        end
        if hudBarFill then
            hudBarFill.Parent.Visible = HUDProgress == nil or HUDProgress.Enabled
            hudBarFill.BackgroundColor3 = colour
            hudBarFill.Size = UDim2.fromScale(length > 0 and math.clamp(at / length, 0, 1) or 0, 1)
        end
    end

    local function stop()
        if sound then
            pcall(function()
                sound:Stop()
            end)
        end
    end

    -- Looping is the engine's job, not ours.
    --
    -- Repeating a song used to mean replaying it from the Ended handler, which is two
    -- problems at once: it leaves an audible gap at every repeat, and Ended is not
    -- something to depend on - a sound whose asset was still loading when Play ran can
    -- fire it immediately or never, and then the music just stops. Looped restarts the
    -- track inside the engine with no gap and no event involved.
    --
    -- Called on every play AND from the two toggles, so turning Loop on part way through a
    -- song loops that song rather than quietly waiting for the next one - which is what
    -- made the toggle look like it did nothing at all.
    local function applyLoop()
        if not (sound and Loop and Shuffle) then return end
        sound.Looped = Loop.Enabled and not Shuffle.Enabled
    end

    local function play(newIndex)
        if #tracks <= 0 then
            index = 0
            refreshHUD()
            return
        end
        -- Stamped before the asset is resolved, not after: a track the executor cannot load
        -- returns below, and leaving the stamp stale would have the watchdog walk the
        -- playlist several times a second complaining about each one.
        lastPlay = tick()
        index = ((newIndex - 1) % #tracks) + 1
        local track = tracks[index]
        local asset = track and assetFor(track.Path)
        if not asset then
            notif('MP3Player', 'Could not load ' .. (track and track.Name or 'that song'), 4, 'warning')
            return
        end
        if not sound then return end
        sound.SoundId = asset
        sound.Volume = Volume.Value / 100
        sound.PlaybackSpeed = Speed.Value
        sound.TimePosition = 0
        applyLoop()
        pcall(function()
            sound:Play()
        end)
        refreshHUD()
    end

    local function advance(step)
        if #tracks <= 0 then return end
        if Shuffle.Enabled and #tracks > 1 then
            local pick = index
            for _ = 1, 8 do
                pick = math.random(1, #tracks)
                if pick ~= index then break end
            end
            play(pick)
            return
        end
        play(index + step)
    end

    -- Spotify: pull the track's own preview clip and keep it as a normal song file.
    local function fetchSpotify(link)
        local id = tostring(link):match('track[/:]([%w]+)')
        if not id then
            notif('MP3Player', 'That is not a Spotify track link', 5, 'warning')
            return nil
        end
        local target = SPOTIFY .. '/' .. id .. '.mp3'
        if isfile and isfile(target) then return target end

        local page
        local ok = pcall(function()
            page = game:HttpGet('https://open.spotify.com/embed/track/' .. id, true)
        end)
        if not ok or type(page) ~= 'string' then
            notif('MP3Player', 'Could not reach Spotify', 5, 'warning')
            return nil
        end
        local url = page:match('"audioPreviewUrl":"(.-)"') or page:match('(https://p%.scdn%.co/mp3%-preview/[%w%-%._%?=]+)')
        if url then
            url = url:gsub('\\u002F', '/'):gsub('\\/', '/')
        end
        if not url then
            notif('MP3Player', 'Spotify gave no preview for that track', 6, 'warning')
            return nil
        end

        local data
        local got = pcall(function()
            data = game:HttpGet(url, true)
        end)
        if not got or type(data) ~= 'string' or #data < 1024 then
            notif('MP3Player', 'Could not download that preview', 5, 'warning')
            return nil
        end
        if isfolder and not isfolder(SPOTIFY) and makefolder then
            makefolder(SPOTIFY)
        end
        local written = pcall(function()
            writefile(target, data)
        end)
        if not written then
            notif('MP3Player', 'Could not save that preview', 5, 'warning')
            return nil
        end
        notif('MP3Player', 'Saved the Spotify preview (30 seconds is all Spotify gives out)', 6)
        return target
    end

    local function playSpotify()
        local target = fetchSpotify(SpotifyLink.Value)
        if not target then return end
        scan(false)
        for i, track in tracks do
            if track.Path:lower():find(tostring(target):lower(), 1, true) or track.Path == target then
                play(i)
                return
            end
        end
        -- Not in the scanned list (a playlist filter is on): play it directly.
        local asset = assetFor(target)
        if asset and sound then
            sound.SoundId = asset
            sound.Volume = Volume.Value / 100
            sound.PlaybackSpeed = Speed.Value
            pcall(function()
                sound:Play()
            end)
        end
    end

    MP3Player = vape.Categories.Utility:CreateModule({
        Name = 'MP3Player',
        Function = function(callback)
            if callback then
                if not (listfiles and getcustomasset) then
                    notif('MP3Player', 'Your executor cannot read local files, so there is nothing to play', 6, 'warning')
                    return task.spawn(function()
                        if MP3Player.Enabled then MP3Player:Toggle() end
                    end)
                end
                if isfolder and makefolder then
                    if not isfolder(SONGS) then makefolder(SONGS) end
                    if not isfolder(SPOTIFY) then makefolder(SPOTIFY) end
                end

                sound = Instance.new('Sound')
                sound.Name = 'AetherMP3'
                sound.Volume = Volume.Value / 100
                sound.PlaybackSpeed = Speed.Value
                sound.Parent = vape.gui
                MP3Player:Clean(sound)
                -- Only ever advances: a looping track never ends, because Looped keeps it
                -- going inside the engine.
                MP3Player:Clean(sound.Ended:Connect(function()
                    if not MP3Player.Enabled then return end
                    advance(1)
                end))

                -- Toggle() shows the HUD frame for any module with a Size, so put Show HUD back in
                -- charge of it now that the module is on.
                if MP3Player.Children then
                    MP3Player.Children.Visible = ShowHUD.Enabled
                end

                scan(true)
                if SpotifyMode.Enabled and (SpotifyLink.Value or '') ~= '' then
                    task.spawn(playSpotify)
                elseif #tracks > 0 then
                    play(Shuffle.Enabled and math.random(1, #tracks) or 1)
                end

                MP3Player:Clean(task.spawn(function()
                    while MP3Player.Enabled do
                        if AutoRefresh.Enabled and tick() - lastScan > 3 then
                            lastScan = tick()
                            local changed = scan(true)
                            -- Nothing playing and songs have just appeared: start on them.
                            if changed and sound and not sound.IsPlaying and #tracks > 0 then
                                play(index > 0 and index or 1)
                            end
                        end
                        -- Backstop for a track that finished without Ended firing, which is
                        -- what left the playlist sitting in silence part way through. A
                        -- looping track is still playing, so this never touches it, and the
                        -- second since the last start keeps it off a song that is loading.
                        if sound and #tracks > 0 and sound.SoundId ~= '' and sound.IsLoaded
                            and not sound.IsPlaying and not sound.IsPaused
                            and (tick() - lastPlay) > 1 then
                            advance(1)
                        end
                        refreshHUD()
                        task.wait(0.2)
                    end
                end))
            else
                stop()
                sound = nil
                index = 0
                scanKey = ''
                refreshHUD()
            end
        end,
        Tooltip = 'Plays your own mp3 files from the aetherv2/songs folder, with a HUD and a live-refreshing playlist',
        Size = UDim2.fromOffset(236, 66),
        ExtraText = function()
            local track = tracks[index]
            return track and track.Name or nil
        end
    })

    -- HUD, built into the draggable frame the GUI hands us (same pattern AutoWin uses).
    if MP3Player.Children then
        local hud = MP3Player.Children
        if hud.Position == UDim2.new() then
            hud.Position = UDim2.fromOffset(16, 340)
        end
        hudBackground = Instance.new('Frame')
        hudBackground.Size = UDim2.fromScale(1, 1)
        hudBackground.BackgroundColor3 = Color3.new()
        hudBackground.BackgroundTransparency = 0.35
        hudBackground.BorderSizePixel = 0
        hudBackground.Parent = hud
        local corner = Instance.new('UICorner')
        corner.CornerRadius = UDim.new(0, 5)
        corner.Parent = hudBackground

        local title = Instance.new('TextLabel')
        title.Size = UDim2.new(1, -14, 0, 16)
        title.Position = UDim2.fromOffset(9, 5)
        title.BackgroundTransparency = 1
        title.Font = Enum.Font.GothamBold
        title.TextSize = 12
        title.TextXAlignment = Enum.TextXAlignment.Left
        title.TextColor3 = Color3.fromRGB(170, 170, 170)
        title.Text = 'MP3Player'
        title.Parent = hudBackground

        hudName = Instance.new('TextLabel')
        hudName.Size = UDim2.new(1, -18, 0, 18)
        hudName.Position = UDim2.fromOffset(9, 21)
        hudName.BackgroundTransparency = 1
        hudName.Font = Enum.Font.GothamMedium
        hudName.TextSize = 13
        hudName.TextXAlignment = Enum.TextXAlignment.Left
        hudName.TextTruncate = Enum.TextTruncate.AtEnd
        hudName.TextColor3 = Color3.new(1, 1, 1)
        hudName.Text = 'No song loaded'
        hudName.Parent = hudBackground

        hudTime = Instance.new('TextLabel')
        hudTime.Size = UDim2.new(1, -18, 0, 14)
        hudTime.Position = UDim2.fromOffset(-9, 5)
        hudTime.BackgroundTransparency = 1
        hudTime.Font = Enum.Font.Gotham
        hudTime.TextSize = 11
        hudTime.TextXAlignment = Enum.TextXAlignment.Right
        hudTime.TextColor3 = Color3.new(1, 1, 1)
        hudTime.Text = ''
        hudTime.Parent = hudBackground

        local bar = Instance.new('Frame')
        bar.Size = UDim2.new(1, -18, 0, 4)
        bar.Position = UDim2.fromOffset(9, 46)
        bar.BackgroundColor3 = Color3.fromRGB(70, 70, 70)
        bar.BorderSizePixel = 0
        bar.Parent = hudBackground
        local barCorner = Instance.new('UICorner')
        barCorner.CornerRadius = UDim.new(1, 0)
        barCorner.Parent = bar

        hudBarFill = Instance.new('Frame')
        hudBarFill.Size = UDim2.fromScale(0, 1)
        hudBarFill.BackgroundColor3 = Color3.new(1, 1, 1)
        hudBarFill.BorderSizePixel = 0
        hudBarFill.Parent = bar
        local fillCorner = Instance.new('UICorner')
        fillCorner.CornerRadius = UDim.new(1, 0)
        fillCorner.Parent = hudBarFill
    end

    MP3Player:CreateButton({
        Name = 'Play / Pause',
        Function = function()
            if not sound then return end
            if sound.IsPlaying then
                sound:Pause()
            elseif sound.SoundId ~= '' then
                sound:Resume()
            else
                play(index > 0 and index or 1)
            end
        end,
        Tooltip = 'Pause or resume the current song'
    })
    MP3Player:CreateButton({
        Name = 'Next song',
        Function = function()
            advance(1)
        end
    })
    MP3Player:CreateButton({
        Name = 'Previous song',
        Function = function()
            advance(-1)
        end
    })
    MP3Player:CreateButton({
        Name = 'Refresh songs',
        Function = function()
            lastScan = tick()
            scan(true)
            refreshHUD()
        end,
        Tooltip = 'Re-read the songs folder right now'
    })
    Volume = MP3Player:CreateSlider({
        Name = 'Volume',
        Min = 0,
        Max = 100,
        Default = 40,
        Suffix = '%',
        Function = function(val)
            if sound then
                sound.Volume = val / 100
            end
        end
    })
    Speed = MP3Player:CreateSlider({
        Name = 'Speed',
        Min = 0.5,
        Max = 2,
        Default = 1,
        Decimal = 100,
        Suffix = 'x',
        Function = function(val)
            if sound then
                sound.PlaybackSpeed = val
            end
        end,
        Tooltip = 'Playback speed'
    })
    Shuffle = MP3Player:CreateToggle({
        Name = 'Shuffle',
        Function = applyLoop,
        Tooltip = 'Pick the next song at random instead of in order'
    })
    Loop = MP3Player:CreateToggle({
        Name = 'Loop song',
        Function = applyLoop,
        Tooltip = 'Repeat the current song instead of moving on'
    })
    AutoRefresh = MP3Player:CreateToggle({
        Name = 'Auto refresh',
        Default = true,
        Tooltip = 'Watch the songs folder and pick up new or deleted files while you play'
    })
    PlayField = MP3Player:CreateTextBox({
        Name = 'Play song',
        Placeholder = 'song name',
        -- TextBox hands us `enter`, not the text, and fires on every keystroke - so only act once
        -- the name has actually been submitted.
        Function = function(enter)
            if not enter then return end
            local val = PlayField and PlayField.Value or ''
            if val == '' then return end
            scan(false)
            local needle = val:lower()
            for i, track in tracks do
                if track.Name:lower():find(needle, 1, true) then
                    play(i)
                    return
                end
            end
            notif('MP3Player', 'No song matching "' .. val .. '"', 4, 'warning')
        end,
        Tooltip = 'Type part of a song name to jump straight to it'
    })
    Playlist = MP3Player:CreateTextList({
        Name = 'Playlist',
        Placeholder = 'song name',
        Function = function()
            scan(true)
        end,
        Tooltip = 'Leave empty to play everything in the folder. Add names and only those play, in the order you list them'
    })
    SpotifyMode = MP3Player:CreateToggle({
        Name = 'Spotify mode',
        Tooltip = 'Play a song from a Spotify link. Only its 30-second preview, saved into songs/spotify',
        Function = function(callback)
            pcall(function()
                SpotifyLink.Object.Visible = callback
            end)
            if callback and MP3Player.Enabled and SpotifyLink.Value ~= '' then
                task.spawn(playSpotify)
            end
        end
    })
    SpotifyLink = MP3Player:CreateTextBox({
        Name = 'Spotify link',
        Placeholder = 'open.spotify.com/track/...',
        Darker = true,
        Visible = false,
        Function = function(enter)
            if not enter then return end
            if MP3Player.Enabled and SpotifyMode.Enabled and (SpotifyLink.Value or '') ~= '' then
                task.spawn(playSpotify)
            end
        end
    })
    ShowHUD = MP3Player:CreateToggle({
        Name = 'Show HUD',
        Default = true,
        Tooltip = 'Show the now-playing panel. Drag it by its own frame to move it',
        Function = function(callback)
            pcall(function()
                HUDProgress.Object.Visible = callback
                HUDTime.Object.Visible = callback
                HUDColor.Object.Visible = callback
            end)
            if MP3Player.Children then
                MP3Player.Children.Visible = callback and MP3Player.Enabled
            end
        end
    })
    HUDProgress = MP3Player:CreateToggle({
        Name = 'Progress bar',
        Default = true,
        Darker = true,
        Tooltip = 'Show how far through the song you are'
    })
    HUDTime = MP3Player:CreateToggle({
        Name = 'Show time',
        Default = true,
        Darker = true,
        Tooltip = 'Show elapsed and total time'
    })
    HUDColor = MP3Player:CreateColorSlider({
        Name = 'HUD color',
        Darker = true,
        DefaultOpacity = 0.55,
        Function = refreshHUD
    })
end)

run(function()
    local AntiSuffocate
    local Mode

    -- Burial check. Push mode needs the player fully buried (body plus the
    -- cells above and below) before nudging, but TP mode must also fire when
    -- only part of the body is inside a block - most importantly legs-only
    -- suffocation, where the body/head cells are still free.
    local function isSuffocating(root, mode)
        local body = getPlacedBlock(root.Position)
        local head = getPlacedBlock(root.Position + Vector3.new(0, 2, 0))
        local legs = getPlacedBlock(root.Position - Vector3.new(0, 2, 0))
        if mode == 'TP' then
            return (body or legs) and true or false
        end
        return (body and head and legs) and true or false
    end

    -- TP mode: pop straight up to the top of the block column we are stuck in so our
    -- feet rest on the highest ground with nothing above our head.
    local function teleportOut(root)
        local hip = entitylib.character.HipHeight or 2.5
        local base = root.Position
        for step = 1, 26 do
            local probe = base + Vector3.new(0, step, 0)
            local ground = getPlacedBlock(probe - Vector3.new(0, 2, 0))
            if ground and not getPlacedBlock(probe) and not getPlacedBlock(probe + Vector3.new(0, 2, 0)) then
                local topY = ground.Position.Y + ground.Size.Y / 2
                root.CFrame = CFrame.new(base.X, topY + hip + 0.1, base.Z) * root.CFrame.Rotation
                root.AssemblyLinearVelocity = Vector3.zero
                return true
            end
        end
    end

    AntiSuffocate = vape.Categories.Utility:CreateModule({
	Name = 'AntiSuffocate',
	Function = function(call)
		if call then
			repeat
				if entitylib.isAlive then
					local root = entitylib.character.RootPart
					if isSuffocating(root, Mode.Value) then
						if Mode.Value == 'TP' then
							teleportOut(root)
						else
							root.CFrame += Vector3.new(0, 0.5, 0)
							if root.AssemblyLinearVelocity.Y < -1 then
								root.AssemblyLinearVelocity = Vector3.zero
							end
						end
					end
				end
				task.wait()
			until not AntiSuffocate.Enabled
		end
	end,
	Tooltip = 'Prevents you from suffocating in blocks',
    })
    Mode = AntiSuffocate:CreateDropdown({
	Name = 'Mode',
	List = {'Push', 'TP'},
	Default = 'Push',
	Tooltip = 'Push nudges you up while fully buried. TP jumps you to the top and also fires on partial burials'
    })
end)

run(function()
    local AutoBalloon

    AutoBalloon = vape.Categories.Utility:CreateModule({
        Name = 'AutoBalloon',
        Function = function(callback)
            if callback then
                repeat task.wait() until store.matchState ~= 0 or (not AutoBalloon.Enabled)
                if not AutoBalloon.Enabled then return end

                local lowestpoint = math.huge
                for _, v in store.blocks do
                    local point = (v.Position.Y - (v.Size.Y / 2)) - 50
                    if point < lowestpoint then
                        lowestpoint = point
                    end
                end

                repeat
                    if entitylib.isAlive then
                        if entitylib.character.RootPart.Position.Y < lowestpoint and (lplr.Character:GetAttribute('InflatedBalloons') or 0) < 3 then
                            local balloon = getItem('balloon')
                            if balloon then
                                for _ = 1, 3 do
                                    bedwars.BalloonController:inflateBalloon()
                                end
                            end
                            task.wait(0.1)
                        end
                    end
                    task.wait(0.1)
                until not AutoBalloon.Enabled
            end
        end,
        Tooltip = 'Inflates when you fall into the void'
    })
end)

run(function()
    local AntiLasso
    local Chance
    local Check
    local currentConnections = {}
    local currentCharacter
    local activeLasso
    local ignoredLasso
    local lassoVersion = 0
    local returnFilter = RaycastParams.new()
    local returnOverlap = OverlapParams.new()

    returnFilter.FilterType = Enum.RaycastFilterType.Exclude
    returnFilter.RespectCanCollide = true
    returnFilter.IgnoreWater = true
    returnOverlap.FilterType = Enum.RaycastFilterType.Exclude
    returnOverlap.RespectCanCollide = true

    local function disconnectCharacter()
        for _, connection in currentConnections do
            connection:Disconnect()
        end
        table.clear(currentConnections)
        currentCharacter = nil
    end

    local function isFinite(value)
        return type(value) == 'number' and value == value and value > -math.huge and value < math.huge
    end

    local function isFiniteCFrame(value)
        if typeof(value) ~= 'CFrame' then return false end
        for _, component in {value:GetComponents()} do
            if not isFinite(component) then return false end
        end
        return true
    end

    -- What a lasso looks like on a character. The old check only ever accepted a direct child of
    -- the character holding a descendant named exactly 'Rope', which misses the constraint itself
    -- and anything the game renames between updates, so a lasso that carried no 'LassoHooked' tag
    -- was never seen at all.
    local function isLassoPart(inst)
        if inst:IsA('RopeConstraint') then return true end
        local name = inst.Name:lower()
        return name:find('lasso', 1, true) ~= nil or name:find('rope', 1, true) ~= nil
    end

    local function getLassoObject(character)
        for _, descendant in character:GetDescendants() do
            if isLassoPart(descendant) then
                return descendant
            end
        end
    end

    local function hasClearance(character, root, position)
        returnOverlap.FilterDescendantsInstances = {character, gameCamera}
        for _, part in workspace:GetPartBoundsInBox(CFrame.new(position), root.Size * Vector3.new(0.9, 1, 0.9), returnOverlap) do
            local queryIgnored = bedwars.QueryUtil.isQueryIgnored
            if part.CanCollide and not (type(queryIgnored) == 'function' and queryIgnored(bedwars.QueryUtil, part)) then
                return false
            end
        end
        return true
    end

    local function getSafeReturnCFrame(event)
        local character, root, saved = event.character, event.root, event.cframe
        local humanoid = character:FindFirstChildOfClass('Humanoid')
        if not isFiniteCFrame(saved) or not root.Parent or not humanoid or humanoid.Health <= 0 then return end
        local position = saved.Position
        if position.Y <= workspace.FallenPartsDestroyHeight + 12 then return end

        returnFilter.FilterDescendantsInstances = {character, gameCamera}
        local ground = workspace:Raycast(position + Vector3.yAxis * 3, -Vector3.yAxis * 99, returnFilter)
        if ground and position.Y - ground.Position.Y >= 1 and hasClearance(character, root, position) then
            return saved
        end

        local offsets = {Vector3.zero}
        for radius = 3, 12, 3 do
            for _, direction in {
                Vector3.xAxis,
                -Vector3.xAxis,
                Vector3.zAxis,
                -Vector3.zAxis,
                Vector3.new(1, 0, 1).Unit,
                Vector3.new(1, 0, -1).Unit,
                Vector3.new(-1, 0, 1).Unit,
                Vector3.new(-1, 0, -1).Unit
            } do
                table.insert(offsets, direction * radius)
            end
        end

        local best, bestDistance
        for _, offset in offsets do
            local origin = position + offset + Vector3.yAxis * 12
            local result = workspace:Raycast(origin, -Vector3.yAxis * 72, returnFilter)
            if result and result.Instance.CanCollide then
                local candidate = Vector3.new(origin.X, result.Position.Y + humanoid.HipHeight + root.Size.Y / 2, origin.Z)
                local distance = (candidate - position).Magnitude
                if candidate.Y > workspace.FallenPartsDestroyHeight + 12 and hasClearance(character, root, candidate)
                    and (not bestDistance or distance < bestDistance)
                then
                    best, bestDistance = candidate, distance
                end
            end
        end
        return best and CFrame.new(best) * saved.Rotation or nil
    end

    local function clearLasso(event)
        if activeLasso ~= event then return end
        activeLasso = nil
        if event.root.Parent then
            event.root.Anchored = false
        end
    end

    local function returnPlayer(event, visualReleased)
        if activeLasso ~= event or event.returned or not AntiLasso.Enabled then return false end
        if collectionService:HasTag(event.character, 'LassoHooked') then return false end
        if not visualReleased and getLassoObject(event.character) then return false end
        local root = event.root
        local returnCFrame = getSafeReturnCFrame(event)
        if not returnCFrame or lplr.Character ~= event.character or not entitylib.isAlive or entitylib.character.RootPart ~= root then
            clearLasso(event)
            return true
        end
        event.returned = true
        root.Anchored = false
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
        root.CFrame = returnCFrame
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
        if activeLasso == event then
            activeLasso = nil
        end
        return true
    end

    local function waitForRelease(event)
        task.spawn(function()
            local visualReleasedAt
            while activeLasso == event and AntiLasso.Enabled and lplr.Character == event.character and event.root.Parent do
                local tagged = collectionService:HasTag(event.character, 'LassoHooked')
                local visual = getLassoObject(event.character)
                if not tagged and not visual then
                    returnPlayer(event)
                    return
                end
                if not tagged then
                    visualReleasedAt = visualReleasedAt or tick()
                    if tick() - visualReleasedAt >= 1 then
                        returnPlayer(event, true)
                        return
                    end
                else
                    visualReleasedAt = nil
                end
                task.wait(0.05)
            end
        end)
    end

    local function startLasso(character, nativeEvent)
        if not AntiLasso.Enabled or character ~= lplr.Character or ignoredLasso == character then return end
        if activeLasso and activeLasso.character == character then
            if not nativeEvent or not activeLasso.releaseSeen then return end
            clearLasso(activeLasso)
        end
        if Random.new(os.clock()):NextNumber(1, 100) > Chance.Value or Check.Enabled and not entitylib.EntityPosition({
            Range = 50,
            Part = 'RootPart',
            Players = true
        }) then
            if nativeEvent then ignoredLasso = character end
            return
        end
        local root = character:FindFirstChild('HumanoidRootPart') or character.PrimaryPart
        local humanoid = character:FindFirstChildOfClass('Humanoid')
        if not root or not humanoid or humanoid.Health <= 0 or not isFiniteCFrame(root.CFrame) then return end
        if activeLasso then clearLasso(activeLasso) end
        lassoVersion += 1
        local event = {
            cframe = root.CFrame,
            character = character,
            root = root,
            token = lassoVersion
        }
        activeLasso = event
        root.Anchored = true
        waitForRelease(event)
    end

    local function releaseLasso(character)
        if ignoredLasso == character then
            ignoredLasso = nil
            return
        end
        local event = activeLasso
        if not event or event.character ~= character then return end
        event.releaseSeen = true
        task.defer(function()
            local deadline = tick() + 1
            repeat
                if activeLasso ~= event or returnPlayer(event) then return end
                task.wait()
            until tick() >= deadline
            returnPlayer(event, true)
        end)
    end

    local function Added(character)
        local previousCharacter = currentCharacter
        disconnectCharacter()
        if previousCharacter ~= character then ignoredLasso = nil end
        if not AntiLasso.Enabled or not character or not character.Parent then return end
        if activeLasso then clearLasso(activeLasso) end
        currentCharacter = character
        -- DescendantAdded, not ChildAdded. The rope is built under the object the game parents to
        -- the character, so at the instant ChildAdded fired that object was still empty and the
        -- lasso went unnoticed every time - which, on a build that no longer tags the character,
        -- left the module with nothing to react to at all.
        table.insert(currentConnections, character.DescendantAdded:Connect(function(descendant)
            if isLassoPart(descendant) then
                startLasso(character)
            end
        end))
        table.insert(currentConnections, character.Destroying:Connect(function()
            if currentCharacter == character then
                disconnectCharacter()
            end
            if activeLasso and activeLasso.character == character then
                clearLasso(activeLasso)
            end
        end))
        local humanoid = character:FindFirstChildOfClass('Humanoid')
        if humanoid then
            table.insert(currentConnections, humanoid.Died:Connect(function()
                if activeLasso and activeLasso.character == character then
                    clearLasso(activeLasso)
                end
            end))
        end
        if collectionService:HasTag(character, 'LassoHooked') or getLassoObject(character) then
            startLasso(character, collectionService:HasTag(character, 'LassoHooked'))
        end
    end

    AntiLasso = vape.Categories.Utility:CreateModule({
        Name = 'AntiLasso',
        Function = function(callback)
            if callback then
                AntiLasso:Clean(collectionService:GetInstanceAddedSignal('LassoHooked'):Connect(function(character)
                    if character == lplr.Character then
                        startLasso(character, true)
                    end
                end))
                AntiLasso:Clean(collectionService:GetInstanceRemovedSignal('LassoHooked'):Connect(function(character)
                    if character == lplr.Character then
                        releaseLasso(character)
                    end
                end))
                AntiLasso:Clean(entitylib.Events.LocalAdded:Connect(function(ent)
                    task.defer(function()
                        if AntiLasso.Enabled and ent and ent.Character then
                            Added(ent.Character)
                        end
                    end)
                end))
                AntiLasso:Clean(lplr.OnTeleport:Connect(function()
                    if activeLasso then clearLasso(activeLasso) end
                    ignoredLasso = nil
                    disconnectCharacter()
                end))
                if entitylib.isAlive then
                    Added(lplr.Character)
                end
            else
                lassoVersion += 1
                ignoredLasso = nil
                disconnectCharacter()
                if activeLasso then clearLasso(activeLasso) end
            end
        end,
        Tooltip = 'Prevents you from getting pulled by lasso projectile'
    })

    Chance = AntiLasso:CreateSlider({
        Name = 'Chance',
        Min = 0,
        Max = 100,
        Default = 100,
        Suffix = '%'
    })
    Check = AntiLasso:CreateToggle({Name = 'Only when targeting'})
end)

run(function()
    local AutoLasso
    local Targets
    local Range
    local Angle

    local projectileRemote, lastshot = {InvokeServer = function() end}, tick()
    task.spawn(function()
        projectileRemote = bedwars.Client:Get(remotes.FireProjectile).instance
    end)

    local rayCheck = RaycastParams.new()

    AutoLasso = vape.Categories.Utility:CreateModule({
        Name = 'AutoLasso',
        Function = function(callback)
            if callback then
                repeat
                    if entitylib.isAlive and tick() > lastshot then
                        local lasso = getItem('lasso')
                        if lasso then
                            local ent = entitylib.EntityPosition({
                                Range = Range.Value,
                                Part = 'RootPart',
                                Wallcheck = Targets.Walls.Enabled,
                                Players = Targets.Players.Enabled,
                                NPCs = Targets.NPCs.Enabled,
                                Sort = sortmethods.Distance
                            })

                            if ent then
                                local selfpos = entitylib.character.RootPart.Position
                                local localfacing = gameCamera.CFrame.LookVector * Vector3.new(1, 0, 1)
                                local delta = (ent.RootPart.Position - selfpos) * Vector3.new(1, 0, 1)
                                if delta.Magnitude > 0.001 and math.acos(math.clamp(localfacing:Dot(delta.Unit), -1, 1)) <= (math.rad(Angle.Value) / 2) then
                                    local calc = prediction.SolveTrajectory(selfpos, 200, 135, ent.RootPart.Position, ent.RootPart.Velocity, workspace.Gravity, ent.Humanoid.HipHeight or 2, nil, rayCheck)
                                    if calc then
                                        local old = store.inventory.hotbarSlot
                                        local new = getHotbar(lasso.tool)
                                        if new then
                                            switchItem(lasso.tool)
                                            hotbarSwitch(new)
                                        end

                                        local res = projectileRemote:InvokeServer(
                                            lasso.tool,
                                            'lasso',
                                            'lasso',
                                            selfpos,
                                            selfpos,
                                            CFrame.lookAt(selfpos, calc).LookVector * 200,
                                            httpService:GenerateGUID(true),
                                            {
                                                drawDurationSeconds = 1,
                                                shotId = httpService:GenerateGUID(false)
                                            },
                                            workspace:GetServerTimeNow() - 0.045
                                        )
                                        if res then
                                            lastshot = tick() + 10.5
                                        end
                                        hotbarSwitch(old)
                                        task.wait(0.1)
                                    end
                                end
                            end
                        end
                    end
                    task.wait(0.05)
                until not AutoLasso.Enabled
            end
        end
    })

    Targets = AutoLasso:CreateTargets({Players = true})
    Range = AutoLasso:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 60,
        Default = 60,
        Suffix = function(val)
            return val <= 1 and 'stud' or 'studs'
        end
    })
    Angle = AutoLasso:CreateSlider({
        Name = 'Max angle',
        Min = 1,
        Max = 360,
        Default = 120
    })
end)

run(function()
    local AutoPearl
    local Legit
    local Back
    local Check
    local LandCheck
    local BackDelay
    local Limit

    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true
    rayCheck.FilterType = Enum.RaycastFilterType.Include
    local projectileRemote = {InvokeServer = function(self, ...) end}
    task.spawn(function()
	projectileRemote = bedwars.Client:Get(remotes.FireProjectile).instance
    end)

    local function firePearl(pos, spot, item)
	if Check.Enabled then
		for _, v in store.selfProjectiles do
			if v.Name == 'telepearl' then
				return
			end
		end
	end
	local hotbar, old = getHotbar(item.tool), store.hand

	switchItem(item.tool)
	if Legit.Enabled and hotbar then
		hotbarSwitch(hotbar)
	end

	local meta = bedwars.ProjectileMeta.telepearl
	local calc = prediction.SolveTrajectory(pos, meta.launchVelocity, meta.gravitationalAcceleration, spot, Vector3.zero, workspace.Gravity, 0, 0)
	local landed = false

	if calc then
		local dir = CFrame.lookAt(pos, calc).LookVector * meta.launchVelocity
		local projectile = bedwars.ProjectileController:createLocalProjectile(meta, 'telepearl', 'telepearl', pos, nil, dir, {drawDurationSeconds = 1})
		local res = projectileRemote:InvokeServer(
			item.tool,
			'telepearl',
			'telepearl',
			pos,
			pos,
			dir,
			httpService:GenerateGUID(true),
			{
                    drawDurationSeconds = 1,
                    shotId = httpService:GenerateGUID(false)
                },
			workspace:GetServerTimeNow() - 0.045
		)
		task.spawn(function()
			repeat
				task.wait()
			until not projectile or not projectile.Parent
			landed = true
		end)
		if res then
			pcall(function()
				res.Parent = replicatedStorage
			end)
		end
	end

	if Back.Enabled and LandCheck.Enabled then
		repeat
			task.wait()
		until landed
	end
	if Back.Enabled and old and old.tool then
		task.wait(BackDelay:GetRandomValue())
		switchItem(old.tool)
		if Legit.Enabled and getHotbar(old.tool) then
			hotbarSwitch(getHotbar(old.tool))
		end
	end
    end

    local function findNearGround(origin)
	for _, v in {Vector3.new(1, 0, 0), Vector3.new(0, 0, 1), Vector3.new(-1, 0, 0), Vector3.new(0, 0, -1)} do
		for i = 1, 24 do
			local ray = workspace:Raycast((origin.Position + (Vector3.yAxis * 3)) + (v * i), Vector3.new(0, -60, 0), rayCheck)
			if ray then
				return ray.Position
			end
		end
	end
	return nil
    end

    AutoPearl = vape.Categories.Utility:CreateModule({
	Name = 'AutoPearl',
	Function = function(callback)
		if callback then
			local check, lasty
			repeat
				if entitylib.isAlive and (not Limit.Enabled or store.hand.tool and store.hand.tool.Name == 'telepearl') then
					local root = entitylib.character.RootPart
					local pearl = getItem('telepearl')
					rayCheck.FilterDescendantsInstances = {store.map}
					rayCheck.CollisionGroup = root.CollisionGroup

					if entitylib.character.Humanoid.FloorMaterial ~= Enum.Material.Air then
						lasty = root.CFrame
					end

					if pearl and root.Velocity.Y < -100 and not workspace:Raycast(root.Position, Vector3.new(0, -200, 0), rayCheck) then
						if not check then
							check = true
							local ground = findNearGround(root.CFrame + Vector3.new(0, 40, 0)) or findNearGround(lasty and lasty + Vector3.new(0, 5, 0) or root.CFrame)
							if ground then
								firePearl(root.Position, ground, pearl)
							end
						end
					else
						check = false
					end
				end
				task.wait(0.1)
			until not AutoPearl.Enabled
		end
	end,
	Tooltip = 'Automatically throws a pearl onto nearby ground after\nfalling a certain distance'
    })

    Legit = AutoPearl:CreateToggle({
	Name = 'Legit Switch',
	Tooltip = 'Visualizes the switching clientside',
	Default = true
    })
    Back = AutoPearl:CreateToggle({
	Name = 'Switch back',
	Default = true,
	Function = function(callback)
		if BackDelay then
			BackDelay.Object.Visible = callback
		end
		if LandCheck then
			LandCheck.Object.Visible = callback
		end
	end,
	Tooltip = 'Switches back to the last slot before pearl'
    })
    LandCheck = AutoPearl:CreateToggle({
	Name = 'Only after landed',
	Tooltip = 'Only switches back after your pearl landed',
	Darker = true
    })
    Check = AutoPearl:CreateToggle({
	Name = 'Pearl check',
	Tooltip = 'Doesn\'t throw a pearl if you are already pearling',
	Default = true
    })
    BackDelay = AutoPearl:CreateTwoSlider({
	Name = 'Switch Back Delay',
	Min = 0,
	Max = 2,
	DefaultMin = 0.1,
	DefaultMax = 0.2,
	Darker = true
    })
    Limit = AutoPearl:CreateToggle({
	Name = 'Limit to item',
	Tooltip = 'Only throws pearl when holding a pearl'
    })
end)

run(function()
    local TritonClutch
    local Legit
    local Back
    local LandCheck
    local BackDelay
    local Limit
    local Recall
    local NoCamera

    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true
    rayCheck.FilterType = Enum.RaycastFilterType.Include
    local projectileRemote = {InvokeServer = function() end}
    task.spawn(function()
	projectileRemote = bedwars.Client:Get(remotes.FireProjectile).instance
    end)

    local harpoonAbilities = {'harpoon', 'HARPOON', 'harpoon_throw', 'HARPOON_THROW', 'triton_harpoon', 'TRITON_HARPOON'}
    local virtualInputManager = cloneref(game:GetService('VirtualInputManager'))

    local function isHarpoonTool(tool)
	local name = tool and tool.Name and tool.Name:lower()
	return name == 'harpoon' or name == 'trident' or name == 'triton_harpoon'
    end

    local function clickHeldHarpoon(target)
	local camera = workspace.CurrentCamera
	if not camera then
		return false
	end

	local before = #store.selfProjectiles
	local viewport = camera.ViewportSize
	local original = camera.CFrame
	pcall(function()
		camera.CFrame = CFrame.lookAt(original.Position, target)
	end)
	virtualInputManager:SendMouseButtonEvent(viewport.X / 2, viewport.Y / 2, 0, true, game, 0)
	task.wait()
	virtualInputManager:SendMouseButtonEvent(viewport.X / 2, viewport.Y / 2, 0, false, game, 0)
	camera.CFrame = original

	local started = tick()
	repeat
		if #store.selfProjectiles > before then
			return true
		end
		task.wait()
	until tick() - started > 0.25
	return false
    end

    local function waitForHarpoonClutch()
	local started = tick()
	repeat
		task.wait()
		local root = entitylib.isAlive and entitylib.character.RootPart
		if root and root.Velocity.Y > -10 then
			return true
		end
	until not TritonClutch.Enabled or tick() - started > 3
	return false
    end

    task.spawn(function()
	local success, abilityIds = pcall(function()
		return require(replicatedStorage.TS.ability['ability-id']).AbilityId
	end)
	if success then
		for _, ability in abilityIds do
			local lowered = tostring(ability):lower()
			if lowered:find('harpoon', 1, true) then
				table.insert(harpoonAbilities, ability)
			end
		end
	end
    end)

    local function useAbility(list, payloads)
	for _, ability in list do
		local allowed = true
		pcall(function()
			allowed = not bedwars.AbilityController.canUseAbility or bedwars.AbilityController:canUseAbility(ability)
		end)

		if allowed then
			for _, data in payloads do
				local success, result = pcall(function()
					return bedwars.AbilityController:useAbility(ability, newproxy(true), data)
				end)
				if success and result ~= false then
					return true
				end

				success, result = pcall(function()
					return bedwars.AbilityController:useAbility(ability, data)
				end)
				if success and result ~= false then
					return true
				end

				pcall(function()
					bedwars.Client:Get(remotes.UseAbility).instance:FireServer(ability, data)
				end)
			end
		end
	end
	return false
    end

    local function fireHarpoonProjectile(pos, spot, item)
	local projectileType = 'harpoon_projectile'
	local meta = bedwars.ProjectileMeta[projectileType]
	if not meta then
		return false
	end

	local launchVelocity = meta.launchVelocity or 160
	local gravity = meta.gravitationalAcceleration or 0
	local calc = prediction.SolveTrajectory(pos, launchVelocity, gravity, spot, Vector3.zero, workspace.Gravity, 0, 0) or spot
	local dir = CFrame.lookAt(pos, calc).LookVector * launchVelocity
	local shotId = httpService:GenerateGUID(false)
	local landed = false
	local projectile

	pcall(function()
		projectile = bedwars.ProjectileController:createLocalProjectile(meta, projectileType, projectileType, pos, nil, dir, {drawDurationSeconds = 1})
	end)

	if projectile then
		task.spawn(function()
			repeat
				task.wait()
			until not projectile or not projectile.Parent
			landed = true
		end)
	end

	local success, result = pcall(function()
		return projectileRemote:InvokeServer(
			item.tool,
			projectileType,
			projectileType,
			pos,
			pos,
			dir,
			httpService:GenerateGUID(true),
			{
				drawDurationSeconds = 1,
				shotId = shotId
			},
			workspace:GetServerTimeNow() - 0.045
		)
	end)

	return success and result ~= nil, function()
		local started = tick()
		repeat
			task.wait()
		until landed or not TritonClutch.Enabled or tick() - started > 3
		return landed
	end
    end

    local function useHarpoon(pos, spot, item)
	local hotbar, old = getHotbar(item.tool), store.hand
	switchItem(item.tool)
	if Legit.Enabled and hotbar then
		hotbarSwitch(hotbar)
	end

	local used, clutchCheck, recallWait
	if not NoCamera.Enabled and clickHeldHarpoon(spot) then
		clutchCheck = waitForHarpoonClutch
		used = true
	else
		used, clutchCheck = fireHarpoonProjectile(pos, spot, item)
	end

	if not used then
		used = useAbility(harpoonAbilities, {
			{target = spot, origin = pos},
			{targetPosition = spot, position = pos},
			{position = spot},
			spot
		})
		clutchCheck = waitForHarpoonClutch
	end

	if used and Recall.Enabled then
		recallWait = function()
			task.wait(1.25)
			virtualInputManager:SendKeyEvent(true, Enum.KeyCode.C, false, game)
			task.wait()
			virtualInputManager:SendKeyEvent(false, Enum.KeyCode.C, false, game)

			local started, lastPosition, stable = tick(), nil, 0
			repeat
				task.wait(0.1)
				local root = entitylib.isAlive and entitylib.character.RootPart
				if root then
					local currentPosition = root.Position
					local moved = lastPosition and (currentPosition - lastPosition).Magnitude or math.huge
					if tick() - started > 0.75 and moved < 1 and root.Velocity.Magnitude < 8 then
						stable += 0.1
						if stable >= 0.3 then
							return true
						end
					else
						stable = 0
					end
					lastPosition = currentPosition
				end
			until not TritonClutch.Enabled or tick() - started > 7
			return false
		end
	end

	if Back.Enabled and LandCheck.Enabled and clutchCheck then
		clutchCheck()
	end
	if Back.Enabled and old and old.tool then
		if recallWait then
			recallWait()
		else
			task.wait(BackDelay:GetRandomValue())
		end
		switchItem(old.tool)
		if Legit.Enabled and getHotbar(old.tool) then
			hotbarSwitch(getHotbar(old.tool))
		end
	elseif recallWait then
		task.spawn(recallWait)
	end
    end

    local function findNearGround(origin, root)
	local best, bestScore
	local originPosition = origin.Position
	local velocity = root and root.Velocity or Vector3.zero
	local horizontalVelocity = Vector3.new(velocity.X, 0, velocity.Z)
	local fallSpeed = math.max(-velocity.Y, 0)
	local samples = {}

	local function addSample(position)
		table.insert(samples, position)
	end

	local function getAimPoint(ray, predictedPosition)
		local hit = ray.Position + (ray.Normal * 0.35)
		local part = ray.Instance
		if part and part:IsA('BasePart') then
			local size = part.Size
			local localPredicted = part.CFrame:PointToObjectSpace(predictedPosition)
			local edgeMargin = math.min(0.45, math.max(math.min(size.X, size.Z) * 0.2, 0.08))
			local xLimit = math.max((size.X * 0.5) - edgeMargin, 0)
			local zLimit = math.max((size.Z * 0.5) - edgeMargin, 0)
			localPredicted = Vector3.new(math.clamp(localPredicted.X, -xLimit, xLimit), size.Y * 0.5 + 0.25, math.clamp(localPredicted.Z, -zLimit, zLimit))
			hit = part.CFrame:PointToWorldSpace(localPredicted)
		end
		return hit
	end

	addSample(originPosition)
	for time = 0.15, 2.4, 0.15 do
		local predictedPosition = originPosition + (horizontalVelocity * time) + Vector3.new(0, (velocity.Y * time) - (workspace.Gravity * time * time * 0.5), 0)
		local center = Vector3.new(predictedPosition.X, originPosition.Y, predictedPosition.Z)
		addSample(center)
		for radius = 1, 12, 1 do
			for angle = 0, 315, 45 do
				local radians = math.rad(angle)
				addSample(center + Vector3.new(math.cos(radians) * radius, 0, math.sin(radians) * radius))
			end
		end
	end

	for radius = 16, 72, 4 do
		for angle = 0, 315, 45 do
			local radians = math.rad(angle)
			addSample(originPosition + (horizontalVelocity * 0.65) + Vector3.new(math.cos(radians) * radius, 0, math.sin(radians) * radius))
		end
	end

	for _, sample in samples do
		local ray = workspace:Raycast(sample + Vector3.new(0, 128, 0), Vector3.new(0, -420, 0), rayCheck)
		if ray then
			local drop = math.max(originPosition.Y - ray.Position.Y, 1)
			local timeToPlatform = math.clamp((math.sqrt((fallSpeed * fallSpeed) + (2 * workspace.Gravity * drop)) - fallSpeed) / workspace.Gravity, 0.05, 2.5)
			local predictedPosition = originPosition + (horizontalVelocity * timeToPlatform)
			local aimPoint = getAimPoint(ray, predictedPosition)
			local horizontalDistance = (Vector3.new(aimPoint.X, originPosition.Y, aimPoint.Z) - Vector3.new(originPosition.X, originPosition.Y, originPosition.Z)).Magnitude
			local predictedDistance = (Vector3.new(aimPoint.X, predictedPosition.Y, aimPoint.Z) - Vector3.new(predictedPosition.X, predictedPosition.Y, predictedPosition.Z)).Magnitude
			local score = (predictedDistance * 1.35) + (horizontalDistance * 0.25) + (drop * 0.015)
			if not bestScore or score < bestScore then
				best, bestScore = aimPoint, score
			end
		end
	end
	return best
    end


    TritonClutch = kits:CreateModule({
	Name = 'TritonClutch',
	Category = 'Ability',
	Function = function(callback)
		if callback then
			local lasty, attempted
			repeat
				if entitylib.isAlive and (not Limit.Enabled or isHarpoonTool(store.hand.tool)) then
					local root = entitylib.character.RootPart
					local harpoon = getItem('harpoon') or getItem('triton_harpoon') or getItem('trident')
					rayCheck.FilterDescendantsInstances = {store.map}
					rayCheck.CollisionGroup = root.CollisionGroup

					local onGround = entitylib.character.Humanoid.FloorMaterial ~= Enum.Material.Air
					if onGround then
						lasty = root.CFrame
						attempted = false
					end

					if not onGround and not attempted and harpoon and root.Velocity.Y < -60 and not workspace:Raycast(root.Position, Vector3.new(0, -140, 0), rayCheck) then
						attempted = true
						local ground = findNearGround(root.CFrame, root) or findNearGround(lasty and lasty + Vector3.new(0, 5, 0) or root.CFrame, root)
						if ground then
							useHarpoon(root.Position, ground, harpoon)
						end
					end
				end
				task.wait(0.03)
			until not TritonClutch.Enabled
		end
	end,
	Tooltip = 'Automatically throws Triton\'s harpoon onto nearby ground after falling a certain distance'
    })

    Legit = TritonClutch:CreateToggle({
	Name = 'Legit Switch',
	Tooltip = 'Visualizes the switching clientside',
	Default = true
    })
    Back = TritonClutch:CreateToggle({
	Name = 'Switch back',
	Default = true,
	Function = function(callback)
		if BackDelay then
			BackDelay.Object.Visible = callback
		end
		if LandCheck then
			LandCheck.Object.Visible = callback
		end
	end,
	Tooltip = 'Switches back to the previous slot after Recall finishes, or after the clutch delay when Recall is off'
    })
    LandCheck = TritonClutch:CreateToggle({
	Name = 'Only after clutch',
	Tooltip = 'Waits for the harpoon clutch before switching back; Recall still waits until the recall finishes',
	Darker = true
    })
    BackDelay = TritonClutch:CreateTwoSlider({
	Name = 'Switch Back Delay',
	Min = 0,
	Max = 2,
	DefaultMin = 0.1,
	DefaultMax = 0.2,
	Darker = true
    })
    Limit = TritonClutch:CreateToggle({
	Name = 'Limit to items',
	Tooltip = "Only throws Triton's harpoon when holding the harpoon or trident"
    })
    NoCamera = TritonClutch:CreateToggle({
	Name = 'Prevent Camera Movement',
	Tooltip = 'Uses server projectile logic instead of moving your camera for the click fallback',
	Default = true
    })
    Recall = TritonClutch:CreateToggle({
	Name = 'Recall',
	Tooltip = 'Presses C to activate Recall / Go to base after clutching'
    })
end)



run(function()
    local AutoPlay
    local Random
    -- One queue attempt in flight at a time; the death and match-end paths can both fire.
    local queueing = false

    local function isEveryoneDead()
        return #bedwars.Store:getState().Party.members <= 0
    end

    -- BedWars only accepts a queue request from the party leader, and only while the party is not
    -- already queued. Playing solo there is no party at all, so reading Party.leader.userId threw
    -- straight out of the event handler and the queue was never even attempted - which is most of
    -- "AutoPlay doesn't queue". A missing leader is us.
    local function canQueue()
        local ok, res = pcall(function()
            local state = bedwars.Store:getState()
            if state.Game.customMatch then return false end
            local party = state.Party
            local leader = party and party.leader
            if leader and leader.userId and leader.userId ~= lplr.UserId then return false end
            return (party and party.queueState or 0) == 0
        end)
        return ok and res == true
    end

    local function pickMode()
        if not Random.Enabled then return store.queueType end
        local listofmodes = {}
        pcall(function()
            for i, v in bedwars.QueueMeta do
                if not v.disabled and not v.voiceChatOnly and not v.rankCategory then
                    table.insert(listofmodes, i)
                end
            end
        end)
        return #listofmodes > 0 and listofmodes[math.random(1, #listofmodes)] or store.queueType
    end

    local function joinQueue()
        if queueing or not AutoPlay.Enabled or not canQueue() then return end
        queueing = true
        local mode = pickMode()
        pcall(function() bedwars.QueueController:joinQueue(mode) end)
        -- The request sent on the match-end frame is sometimes swallowed while the end screen is
        -- still animating in. Check back once and send it again if nothing took, rather than
        -- firing blind and sitting in the lobby.
        task.delay(6, function()
            if AutoPlay.Enabled and canQueue() then
                pcall(function() bedwars.QueueController:joinQueue(mode) end)
            end
            queueing = false
        end)
    end

    AutoPlay = vape.Categories.Utility:CreateModule({
        Name = 'AutoPlay',
        Function = function(callback)
            if callback then
                queueing = false
                AutoPlay:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(deathTable)
                    if deathTable.finalKill and deathTable.entityInstance == lplr.Character and isEveryoneDead() and store.matchState ~= 2 then
                        joinQueue()
                    end
                end))
                AutoPlay:Clean(vapeEvents.MatchEndEvent.Event:Connect(joinQueue))
            end
        end,
        Tooltip = 'Automatically queues after the match ends'
    })
    Random = AutoPlay:CreateToggle({
        Name = 'Random',
        Tooltip = 'Chooses a random mode'
    })
end)

run(function()
    local AutoRelease
    local Percentage
    local Delay

    local launchHook, last = nil, 0
    local charge = 0

    AutoRelease = vape.Categories.Utility:CreateModule({
	Name = 'AutoRelease',
	Function = function(call)
		if call then
			launchHook = bedwars.ProjectileLaunchHook:Add('AutoRelease', 20, function(nextLaunch, ...)
				local projmeta = select(2, ...)
				if projmeta and typeof(projmeta) == 'table' then
					charge = (projmeta.velocityMultiplier / 1) * 100
					last = os.clock() + 0.1
				end

				return nextLaunch(...)
			end)

			repeat
				if last > os.clock() and charge >= Percentage.Value then
					task.wait(Delay.Value)
					mouse1click()
					task.wait(0.2)
				end
				task.wait()
			until not AutoRelease.Enabled
		else
			if launchHook then
				launchHook()
				launchHook = nil
			end
		end
	end,
        Tooltip = 'Automatically releases your projectile source when\nat certain charging percentage'
    })

    Percentage = AutoRelease:CreateSlider({
	Name = 'Percentage',
	Min = 0,
	Max = 100,
	Suffix = '%',
	Default = 100,
    })
    Delay = AutoRelease:CreateSlider({
	Name = 'Release delay',
	Min = 0,
	Max = 5,
	Default = 0.5,
	Decimal = 10,
	Suffix = function(val)
		return val <= 1 and 'sec' or 'secs'
	end,
    })
end)

run(function()
    local AutoShoot
    local Targets
    local Check
    local Range
    local Projectiles
	local FireRate
	local SwitchDelay
	-- Ground search params for the trajectory solve, and nothing else. Exclude rather than
	-- Include-the-map: in this game a target is almost always standing on a block somebody
	-- placed, which is not part of the static map, so an Include list of the map alone casts
	-- straight past whatever they are stood on and reports the floor of the world far below -
	-- and the solve then leads them as though they were about to fall into it. Worse, the list
	-- was built at load time, so on any join where the map had not streamed in yet it held a
	-- single nil, and an EMPTY Include list makes every cast return nothing at all.
	local rayCheck = RaycastParams.new()
	rayCheck.FilterType = Enum.RaycastFilterType.Exclude
	rayCheck.RespectCanCollide = true

	local FireDelays = {}
    local function getAmmo(check)
	for _, item in store.inventory.inventory.items do
		if check.ammoItemTypes and table.find(check.ammoItemTypes, item.itemType) then
			return item.itemType
		end
	end
	return
    end

    local function getProjectiles()
	local items = {}
	for _, item in store.inventory.inventory.items do
			-- ItemMeta has no entry for an item this build has not seen, and indexing
			-- projectileSource on nil throws right here - inside the module's own loop
			-- thread, which kills it for good. One unknown item in the inventory must not
			-- be able to do that.
			local meta = bedwars.ItemMeta[item.itemType]
			local proj = meta and meta.projectileSource
		local ammo = proj and getAmmo(proj)
			if ammo and (table.find(Projectiles.ListEnabled, ammo) or table.find(Projectiles.ListEnabled, item.itemType) or table.find(Projectiles.ListEnabled, meta.displayName)) then
			table.insert(items, {
				item,
				ammo,
				proj.projectileType(ammo),
					proj
			})
		end
	end
	return items
    end

	local function getEntity()
	if not entitylib.isAlive then return nil end
	local selfpos = entitylib.character.RootPart.Position
		local plrs = entitylib.AllPosition({
			Origin = selfpos,
		Part = 'RootPart',
			Range = Range.Value,
		Players = Targets.Players.Enabled,
		NPCs = Targets.NPCs.Enabled,
			Wallcheck = Targets.Walls.Enabled,
			Limit = 10
	})
		if #plrs > 0 then
			for _, ent in plrs do
				local localfacing = entitylib.character.RootPart.CFrame.LookVector * Vector3.new(1, 0, 1)
				local delta = (ent.RootPart.Position - selfpos) * Vector3.new(1, 0, 1)
				local angle = localfacing.Magnitude > 0 and delta.Magnitude > 0 and math.acos(math.clamp(localfacing.Unit:Dot(delta.Unit), -1, 1)) or 0
				if angle > (math.rad(120) / 2) then continue end
				return ent
		end
	end
		return nil
    end

    AutoShoot = vape.Categories.Utility:CreateModule({
	Name = 'AutoShoot',
		Function = function(callback)
			if callback then
			-- Each pass is isolated. This loop IS the module: if anything inside it throws,
			-- the thread dies and AutoShoot sits there lit in the menu and inert until it is
			-- toggled off and on, with nothing said about why. A bad pass now costs one shot.
			local reported = false
			local function pass()
					if entitylib.isAlive and store.hand.toolType == 'sword' and (tick() - bedwars.SwordController.lastSwing) < 0.2 then
						local hotbar = store.hand.tool and getHotbar(store.hand.tool) or nil
							for _, data in getProjectiles() do
							local item, ammo, projectile, itemMeta = unpack(data)
							if (FireDelays[item.itemType] or 0) < tick() then
								local ent = getEntity()
								local slot = getHotbar(item.tool)
								-- hotbarSwitch reports whether it had to move, not whether the
								-- projectile is now in hand, so a projectile that was already the
								-- selected slot read as a failure and the shot was dropped. Gate on
								-- the slot existing instead, and switch only when it is not current.
								if (not Check.Enabled or ent) and slot then
									hotbarSwitch(slot)
									pcall(function()
										bedwars.Client:Get('TridentUnanchor'):SendToServer()
									end)
									local meta = bedwars.ProjectileMeta[projectile]
									local projSpeed, gravity = meta.launchVelocity or 100, meta.gravitationalAcceleration or 196.2
									-- SolveTrajectory takes (origin, speed, projectileGravity,
									-- targetPosition, targetVelocity, playerGravity, playerHeight,
									-- playerJump, params, iterations, ping). This used to pass
									-- fourteen arguments: a boolean landed in `iterations` and a
									-- Vector3 in `ping`, and both go through math.clamp, so it
									-- threw on every single shot. Nothing catches that here, so
									-- the error killed the module's own loop thread - AutoShoot
									-- stayed lit in the menu and never fired again until it was
									-- toggled off and on, which is exactly what "AutoShoot doesn't
									-- work" was.
									rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera}
									local calc = ent and prediction.SolveTrajectory(
										entitylib.character.RootPart.Position,
										projSpeed,
										gravity,
										ent.RootPart.Position,
										ent.RootPart.AssemblyLinearVelocity,
										workspace.Gravity,
										ent.HipHeight,
										ent.Jumping and 42.6 or nil,
										rayCheck,
										nil,
										lplr:GetNetworkPing()
									) or nil
									-- With Target check off there is no entity to solve against, and
									-- a solve can fail even with one, so `calc` was nil and the shot
									-- was silently dropped every time - the module switched to the
									-- projectile, fired nothing and switched back. Fall back to the
									-- direction the camera is pointing so there is always a shot.
									if not calc then
										local origin = entitylib.character.RootPart.Position
										calc = origin + (gameCamera.CFrame.LookVector * 100)
									end
									if calc then
										local shootPosition = (CFrame.new(entitylib.character.RootPart.Position, calc) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ))).Position
										local dir, id = CFrame.lookAt(shootPosition, calc).LookVector, httpService:GenerateGUID(true)
										bedwars.ProjectileController:createLocalProjectile(meta, ammo, projectile, shootPosition, id, dir * projSpeed, {drawDurationSeconds = 1})
										bedwars.Client:Get(remotes.FireProjectile):CallServerAsync(
											item.tool,
											ammo,
											projectile,
											shootPosition,
											entitylib.character.RootPart.Position,
											dir * projSpeed,
											id,
											{
												drawDurationSeconds = 1,
												shotId = httpService:GenerateGUID(false),
											},
											workspace:GetServerTimeNow() - 0.045
										):andThen(function(res)
											if res then
												res.Parent = replicatedStorage
									end
										end)
										FireDelays[item.itemType] = tick() + (itemMeta.fireDelaySec + FireRate:GetRandomValue())
										task.wait(SwitchDelay.Value)
								end
							end
						end
					end
						hotbarSwitch(hotbar)
				end
			end
			repeat
				local ok, err = pcall(pass)
				if not ok and not reported then
					reported = true
					warn('[AetherV2] AutoShoot: '..tostring(err))
				end
				task.wait(0.1)
			until not AutoShoot.Enabled
			end
	end,
		Tooltip = 'Automatically crossbow macro\'s'
    })

	Targets = AutoShoot:CreateTargets({Players = true})
	Range = AutoShoot:CreateSlider({
		Name = 'Range',
		Min = 5,
		Max = 60,
		Default = 22,
		Suffix = ' studs',
		Tooltip = 'How far a target can be and still count for Target check. Was fixed at 22 studs'
	})
    Check = AutoShoot:CreateToggle({
		Name = 'Target check',
	Default = true,
	Function = function(callback)
			if Targets.Object then
		Targets.Object.Visible = callback
	end
	end
    })
    Projectiles = AutoShoot:CreateTextList({
	Name = 'Projectiles',
		Default = {'arrow', 'snowball'}
    })
	FireRate = AutoShoot:CreateTwoSlider({
	Name = 'Fire Rate',
	Min = 0,
	Max = 1,
	DefaultMin = 0.05,
	DefaultMax = 0.12,
	Decimal = 100
    })
	SwitchDelay = AutoShoot:CreateSlider({
		Name = 'Switch Delay',
	Min = 0,
	Max = 1,
	Decimal = 100,
	Suffix = 'seconds',
		Default = 0.02
    })
end)
run(function()
    local AutoToxic
    local GG
    local Delay
    local TrollTriggers
    local trollCooldown = 0
    local Toggles, Lists, said, dead = {}, {}, {}

    -- Actually push a line to chat. Split out so both the message picker below and
    -- the match-end "gg" can share the Delay slider: when Delay > 0 the send is
    -- deferred that many seconds (the message is still chosen now, so the
    -- no-repeat logic is unaffected).
    local function doSend(text)
        if not text or text == '' then return end
        local wait = Delay and Delay.Value or 0
        local function push()
            if textChatService.ChatVersion == Enum.ChatVersion.TextChatService then
                textChatService.ChatInputBarConfiguration.TargetTextChannel:SendAsync(text)
            else
                replicatedStorage.DefaultChatSystemChatEvents.SayMessageRequest:FireServer(text, 'All')
            end
        end
        if wait > 0 then
            task.delay(wait, function() pcall(push) end)
        else
            push()
        end
    end

    local function sendMessage(name, obj, default)
        local tab = Lists[name].ListEnabled
        local custommsg = #tab > 0 and tab[math.random(1, #tab)] or default
        if not custommsg then return end
        if #tab > 1 and custommsg == said[name] then
            repeat
                task.wait()
                custommsg = tab[math.random(1, #tab)]
            until custommsg ~= said[name]
        end
        said[name] = custommsg

        custommsg = custommsg and custommsg:gsub('<obj>', obj or '') or ''
        doSend(custommsg)
    end

    AutoToxic = vape.Categories.Utility:CreateModule({
        Name = 'AutoToxic',
        Function = function(callback)
            if callback then
                AutoToxic:Clean(vapeEvents.BedwarsBedBreak.Event:Connect(function(bedTable)
                    if Toggles.BedDestroyed.Enabled and bedTable.brokenBedTeam.id == lplr:GetAttribute('Team') then
                        sendMessage('BedDestroyed', (bedTable.player.DisplayName or bedTable.player.Name), 'how dare you >:( | <obj>')
                    elseif Toggles.Bed.Enabled and bedTable.player.UserId == lplr.UserId then
                        local team = bedwars.QueueMeta[store.queueType].teams[tonumber(bedTable.brokenBedTeam.id)]
                        sendMessage('Bed', team and team.displayName:lower() or 'white', 'nice bed lul | <obj>')
                    end
                end))
                AutoToxic:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(deathTable)
                    if deathTable.finalKill then
                        local killer = playersService:GetPlayerFromCharacter(deathTable.fromEntity)
                        local killed = playersService:GetPlayerFromCharacter(deathTable.entityInstance)
                        if not killed or not killer then return end
                        if killed == lplr then
                            if (not dead) and killer ~= lplr and Toggles.Death.Enabled then
                                dead = true
                                sendMessage('Death', (killer.DisplayName or killer.Name), 'my gaming chair subscription expired :( | <obj>')
                            end
                        elseif killer == lplr and Toggles.Kill.Enabled then
                            sendMessage('Kill', (killed.DisplayName or killed.Name), 'vxp on top | <obj>')
                        end
                    end
                end))
                AutoToxic:Clean(vapeEvents.MatchEndEvent.Event:Connect(function(winstuff)
                    if GG.Enabled then
                        doSend('gg')
                    end

                    local myTeam = bedwars.Store:getState().Game.myTeam
                    if myTeam and myTeam.id == winstuff.winningTeamId or lplr.Neutral then
                        if Toggles.Win.Enabled then
                            sendMessage('Win', nil, 'yall garbage')
                        end
                    end
                end))

                -- Troll: watch incoming chat and clap back when another player calls you
                -- a hacker/cheater (or any configured trigger phrase). A short cooldown
                -- stops it spamming when several people pile on at once.
                local function handleIncoming(speakerName, text, speakerUserId)
                    if not (Toggles.Troll and Toggles.Troll.Enabled) or not text or text == '' then return end
                    if speakerUserId and speakerUserId == lplr.UserId then return end
                    if speakerName and speakerName == lplr.Name then return end
                    if tick() < trollCooldown then return end
                    local lower = text:lower()
                    for _, phrase in TrollTriggers.ListEnabled do
                        if phrase ~= '' and lower:find(phrase:lower(), 1, true) then
                            trollCooldown = tick() + 6
                            task.spawn(sendMessage, 'Troll', speakerName, 'mad cause bad | <obj>')
                            break
                        end
                    end
                end

                if textChatService.ChatVersion == Enum.ChatVersion.TextChatService then
                    AutoToxic:Clean(textChatService.MessageReceived:Connect(function(message)
                        local src = message.TextSource
                        handleIncoming(src and src.Name, message.Text, src and src.UserId)
                    end))
                else
                    AutoToxic:Clean(replicatedStorage.DefaultChatSystemChatEvents.OnMessageDoneFiltering.OnClientEvent:Connect(function(data)
                        if type(data) == 'table' then
                            handleIncoming(data.FromSpeaker, data.Message, nil)
                        end
                    end))
                end
            end
        end,
        Tooltip = 'Says a message after a certain action'
    })
    GG = AutoToxic:CreateToggle({
        Name = 'AutoGG',
        Default = true
    })
    Delay = AutoToxic:CreateSlider({
        Name = 'Delay',
        Min = 0,
        Max = 10,
        Default = 0,
        Decimal = 10,
        Suffix = 's',
        Tooltip = 'How long to wait after the triggering action before sending, 0 for instant'
    })
    for _, v in {'Kill', 'Death', 'Bed', 'BedDestroyed', 'Win'} do
        Toggles[v] = AutoToxic:CreateToggle({
            Name = v..' ',
            Function = function(callback)
                if Lists[v] then
                    Lists[v].Object.Visible = callback
                end
            end
        })
        Lists[v] = AutoToxic:CreateTextList({
            Name = v,
            Darker = true,
            Visible = false
        })
    end
    Toggles.Troll = AutoToxic:CreateToggle({
        Name = 'Troll ',
        Tooltip = 'Detects when someone calls you a hacker/cheater in chat and automatically replies',
        Function = function(callback)
            if TrollTriggers then TrollTriggers.Object.Visible = callback end
            if Lists.Troll then Lists.Troll.Object.Visible = callback end
        end
    })
    TrollTriggers = AutoToxic:CreateTextList({
        Name = 'Troll Triggers',
        Tooltip = 'Phrases said by others that trigger a reply (matched anywhere in their message)',
        Default = {'hacker', 'hacks', 'hacking', 'hax', 'cheater', 'cheating', 'cheat', 'exploiter', 'exploiting', 'aimbot'},
        Darker = true,
        Visible = false
    })
    Lists.Troll = AutoToxic:CreateTextList({
        Name = 'Troll Replies',
        Tooltip = 'Replies to send. <obj> is replaced with the accuser\'s name',
        Default = {'mad cause bad | <obj>', 'skill issue <obj>', 'cry about it <obj>', 'not my fault youre bad', 'imagine losing to a "hacker" lol'},
        Darker = true,
        Visible = false
    })
end)

run(function()
    local AutoVoidDrop
    local OwlCheck
    local PearlCheck

    local pearlRay = RaycastParams.new()
    pearlRay.RespectCanCollide = true
    pearlRay.FilterType = Enum.RaycastFilterType.Exclude

    -- Where a telepearl we threw is going to put us. The arc is walked forward in short steps
    -- with a cast between each pair, so the first thing it would hit is the landing. Estimated,
    -- not exact - it only has to answer "is there ground at the end of this", which is the
    -- difference between saving the loot and throwing it into the void for nothing.
    local function pearlLandsOnGround(pearl, lowestpoint)
        local position = pearl.Position
        local velocity = pearl.AssemblyLinearVelocity
        -- A pearl carried by a controller rather than by physics reports no velocity, and there
        -- is nothing to project from. Unknown counts as "keep the loot".
        if velocity.Magnitude < 1 then return true end

        local meta = bedwars.ProjectileMeta.telepearl
        local gravity = (meta and meta.gravitationalAcceleration) or workspace.Gravity
        pearlRay.FilterDescendantsInstances = {lplr.Character, gameCamera, pearl}

        local step = 0.05
        for _ = 1, 120 do
            local nextPosition = position + (velocity * step)
            local result = workspace:Raycast(position, nextPosition - position, pearlRay)
            if result then
                return result.Position.Y > lowestpoint
            end
            if nextPosition.Y < lowestpoint then return false end
            position = nextPosition
            velocity -= Vector3.new(0, gravity * step, 0)
        end
        -- Still airborne after six seconds: no landing found, so it is not saving us.
        return false
    end

    local function pearlWillSave(lowestpoint)
        for _, projectile in store.selfProjectiles do
            if projectile.Parent and projectile.Name == 'telepearl' and pearlLandsOnGround(projectile, lowestpoint) then
                return true
            end
        end
        return false
    end

    AutoVoidDrop = vape.Categories.Utility:CreateModule({
        Name = 'AutoVoidDrop',
        Function = function(callback)
            if callback then
                repeat task.wait() until store.matchState ~= 0 or (not AutoVoidDrop.Enabled)
                if not AutoVoidDrop.Enabled then return end

                local lowestpoint = math.huge
                for _, v in store.blocks do
                    local point = (v.Position.Y - (v.Size.Y / 2)) - 50
                    if point < lowestpoint then
                        lowestpoint = point
                    end
                end

                repeat
                    if entitylib.isAlive then
                        local root = entitylib.character.RootPart
                        if root.Position.Y < lowestpoint and (lplr.Character:GetAttribute('InflatedBalloons') or 0) <= 0 and not getItem('balloon') then
                            local saved = OwlCheck.Enabled and root:FindFirstChild('OwlLiftForce')
                                or (PearlCheck.Enabled and pearlWillSave(lowestpoint))
                            if not saved then
                                for _, item in {'iron', 'diamond', 'emerald', 'gold'} do
                                    item = getItem(item)
                                    if item then
                                        item = bedwars.Client:Get(remotes.DropItem):CallServer({
                                            item = item.tool,
                                            amount = item.amount
                                        })

                                        if item then
                                            item:SetAttribute('ClientDropTime', tick() + 100)
                                        end
                                    end
                                end
                            end
                        end
                    end

                    task.wait(0.1)
                until not AutoVoidDrop.Enabled
            end
        end,
        Tooltip = 'Drops resources when you fall into the void'
    })
    OwlCheck = AutoVoidDrop:CreateToggle({
        Name = 'Owl check',
        Default = true,
        Tooltip = 'Refuses to drop items if being picked up by an owl'
    })
    PearlCheck = AutoVoidDrop:CreateToggle({
        Name = 'Pearl check',
        Default = true,
        Tooltip = 'Keeps your loot if a telepearl you threw is still in the air and looks like it lands on ground'
    })
end)

run(function()
    local BackTrack
    local Mode
    local Latency
    local Tick

    BackTrack = vape.Categories.Utility:CreateModule({
        Name = 'BackTrack',
        Function = function(callback)
            if callback then
                repeat
                    local ent = entitylib.EntityPosition({
                        Part = 'RootPart',
                        Range = 22,
                        Players = true,
                        Wallcheck = true,
                    })

                    if ent then
                        if Mode.Value == 'Manual' then
                            setfflag('TargetTimeDelayFacctorTenths', '50000')
                            task.wait(0.05 * Tick.Value)
                            setfflag('TargetTimeDelayFacctorTenths', '20')
                            task.wait(0.05 * Tick.Value)
                        else
                            setfflag('TargetTimeDelayFacctorTenths', tostring(math.floor(20 + (Latency:GetRandomValue() / 20))))
                            task.wait(1)
                        end
                    else
                        setfflag('TargetTimeDelayFacctorTenths', '20')
                    end
                    task.wait()
                until not BackTrack.Enabled
            end
        end,
        Tooltip = 'Lags targets at certain times to increase attack distance'
    })
    getgenv().Backtrack = BackTrack
    Latency = BackTrack:CreateTwoSlider({
        Name = 'Latency',
        Min = 1,
        Max = 500,
        DefaultMin = 50,
        DefaultMax = 120,
        Darker = true,
    })
    Tick = BackTrack:CreateSlider({
        Name = 'Ticks',
        Min = 1,
        Max = 20,
        Default = 5,
        Darker = true,
        Visible = false,
    })
    Mode = BackTrack:CreateDropdown({
        Name = 'Mode',
        List = { 'Manual', 'Lag Based' },
        Default = 'Manual',
        Function = function(val)
            if Latency and Tick then
                Latency.Object.Visible = val == 'Manual'
                Tick.Object.Visible = val == 'Lag Based'
            end
        end,
    })
end)

run(function()
    -- CheatDetector
    --
    -- Everything here is measured through our own connection, which is the whole problem: what we
    -- see is a lagged, interpolated copy of what the server actually resolved. So every check is
    -- built the same way - a reading only counts when it is impossible rather than merely
    -- surprising, readings taken through bad conditions are thrown away instead of counted, and
    -- nobody is flagged until several independent readings of the same kind have stacked up.
    --
    -- Nothing here looks at what anybody is RUNNING. There is no module list, no remote name and
    -- no signature to keep up to date - every check reads position, timing and replicated state,
    -- which is all a cheat can never hide, because the whole point of a cheat is that the server
    -- and everyone else can see what it did.
    --
    -- One loop does all the polling. Each position-based check is a function fed the same
    -- once-per-tick snapshot of every player rather than its own thread walking the entity list,
    -- so the cost of the module is one pass over the players every tenth of a second no matter
    -- how many checks are ticked on.
    local CheatDetector
    local Toggles = {}

    -- Detections, in the order they are offered. A group with children is a heading: its own
    -- toggle gates the whole family, and the children pick which of them run.
    local GROUPS = {
        {Name = 'Impossible hits', Children = {'Killaura', 'SilentAim', 'HitBoxes', 'Reach'}},
        {Name = 'Blatant modules', Children = {'PlayerAttach', 'AntiDeath', 'Phase', 'Invisible', 'HighJump', 'Speed'}},
        {Name = 'AutoKit'},
        {Name = 'Crashers', Children = {'Animation', 'Remote'}},
        {Name = 'Breaker'},
        {Name = 'ProjectileAimbot and Aura'}
    }

    -- Off by default, and deliberately named so nobody leaves it on by accident. Every check below
    -- is written to read somebody else's replicated state, and the local player is normally exempt
    -- from all of them; this lifts that exemption so the detector measures us too. It changes who
    -- is looked at and nothing else - the checks still read behaviour, never which of our own
    -- modules happen to be on, so a flag here means the cheat was actually visible from outside.
    local DETECT_SELF = '[TEST] Detect self'

    -- How often every position-based check gets its sample.
    local POLL_INTERVAL = 0.1
    -- A strike older than this is forgotten. Long enough that a cheat running all match keeps
    -- stacking up, short enough that unrelated anomalies minutes apart never add together.
    local STRIKE_MEMORY = 45
    -- Nothing is measured through a connection worse than this. Above it, event timings and
    -- replicated positions are both fiction and every check would be reading noise. Our own
    -- behaviour is exempt: there is no network between us and our own character.
    local MAX_PING = 0.3
    -- A position step larger than this is streaming, a respawn or a real teleport, never movement.
    local TELEPORT_STEP = 100

    -- Speed. Sprint in this game is 20 studs/s and every legitimate way past that - a potion, a
    -- kit dash, a launch pad - is either a burst that decays within a second or announces itself
    -- through a status effect. So the limit is only a little over sprint, and what makes it safe
    -- is that it has to be HELD: the average has to stay over it across a continuous run of
    -- movement, which a dash, a pounce, a grapple or a knockback cannot do.
    local SPEED_LIMIT = 22
    local SPEED_WINDOW = 1.6
    -- No single sample above this is movement at all - it is a respawn, a streaming pop or a
    -- teleport that did not set the attribute. Counting one of those into a run is how a player
    -- who then simply sprints away gets flagged for it, so a sample this size ends the run.
    local SPEED_SANE = 60

    -- Reach. Every sword in the game swings 14.4 studs or less, so a hit landing past this is
    -- past the weapon whatever is being held. This is the one number that catches an aura built
    -- to fake its own position: the fake goes in the packet, but the body everyone else sees
    -- stays where it really is, and that is what gets measured here.
    local REACH_LIMIT = 15.5

    -- Killaura. No hand clicks faster than this, whatever the CPS cap says.
    local MIN_HUMAN_INTERVAL = 0.1
    -- An aura fires the instant the swing cooldown is up, every time, so the gaps between its
    -- hits stop varying. A hand saturating the same cooldown still scatters by tens of
    -- milliseconds, so the window is deliberately tighter than human jitter.
    local CADENCE_SAMPLES = 6
    local CADENCE_SPREAD = 0.03
    -- Sustained rate. A sword is on a cooldown near three tenths of a second, so even a hand
    -- that never misses and never stops cannot land four a second - which is where this sits,
    -- deliberately above the fastest legitimate weapon rather than at the pace of a fast mouse.
    local BURST_HITS, BURST_WINDOW = 10, 2.5
    -- Aura targeting: hitting this many different players inside the window means the aim moved
    -- between them instantly, which is the one signature clicking quickly cannot produce.
    local SWITCH_VICTIMS, SWITCH_WINDOW = 3, 1.2

    -- PlayerAttach. Riding somebody puts you inside arm's length of them and holds you there,
    -- with the separation barely moving, while the pair of you travel. Getting there is a jump
    -- no run can make.
    local ATTACH_RANGE = 3
    local ATTACH_SAMPLES = 10
    local ATTACH_TRAVEL = 6
    local ATTACH_JITTER = 1.2
    local ATTACH_JUMP = 12
    local ATTACH_RATE = 100

    -- AntiDeath. Parking the hitbox out of reach and bringing it back is a vertical step no fall
    -- produces: free fall tops out near 200 studs/s, so anything past this was set, not fallen.
    local VERTICAL_TELEPORT = 25
    local VERTICAL_RATE = 320
    local VERTICAL_REVERSALS, VERTICAL_MEMORY = 2, 3

    -- Crashers are floods, and the bar has to sit well above a player having a busy second -
    -- jumping while spamming a sword throws out a surprising number of both animations and
    -- replicated actions. These are per SECOND, not per three.
    local ANIMATION_FLOOD, ANIMATION_WINDOW = 30, 1
    local REMOTE_FLOOD, REMOTE_WINDOW = 45, 1

    -- How many readings of one kind before a player is flagged. Set per check rather than shared:
    -- a Reach reading is one clean measurement, a Phase reading is a guess about geometry we only
    -- half see, and they cannot sensibly share a threshold.
    local REQUIRED = {
        Killaura = 3,
        SilentAim = 4,
        HitBoxes = 4,
        Reach = 3,
        PlayerAttach = 2,
        AntiDeath = 2,
        Phase = 6,
        Invisible = 4,
        HighJump = 4,
        Speed = 3,
        AutoKit = 4,
        Animation = 3,
        Remote = 3,
        Breaker = 4,
        ProjectileAim = 4
    }

    local strikes = {}
    -- When each player last took a hit. Knockback throws people faster than they can run, so a
    -- speed sample taken just after one measures the hit, not the player.
    local lastHurt = {}

    local function enabled(name)
        local toggle = Toggles[name]
        return toggle ~= nil and toggle.Enabled == true
    end

    -- A child check runs only while its heading is on as well, so switching a family off switches
    -- off everything under it without disturbing which children were picked.
    local function checkEnabled(group, name)
        if not enabled(group) then return false end
        return group == name or enabled(name)
    end

    -- The one place the self exemption is decided. Checks ask this instead of comparing against
    -- lplr themselves, so the toggle reaches all of them at once and nothing is left half exempt.
    local function selfExcluded(plr)
        return plr == lplr and not enabled(DETECT_SELF)
    end

    -- entitylib keeps our own entity apart from the rest - entitylib.List is everyone but us - so a
    -- check that walks the list can never see the local player no matter what the guards say. This
    -- hands back that same list with our entity on the end while the toggle is on, which is what
    -- lets the polling checks read us without each of them knowing where our entity is kept.
    local function entities()
        if not enabled(DETECT_SELF) or not entitylib.isAlive or not entitylib.character then
            return entitylib.List
        end
        local list = table.clone(entitylib.List)
        table.insert(list, entitylib.character)
        return list
    end

    local function strikeCount(plr, reason)
        local perPlayer = strikes[plr]
        if not perPlayer then return 0 end
        local list = perPlayer[reason]
        if not list then return 0 end
        local now, count = tick(), 0
        for i = #list, 1, -1 do
            if now - list[i] > STRIKE_MEMORY then
                table.remove(list, i)
            else
                count += 1
            end
        end
        return count
    end

    local function Added(player, reason, detail)
        if not CheatersFlagged[player] then
            CheatersFlagged[player] = true
            whitelist.customtags[player.Name] = {{text = 'CHEATER', color = Color3.new(1, 0, 0)}}
            -- Say what was actually measured, not just which check fired. A flag you cannot
            -- sanity-check yourself is a flag you have to take on trust.
            notif('CheatDetector', `{player.Name} flagged for {reason:lower()}{detail and ' ('..detail..')' or ''}`, 10, 'alert')
        end
    end

    -- One reading is an oddity, several is a pattern. Nothing reaches Added until the pattern is
    -- there, at whatever count this particular check needs to be worth trusting.
    local function strike(plr, reason, label, detail)
        if not plr or selfExcluded(plr) or CheatersFlagged[plr] then return end
        strikes[plr] = strikes[plr] or {}
        strikes[plr][reason] = strikes[plr][reason] or {}
        table.insert(strikes[plr][reason], tick())
        if strikeCount(plr, reason) >= (REQUIRED[reason] or 5) then
            Added(plr, label or reason, detail)
        end
    end

    local function ping()
        local value = 0
        pcall(function()
            value = lplr:GetNetworkPing()
        end)
        return value
    end

    -- Our own connection is the measuring instrument. When it is bad, every reading of somebody
    -- else is wrong in a direction that produces false positives, so we take none at all. Nothing
    -- sits between us and our own character, so measuring ourselves is always allowed.
    local function conditionsUsable(plr)
        if plr == lplr then return true end
        return ping() <= MAX_PING
    end

    local function recentlyTeleported(plr)
        return (workspace:GetServerTimeNow() - (plr:GetAttribute('LastTeleported') or 0)) <= 1
    end

    ------------------------------------------------------------------------
    -- Status effects.
    ------------------------------------------------------------------------
    -- Kits are the reason speed and jump checks need this. A kit that is MEANT to move you fast -
    -- a reaper's drift, a dash, a wind push - replicates a status attribute onto the character
    -- while it is doing it, so the sample is thrown away rather than counted. Matched on what the
    -- effect is called rather than on a list of kits, so a kit added next update is covered by
    -- the words it uses, and a kit renamed does not quietly become undetectable.
    local EFFECT_WORDS = {
        Movement = {'speed', 'dash', 'sprint', 'haste', 'boost', 'launch', 'grapple', 'balloon', 'wind', 'momentum', 'charge', 'rush', 'swift', 'leap', 'pounce', 'slide', 'drift', 'frenzy'},
        Vertical = {'jump', 'launch', 'bounce', 'pad', 'grapple', 'balloon', 'levitat', 'fly', 'wind', 'rocket', 'leap', 'pounce'},
        Invisible = {'invis', 'vanish', 'cloak', 'ghost'},
        Ability = {'ability', 'kit_', 'kitability', 'cooldown'}
    }

    -- One pass over a character's attributes per tick, producing every flag the checks want.
    -- Reading them separately meant walking the same attribute table three times a tick per
    -- player for answers that all come out of the same read.
    local function effectsOf(char)
        local flags = {}
        if not char then return flags end
        for name, value in char:GetAttributes() do
            if type(name) ~= 'string' or value == false or value == 0 then continue end
            local lowered = name:lower()
            for key, words in EFFECT_WORDS do
                if flags[key] then continue end
                for _, word in words do
                    if lowered:find(word, 1, true) then
                        flags[key] = true
                        break
                    end
                end
            end
        end
        return flags
    end

    local function weaponReach(plr)
        local inv = store.inventories[plr]
        local hand = inv and inv.hand
        -- The old check read hand.tool.Name, which is nil for anything the game hands over as a
        -- plain item rather than a Tool - so the reach fell back to the default for half the
        -- weapons in the game and flagged anyone holding a long one.
        local itemType = hand and (hand.itemType or (hand.tool and hand.tool.Name))
        local meta = itemType and bedwars.ItemMeta[itemType]
        local sword = meta and meta.sword
        return (sword and sword.attackRange or 14.4)
    end

    -- Lowest solid ground anywhere on the map, minus a margin. Below this is the void, and nothing
    -- alive belongs there. Recomputed on a timer rather than per sample: it walks every block on
    -- the map, and the floor of the world does not move between ticks.
    local voidCached, voidStamp = -300, 0
    local function voidLevel()
        local now = os.clock()
        if now - voidStamp < 5 then return voidCached end
        voidStamp = now
        local lowest = math.huge
        for _, v in store.blocks do
            local point = (v.Position.Y - (v.Size.Y / 2)) - 50
            if point < lowest then
                lowest = point
            end
        end
        voidCached = lowest < math.huge and lowest or -300
        return voidCached
    end

    -- What the game itself says a kit's movement is worth. Read out of the kit metadata rather
    -- than from a list of kit names: a kit added, renamed or rebalanced next update is covered by
    -- whatever its own meta says about itself, and there is nothing here to keep up to date. Any
    -- move-speed multiplier the meta declares raises that player's ceiling by the same
    -- proportion, so a kit whose whole point is moving fast is never flagged for moving fast.
    local kitCeilings = {}
    local function speedCeiling(plr)
        local kit = plr:GetAttribute('PlayingAsKits') or plr:GetAttribute('PlayingAsKit')
        if type(kit) ~= 'string' or kit == '' or kit == 'none' then return SPEED_LIMIT end
        local cached = kitCeilings[kit]
        if cached then return cached end

        local multiplier = 1
        pcall(function()
            local meta = bedwars.BedwarsKitMeta and bedwars.BedwarsKitMeta[kit]
            if type(meta) ~= 'table' then return end
            local function scan(tab, depth)
                for key, value in tab do
                    if type(value) == 'number' and type(key) == 'string' then
                        local lowered = key:lower()
                        -- Only a movement multiplier, never a raw number and never a speed that
                        -- belongs to something else the kit throws.
                        if lowered:find('speed') and (lowered:find('multiplier') or lowered:find('move')) then
                            multiplier = math.max(multiplier, value)
                        end
                    elseif type(value) == 'table' and depth < 3 then
                        scan(value, depth + 1)
                    end
                end
            end
            scan(meta, 1)
        end)

        local ceiling = SPEED_LIMIT * math.clamp(multiplier, 1, 2)
        kitCeilings[kit] = ceiling
        return ceiling
    end

    -- Rolling counter shared by every rate-based check: record an event, get back how many landed
    -- inside `window`.
    local function bumpRate(store_, key, window)
        local list = store_[key]
        if not list then
            list = {}
            store_[key] = list
        end
        local now = os.clock()
        table.insert(list, now)
        for i = #list, 1, -1 do
            if now - list[i] > window then
                table.remove(list, i)
            end
        end
        return #list
    end

    ------------------------------------------------------------------------
    -- Animation watch, shared.
    ------------------------------------------------------------------------
    -- Two checks want the same fact from different angles: the crasher check wants how OFTEN a
    -- player starts animations, and killaura's packet signal wants whether they started one at
    -- all. One hook per character answers both.
    local animationLast, animationRates, animationHooked = {}, {}, {}
    -- How many hits anywhere in the match arrived with a swing behind them. Until the game has
    -- proven to us that it replicates swings at all, "no swing behind that hit" means nothing,
    -- and the packet signal stays switched off rather than flagging the entire lobby.
    local animationBacked = 0

    local function watchAnimations(list)
        for _, rec in list do
            local plr = rec.Player
            if animationHooked[plr] == rec.Character then continue end
            local humanoid = rec.Character:FindFirstChildOfClass('Humanoid')
            local animator = humanoid and humanoid:FindFirstChildOfClass('Animator')
            if not animator then continue end
            animationHooked[plr] = rec.Character
            CheatDetector:Clean(animator.AnimationPlayed:Connect(function()
                animationLast[plr] = os.clock()
                if not checkEnabled('Crashers', 'Animation') then return end
                if CheatersFlagged[plr] then return end
                if bumpRate(animationRates, plr, ANIMATION_WINDOW) >= ANIMATION_FLOOD then
                    animationRates[plr] = nil
                    strike(plr, 'Animation', 'animation spam', `{ANIMATION_FLOOD} animation starts inside {ANIMATION_WINDOW}s`)
                end
            end))
        end
    end

    -- Which heading each check belongs to, so a family can be switched off in one place.
    local CHECK_GROUP = {
        Killaura = 'Impossible hits',
        SilentAim = 'Impossible hits',
        HitBoxes = 'Impossible hits',
        Reach = 'Impossible hits',
        PlayerAttach = 'Blatant modules',
        AntiDeath = 'Blatant modules',
        Phase = 'Blatant modules',
        Invisible = 'Blatant modules',
        HighJump = 'Blatant modules',
        Speed = 'Blatant modules',
        AutoKit = 'AutoKit',
        Animation = 'Crashers',
        Remote = 'Crashers',
        Breaker = 'Breaker',
        ProjectileAim = 'ProjectileAimbot and Aura'
    }
    -- The checks whose toggle name is the heading itself.
    local CHECK_TOGGLE = {
        AutoKit = 'AutoKit',
        Breaker = 'Breaker',
        ProjectileAim = 'ProjectileAimbot and Aura'
    }

    local function wanted(name)
        local group = CHECK_GROUP[name]
        return group ~= nil and checkEnabled(group, CHECK_TOGGLE[name] or name)
    end

    ------------------------------------------------------------------------
    -- Polling checks.
    ------------------------------------------------------------------------
    -- Each entry is a factory: it is called once when the module starts and hands back the
    -- function that runs against every snapshot, so all of a check's state is private to one
    -- run of the module and starts empty on the next.
    local Pollers = {}

    ------------------------------------------------------------------------
    -- Speed.
    ------------------------------------------------------------------------
    -- Not "how fast was that one step" - a knockback, a dash and a bad interpolation all answer
    -- that loudly. This measures a continuous run: distance actually covered over the time it
    -- took, with the run reset the moment anything makes a sample untrustworthy (a buff, a
    -- teleport, a hit taken, leaving the ground, or simply slowing down). What is left is speed
    -- that was HELD, which is the difference between a kit ability and a speed hack.
    Pollers.Speed = function()
        local tracks = {}
        return function(now, list)
            local seen = {}
            for _, rec in list do
                local plr = rec.Player
                seen[plr] = true
                local track = tracks[plr]
                -- A respawn is a new character in the same player's name, and the position it
                -- starts at has nothing to do with the one the last one died at.
                if not track or track.Character ~= rec.Character then
                    tracks[plr] = {Character = rec.Character, Ceiling = speedCeiling(plr), Position = rec.Flat, Time = now, Distance = 0, Start = now, Samples = 0, Above = 0}
                    continue
                end
                local ceiling = track.Ceiling or SPEED_LIMIT

                local delta = now - track.Time
                local step = (rec.Flat - track.Position).Magnitude
                track.Position, track.Time = rec.Flat, now

                local usable = delta >= 0.05 and delta <= 0.5
                    and step <= TELEPORT_STEP
                    and (step / delta) <= SPEED_SANE
                    and not rec.Teleported
                    and not rec.Effects.Movement
                    and not rec.Hurt
                    and math.abs(rec.Velocity.Y) < 14
                    -- Sprint pace keeps a run alive, anything below it ends the run. That is
                    -- deliberately generous: a kit dash decays into a sprint rather than a stop,
                    -- so the sprinting that follows stays in the window and drags the average
                    -- back under the limit, while a hack that simply holds one speed does not.
                    and (step / delta) > (ceiling * 0.85)
                if not usable then
                    track.Distance, track.Start, track.Samples, track.Above = 0, now, 0, 0
                    continue
                end

                track.Distance += step
                track.Samples += 1
                if (step / delta) > ceiling then
                    track.Above += 1
                end

                local span = now - track.Start
                if span >= SPEED_WINDOW and track.Samples >= 8 then
                    local average = track.Distance / span
                    local share = track.Above / track.Samples
                    track.Distance, track.Start, track.Samples, track.Above = 0, now, 0, 0
                    -- Both, and the second one is what keeps kits out of this. A dash, a pounce or
                    -- a wind push is a spike that decays: most of the window sits at running pace
                    -- even when the average of it is dragged over the limit. A hack holds one
                    -- speed, so nearly every sample in its window is over on its own.
                    if average > ceiling and share >= 0.7 then
                        strike(plr, 'Speed', 'speeding', `{math.floor(average)} studs/s held for {math.floor(span * 10) / 10}s, ceiling {math.floor(ceiling)}`)
                    end
                end
            end
            for plr in tracks do
                if not seen[plr] then tracks[plr] = nil end
            end
        end
    end

    ------------------------------------------------------------------------
    -- PlayerAttach.
    ------------------------------------------------------------------------
    -- Two halves of the same behaviour, either of which is enough on its own. Getting there: a
    -- position step no run can make, landing on top of somebody. Staying there: held inside arm's
    -- length of one player while the pair actually travel, with the separation barely changing -
    -- two players who merely happen to be close bob around each other by whole studs.
    Pollers.PlayerAttach = function()
        local held, previous = {}, {}
        return function(now, list, delta)
            local seen = {}
            for _, rec in list do
                local plr, position = rec.Player, rec.Position
                seen[plr] = true
                local last = previous[plr]
                -- Same player, different body: the step from where they died to where they
                -- respawned is not a step they took.
                local before = last and last.Character == rec.Character and last.Position or nil
                previous[plr] = {Character = rec.Character, Position = position}

                local nearest, nearestPlr = math.huge, nil
                for _, other in list do
                    if other.Player == plr then continue end
                    local separation = (position - other.Position).Magnitude
                    if separation < nearest then
                        nearest, nearestPlr = separation, other.Player
                    end
                end
                if not nearestPlr then
                    held[plr] = nil
                    continue
                end

                local step = before and (position - before).Magnitude or 0
                -- Rate, not raw distance: a poll stretched by a lag spike covers plenty of ground
                -- at a run, and calling that a teleport would flag whoever was standing nearby.
                local rate = delta > 0 and (step / delta) or 0
                if before and step > ATTACH_JUMP and rate > ATTACH_RATE and step <= TELEPORT_STEP and nearest <= ATTACH_RANGE * 2 and not rec.Teleported then
                    strike(plr, 'PlayerAttach', 'player attach', `{math.floor(step)} studs onto {nearestPlr.Name} in one step`)
                end

                if nearest > ATTACH_RANGE then
                    held[plr] = nil
                    continue
                end

                local entry = held[plr]
                if not entry or entry.Target ~= nearestPlr then
                    entry = {Target = nearestPlr, Count = 0, Travel = 0, Min = nearest, Max = nearest}
                    held[plr] = entry
                end
                entry.Count += 1
                entry.Travel += step
                entry.Min = math.min(entry.Min, nearest)
                entry.Max = math.max(entry.Max, nearest)
                if entry.Count >= ATTACH_SAMPLES and entry.Travel > ATTACH_TRAVEL and (entry.Max - entry.Min) < ATTACH_JITTER then
                    held[plr] = nil
                    strike(plr, 'PlayerAttach', 'player attach', `rode {nearestPlr.Name} at {math.floor(nearest * 10) / 10} studs`)
                end
            end
            for plr in held do
                if not seen[plr] then held[plr] = nil end
            end
            for plr in previous do
                if not seen[plr] then previous[plr] = nil end
            end
        end
    end

    ------------------------------------------------------------------------
    -- AntiDeath.
    ------------------------------------------------------------------------
    -- The hitbox taken somewhere nothing can reach it and brought straight back. Both halves are
    -- read: alive and holding a position below every block on the map, and the vertical step
    -- itself - dropped and returned faster than gravity can move anything, over and over, which
    -- is what parking a hitbox out of a fight and putting it back looks like from outside.
    Pollers.AntiDeath = function()
        local tracks = {}
        return function(now, list, delta)
            local floor = voidLevel()
            local seen = {}
            for _, rec in list do
                local plr, position = rec.Player, rec.Position
                seen[plr] = true
                local track = tracks[plr]
                if not track or track.Character ~= rec.Character then
                    tracks[plr] = {Character = rec.Character, Y = position.Y, Flat = rec.Flat, Below = 0, Direction = 0, Reversals = {}}
                    continue
                end

                local rise = position.Y - track.Y
                local flatStep = (rec.Flat - track.Flat).Magnitude
                track.Y, track.Flat = position.Y, rec.Flat

                if position.Y < floor and not rec.Teleported then
                    track.Below += 1
                    -- Held there rather than passing through: a real fall into the void ends in a
                    -- death within a second or so.
                    if track.Below >= 3 then
                        track.Below = 0
                        strike(plr, 'AntiDeath', 'anti death', `alive {math.floor(floor - position.Y)} studs below the map`)
                    end
                else
                    track.Below = 0
                end

                if rec.Teleported or delta <= 0 then continue end
                -- Straight up or straight down, faster than free fall, with the body barely
                -- moving sideways. Nothing physical does this.
                if math.abs(rise) < VERTICAL_TELEPORT or (math.abs(rise) / delta) < VERTICAL_RATE or flatStep > 15 then continue end

                local direction = rise > 0 and 1 or -1
                if track.Direction ~= 0 and direction ~= track.Direction then
                    table.insert(track.Reversals, now)
                end
                track.Direction = direction
                for i = #track.Reversals, 1, -1 do
                    if now - track.Reversals[i] > VERTICAL_MEMORY then
                        table.remove(track.Reversals, i)
                    end
                end
                if #track.Reversals >= VERTICAL_REVERSALS then
                    table.clear(track.Reversals)
                    track.Direction = 0
                    strike(plr, 'AntiDeath', 'anti death', `hitbox thrown {math.floor(math.abs(rise))} studs up and down`)
                end
            end
            for plr in tracks do
                if not seen[plr] then tracks[plr] = nil end
            end
        end
    end

    ------------------------------------------------------------------------
    -- Phase.
    ------------------------------------------------------------------------
    -- Standing inside solid geometry. Every part of this is arguable on its own - a body clips a
    -- block on a slope, streaming puts a block in late - so the reading needs the root buried in
    -- something solid across consecutive samples while the player is not being carried by
    -- anything, and it needs the most readings of any check before it flags. Sampled every third
    -- tick because it is the only check here that costs a spatial query.
    Pollers.Phase = function()
        local buried = {}
        local overlap = OverlapParams.new()
        overlap.FilterType = Enum.RaycastFilterType.Exclude
        local skip = 0
        return function(now, list)
            skip += 1
            if skip % 3 ~= 0 then return end
            local seen = {}
            for _, rec in list do
                local plr = rec.Player
                seen[plr] = true
                if rec.Teleported or rec.Effects.Movement then
                    buried[plr] = nil
                    continue
                end

                overlap.FilterDescendantsInstances = {rec.Character, lplr.Character, gameCamera}
                -- A box well inside the torso, so brushing a wall is not enough - the body has
                -- to be in the block.
                local parts = workspace:GetPartBoundsInBox(CFrame.new(rec.Position), Vector3.new(1, 1, 1), overlap)
                local solid = false
                for _, part in parts do
                    if part.CanCollide and part.Anchored then
                        solid = true
                        break
                    end
                end

                if solid then
                    buried[plr] = (buried[plr] or 0) + 1
                    if buried[plr] >= 4 then
                        buried[plr] = 0
                        strike(plr, 'Phase', 'phasing', 'stood inside a solid block')
                    end
                else
                    buried[plr] = nil
                end
            end
            for plr in buried do
                if not seen[plr] then buried[plr] = nil end
            end
        end
    end

    ------------------------------------------------------------------------
    -- Invisible.
    ------------------------------------------------------------------------
    -- Every limb fully transparent while the player is alive, moving and carrying no invisibility
    -- effect of their own. Movement is what separates this from a ragdoll or a death animation,
    -- and the status-effect check is what keeps the game's own invisibility potion out of it.
    Pollers.Invisible = function()
        local hidden = {}
        local skip = 0
        return function(now, list)
            -- Every fifth tick. Walking a character's whole descendant tree is the most expensive
            -- read in the module, and nobody turns invisible for a tenth of a second.
            skip += 1
            if skip % 5 ~= 0 then return end
            local seen = {}
            for _, rec in list do
                local plr = rec.Player
                seen[plr] = true
                if rec.Effects.Invisible or rec.Velocity.Magnitude < 4 then
                    hidden[plr] = nil
                    continue
                end

                local visible, counted = false, 0
                for _, part in rec.Character:GetDescendants() do
                    if part:IsA('BasePart') and part.Name ~= 'HumanoidRootPart' then
                        counted += 1
                        if part.Transparency < 0.95 then
                            visible = true
                            break
                        end
                    end
                end

                -- No limbs found at all means the character has not streamed in, which is not
                -- the same thing as being invisible.
                if counted >= 4 and not visible then
                    hidden[plr] = (hidden[plr] or 0) + 1
                    if hidden[plr] >= 3 then
                        hidden[plr] = 0
                        strike(plr, 'Invisible', 'invisibility', 'moving with every limb hidden')
                    end
                else
                    hidden[plr] = nil
                end
            end
            for plr in hidden do
                if not seen[plr] then hidden[plr] = nil end
            end
        end
    end

    ------------------------------------------------------------------------
    -- HighJump.
    ------------------------------------------------------------------------
    -- Rising further off one jump than the game's own jump power allows. Measured as a climb from
    -- a standing start rather than as an instantaneous velocity, because a launch pad or a
    -- knockback shows up in velocity and both of those are legitimate.
    Pollers.HighJump = function()
        local tracked = {}
        return function(now, list)
            local seen = {}
            for _, rec in list do
                local plr = rec.Player
                seen[plr] = true
                if rec.Teleported or rec.Effects.Vertical or rec.Hurt then
                    tracked[plr] = nil
                    continue
                end

                local y = rec.Position.Y
                local entry = tracked[plr]
                if rec.Grounded then
                    tracked[plr] = {Base = y, Peak = y}
                elseif entry then
                    entry.Peak = math.max(entry.Peak, y)
                    -- Roblox's own jump tops out near 7 studs, and BedWars kits that go higher
                    -- all announce themselves through a status effect, which is excluded above.
                    -- 18 is far past anything left.
                    if (entry.Peak - entry.Base) > 18 then
                        tracked[plr] = nil
                        strike(plr, 'HighJump', 'high jump', `rose {math.floor(entry.Peak - entry.Base)} studs off one jump`)
                    end
                end
            end
            for plr in tracked do
                if not seen[plr] then tracked[plr] = nil end
            end
        end
    end

    ------------------------------------------------------------------------
    -- AutoKit.
    ------------------------------------------------------------------------
    -- A kit ability is a cooldown, and a script fires it the instant it is up - every time. What
    -- gives it away is not the speed but the regularity: the gaps between activations stop
    -- varying. A hand cannot hold an interval to within a tenth of a second five times running.
    Pollers.AutoKit = function()
        local activations, previous = {}, {}
        return function(now, list)
            local seen = {}
            for _, rec in list do
                local plr = rec.Player
                seen[plr] = true
                local active = rec.Effects.Ability
                local was = previous[plr]
                previous[plr] = active
                if not active or was then continue end

                -- Rising edge: the ability just went off.
                local times = activations[plr]
                if not times then
                    times = {}
                    activations[plr] = times
                end
                table.insert(times, now)
                if #times > 6 then
                    table.remove(times, 1)
                end
                if #times < 6 then continue end

                local shortest, longest = math.huge, 0
                for i = 2, #times do
                    local gap = times[i] - times[i - 1]
                    shortest = math.min(shortest, gap)
                    longest = math.max(longest, gap)
                end
                -- Five gaps that agree to within a tenth of a second, and none of them long
                -- enough to be somebody simply playing at a steady pace.
                if (longest - shortest) < 0.1 and longest < 30 then
                    table.clear(times)
                    strike(plr, 'AutoKit', 'automated kit use', `5 activations {math.floor(longest * 100) / 100}s apart`)
                end
            end
            for plr in activations do
                if not seen[plr] then
                    activations[plr] = nil
                    previous[plr] = nil
                end
            end
        end
    end

    ------------------------------------------------------------------------
    -- Event-driven checks.
    ------------------------------------------------------------------------
    -- Same idea as the pollers: a factory called once at startup which puts its connections in
    -- place. Everything they need about a player is read at the moment of the event.
    local Events = {}

    ------------------------------------------------------------------------
    -- Killaura.
    ------------------------------------------------------------------------
    -- Four things an aura does that a hand does not, any one of which is a reading:
    --
    --   * hits closer together than anybody can click at all;
    --   * a cadence that does not vary, because the aura fires the moment the cooldown is up
    --     rather than whenever a finger happened to come down;
    --   * a run of hits held at a rate no hand sustains;
    --   * damage on several different people in the time it takes to turn to face one of them.
    --
    -- Plus the packet case: an aura that talks straight to the server does not swing anything,
    -- so the damage lands with no animation behind it. That one is only trusted once other
    -- players in the same match have proven that swings do reach us, so a game that simply does
    -- not replicate them cannot make the check flag everybody.
    Events.Killaura = function()
        local last, intervals, victims, hits, quiet = {}, {}, {}, {}, {}

        CheatDetector:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
            if not wanted('Killaura') then return end
            if damageTable.damageType ~= 0 or not damageTable.fromEntity then return end

            local from = playersService:GetPlayerFromCharacter(damageTable.fromEntity)
            if not from or selfExcluded(from) or CheatersFlagged[from] then return end
            if not conditionsUsable(from) then return end

            local victim = damageTable.entityInstance and playersService:GetPlayerFromCharacter(damageTable.entityInstance)
            local now = os.clock()

            -- Was there a swing behind this hit?
            if (now - (animationLast[from] or 0)) <= 0.4 then
                animationBacked += 1
                quiet[from] = 0
            elseif animationBacked >= 5 then
                quiet[from] = (quiet[from] or 0) + 1
                if quiet[from] >= 6 then
                    quiet[from] = 0
                    strike(from, 'Killaura', 'using killaura', '6 hits with no swing behind them')
                end
            end

            -- Several different people inside the time it takes to turn around.
            if victim then
                local seen = victims[from]
                if not seen then
                    seen = {}
                    victims[from] = seen
                end
                seen[victim] = now
                local distinct = 0
                for plr, stamp in seen do
                    if now - stamp > SWITCH_WINDOW then
                        seen[plr] = nil
                    else
                        distinct += 1
                    end
                end
                if distinct >= SWITCH_VICTIMS then
                    table.clear(seen)
                    strike(from, 'Killaura', 'using killaura', `{distinct} different targets inside {SWITCH_WINDOW}s`)
                end
            end

            local previous = last[from]
            last[from] = now
            if not previous then return end

            local interval = now - previous
            -- Two events delivered in the same frame were batched by the network, not thrown that
            -- fast. Reading a batch as a zero interval is how a check like this flags people who
            -- are simply being replicated to us in bursts.
            if interval <= 0.008 then return end

            if interval < MIN_HUMAN_INTERVAL then
                strike(from, 'Killaura', 'using killaura', `hits {math.floor(interval * 1000)}ms apart`)
                return
            end

            -- Held rate. Not one fast hit - a run of them.
            if bumpRate(hits, from, BURST_WINDOW) >= BURST_HITS then
                hits[from] = nil
                strike(from, 'Killaura', 'using killaura', `{BURST_HITS} hits inside {BURST_WINDOW}s`)
            end

            -- Cadence. Only gaps short enough to be a weapon on cooldown are considered: a run of
            -- evenly spaced hits seconds apart is somebody trading, not a machine.
            local run = intervals[from]
            if not run then
                run = {}
                intervals[from] = run
            end
            if interval > 0.6 then
                table.clear(run)
                return
            end
            table.insert(run, interval)
            if #run > CADENCE_SAMPLES then
                table.remove(run, 1)
            end
            if #run < CADENCE_SAMPLES then return end

            local shortest, longest = math.huge, 0
            for _, value in run do
                shortest = math.min(shortest, value)
                longest = math.max(longest, value)
            end
            if (longest - shortest) <= CADENCE_SPREAD then
                table.clear(run)
                strike(from, 'Killaura', 'using killaura', `{CADENCE_SAMPLES} hits {math.floor(shortest * 1000)}ms apart to the millisecond`)
            end
        end))
    end

    ------------------------------------------------------------------------
    -- Reach.
    ------------------------------------------------------------------------
    -- The measurement an aura cannot fake. It can put whatever position it likes in the packet it
    -- sends the server, but the body the rest of us see stays where the player really is, so the
    -- distance between the two characters at the moment damage lands is the honest one. Every
    -- sword in the game swings 14.4 studs or less; past 15.5 the hit came from somewhere the
    -- weapon does not reach.
    Events.Reach = function()
        CheatDetector:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
            if not wanted('Reach') then return end
            if damageTable.damageType ~= 0 or not damageTable.fromEntity or not damageTable.entityInstance then return end

            local attacker = playersService:GetPlayerFromCharacter(damageTable.fromEntity)
            if not attacker or selfExcluded(attacker) or CheatersFlagged[attacker] then return end
            if not conditionsUsable(attacker) or recentlyTeleported(attacker) then return end

            local fromRoot = damageTable.fromEntity.PrimaryPart
            local toRoot = damageTable.entityInstance.PrimaryPart
            if not fromRoot or not toRoot then return end

            local distance = (fromRoot.Position - toRoot.Position).Magnitude
            -- Ping converted into studs rather than added as seconds, and kept small: this is an
            -- allowance for our own view of two moving bodies, not for the weapon.
            local allowance = math.clamp(ping() * 20, 0, 3)
            local limit = math.max(weaponReach(attacker) + 1.1, REACH_LIMIT) + allowance

            if distance > limit then
                strike(attacker, 'Reach', 'using reach', `{math.floor(distance * 10) / 10} studs, limit {math.floor(limit * 10) / 10}`)
            end
        end))
    end

    ------------------------------------------------------------------------
    -- HitBoxes.
    ------------------------------------------------------------------------
    -- An expanded hitbox lives on the attacker's own client, so it is never visible from here
    -- directly. What it produces that a normal swing cannot is a hit landing while the attacker is
    -- facing well off the target: the swing resolved against a box far wider than the body. The
    -- distance has to be inside legitimate reach too, otherwise this is just Reach again and one
    -- swing would be counted twice.
    Events.HitBoxes = function()
        CheatDetector:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
            if not wanted('HitBoxes') then return end
            if damageTable.damageType ~= 0 or not damageTable.fromEntity or not damageTable.entityInstance then return end

            local attacker = playersService:GetPlayerFromCharacter(damageTable.fromEntity)
            if not attacker or selfExcluded(attacker) or CheatersFlagged[attacker] then return end
            if not conditionsUsable(attacker) or recentlyTeleported(attacker) then return end

            local fromRoot = damageTable.fromEntity.PrimaryPart
            local toRoot = damageTable.entityInstance.PrimaryPart
            if not fromRoot or not toRoot then return end

            local delta = (toRoot.Position - fromRoot.Position)
            local distance = delta.Magnitude
            -- Point blank the angle means nothing - the bodies overlap and any heading hits - and
            -- past the weapon's own reach this is Reach's reading, not this one.
            if distance < 6 or distance > REACH_LIMIT then return end

            local facing = fromRoot.CFrame.LookVector * Vector3.new(1, 0, 1)
            local toward = delta * Vector3.new(1, 0, 1)
            if facing.Magnitude < 0.01 or toward.Magnitude < 0.01 then return end

            local angle = math.deg(math.acos(math.clamp(facing.Unit:Dot(toward.Unit), -1, 1)))
            -- 70 degrees off and still landing means the swing did not resolve against the body
            -- that is being drawn. Wide enough that our own interpolation of a strafing player
            -- cannot get there on its own.
            if angle > 70 then
                strike(attacker, 'HitBoxes', 'expanded hitboxes', `hit {math.floor(angle)} degrees off target`)
            end
        end))
    end

    ------------------------------------------------------------------------
    -- SilentAim.
    ------------------------------------------------------------------------
    -- The projectile equivalent: a shot that lands on someone the shooter was never pointing at.
    -- Only long shots are considered, because at close range the angle to a target is wide even
    -- when aimed honestly, and only non-melee damage, so a sword swing is never counted here.
    Events.SilentAim = function()
        CheatDetector:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
            if not wanted('SilentAim') then return end
            if damageTable.damageType == 0 or not damageTable.fromEntity or not damageTable.entityInstance then return end

            local attacker = playersService:GetPlayerFromCharacter(damageTable.fromEntity)
            if not attacker or selfExcluded(attacker) or CheatersFlagged[attacker] then return end
            if not conditionsUsable(attacker) or recentlyTeleported(attacker) then return end

            local fromRoot = damageTable.fromEntity.PrimaryPart
            local toRoot = damageTable.entityInstance.PrimaryPart
            if not fromRoot or not toRoot then return end

            local delta = (toRoot.Position - fromRoot.Position) * Vector3.new(1, 0, 1)
            -- A thrown projectile arcs, and a short lob can leave at a heading well off the
            -- target quite legitimately. Distance is what makes the heading meaningful.
            if delta.Magnitude < 25 then return end

            local facing = fromRoot.CFrame.LookVector * Vector3.new(1, 0, 1)
            if facing.Magnitude < 0.01 then return end

            local angle = math.deg(math.acos(math.clamp(facing.Unit:Dot(delta.Unit), -1, 1)))
            if angle > 50 then
                strike(attacker, 'SilentAim', 'silent aim', `landed a shot {math.floor(angle)} degrees off their heading`)
            end
        end))
    end

    ------------------------------------------------------------------------
    -- ProjectileAimbot and Aura.
    ------------------------------------------------------------------------
    -- Aimbot is not one impossible shot, it is never missing. Landing projectile after projectile
    -- on live players at long range, faster than they can be aimed, is the thing no hand does.
    Events.ProjectileAim = function()
        local hits = {}
        CheatDetector:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
            if not wanted('ProjectileAim') then return end
            if damageTable.damageType == 0 or not damageTable.fromEntity or not damageTable.entityInstance then return end

            local attacker = playersService:GetPlayerFromCharacter(damageTable.fromEntity)
            local victim = playersService:GetPlayerFromCharacter(damageTable.entityInstance)
            -- Players only. A projectile stream into a mob or a bed is a different thing entirely.
            if not attacker or not victim or selfExcluded(attacker) or CheatersFlagged[attacker] then return end
            if not conditionsUsable(attacker) then return end

            local fromRoot = damageTable.fromEntity.PrimaryPart
            local toRoot = damageTable.entityInstance.PrimaryPart
            if not fromRoot or not toRoot then return end
            if (toRoot.Position - fromRoot.Position).Magnitude < 30 then return end

            -- Four long-range projectile hits on players inside six seconds. Bows are slow to
            -- draw, so this is well past what the weapon itself allows aimed by hand.
            if bumpRate(hits, attacker, 6) >= 4 then
                hits[attacker] = nil
                strike(attacker, 'ProjectileAim', 'projectile aimbot', '4 long-range projectile hits inside 6s')
            end
        end))
    end

    ------------------------------------------------------------------------
    -- Breaker.
    ------------------------------------------------------------------------
    -- Blocks coming apart faster than a tool can swing, or coming apart from across the map. Both
    -- are read off the break event itself, which carries who did it and where.
    Events.Breaker = function()
        local rates = {}
        CheatDetector:Clean(vapeEvents.BreakBlockEvent.Event:Connect(function(data)
            if not wanted('Breaker') then return end
            local plr = data.player
            if not plr or selfExcluded(plr) or CheatersFlagged[plr] then return end
            if not conditionsUsable(plr) then return end

            local blockPosition = data.blockRef and data.blockRef.blockPosition
            if typeof(blockPosition) == 'Vector3' then
                local root
                for _, ent in entities() do
                    if ent.Player == plr then
                        root = ent.RootPart
                        break
                    end
                end
                if root and root.Parent then
                    local distance = (root.Position - (blockPosition * 3)).Magnitude
                    -- Block reach in this game is well under 30 studs even with every modifier.
                    if distance > 45 and not recentlyTeleported(plr) then
                        strike(plr, 'Breaker', 'block breaker', `broke a block {math.floor(distance)} studs away`)
                        return
                    end
                end
            end

            -- Twelve blocks inside two seconds. Flat out with the fastest tool in the game on the
            -- softest block is not close to this, and a burst that size cannot be a batch of
            -- replicated events either.
            if bumpRate(rates, plr, 2) >= 12 then
                rates[plr] = nil
                strike(plr, 'Breaker', 'block breaker', '12 blocks broken inside 2s')
            end
        end))
    end

    ------------------------------------------------------------------------
    -- Crashers: Remote.
    ------------------------------------------------------------------------
    -- Another player's remote traffic is not visible from here, but its effect is: a crasher
    -- pushes replicated actions out at a rate the game itself never produces. Block places and
    -- breaks and damage events are all counted together, because a crasher does not care which
    -- remote it is hammering. The bar is per second and set well past a busy one: jumping around
    -- spamming a sword while building throws out a lot of events, and none of that is a crash.
    Events.Remote = function()
        local rates = {}

        local function count(plr)
            if not wanted('Remote') then return end
            if not plr or selfExcluded(plr) or CheatersFlagged[plr] then return end
            if bumpRate(rates, plr, REMOTE_WINDOW) >= REMOTE_FLOOD then
                rates[plr] = nil
                strike(plr, 'Remote', 'remote spam', `{REMOTE_FLOOD} replicated actions inside {REMOTE_WINDOW}s`)
            end
        end

        CheatDetector:Clean(vapeEvents.BreakBlockEvent.Event:Connect(function(data)
            count(data.player)
        end))
        CheatDetector:Clean(vapeEvents.PlaceBlockEvent.Event:Connect(function(data)
            count(data and data.player)
        end))
        CheatDetector:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
            if not damageTable.fromEntity then return end
            count(playersService:GetPlayerFromCharacter(damageTable.fromEntity))
        end))
    end

    -- One snapshot of everybody worth measuring, taken once per tick and handed to every polling
    -- check. Attributes, ground state and velocity are read here rather than inside each check,
    -- so a player is walked over once however many checks are on.
    local function snapshot(now)
        local list = {}
        for _, ent in entities() do
            local plr, root, char = ent.Player, ent.RootPart, ent.Character
            if not plr or selfExcluded(plr) or CheatersFlagged[plr] then continue end
            if not root or not root.Parent or not char then continue end
            if (ent.Health or 0) <= 0 then continue end

            local position = root.Position
            table.insert(list, {
                Player = plr,
                Character = char,
                Root = root,
                Position = position,
                Flat = position * Vector3.new(1, 0, 1),
                Velocity = root.AssemblyLinearVelocity,
                Grounded = (ent.Humanoid and ent.Humanoid.FloorMaterial ~= Enum.Material.Air) or false,
                Effects = effectsOf(char),
                Teleported = recentlyTeleported(plr),
                Hurt = (now - (lastHurt[plr] or 0)) < 1.5
            })
        end
        return list
    end

    CheatDetector = vape.Categories.Utility:CreateModule({
        Name = 'CheatDetector',
        Function = function(callback)
            if callback then
                table.clear(strikes)
                table.clear(lastHurt)
                table.clear(animationLast)
                table.clear(animationRates)
                table.clear(animationHooked)
                animationBacked = 0
                voidStamp = 0

                -- Feeds the knockback suppression the speed and jump checks rely on.
                CheatDetector:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
                    local victim = damageTable.entityInstance and playersService:GetPlayerFromCharacter(damageTable.entityInstance)
                    if victim then
                        lastHurt[victim] = tick()
                    end
                end))

                -- Every check is put in place, whichever toggles happen to be ticked right now,
                -- and each one asks whether it is wanted as it runs. Building only the ticked
                -- ones meant a detection switched on mid-match did nothing at all until the
                -- module was cycled by hand, which is most of what "half of these do not work"
                -- was. An unwanted check costs one table lookup a tick.
                for name, event in Events do
                    local ok, err = pcall(event)
                    if not ok then
                        warn('[AetherV2] CheatDetector '..name..': '..tostring(err))
                    end
                end

                local running = {}
                for name, poller in Pollers do
                    local ok, fn = pcall(poller)
                    if ok and type(fn) == 'function' then
                        running[name] = fn
                    else
                        warn('[AetherV2] CheatDetector '..name..': '..tostring(fn))
                    end
                end

                local last = tick()
                repeat
                    local now = tick()
                    local delta = now - last
                    last = now

                    -- The animation watch is what the crasher check counts and what killaura
                    -- asks whether a swing happened at all, so it runs for either of them.
                    local watching = wanted('Animation') or wanted('Killaura')
                    local polling = false
                    for name in running do
                        if wanted(name) then
                            polling = true
                            break
                        end
                    end

                    if watching or polling then
                        -- A character coming apart mid-read throws, and an unguarded throw here
                        -- ends the loop and the whole module with it.
                        local taken, list = pcall(snapshot, now)
                        if taken and #list > 0 then
                            if watching then
                                pcall(watchAnimations, list)
                            end
                            for name, fn in running do
                                if not wanted(name) then continue end
                                local ok, err = pcall(fn, now, list, delta)
                                if not ok then
                                    warn('[AetherV2] CheatDetector '..name..': '..tostring(err))
                                end
                            end
                        end
                    end

                    task.wait(POLL_INTERVAL)
                until not CheatDetector.Enabled
            else
                table.clear(strikes)
                table.clear(lastHurt)
                table.clear(animationLast)
                table.clear(animationRates)
                table.clear(animationHooked)
                animationBacked = 0
            end
        end,
        Tooltip = 'Alerts for likely cheaters. Every detection needs several impossible readings, and ignores ones taken on a poor connection'
    })

    local GROUP_TOOLTIPS = {
        ['Impossible hits'] = 'Hits that cannot have been aimed or thrown by hand: killaura, silent aim, expanded hitboxes, reach past any weapon',
        ['Blatant modules'] = 'Movement and state nobody can produce by playing: attach, anti death, phase, invisibility, high jump, speed',
        ['AutoKit'] = 'Kit abilities fired on a fixed interval, the regularity no hand holds',
        ['Crashers'] = 'Floods meant to bury other clients - animations or replicated actions many times a second',
        ['Breaker'] = 'Blocks broken faster than a tool swings, or from across the map',
        ['ProjectileAimbot and Aura'] = 'Long-range projectiles landing on players faster than a bow can be drawn and aimed'
    }
    local CHILD_TOOLTIPS = {
        Killaura = 'Hit rate, an unvarying cadence, several targets at once, or damage with no swing behind it',
        SilentAim = 'Shots landing on someone the shooter was not pointing at',
        HitBoxes = 'Melee landing while facing well off the body being drawn',
        Reach = 'Hits landing past 15.5 studs, further than any sword in the game swings',
        PlayerAttach = 'Teleporting onto a player, or riding them with the gap between you barely moving',
        AntiDeath = 'The hitbox thrown up and down faster than gravity, or held below every block on the map',
        Phase = 'The body stood inside solid geometry across consecutive samples',
        Invisible = 'Moving with every limb hidden and no invisibility effect of their own',
        HighJump = 'Rising far past jump power off one jump, with no launch or ability effect',
        Speed = 'Ground speed held past 22 studs/s - or past whatever the kit\'s own metadata says it is worth - with potions, dashes and knockback excluded',
        Animation = 'Animation starts many times a second, far past anything play produces',
        Remote = 'Replicated actions - places, breaks, hits - many times a second'
    }

    for _, group in GROUPS do
        Toggles[group.Name] = CheatDetector:CreateToggle({
            Name = group.Name,
            Default = true,
            Tooltip = GROUP_TOOLTIPS[group.Name],
            Function = function(callback)
                for _, child in (group.Children or {}) do
                    local toggle = Toggles[child]
                    if toggle and toggle.Object then
                        toggle.Object.Visible = callback
                    end
                end
            end
        })
        for _, child in (group.Children or {}) do
            Toggles[child] = CheatDetector:CreateToggle({
                Name = child,
                Default = true,
                Darker = true,
                Tooltip = CHILD_TOOLTIPS[child]
            })
        end
    end

    -- Last, and under everything else, because it is not a detection - it only changes who the
    -- detections above are allowed to look at. Takes effect immediately: the checks ask about it
    -- as they run rather than reading it once at startup, so there is no need to cycle the module.
    Toggles[DETECT_SELF] = CheatDetector:CreateToggle({
        Name = DETECT_SELF,
        Tooltip = 'Testing aid. Runs every enabled detection against you as well, on your behaviour alone - it never looks at which of your modules are on - and flags you like anyone else if one of them fires',
        Function = function()
            -- Readings taken either side of a change of mind about whether we count are not a
            -- pattern, so whichever way it just moved, our own history starts again from nothing.
            strikes[lplr] = nil
        end
    })
end)

run(function()
    local FakeLag
    local TransmissionOffset
    local Mode
    local Delay

    local rng

    FakeLag = vape.Categories.Utility:CreateModule({
        Name = 'FakeLag',
        Function = function(callback)
            if callback then
                rng = Random.new()

                local clock, restore, after = os.clock(), os.clock(), 0
                repeat
                    local ms = Delay.Value / 1000

                    if Mode.Value == 'Dynamic' then
                        if (os.clock() - clock) >= ms or restore > os.clock() then
                            if clock ~= 9e9 then
                                -- TransmissionOffset is in milliseconds. It was added as raw
                                -- seconds, so the "flush" window lasted 1-10 SECONDS between
                                -- withhold bursts and Dynamic FakeLag barely lagged at all.
                                restore = os.clock() + (TransmissionOffset.Value / 1000)
                                clock = 9e9
                            end
                            setfflag('PhysicsSenderMaxBandwidthBps', '38760')
                        else
                            if clock == 9e9 then
                                clock = os.clock()
                                restore = 0
                            end
                            setfflag('PhysicsSenderMaxBandwidthBps', '0')
                        end
                    elseif Mode.Value == 'Repel' then
                        if store.update > tick() then
                            setfflag('PhysicsSenderMaxBandwidthBps', '0')
                            setfflag('S2PhysicsSenderRate', '0')
                            setfflag('DataSenderRate', '-1')
                            task.wait(rng:NextNumber(70, 150) / 1000)
                            setfflag('PhysicsSenderMaxBandwidthBps', '38760')
                            setfflag('DataSenderRate', '60')
                            setfflag('S2PhysicsSenderRate', '15')
                            after = os.clock() + rng:NextNumber(0.001, (Delay.Value / 1000))
                            store.update = 0
                            num = rng:NextNumber()
                        end
                        if os.clock() > after then
                            num = rng:NextNumber()
                            after = os.clock() + rng:NextNumber(0.001, (Delay.Value / 1000))
                        end
                    elseif Mode.Value == 'Latency' then
                        setfflag('PhysicsSenderMaxBandwidthBps', '0')
                        task.wait(Delay.Value / 1500)
                        setfflag('PhysicsSenderMaxBandwidthBps', '38760')
                        task.wait(ms)
                    end
                    runService.PreRender:Wait()
                until not FakeLag.Enabled
            else
                setfflag('DataSenderRate', '60')
                setfflag('PhysicsSenderMaxBandwidthBps', '38760')
            end
        end,
        Tooltip = 'Delays packets, simulating lag',
        ExtraText = function()
            return Mode and Mode.Value or 'Dynamic'
        end
    })
    getgenv().FakeLag = FakeLag

    TransmissionOffset = FakeLag:CreateSlider({
        Name = 'Transmission Offset',
        Min = 1,
        Max = 10,
        Default = 3,
        Decimal = 5,
        Darker = true,
    })
    Mode = FakeLag:CreateDropdown({
        Name = 'Mode',
        List = { 'Dynamic', 'Repel', 'Latency' },
        Default = 'Dynamic',
        Function = function(val)
            TransmissionOffset.Object.Visible = val == 'Dynamic'
            setfflag('PhysicsSenderMaxBandwidthBps', '38760')
        end,
    })
    Delay = FakeLag:CreateSlider({
        Name = 'Delay',
        Suffix = function()
            return 'ms'
        end,
        Min = 1,
        Max = 500,
        Default = 100,
    })
end)

run(function()
    local KnockbackDelay
    local Chance
    local AirDelay
    local GroundDelay
    local TargetCheck

    local old, rand
    local function apply(type, env, ...)
	local root, mass, dir, knockback = ...
	knockback = knockback and table.clone(knockback) or {}
	knockback[type] = env[type] and knockback[type] or 0
	return old(root, mass, dir, knockback, select(5, ...))
    end

    KnockbackDelay = vape.Categories.Utility:CreateModule({
	Name = 'KnockbackDelay',
	Function = function(callback)
		if callback then
			old, rand = bedwars.KnockbackUtil.applyKnockback, Random.new()
			bedwars.KnockbackUtil.applyKnockback = function(...)
				if rand:NextNumber(0, 100) > Chance.Value then
					return old(...)
				end

				local root, mass, dir, knockback = ...
				if not TargetCheck.Enabled or entitylib.EntityPosition({
					Range = 50,
					Part = 'RootPart',
					Players = true,
				}) then
					local env = {}
					task.delay(AirDelay:GetRandomValue() / 1000, apply, 'horizontal', env, root, mass, dir, knockback, select(5, ...))
					task.delay(GroundDelay:GetRandomValue() / 1000, apply, 'vertical', env, root, mass, dir, knockback, select(5, ...))
					return
				end
				return old(...)
			end
		else
			bedwars.KnockbackUtil.applyKnockback = old or bedwars.KnockbackUtil.applyKnockback
		end
	end,
	Tooltip = 'Delays incoming knockback packets'
    })

    Chance = KnockbackDelay:CreateSlider({
	Name = 'Chance',
	Min = 1,
	Max = 100,
	Default = 40,
	Suffix = '%',
    })
    AirDelay = KnockbackDelay:CreateTwoSlider({
	Name = 'Air delay',
	Min = 0,
	Max = 500,
	DefaultMin = 50,
	DefaultMax = 200,
    })
    GroundDelay = KnockbackDelay:CreateTwoSlider({
	Name = 'Ground delay',
	Min = 0,
	Max = 500,
	DefaultMin = 50,
	DefaultMax = 200,
    })
    TargetCheck = KnockbackDelay:CreateToggle({ Name = 'Target check' })
end)

