run(function()
    local Scaffold
    local Clutch
    local Expand
    local Tower
    local Downwards
    local Diagonal
    local LimitItem
    local Mouse
    local ClutchMode
    local clutchRay = RaycastParams.new()
    local adjacent, lastpos, label = {}, Vector3.zero
    -- Where the last pass filled, so the ground actually covered between passes can be worked out.
    local lastFoot
    local faceAdjacent = {
        Vector3.new(3, 0, 0),
        Vector3.new(-3, 0, 0),
        Vector3.new(0, 3, 0),
        Vector3.new(0, -3, 0),
        Vector3.new(0, 0, 3),
        Vector3.new(0, 0, -3)
    }
    clutchRay.FilterType = Enum.RaycastFilterType.Exclude

    for x = -3, 3, 3 do
        for y = -3, 3, 3 do
            for z = -3, 3, 3 do
                local vec = Vector3.new(x, y, z)
                if vec ~= Vector3.zero then
                    table.insert(adjacent, vec)
                end
            end
        end
    end

    local function nearCorner(poscheck, pos)
        local startpos = poscheck - Vector3.new(3, 3, 3)
        local endpos = poscheck + Vector3.new(3, 3, 3)
        local check = poscheck + (pos - poscheck).Unit * 100
        return Vector3.new(math.clamp(check.X, startpos.X, endpos.X), math.clamp(check.Y, startpos.Y, endpos.Y), math.clamp(check.Z, startpos.Z, endpos.Z))
    end

    local function blockProximity(pos)
        local mag, returned = 60, nil
        local tab = getBlocksInPoints(bedwars.BlockController:getBlockPosition(pos - Vector3.new(21, 21, 21)), bedwars.BlockController:getBlockPosition(pos + Vector3.new(21, 21, 21)))
        for _, v in tab do
            local blockpos = nearCorner(v, pos)
            local newmag = (pos - blockpos).Magnitude
            if newmag < mag then
                mag, returned = newmag, blockpos
            end
        end
        table.clear(tab)
        return returned
    end

    local function checkAdjacent(pos)
        for _, v in adjacent do
            if getPlacedBlock(pos + v) then
                return true
            end
        end
        return false
    end

    local function checkFaceAdjacent(pos)
        for _, v in faceAdjacent do
            if getPlacedBlock(pos + v) then
                return true
            end
        end
        return false
    end

    local function getNearestPlacedAnchor(pos)
        local closest, closestmag
        for x = -3, 3, 3 do
            for y = -3, 3, 3 do
                for z = -3, 3, 3 do
                    local checkpos = roundPos(pos + Vector3.new(x, y, z))
                    local block, blockpos = getPlacedBlock(checkpos)
                    if block then
                        blockpos *= 3
                        local mag = (pos - blockpos).Magnitude
                        if not closestmag or mag < closestmag then
                            closest, closestmag = blockpos, mag
                        end
                    end
                end
            end
        end
        return closest
    end

    local function getClutchPath(startpos, endpos, limit)
        local path, currentpos = {}, startpos

        for _ = 1, limit do
            if currentpos == endpos then break end

            local diff = endpos - currentpos
            local step
            if math.abs(diff.X) >= math.abs(diff.Z) and diff.X ~= 0 then
                step = Vector3.new(math.sign(diff.X) * 3, 0, 0)
            elseif diff.Z ~= 0 then
                step = Vector3.new(0, 0, math.sign(diff.Z) * 3)
            elseif diff.Y ~= 0 then
                step = Vector3.new(0, math.sign(diff.Y) * 3, 0)
            else
                break
            end

            currentpos += step
            if not getPlacedBlock(currentpos) then
                table.insert(path, currentpos)
            end
        end

        return path
    end

    -- Fill every cell the character actually crossed since the last pass, rather than only the
    -- cells sampled at this instant. One pass is 0.03s at best and a dropped frame is far longer,
    -- so above roughly 100 studs/s a single step carries you further than a whole block and the
    -- cell in between is never looked at at all. That skipped cell is the hole you fall through
    -- at speed.
    local function fillPath(fromPos, toPos, wool)
        if not fromPos then return end
        local delta = toPos - fromPos
        local distance = delta.Magnitude
        if distance <= 1.5 then return end
        -- One sample per half-cell, capped so a teleport across the map cannot spin here.
        local steps = math.min(math.ceil(distance / 1.5), 16)
        for step = 1, steps - 1 do
            local pos = roundPos(fromPos:Lerp(toPos, step / steps))
            local block, blockpos = getPlacedBlock(pos)
            if not block then
                blockpos = checkAdjacent(blockpos * 3) and blockpos * 3 or blockProximity(pos)
                if blockpos then
                    task.spawn(bedwars.placeBlock, blockpos, wool, false)
                end
            end
        end
    end

    local function getScaffoldBlock()
        if store.hand.toolType == 'block' then
            return store.hand.tool.Name, store.hand.amount
        elseif (not LimitItem.Enabled) then
            local wool, amount = getWool()
            if wool then
                return wool, amount
            else
                for _, item in store.inventory.inventory.items do
                    if bedwars.ItemMeta[item.itemType].block then
                        return item.itemType, item.amount
                    end
                end
            end
        end

        return nil, 0
    end

    Scaffold = vape.Categories.Utility:CreateModule({
        Name = 'Scaffold',
        Function = function(callback)
            if label then
                label.Visible = callback
            end

            if callback then
                lastFoot = nil
                repeat
                    if not entitylib.isAlive then
                        -- A respawn is not ground that was walked over, so never bridge to it.
                        lastFoot = nil
                    else
                        local wool, amount = getScaffoldBlock()

                        if Mouse.Enabled then
                            if not inputService:IsMouseButtonPressed(0) then
                                wool = nil
                            end
                        end

                        if label then
                            amount = amount or 0
                            label.Text = amount..' <font color="rgb(170, 170, 170)">(Scaffold)</font>'
                            label.TextColor3 = Color3.fromHSV((amount / 128) / 2.8, 0.86, 1)
                        end

                        if wool then
                            local root = entitylib.character.RootPart
                            if Tower.Enabled and inputService:IsKeyDown(Enum.KeyCode.Space) and (not inputService:GetFocusedTextBox()) then
                                root.Velocity = Vector3.new(root.Velocity.X, 38, root.Velocity.Z)
                            end

                            -- Close the ground covered since the last pass before looking ahead,
                            -- so nothing is skipped no matter how fast the character is moving.
                            local footOffset = Vector3.new(0, entitylib.character.HipHeight + (Downwards.Enabled and inputService:IsKeyDown(Enum.KeyCode.LeftShift) and 4.5 or 1.5), 0)
                            local footPos = root.Position - footOffset
                            fillPath(lastFoot, footPos, wool)
                            lastFoot = footPos

                            for i = Expand.Value, 1, -1 do
                                local currentpos = roundPos(footPos + entitylib.character.Humanoid.MoveDirection * (i * 3))
                                if Diagonal.Enabled then
                                    if math.abs(math.round(math.deg(math.atan2(-entitylib.character.Humanoid.MoveDirection.X, -entitylib.character.Humanoid.MoveDirection.Z)) / 45) * 45) % 90 == 45 then
                                        local dt = (lastpos - currentpos)
                                        if ((dt.X == 0 and dt.Z ~= 0) or (dt.X ~= 0 and dt.Z == 0)) and ((lastpos - root.Position) * Vector3.new(1, 0, 1)).Magnitude < 2.5 then
                                            currentpos = lastpos
                                        end
                                    end
                                end

                                local block, blockpos = getPlacedBlock(currentpos)
                                if not block then
                                    blockpos = checkAdjacent(blockpos * 3) and blockpos * 3 or blockProximity(currentpos)
                                    if blockpos then
                                        task.spawn(bedwars.placeBlock, blockpos, wool, false)
                                    end
                                end
                                lastpos = currentpos
                            end
                        end
                    end

                    task.wait(0.03)
                until not Scaffold.Enabled
            else
                Label = nil
            end
        end,
        Tooltip = 'Helps you make bridges/scaffold walk'
    })
    Expand = Scaffold:CreateSlider({
        Name = 'Expand',
        Min = 1,
        Max = 6
    })
    Tower = Scaffold:CreateToggle({
        Name = 'Tower',
        Default = true
    })
    Downwards = Scaffold:CreateToggle({
        Name = 'Downwards',
        Default = true
    })
    Diagonal = Scaffold:CreateToggle({
        Name = 'Diagonal',
        Default = true
    })
    LimitItem = Scaffold:CreateToggle({Name = 'Limit to items'})
    Mouse = Scaffold:CreateToggle({Name = 'Require mouse down'})
    Count = Scaffold:CreateToggle({
        Name = 'Block Count',
        Function = function(callback)
            if callback then
                label = Instance.new('TextLabel')
                label.Size = UDim2.fromOffset(100, 20)
                label.Position = UDim2.new(0.5, 6, 0.5, 60)
                label.BackgroundTransparency = 1
                label.AnchorPoint = Vector2.new(0.5, 0)
                label.Text = '0'
                label.TextColor3 = Color3.new(0, 1, 0)
                label.TextSize = 18
                label.RichText = true
                label.Font = Enum.Font.Arial
                label.Visible = Scaffold.Enabled
                label.Parent = vape.gui
            else
                label:Destroy()
                label = nil
            end
        end
    })

end)

run(function()
    local StaffDetector
    local Mode
    local Clans
    local Party
    local Profile
    local Users
    local NotifyLeave
    local blacklistedclans = {'gg', 'gg2', 'DV', 'DV2'}
    local blacklisteduserids = {1502104539, 3826146717, 4531785383, 1049767300, 4926350670, 653085195, 184655415, 2752307430, 5087196317, 5744061325, 1536265275}
    local joined = {}
    -- Players that have been flagged as staff this session, so 'Notify on leave' can
    -- tell you the moment a detected mod leaves your game.
    local flagged = {}

    local function getRole(plr, id)
        local suc, res = pcall(function()
            return plr:GetRankInGroup(id)
        end)
        if not suc then
            notif('StaffDetector', res, 30, 'alert')
        end
        return suc and res or 0
    end

    local function staffFunction(plr, checktype)
        if not vape.Loaded then
            repeat task.wait() until vape.Loaded
        end

        notif('StaffDetector', 'Staff Detected ('..checktype..'): '..plr.Name..' ('..plr.UserId..')', 60, 'alert')
        whitelist.customtags[plr.Name] = {{text = 'GAME STAFF', color = Color3.new(1, 0, 0)}}
        flagged[plr.UserId] = {Name = plr.Name, Check = checktype}

        if Party.Enabled and not checktype:find('clan') then
            bedwars.PartyController:leaveParty()
        end

        if Mode.Value == 'Uninject' then
            task.spawn(function()
                vape:Uninject()
            end)
            game:GetService('StarterGui'):SetCore('SendNotification', {
                Title = 'StaffDetector',
                Text = 'Staff Detected ('..checktype..')\n'..plr.Name..' ('..plr.UserId..')',
                Duration = 60,
            })
        elseif Mode.Value == 'Requeue' then
            bedwars.QueueController:joinQueue(store.queueType)
        elseif Mode.Value == 'Profile' then
            vape.Save = function() end
            if vape.Profile ~= Profile.Value then
                vape:Load(true, Profile.Value)
            end
        elseif Mode.Value == 'AutoConfig' then
            local safe = {'AutoClicker', 'Reach', 'Sprint', 'HitFix', 'StaffDetector'}
            vape.Save = function() end
            for i, v in vape.Modules do
                if not (table.find(safe, i) or v.Category == 'Render') then
                    if v.Enabled then
                        v:Toggle()
                    end
                    v:SetBind('')
                end
            end
        end
    end

    local function checkFriends(list)
        for _, v in list do
            if joined[v] then
                return joined[v]
            end
        end
        return nil
    end

    local function checkJoin(plr, connection)
        if not plr:GetAttribute('Team') and plr:GetAttribute('Spectator') and not bedwars.Store:getState().Game.customMatch then
            connection:Disconnect()
            local tab, pages = {}, playersService:GetFriendsAsync(plr.UserId)
            for _ = 1, 200 do
                for _, v in pages:GetCurrentPage() do
                    table.insert(tab, v.Id)
                end
                if pages.IsFinished then break end
                pages:AdvanceToNextPageAsync()
            end

            local friend = checkFriends(tab)
            if not friend then
                staffFunction(plr, 'impossible_join')
                return true
            else
                notif('StaffDetector', string.format('Spectator %s joined from %s', plr.Name, friend), 20, 'warning')
            end
        end
    end

    local function playerAdded(plr)
        joined[plr.UserId] = plr.Name
        if plr == lplr then return end

        if table.find(blacklisteduserids, plr.UserId) or table.find(Users.ListEnabled, tostring(plr.UserId)) then
            staffFunction(plr, 'blacklisted_user')
        elseif getRole(plr, 5774246) >= 100 then
            staffFunction(plr, 'staff_role')
        else
            local connection
            connection = plr:GetAttributeChangedSignal('Spectator'):Connect(function()
                checkJoin(plr, connection)
            end)
            StaffDetector:Clean(connection)
            if checkJoin(plr, connection) then
                return
            end

            if not plr:GetAttribute('ClanTag') then
                plr:GetAttributeChangedSignal('ClanTag'):Wait()
            end

            if table.find(blacklistedclans, plr:GetAttribute('ClanTag')) and vape.Loaded and Clans.Enabled then
                connection:Disconnect()
                staffFunction(plr, 'blacklisted_clan_'..plr:GetAttribute('ClanTag'):lower())
            end
        end
    end

    StaffDetector = vape.Categories.Utility:CreateModule({
        Name = 'StaffDetector',
        Function = function(callback)
            if callback then
                table.clear(flagged)
                StaffDetector:Clean(playersService.PlayerAdded:Connect(playerAdded))
                StaffDetector:Clean(playersService.PlayerRemoving:Connect(function(plr)
                    local info = flagged[plr.UserId]
                    if info and NotifyLeave.Enabled then
                        notif('StaffDetector', 'Flagged staff left ('..info.Check..'): '..info.Name..' ('..plr.UserId..')', 20, 'warning')
                    end
                    flagged[plr.UserId] = nil
                end))
                for _, v in playersService:GetPlayers() do
                    task.spawn(playerAdded, v)
                end
            else
                table.clear(joined)
                table.clear(flagged)
            end
        end,
        Tooltip = 'Detects people with a staff rank ingame'
    })
    Mode = StaffDetector:CreateDropdown({
        Name = 'Mode',
        List = {'Uninject', 'Profile', 'Requeue', 'AutoConfig', 'Notify'},
        Function = function(val)
            if Profile.Object then
                Profile.Object.Visible = val == 'Profile'
            end
        end
    })
    Clans = StaffDetector:CreateToggle({
        Name = 'Blacklist clans',
        Default = true
    })
    Party = StaffDetector:CreateToggle({
        Name = 'Leave party'
    })
    NotifyLeave = StaffDetector:CreateToggle({
        Name = 'Notify on leave',
        Tooltip = 'Notifies you when a flagged staff member leaves your game',
        Default = true
    })
    Profile = StaffDetector:CreateTextBox({
        Name = 'Profile',
        Default = 'default',
        Darker = true,
        Visible = false
    })
    Users = StaffDetector:CreateTextList({
        Name = 'Users',
        Placeholder = 'player (userid)'
    })
end)

run(function()
    TrapDisabler = vape.Categories.Utility:CreateModule({
        Name = 'TrapDisabler',
        Tooltip = 'Disables Snap Traps'
    })
end)

run(function()
    ----------------------------------------------------------------------------------------------
    -- AutoWin (v6) - the unattended match brain.
    --
    -- Written to be left running for hours. Three things make that possible, and everything below
    -- is arranged around them:
    --
    --   1. NOTHING BLOCKS. The old build was a stack of nested `while` loops - walk until you
    --      arrive, mine until you are full, fight until it dies - so anything that happened while
    --      one of them was spinning (dying, the match ending, a teammate taking the bed we were
    --      crossing to) was only noticed when that loop happened to finish. This one is a tick
    --      machine: the brain re-decides what to do from the live world every 100ms and every
    --      action it takes is bounded, so it can never be committed to a plan the world has
    --      already invalidated.
    --
    --   2. NOTHING CAN KILL IT. Every tick runs inside a pcall, every game API call is isolated,
    --      and a watchdog thread outside the brain notices when the brain itself has stopped
    --      making progress and resets it. A BedWars update that moves one field breaks one action
    --      for one tick instead of ending an eight hour run.
    --
    --   3. IT ESCALATES INSTEAD OF GIVING UP. Walking and bridging is the default because nothing
    --      about it is rejected by the server. When a route genuinely will not go, the run steps
    --      up a rung at a time - re-plan, tower over it, dash it, speed, fly - up to the ceiling
    --      set by Aggression, and steps back down as soon as it is moving again.
    --
    -- Navigation is a real search, not a greedy walk at the target. A* over the BedWars block grid,
    -- where empty cells cost extra (we bridge them) and placed blocks in the way cost more again
    -- (we mine them), gives a route around walls, over gaps and up towers that a straight line
    -- would spend the whole match nose-first against.
    --
    -- Yuzi: the dash is fired directly (useAbility), never by toggling the LongJump module. LongJump
    -- pins your velocity once its boost window closes, so driving a run through it meant every
    -- crossing ended with the character frozen waiting for a toggle-off that a stall could skip.
    --
    -- With Take over on, this drives your existing modules - AutoBuy, AutoBank, AutoTool, Killaura,
    -- AntiVoid, NoFallDamage, YuziExtender, Anti-AFK - rather than half re-implementing them, and
    -- puts every one of them back exactly as it found them when it stops.
    ----------------------------------------------------------------------------------------------
    local AutoWin
    local Aggression, StartDelay
    local IronAmount, WoolAmount
    local BedReach, PlayerReach, KillPlayers
    local YuziDash, AutoEquipKit, DaoPriority
    local TakeOver, BankLoot, RespawnAfterBed
    local Requeue, Gamemode, ResumeInLobby, AutoRejoin, KeepAwake, StuckLimit
    local ShowHUD, Notify

    -- BedWars' lobby is a different place to the match, so it loads games/6872265039.lua and not
    -- this file. The queue we want after a match therefore has to be handed over on disk; the
    -- lobby's AutoQueue module reads exactly this file.
    local LOBBY_PLACE = 6872265039
    local STATE_FILE = 'aetherv2/profiles/autowin.json'

    -- Blocks sit on a 3-stud grid. A cell's centre is cell * 3, and standing on that cell puts
    -- your feet 1.5 studs above the centre. Every routing decision below is in whole cells.
    local CELL = 3
    local STAND = 1.5
    local WOOL_ITEM, WOOL_PER_BUY, WOOL_PRICE = 'wool_white', 16, 8
    local DAO_TIERS = {'wood_dao', 'stone_dao', 'iron_dao', 'diamond_dao', 'emerald_dao'}
    -- The same ladder AutoBuy walks. Slot 2 of the inventory's armor table is the chestplate, which
    -- is what the ladder is priced on and what the run judges "are we dressed for this" by.
    local ARMOUR_TIERS = {'leather_chestplate', 'iron_chestplate', 'diamond_chestplate', 'emerald_chestplate'}
    -- Yuzi has shipped under both ids; treat either as the dash kit rather than betting on one.
    local YUZI_KITS = {yuzi = true, dasher = true}
    local BANKABLE = {iron = true, gold = true, diamond = true, emerald = true, void_crystal = true}
    -- Never bridge with something that explodes, sticks, or is somebody's bed.
    local BAD_BLOCKS = {'tnt', 'cannon', 'bed', 'trap', 'gumdrop', 'glue', 'ladder', 'sludge', 'bomb', 'beacon', 'spawner', 'chest'}

    -- Escalation ceilings. Tier 0 is walk and bridge; each rung adds one way of getting past
    -- something that walking could not, and the ceiling is what Aggression actually sets.
    local TIER_CEILING = {Safe = 1, Balanced = 2, Blatant = 3}

    -- The launch the dash driver asserts when the game's own handler did not move us, and how long
    -- it holds it for. Held for a short window rather than LongJump's two and a half seconds, so a
    -- dash covers about a dash's worth of ground instead of half the map.
    local DASH_SPEED, DASH_CARRY = 75, 0.55

    -- Bumped on every enable/disable. Every loop below carries the generation it started with and
    -- exits the moment it stops matching, so a toggle can never leave a thread from the previous
    -- run still driving the character.
    local generation = 0

    -- Forward declared: the walker escalates mid-crossing and so has to be able to apply a tier,
    -- but the escalation rungs are defined further down (they need the module driver, which needs
    -- the option handles). Without this the call inside travel would compile as a global read.
    local applyTier

    -- Same reason. The dash driver lives with the walker's driver (they are both velocity writers
    -- and both have to be registered on the module's maid in one place), but everything that sets
    -- these up is in the Yuzi section further down. Declared here so the driver closes over the
    -- real upvalues rather than reading globals that are forever nil.
    local dashUntil, dashDir = 0, nil
    local endDashCarry

    ----------------------------------------------------------------------------------------------
    -- Isolation helpers. Every single call into BedWars goes through one of these, so a field that
    -- moved in a game update costs one action rather than the run.
    ----------------------------------------------------------------------------------------------
    local function safe(fn, ...)
        if type(fn) ~= 'function' then return false end
        local ok, res = pcall(fn, ...)
        if ok then return true, res end
        return false
    end

    local function ask(fn, ...)
        local ok, res = safe(fn, ...)
        if ok then return res end
        return nil
    end

    ----------------------------------------------------------------------------------------------
    -- Run state, all in one table so a reset is a single assignment rather than a dozen forgotten
    -- variables. Anything the brain remembers between ticks lives here.
    ----------------------------------------------------------------------------------------------
    local run_ = {
        phase = 'Idle',
        action = 'Waiting',
        detail = '',
        tier = 0,
        bedFails = {},
        playerFails = {},
        lastBedCount = -1,
        lastProgress = 0,
        queued = false,
        equipped = false,
        deaths = 0,
        lastGear = 0,
        selfResetAt = 0,
        lostBed = false,
    }

    local function resetRun()
        run_.tier = 0
        run_.bedFails = {}
        run_.playerFails = {}
        run_.lastBedCount = -1
        run_.lastProgress = tick()
        run_.queued = false
        run_.equipped = false
        run_.lastEquipTry = 0
        -- Deaths since the last trip to the shop, and when that trip was. Together they are what
        -- turns "I keep dying on the way out" into "go and buy something" instead of into another
        -- identical attempt.
        run_.deaths = 0
        run_.lastGear = 0
        run_.selfResetAt = 0
        run_.lostBed = false
    end

    local function running(gen)
        return AutoWin ~= nil and AutoWin.Enabled and (gen == nil or gen == generation)
    end

    local function maxTier()
        return TIER_CEILING[Aggression and Aggression.Value or 'Balanced'] or 2
    end

    ----------------------------------------------------------------------------------------------
    -- HUD. AutoWin is created with a Size, so the GUI hands us a draggable frame in AutoWin.Children
    -- that is shown exactly while the module is on. Progress goes here rather than into
    -- notifications, because an eight hour run would otherwise be an eight hour notification spam.
    ----------------------------------------------------------------------------------------------
    local hudPhase, hudAction, hudDetail, hudStock, hudFrame

    local function ironCount()
        local item = ask(getItem, 'iron')
        return item and item.amount or 0
    end

    local function blockName()
        local wool = ask(getWool)
        if wool then return wool end
        local inv = store.inventory and store.inventory.inventory
        if not inv or not inv.items then return nil end
        for _, item in pairs(inv.items) do
            local meta = bedwars.ItemMeta[item.itemType]
            if meta and meta.block and (item.amount or 0) > 0 then
                local bad = false
                for _, word in ipairs(BAD_BLOCKS) do
                    if string.find(item.itemType, word) then bad = true end
                end
                if not bad then return item.itemType end
            end
        end
        return nil
    end

    local function blockCount()
        local name = blockName()
        if not name then return 0 end
        local item = ask(getItem, name)
        return item and item.amount or 0
    end

    local function refreshHUD()
        if not hudPhase then return end
        hudPhase.Text = run_.phase
        hudAction.Text = run_.action
        hudDetail.Text = run_.detail
        local tierText = run_.tier > 0 and ('  |  esc ' .. run_.tier) or ''
        hudStock.Text = ironCount() .. ' iron   ' .. blockCount() .. ' blocks' .. tierText
    end

    -- Any argument left nil keeps whatever is showing, and identical text is a no-op, so this is
    -- safe to call on every tick.
    local function status(phase, action, detail)
        local changed = false
        if phase and phase ~= run_.phase then run_.phase, changed = phase, true end
        if action and action ~= run_.action then run_.action, changed = action, true end
        if detail ~= nil and detail ~= run_.detail then run_.detail = detail end
        if changed and action and Notify and Notify.Enabled then
            safe(notif, 'AutoWin', action, 4)
        end
        refreshHUD()
    end

    ----------------------------------------------------------------------------------------------
    -- Handing the queue to the lobby.
    ----------------------------------------------------------------------------------------------
    local function writeState()
        safe(function()
            local data = {
                enabled = AutoWin ~= nil and AutoWin.Enabled or false,
                resume = ResumeInLobby ~= nil and ResumeInLobby.Enabled or false,
                queue = Gamemode and Gamemode.Value or 'Current',
                fallback = store.queueType,
                stamp = os.time()
            }
            writefile(STATE_FILE, httpService:JSONEncode(data))
        end)
    end

    ----------------------------------------------------------------------------------------------
    -- Driving other modules.
    --
    -- Take over remembers a module's enabled state and every option it changes, applies what the
    -- run wants, and puts all of it back on stop - including when the stop is a config load, an
    -- uninject or an error, because the restore is registered on the module's own maid rather than
    -- being something the brain has to remember to do.
    ----------------------------------------------------------------------------------------------
    local driven = {}

    -- Modules live in three places now: the category tabs, the Legit window and the Kits
    -- window. AutoWin drives kit modules (and could drive anything else that moved), so look
    -- in all of them rather than only the tabs.
    local function moduleByName(name)
        if vape.Modules and vape.Modules[name] then return vape.Modules[name] end
        for _, panel in {vape.Kits, vape.Legit} do
            if panel and panel.Modules and panel.Modules[name] then
                return panel.Modules[name]
            end
        end
        return nil
    end

    local function optionOf(module, name)
        if not module or not module.Options then return nil end
        return module.Options[name]
    end

    -- Set one option and remember what it was. Toggles are flipped, sliders and dropdowns are set.
    local function driveOption(module, name, value, record)
        local option = optionOf(module, name)
        if not option then return end
        if type(value) == 'boolean' then
            if option.Enabled == nil or option.Enabled == value then return end
            table.insert(record, {option = option, kind = 'toggle'})
            safe(function() option:Toggle() end)
        elseif option.SetValue then
            if option.Value == value then return end
            table.insert(record, {option = option, kind = 'value', old = option.Value})
            safe(function() option:SetValue(value) end)
        end
    end

    -- `options` is a plain name -> wanted-value map. Returns whether the module is on afterwards,
    -- so callers can fall back to their own implementation when it is missing entirely. `force` is
    -- for the escalation rungs, which are the Aggression setting's own promise and so are not
    -- something the Take over toggle should be able to veto.
    local function takeOver(name, options, force)
        if not force and (not TakeOver or not TakeOver.Enabled) then return false end
        local module = moduleByName(name)
        if not module then return false end
        if driven[name] then return module.Enabled end

        local record = {turnedOn = false, options = {}}
        driven[name] = record

        if options then
            for optionName, value in pairs(options) do
                driveOption(module, optionName, value, record.options)
            end
        end
        if not module.Enabled then
            safe(function() module:Toggle(true) end)
            -- A module whose toggle refused (one that errored out on the way in, say) leaves
            -- Enabled alone. Recording that we switched it on would make the restore switch it
            -- ON at the end of the run, which is the opposite of putting things back.
            record.turnedOn = module.Enabled == true
        end
        return module.Enabled
    end

    -- Turn a driven module back off without releasing it, for the escalation rungs that are only
    -- wanted while a specific stall is being worked through.
    local function releaseOne(name)
        local record = driven[name]
        if not record then return end
        driven[name] = nil
        local module = moduleByName(name)
        if module then
            if record.turnedOn and module.Enabled then
                safe(function() module:Toggle(true) end)
            end
            for _, entry in ipairs(record.options) do
                if entry.kind == 'toggle' then
                    safe(function() entry.option:Toggle() end)
                elseif entry.option.SetValue then
                    safe(function() entry.option:SetValue(entry.old) end)
                end
            end
        end
    end

    local function releaseAll()
        local names = {}
        for name in pairs(driven) do table.insert(names, name) end
        for _, name in ipairs(names) do releaseOne(name) end
    end

    local function isDriving(name)
        return driven[name] ~= nil
    end

    -- Anything that owns the character's velocity. While one of these is on, the walker below
    -- stops asserting velocity itself, because two writers fighting over AssemblyLinearVelocity is
    -- how a character ends up vibrating on the spot instead of going anywhere.
    local function movementModuleActive()
        for _, name in ipairs({'Fly', 'InfiniteFly', 'Speed', 'LongJump', 'Scaffold', 'TPAura'}) do
            local module = moduleByName(name)
            if module and module.Enabled then return true end
        end
        return false
    end

    ----------------------------------------------------------------------------------------------
    -- Character basics.
    ----------------------------------------------------------------------------------------------
    local function myRoot()
        local char = entitylib.character
        if entitylib.isAlive and char and char.RootPart and char.RootPart.Parent then
            return char.RootPart, char
        end
        return nil
    end

    -- store.rootpart means GodMode/AntiDeath has parked the hitbox somewhere. Moving the character
    -- then would drag their parked copy around, so the run holds still until they are done.
    local function alive()
        return entitylib.isAlive and not store.rootpart and myRoot() ~= nil
    end

    -- Distance from the root's centre down to the soles. entitylib already folds the root's half
    -- height (and R6's leg length) into character.HipHeight, so adding root.Size.Y * 0.5 on top of
    -- it - as this used to - double counted it by a stud and left footCell only half a stud of
    -- margin before it started reporting the cell below the one we are standing on.
    local function hipOf(char, root)
        if char and char.HipHeight then return char.HipHeight end
        local humanoid = char and char.Humanoid
        local half = root and root.Size and (root.Size.Y * 0.5) or 1
        return (humanoid and humanoid.HipHeight or 2) + half
    end

    ----------------------------------------------------------------------------------------------
    -- Teams, beds and enemies.
    ----------------------------------------------------------------------------------------------
    local function partOf(obj)
        if not obj then return nil end
        if obj:IsA('BasePart') then return obj end
        return obj.PrimaryPart or obj:FindFirstChildWhichIsA('BasePart')
    end

    -- Our team id. The player attribute is authoritative but is briefly absent right after a spawn
    -- or a teleport, so fall back to the match store and then the character. Every bed and target
    -- decision keys off this: a wrong answer here is what makes a run bridge to its own bed.
    local function myTeam()
        local team = lplr:GetAttribute('Team')
        if team == nil then
            local state = ask(function() return bedwars.Store:getState().Game.myTeam end)
            team = state and state.id
        end
        if team == nil and lplr.Character then
            team = lplr.Character:GetAttribute('Team')
        end
        return team
    end

    -- Unknown team returns false rather than true: skipping a bed for a moment costs nothing,
    -- treating our own bed as fair game costs the game.
    local function isEnemyBed(bed)
        local team = myTeam()
        if team == nil then return false end
        return not bed:GetAttribute('Team' .. team .. 'NoBreak')
    end

    local function bedShielded(bed)
        return (bed:GetAttribute('BedShieldEndTime') or 0) > workspace:GetServerTimeNow()
    end

    local function enemyBeds()
        local beds = {}
        for _, bed in ipairs(collectionService:GetTagged('bed')) do
            if bed.Parent and partOf(bed) and isEnemyBed(bed) then
                table.insert(beds, bed)
            end
        end
        return beds
    end

    -- Our own bed still standing? Without it a respawn is an elimination, so every reset below
    -- checks this first.
    local function ownBedAlive()
        local team = myTeam()
        if team == nil then return false end
        for _, bed in ipairs(collectionService:GetTagged('bed')) do
            if bed.Parent and partOf(bed) and bed:GetAttribute('Team' .. team .. 'NoBreak') then
                return true
            end
        end
        return false
    end

    -- Our bed is gone, so the next death ends the match for us rather than costing a few seconds.
    -- Latched, because a bed never comes back and myTeam() is briefly nil around a spawn - without
    -- the latch the run would flap in and out of playing carefully at exactly the wrong moment.
    local function lastLife()
        if run_.lostBed then return true end
        if myTeam() == nil then return false end
        if not ownBedAlive() then
            run_.lostBed = true
            return true
        end
        return false
    end

    local function healthFraction()
        local char = entitylib.character
        if not char or not char.MaxHealth or char.MaxHealth <= 0 then return 1 end
        return math.clamp((char.Health or 0) / char.MaxHealth, 0, 1)
    end

    -- How far up the armour ladder we are, 0 for nothing. Worn armour first, then the best piece in
    -- the bag - AutoTool and the game itself both equip out of the inventory, so owning it counts.
    local function armourTier()
        local worn = ask(function()
            local armour = store.inventory.inventory.armor
            local entry = armour and armour[2]
            if entry and entry ~= 'empty' and entry.itemType then return entry.itemType end
            local best = getBestArmor(1)
            return best and best.itemType or nil
        end)
        if not worn then return 0 end
        return table.find(ARMOUR_TIERS, worn) or 0
    end

    local function bedName(bed)
        local team = bed:GetAttribute('Team') or bed:GetAttribute('TeamName')
        if type(team) == 'string' then return team .. "'s bed" end
        return 'the nearest bed'
    end

    -- Nearest enemy bed we have not written off, cheapest first. Shielded beds are pushed to the
    -- back rather than skipped, so a run never stands waiting on a shield with a free bed elsewhere.
    local function pickBed(from)
        local best, bestScore
        for _, bed in ipairs(enemyBeds()) do
            if (run_.bedFails[bed] or 0) < 3 then
                local part = partOf(bed)
                if part then
                    local score = (part.Position - from).Magnitude + (bedShielded(bed) and 400 or 0)
                    if not bestScore or score < bestScore then
                        best, bestScore = bed, score
                    end
                end
            end
        end
        if not best then
            -- Everything is written off: forget the failures and try the lot again rather than
            -- standing still with beds left on the map.
            run_.bedFails = {}
            for _, bed in ipairs(enemyBeds()) do
                local part = partOf(bed)
                if part then
                    local score = (part.Position - from).Magnitude
                    if not bestScore or score < bestScore then
                        best, bestScore = bed, score
                    end
                end
            end
        end
        return best
    end

    local function pickEnemy()
        if not entitylib.isAlive then return nil end
        local team = myTeam()
        local all = entitylib.AllPosition({
            Range = math.huge,
            Players = true,
            NPCs = false,
            Part = 'RootPart',
            Sort = sortmethods.Distance
        })
        local best, bestScore
        for _, ent in ipairs(all) do
            -- AllPosition already drops anything entitylib marks un-targetable, but that flag is
            -- computed when an entity spawns and can be stale for a player whose team arrived a
            -- frame later, so the team is re-checked here. A teammate is never a target.
            local ok = ent.Player and ent.Targetable and ent.RootPart and ent.RootPart.Parent
            if ok and team ~= nil and ent.Player:GetAttribute('Team') == team then ok = false end
            if ok and (run_.playerFails[ent.Character] or 0) >= 2 then ok = false end
            if ok then
                local root = myRoot()
                local score = root and (ent.RootPart.Position - root.Position).Magnitude or 0
                if not bestScore or score < bestScore then
                    best, bestScore = ent, score
                end
            end
        end
        if not best then run_.playerFails = {} end
        return best
    end

    ----------------------------------------------------------------------------------------------
    -- The block grid.
    ----------------------------------------------------------------------------------------------
    local cellParams = RaycastParams.new()
    cellParams.FilterType = Enum.RaycastFilterType.Exclude
    cellParams.RespectCanCollide = true

    local function cellOf(pos)
        return bedwars.BlockController:getBlockPosition(pos)
    end

    local function worldOf(cell)
        return cell * CELL
    end

    -- Solidity is asked for thousands of times per route, so it is cached for a fraction of a
    -- second. Short enough that a block we just placed is seen almost immediately, long enough that
    -- one A* pass is not thousands of raycasts.
    local solidCache, solidStamp = {}, 0

    local function clearGrid()
        solidCache = {}
        solidStamp = tick()
    end

    -- Pack a cell into one number to key the cache with. The strides have to be larger than the
    -- widest a component can get after the offset, or cells alias onto each other and the router
    -- reads one cell's solidity for another - which shows up as a bridge built into thin air.
    -- +-1024 cells is +-3072 studs, comfortably past the edge of any map.
    local KEY_SPAN, KEY_BIAS = 2048, 1024
    local function cellKey(cell)
        return (cell.X + KEY_BIAS) * (KEY_SPAN * KEY_SPAN) + (cell.Y + KEY_BIAS) * KEY_SPAN + (cell.Z + KEY_BIAS)
    end

    local function solidAt(cell)
        if tick() - solidStamp > 0.3 then clearGrid() end
        local key = cellKey(cell)
        local cached = solidCache[key]
        if cached ~= nil then return cached end

        local world = worldOf(cell)
        local result = ask(getPlacedBlock, world) ~= nil
        if not result then
            cellParams.FilterDescendantsInstances = {lplr.Character, gameCamera, AntiFallPart}
            result = workspace:Raycast(world + Vector3.new(0, 1.45, 0), Vector3.new(0, -2.9, 0), cellParams) ~= nil
        end
        solidCache[key] = result
        return result
    end

    local function forgetCell(cell)
        solidCache[cellKey(cell)] = nil
    end

    -- The cell our feet are resting on, derived from the real hip height rather than assumed, so
    -- R6, R15 and every kit that changes the character's size all land on the right row.
    local function footCell(root, char)
        local pos = root.Position
        return cellOf(Vector3.new(pos.X, pos.Y - hipOf(char, root) - STAND, pos.Z))
    end

    local function isBadBlock(itemType)
        for _, word in ipairs(BAD_BLOCKS) do
            if string.find(itemType, word) then return true end
        end
        return false
    end

    local function placeAt(cell)
        if solidAt(cell) then return true end
        local name = blockName()
        if not name or isBadBlock(name) then return false end
        safe(bedwars.placeBlock, worldOf(cell), name)
        forgetCell(cell)
        return true
    end

    local function breakAt(cell)
        local block = ask(getPlacedBlock, worldOf(cell))
        if not block then return true end
        safe(bedwars.breakBlock, block, true, true, nil, true, breakmethods.Distance, 360, false)
        forgetCell(cell)
        return ask(getPlacedBlock, worldOf(cell)) == nil
    end

    ----------------------------------------------------------------------------------------------
    -- Route finding.
    --
    -- A* over the grid. A cell can be walked on if something is already there, or if we are
    -- carrying blocks and can put something there; a cell we would have to walk THROUGH can be
    -- mined out when breaking is allowed. Costs are what make the route sensible rather than merely
    -- possible: existing ground is cheapest, bridging costs a block, mining costs time, and towering
    -- straight up costs most of all - so it goes round things it can go round, and only builds when
    -- building is genuinely the way.
    ----------------------------------------------------------------------------------------------
    local HEAD_CELLS = {Vector3.new(0, 1, 0), Vector3.new(0, 2, 0)}
    local STEP_DIRS = {Vector3.new(1, 0, 0), Vector3.new(-1, 0, 0), Vector3.new(0, 0, 1), Vector3.new(0, 0, -1)}
    local DROPS = {0, 1, -1, -2, -3}

    -- Minimal binary heap. A linear open list turns a long route into a visible frame hitch.
    local function heapPush(heap, node, priority)
        local index = #heap + 1
        heap[index] = {node = node, priority = priority}
        while index > 1 do
            local parent = math.floor(index / 2)
            if heap[parent].priority <= heap[index].priority then break end
            heap[parent], heap[index] = heap[index], heap[parent]
            index = parent
        end
    end

    local function heapPop(heap)
        local size = #heap
        if size == 0 then return nil end
        local top = heap[1]
        heap[1] = heap[size]
        heap[size] = nil
        size = size - 1
        local index = 1
        while true do
            local left, right, smallest = index * 2, index * 2 + 1, index
            if left <= size and heap[left].priority < heap[smallest].priority then smallest = left end
            if right <= size and heap[right].priority < heap[smallest].priority then smallest = right end
            if smallest == index then break end
            heap[index], heap[smallest] = heap[smallest], heap[index]
            index = smallest
        end
        return top.node
    end

    -- Can we stand on `cell` with our head clear? Returns nil when we cannot, or the extra cost of
    -- getting it into that state (placing a block, mining what is in the way).
    local function stepCost(cell, canPlace, allowBreak)
        local extra = 0
        if not solidAt(cell) then
            if not canPlace then return nil end
            extra = extra + 1.4
        end
        for _, offset in ipairs(HEAD_CELLS) do
            local head = cell + offset
            if solidAt(head) then
                if not allowBreak then return nil end
                if ask(getPlacedBlock, worldOf(head)) == nil then return nil end
                extra = extra + 2.2
            end
        end
        return extra
    end

    local function heuristic(cell, goal)
        local dx = math.abs(cell.X - goal.X)
        local dy = math.abs(cell.Y - goal.Y)
        local dz = math.abs(cell.Z - goal.Z)
        return dx + dz + dy * 1.3
    end

    -- Returns a list of cells from just after `startCell` to the best cell it reached. When the goal
    -- is unreachable inside the budget it returns the route to whatever got closest, so the run
    -- always has somewhere to walk instead of standing still deciding it cannot.
    local function planRoute(startCell, goalCell, canPlace, allowBreak, gen)
        clearGrid()
        local budget = math.clamp(400 + heuristic(startCell, goalCell) * 30, 800, 6000)
        local limit = heuristic(startCell, goalCell) + 60

        local cameFrom, gScore, closed = {}, {}, {}
        local heap = {}
        local startKey = cellKey(startCell)
        gScore[startKey] = 0
        heapPush(heap, startCell, heuristic(startCell, goalCell))

        local bestCell, bestScore = startCell, heuristic(startCell, goalCell)
        local expansions = 0

        while true do
            local current = heapPop(heap)
            if not current then break end
            local key = cellKey(current)
            if not closed[key] then
                closed[key] = true
                expansions = expansions + 1

                local score = heuristic(current, goalCell)
                if score < bestScore then
                    bestCell, bestScore = current, score
                end
                if score <= 0.5 then
                    bestCell = current
                    break
                end
                if expansions >= budget then break end
                -- Yield periodically so a long route is spread over a few frames instead of
                -- freezing one. The generation check makes a toggle-off abandon the search.
                if expansions % 350 == 0 then
                    task.wait()
                    if not running(gen) then return nil end
                end

                local base = gScore[key] or 0
                for _, dir in ipairs(STEP_DIRS) do
                    for _, dy in ipairs(DROPS) do
                        local neighbour = current + dir + Vector3.new(0, dy, 0)
                        local nKey = cellKey(neighbour)
                        if not closed[nKey] and heuristic(neighbour, goalCell) <= limit then
                            -- Stepping up or down onto ground only works where ground already is;
                            -- only the level step is allowed to build its own footing, which is
                            -- what keeps bridges flat and staircases honest.
                            local allowedPlace = canPlace and dy == 0
                            local extra = stepCost(neighbour, allowedPlace, allowBreak)
                            if extra and (dy == 0 or solidAt(neighbour)) then
                                local cost = base + 1 + extra + (dy > 0 and 0.8 or 0) + (dy < 0 and math.abs(dy) * 0.3 or 0)
                                if cost < (gScore[nKey] or math.huge) then
                                    gScore[nKey] = cost
                                    cameFrom[nKey] = current
                                    heapPush(heap, neighbour, cost + heuristic(neighbour, goalCell))
                                end
                            end
                        end
                    end
                end

                -- Towering straight up. Expensive, and only when we have something to build with,
                -- but it is the only way onto a raised island or over a base wall.
                if canPlace then
                    local up = current + Vector3.new(0, 1, 0)
                    local upKey = cellKey(up)
                    if not closed[upKey] and heuristic(up, goalCell) <= limit then
                        local extra = stepCost(up, true, allowBreak)
                        if extra then
                            local cost = base + 2.6 + extra
                            if cost < (gScore[upKey] or math.huge) then
                                gScore[upKey] = cost
                                cameFrom[upKey] = current
                                heapPush(heap, up, cost + heuristic(up, goalCell))
                            end
                        end
                    end
                end
            end
        end

        local route, cursor = {}, bestCell
        local guard = 0
        while cursor and cellKey(cursor) ~= startKey and guard < 512 do
            table.insert(route, 1, cursor)
            cursor = cameFrom[cellKey(cursor)]
            guard = guard + 1
        end
        return route
    end

    ----------------------------------------------------------------------------------------------
    -- The walker.
    --
    -- The character WALKS. Writing a position straight onto a cell several studs away is rejected
    -- by the server's movement check and pulled back, which is what made the old hop-based build sit
    -- in place teleporting and being dragged back forever. So the humanoid is pointed at the next
    -- cell and the game moves us at the speed it gives us. There is nothing here for a server to
    -- reject.
    ----------------------------------------------------------------------------------------------
    local moveDir, driving, holdStill = Vector3.zero, false, false

    -- Jumping.
    --
    -- `Humanoid.Jump = true` on its own is not a jump in BedWars. The game drives the character
    -- through its own controller, and the flag is routinely consumed or overwritten before the
    -- humanoid's state machine ever acts on it - which is why the run used to grind into every kerb
    -- and every step-up instead of hopping over it. What actually works, and is what the rest of
    -- this script uses (the Zephyr fall clutch, Speed's AutoJump), is asking for the state change
    -- directly. The velocity assert underneath it is the backstop: if a frame later we are still
    -- not going up, we put the lift in ourselves.
    --
    -- The fallback is deliberately a one-shot impulse rather than a velocity the driver holds for
    -- the length of the window: held, it would not be a jump at all, it would be six blocks of lift
    -- and a speed check failed in front of everybody. The driver reads and rewrites Y unchanged, so
    -- one impulse is all a jump needs from us.
    local JUMP_POWER = 50
    local jumpUntil, jumpFloor = 0, 0

    local function stopMoving()
        moveDir, driving, holdStill = Vector3.zero, false, false
        jumpUntil, jumpFloor = 0, 0
    end

    -- Ask for a jump and mean it.
    local function requestJump(char, root)
        if not char or not root or not char.Humanoid then return false end
        local humanoid = char.Humanoid
        -- Only ever a jump from the floor. Asked for in mid-air the humanoid rightly refuses, and
        -- the backstop below would then read "we are not going up" and put in an impulse of its
        -- own - a double jump nobody asked for and everybody can see.
        local grounded = ask(function() return humanoid.FloorMaterial ~= Enum.Material.Air end)
        if grounded ~= true then return false end

        safe(function()
            humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
            humanoid.Jump = true
        end)
        -- The humanoid latches Jump, so clear it shortly after or it queues a second unwanted jump
        -- on the frame we land. Same shape as the Zephyr clutch.
        task.delay(0.2, function()
            safe(function()
                if humanoid.Parent then humanoid.Jump = false end
            end)
        end)
        local power = ask(function() return humanoid.JumpPower end)
        if type(power) ~= 'number' or power <= 0 then power = JUMP_POWER end
        jumpFloor = power
        jumpUntil = tick() + 0.35
        -- The backstop, and the reason this works where `Humanoid.Jump = true` did not: give the
        -- humanoid a couple of frames to do it, and put the lift in ourselves only if it plainly
        -- has not. Asserting on the same frame would stack with the humanoid's own impulse and
        -- launch us a block too high, which reads to the server as a speed hack.
        task.delay(0.06, function()
            if tick() > jumpUntil then return end
            if movementModuleActive() then return end
            local now = myRoot()
            if not now or not isnetworkowner(now) then return end
            local velocity = now.AssemblyLinearVelocity
            if velocity.Y < jumpFloor * 0.45 then
                now.AssemblyLinearVelocity = Vector3.new(velocity.X, jumpFloor, velocity.Z)
            end
        end)
        return true
    end

    local function startDriver(gen)
        AutoWin:Clean(runService.Stepped:Connect(function()
            if not running(gen) or not driving then return end
            if store.rootpart then return end
            local root, char = myRoot()
            if not root or not char or not char.Humanoid then return end

            -- Point the humanoid so it turns to face the way we are going and plays the walk.
            safe(function() char.Humanoid:Move(moveDir, false) end)

            -- ...but do not rely on Humanoid:Move alone. BedWars drives the character through its
            -- own controller, which can leave a scripted Move doing nothing at all. Asserting the
            -- same movement as velocity is what makes the walk actually start - at the humanoid's
            -- own walk speed, so it stays well inside the server's speed check. Skipped entirely
            -- while a movement module owns the velocity, because two writers fighting over it is
            -- how a character ends up vibrating instead of travelling.
            if movementModuleActive() then return end
            if not isnetworkowner(root) then return end
            -- Y is read and written back untouched, in every branch: the horizontal is ours to
            -- drive, the vertical belongs to the jump and to gravity.
            local velocity = root.AssemblyLinearVelocity
            if moveDir.Magnitude > 0 and not holdStill then
                local speed = char.Humanoid.WalkSpeed
                if speed <= 0 then speed = 16 end
                local horizontal = moveDir.Unit * speed
                root.AssemblyLinearVelocity = Vector3.new(horizontal.X, velocity.Y, horizontal.Z)
            else
                root.AssemblyLinearVelocity = Vector3.new(0, velocity.Y, 0)
            end
        end))

        -- The dash driver. Separate from the walker above because a dash happens with the walker
        -- deliberately switched off (dashToward calls stopMoving first), and because it has to run
        -- on PreSimulation - the same step LongJump and Speed write on - to survive the frame.
        AutoWin:Clean(runService.PreSimulation:Connect(function(dt)
            if not dashDir or tick() >= dashUntil then return end
            if not running(gen) or store.rootpart then
                endDashCarry()
                return
            end
            local root, char = myRoot()
            if not root or not char or not char.Humanoid then
                endDashCarry()
                return
            end
            if not isnetworkowner(root) then return end

            local velocity = root.AssemblyLinearVelocity
            local flat = Vector3.new(velocity.X, 0, velocity.Z).Magnitude
            -- Where the game's own handler ran, it is already carrying us faster than this, and the
            -- right thing to do is nothing at all. Taking the max instead would read back our own
            -- write every frame and pin the launch at its peak for the whole window - a dash that
            -- never decays and goes half again as far as a real one.
            if flat < DASH_SPEED then
                root.AssemblyLinearVelocity = Vector3.new(dashDir.X * DASH_SPEED, velocity.Y, dashDir.Z * DASH_SPEED)
            end

            -- A dash travels flat. Left to gravity, a launch fired across a gap arrives below the
            -- far edge and the run ends in the void, so most of the fall is cancelled for the few
            -- frames the launch lasts - exactly what the game's own dash does.
            if char.Humanoid.FloorMaterial == Enum.Material.Air and velocity.Y < 0 then
                root.AssemblyLinearVelocity += Vector3.new(0, dt * workspace.Gravity * 0.85, 0)
            end
        end))
        AutoWin:Clean(endDashCarry)
        AutoWin:Clean(stopMoving)
    end

    -- Climb one level: jump, and drop a block into the cell our feet just left. Placing at the apex
    -- is too late - you are already falling back down before the block exists - so it goes in as
    -- soon as we are clear of the cell.
    local function towerUp(cell, gen)
        local root, char = myRoot()
        if not root or not char or not char.Humanoid then return end
        if not blockName() then return end
        holdStill = true
        moveDir = Vector3.zero
        local startY = root.Position.Y
        requestJump(char, root)
        local deadline = tick() + 0.8
        local placed = false
        while running(gen) and tick() < deadline do
            task.wait()
            local current = myRoot()
            if not current then break end
            if current.Position.Y - startY >= CELL + 0.2 then
                placeAt(cell + Vector3.new(0, 1, 0))
                placed = true
                break
            end
        end
        holdStill = false
        return placed
    end

    ----------------------------------------------------------------------------------------------
    -- Travel.
    --
    -- One call walks us to a moving target, re-planning whenever the world stops agreeing with the
    -- plan. It returns as soon as anything happens that the brain needs to re-decide on - arrival,
    -- death, the target vanishing, the match ending - so the brain is never stuck inside it.
    --
    -- Returns 'arrived', 'lost', 'noblocks', 'stuck' or 'abort'.
    ----------------------------------------------------------------------------------------------
    local LOOKAHEAD = 3

    local function travel(gen, getGoal, stopRange, allowBreak, label, budget)
        local deadline = tick() + (budget or 45)
        local route, routeIndex, plannedGoal = nil, 1, nil
        local best, stallSince = math.huge, tick()
        local lastJump, lastPlan = 0, 0
        -- Ground truth for "am I actually moving". Distance-to-goal cannot answer that: strafing
        -- along a wall closes no distance while moving perfectly well, and grinding into a kerb
        -- closes no distance while moving not at all. Comparing where we WERE separates the two,
        -- and pressed-into-something is the case a jump fixes.
        local lastPos, lastPosAt = nil, tick()
        driving = true

        while running(gen) and tick() < deadline do
            if not alive() then
                stopMoving()
                return 'abort'
            end
            local goal = getGoal()
            local root, char = myRoot()
            if not goal or not root or not char then
                stopMoving()
                return 'lost'
            end

            local flat = ((goal - root.Position) * Vector3.new(1, 0, 1)).Magnitude
            if flat <= stopRange and math.abs(goal.Y - root.Position.Y) <= 14 then
                stopMoving()
                return 'arrived'
            end

            status(nil, label, string.format('%d studs  |  %d blocks', math.floor(flat), blockCount()))

            -- Progress is measured in three dimensions. Towering to a raised bed closes no
            -- horizontal distance at all, and judging it flat would call a climb that is working
            -- perfectly well a stall.
            local remaining = (goal - root.Position).Magnitude
            if remaining < best - 1.5 then
                best, stallSince = remaining, tick()
                run_.lastProgress = tick()
            elseif tick() - stallSince > 6 then
                -- Not moving. Re-plan first (cheap, and usually enough after a block landed or an
                -- enemy filled a gap), then climb the escalation ladder.
                stallSince = tick()
                route = nil
                if run_.tier < maxTier() then
                    run_.tier = run_.tier + 1
                    -- Applied here rather than left for the brain's next tick: a crossing can spend
                    -- a minute inside this loop, and an escalation that only takes effect once we
                    -- return is an escalation that never happens where it was needed.
                    applyTier()
                    status(nil, nil, 'stalled - escalating to ' .. run_.tier)
                elseif tick() - run_.lastProgress > 40 then
                    stopMoving()
                    return 'stuck'
                end
            end

            local here = footCell(root, char)
            local goalCell = cellOf(Vector3.new(goal.X, goal.Y - STAND, goal.Z))

            -- Re-plan when there is no route, the target has walked away from the one we have, or
            -- we have fallen off it entirely.
            local needsPlan = route == nil or routeIndex > #route
            if not needsPlan and plannedGoal and (goalCell - plannedGoal).Magnitude > 2 then needsPlan = true end
            if not needsPlan and route[routeIndex] and (route[routeIndex] - here).Magnitude > 3.5 then needsPlan = true end
            if needsPlan and tick() - lastPlan < 0.35 then
                -- Never re-plan twice in the same breath; it turns a stall into a slideshow.
                task.wait(0.1)
            elseif needsPlan then
                lastPlan = tick()
                plannedGoal = goalCell
                route = planRoute(here, goalCell, blockCount() > 0, allowBreak, gen)
                routeIndex = 1
                if not running(gen) then
                    stopMoving()
                    return 'abort'
                end
                if not route or #route == 0 then
                    -- Nowhere to go at all. With no blocks that is simply the answer; with blocks
                    -- it means the search is boxed in, which the escalation above will handle.
                    if blockCount() <= 0 then
                        stopMoving()
                        return 'noblocks'
                    end
                    task.wait(0.15)
                end
            end

            if route and route[routeIndex] then
                -- Advance the cursor past everything we have already walked over.
                local guard = 0
                while route[routeIndex] and (route[routeIndex] - here).Magnitude < 0.6 and guard < 8 do
                    routeIndex = routeIndex + 1
                    guard = guard + 1
                end

                local next_ = route[routeIndex]
                if next_ then
                    -- Footing. Blocks are asked for several cells early, because walking covers a
                    -- cell in about a seventh of a second and a placement does not come back that
                    -- fast. Nothing is ever stepped onto before the block has actually arrived.
                    for offset = 0, LOOKAHEAD do
                        local cell = route[routeIndex + offset]
                        if not cell then break end
                        if not solidAt(cell) then
                            if not blockName() then
                                stopMoving()
                                return 'noblocks'
                            end
                            placeAt(cell)
                        end
                    end

                    -- Head room. Mine placed blocks out of the way when allowed - that is how we
                    -- tunnel into a base - and treat map geometry as a wall to route around.
                    local blocked = false
                    for _, offset in ipairs(HEAD_CELLS) do
                        local head = next_ + offset
                        if solidAt(head) then
                            if allowBreak and ask(getPlacedBlock, worldOf(head)) then
                                status(nil, 'Mining through', '')
                                breakAt(head)
                            end
                            if solidAt(head) then blocked = true end
                        end
                    end

                    if blocked then
                        route = nil
                        moveDir = Vector3.zero
                        task.wait(0.1)
                    elseif not solidAt(next_) then
                        -- The block we asked for has not landed. Hold on the edge rather than
                        -- walking off it, and pick the walk up on a later pass.
                        moveDir = Vector3.zero
                        task.wait(0.05)
                    else
                        local aim = worldOf(next_) + Vector3.new(0, STAND + hipOf(char, root), 0)
                        local delta = (aim - root.Position) * Vector3.new(1, 0, 1)
                        moveDir = delta.Magnitude > 0.05 and delta.Unit or Vector3.zero

                        local canJump = tick() - lastJump > 0.35
                        if next_.Y > here.Y and canJump then
                            lastJump = tick()
                            -- Straight up (the cell directly overhead) is a tower and needs a block
                            -- under our feet on the way. A step UP AND ALONG is just a jump - it
                            -- used to be sent to towerUp too as soon as we got within half a cell,
                            -- which stood still, jumped, and dropped a block on our own head
                            -- instead of stepping onto the ledge in front of us.
                            local sameColumn = next_.X == here.X and next_.Z == here.Z
                            if sameColumn and delta.Magnitude <= CELL * 0.5 then
                                towerUp(here, gen)
                            else
                                requestJump(char, root)
                            end
                        elseif canJump and lastPos and moveDir.Magnitude > 0 and not holdStill then
                            -- Pressed into something the route thinks is walkable: a kerb, a block
                            -- an enemy dropped in front of us, the lip of our own bridge. Nothing
                            -- above ever asked for a jump here, so the run just leaned on it until
                            -- the stall timer escalated. Hop it.
                            local moved = (root.Position - lastPos).Magnitude
                            if moved < 0.35 and tick() - lastPosAt > 0.3 and char.Humanoid.FloorMaterial ~= Enum.Material.Air then
                                lastJump = tick()
                                requestJump(char, root)
                            end
                        end

                        if not lastPos or (root.Position - lastPos).Magnitude > 0.35 then
                            lastPos, lastPosAt = root.Position, tick()
                        end
                        task.wait()
                    end
                else
                    task.wait(0.05)
                end
            else
                task.wait(0.05)
            end
        end

        stopMoving()
        if not running(gen) then return 'abort' end
        return 'stuck'
    end

    ----------------------------------------------------------------------------------------------
    -- Yuzi.
    --
    -- The dash is cast directly rather than by switching LongJump on, because LongJump pins your
    -- velocity the moment its own boost window closes - left on, that holds the run frozen in place,
    -- and it is why crossings used to end standing still in mid-map.
    --
    -- FIRING THE REMOTE IS NOT A DASH. This is the part that made the run "use its ability and stay
    -- exactly where it was": the raw useAbility FireServer is taken by the server - it stamps the
    -- cooldown, plays the effect, and CanDashNext moves forward, so from the outside the dash was
    -- genuinely spent - but the MOVEMENT is applied on the client, by the game's own ability
    -- handler, which a bare FireServer never runs. LongJump gets away with the same remote only
    -- because it then drives the velocity itself for the next two seconds. So the cast goes through
    -- the AbilityController (the real dash, handler and all), the remote is kept as the fallback
    -- for builds where that signature has moved, and either way the launch is carried by the dash
    -- driver below - which is what makes the crossing land whether the handler ran or not.
    --
    -- Every launch is checked first. A dash is a flat line fired blind, so anything solid in the way
    -- was a wall taken at full speed and a launch that came up short of the far island was a fall
    -- into the void. Beam clear and a landing with ground under it, or we do not launch.
    ----------------------------------------------------------------------------------------------
    local dashRay = RaycastParams.new()
    dashRay.RespectCanCollide = true
    dashRay.FilterType = Enum.RaycastFilterType.Exclude

    -- Deliberately short to begin with, then tracked against how far dashes actually carry on this
    -- kit and this map rather than assumed.
    local dashRange = 30

    local function hasYuziKit()
        local kit = store.equippedKit
        if kit == nil or kit == '' then kit = lplr:GetAttribute('PlayingAsKit') end
        if kit == nil then return false end
        return YUZI_KITS[string.lower(tostring(kit))] == true
    end

    local function getDao()
        local hand = store.hand and store.hand.tool
        if hand and table.find(DAO_TIERS, hand.Name) then
            return ask(getItem, hand.Name)
        end
        -- Best tier we own, so a dash is never fired off the wooden one while an emerald is in the
        -- bag: the dao in hand is also the sword the fight after it is taken with.
        for index = #DAO_TIERS, 1, -1 do
            local item = ask(getItem, DAO_TIERS[index])
            if item then return item end
        end
        return nil
    end

    local function dashReady()
        local ready = ask(function()
            return (lplr.Character:GetAttribute('CanDashNext') or 0) < workspace:GetServerTimeNow()
                and bedwars.AbilityController:canUseAbility('dash')
        end)
        return ready == true
    end

    local function flatDistance(from, to)
        return ((to - from) * Vector3.new(1, 0, 1)).Magnitude
    end

    local function dashFilter()
        dashRay.FilterDescendantsInstances = {lplr.Character, gameCamera, AntiFallPart}
    end

    -- Cast at chest height, not from the feet: a dash rides over a one-block lip, and casting low
    -- reads every kerb as a wall and refuses to ever launch.
    local function beamClear(from, target)
        dashFilter()
        local origin = from + Vector3.new(0, 2, 0)
        local aim = Vector3.new(target.X, origin.Y, target.Z)
        local delta = aim - origin
        if delta.Magnitude < 1 then return true end
        return workspace:Raycast(origin, delta, dashRay) == nil
    end

    -- Would this launch put us down over open air? Only a question when the target is further off
    -- than one dash carries; inside that, we arrive at the target itself.
    local function landingSafe(from, target)
        if flatDistance(from, target) <= dashRange then return true end
        local delta = Vector3.new(target.X, from.Y, target.Z) - from
        if delta.Magnitude < 1 then return true end
        dashFilter()
        local landing = from + delta.Unit * dashRange
        return workspace:Raycast(landing + Vector3.new(0, 8, 0), Vector3.new(0, -60, 0), dashRay) ~= nil
    end

    -- Hand the launch to the driver in startDriver. Friction is dropped for its length the same way
    -- every other movement module in this script does it, or the character's own drag bleeds most
    -- of the launch off before it has covered anything.
    local function beginDashCarry(direction)
        local flat = Vector3.new(direction.X, 0, direction.Z)
        if flat.Magnitude < 0.1 then return end
        dashDir = flat.Unit
        dashUntil = tick() + DASH_CARRY
        frictionTable.AutoWin = true
        updateVelocity()
    end

    function endDashCarry()
        dashUntil, dashDir = 0, nil
        if frictionTable.AutoWin then
            frictionTable.AutoWin = nil
            updateVelocity()
        end
    end

    local function fireDash(direction, origin, item)
        local data = {
            direction = direction,
            origin = origin,
            weapon = item.itemType
        }
        safe(function() bedwars.SwordController.lastAttack = workspace:GetServerTimeNow() end)

        -- The controller first: this is the call that runs the client-side dash handler, and so the
        -- only one of the three that moves you on its own. Both signatures are tried because the
        -- middle argument has come and gone across BedWars builds - same ladder useToolAbility uses.
        local cast = ask(function()
            return bedwars.AbilityController:useAbility('dash', newproxy(true), data)
        end)
        if cast == nil or cast == false then
            cast = ask(function()
                return bedwars.AbilityController:useAbility('dash', data)
            end)
        end
        if cast == nil or cast == false then
            cast = ask(function()
                local events = replicatedStorage['events-@easy-games/game-core:shared/game-core-networking@getEvents.Events']
                events.useAbility:FireServer('dash', data)
                return true
            end)
        end
        if cast == nil or cast == false then return false end

        beginDashCarry(direction)
        return true
    end

    -- Dash at a (possibly moving) target until we are in range. Returning false simply means the
    -- caller bridges the rest, so this can never strand a run.
    local function dashToward(gen, getGoal, stopRange, label)
        if not YuziDash or not YuziDash.Enabled then return false end
        local best, stalled = math.huge, 0

        for _ = 1, 10 do
            if not running(gen) or not alive() then break end
            local goal, root = getGoal(), myRoot()
            if not goal or not root then break end

            local left = flatDistance(root.Position, goal)
            if left <= stopRange + 4 then break end
            if left < best - 4 then
                best, stalled = left, 0
                run_.lastProgress = tick()
            else
                stalled = stalled + 1
                -- Two dashes that got us no closer means the way is blocked or the drop is wrong.
                -- Stop wasting them and hand back to the bridge.
                if stalled >= 2 then break end
            end

            local dao = getDao()
            if not dao or not dao.tool then break end
            if not (beamClear(root.Position, goal) and landingSafe(root.Position, goal)) then break end

            local waitUntil = tick() + 4
            while running(gen) and alive() and not dashReady() and tick() < waitUntil do
                status('Yuzi', 'Waiting on the dash', string.format('%d studs', math.floor(left)))
                task.wait(0.1)
            end
            if not dashReady() then break end

            stopMoving()
            -- The dao has to genuinely be in hand before the ability is fired; the server reads the
            -- held weapon, and store.hand only catches up on the next store update.
            safe(switchItem, dao.tool, 0.1)
            local handDeadline = tick() + 0.6
            while running(gen) and tick() < handDeadline and not (store.hand and store.hand.tool == dao.tool) do
                task.wait(0.05)
            end

            root = myRoot()
            if not root then break end
            local direction = (Vector3.new(goal.X, root.Position.Y, goal.Z) - root.Position)
            if direction.Magnitude < 1 then break end
            direction = direction.Unit
            root.CFrame = CFrame.lookAt(root.Position, root.Position + direction)
            status('Yuzi', label or 'Dashing', string.format('%d studs', math.floor(left)))

            local launchFrom = root.Position
            if not fireDash(direction, root.Position, dao) then break end

            -- Let the launch play out and settle before measuring, or the next pass reads
            -- mid-flight numbers and thinks it went nowhere.
            local settle = tick() + 1.1
            while running(gen) and tick() < settle do
                local now, moving = myRoot(), getGoal()
                if now and moving and flatDistance(now.Position, moving) <= stopRange then break end
                task.wait(0.05)
            end
            endDashCarry()

            -- A dash that spent the cooldown and moved us nowhere is the one failure that used to
            -- go completely unnoticed: the ability was accepted, so nothing here read as an error,
            -- and the run stood in place burning dashes at a bed it was never going to reach. Two
            -- of those and the bridge takes over.
            local after = myRoot()
            if after and (after.Position - launchFrom).Magnitude < 6 then
                stalled = stalled + 1
                if stalled >= 2 then
                    status('Yuzi', 'The dash is not moving us - bridging instead', '')
                    break
                end
            end

            -- Learn how far a dash really carries here, so the landing check above is answering
            -- with a measured number instead of a guess.
            local landed, aim = myRoot(), getGoal()
            if landed and aim then
                local covered = left - flatDistance(landed.Position, aim)
                if covered > 4 then
                    dashRange = math.clamp(dashRange + (covered - dashRange) * 0.35, 18, 120)
                end
            end
        end

        local root, goal = myRoot(), getGoal()
        if root and goal then return flatDistance(root.Position, goal) <= stopRange + 4 end
        return false
    end

    ----------------------------------------------------------------------------------------------
    -- Kit and gear.
    ----------------------------------------------------------------------------------------------
    -- Pick Yuzi in the pre-game. BedwarsActivateKit is the same remote the game's own kit picker
    -- fires, so this is the kit genuinely being selected rather than a UI trick - but it only lands
    -- while the match has not started and only if the account actually owns the kit, so a rejection
    -- is normal and silent. A run with the wrong kit is still a run.
    local function equipYuzi()
        if run_.equipped then return end
        if not AutoEquipKit or not AutoEquipKit.Enabled then return end
        if hasYuziKit() then
            run_.equipped = true
            return
        end
        if store.matchState ~= 0 then return end
        -- Only try once every few seconds: this is polled from the brain's waiting state.
        if tick() - (run_.lastEquipTry or 0) < 4 then return end
        run_.lastEquipTry = tick()

        local chosen = ask(function()
            for id in pairs(bedwars.BedwarsKitMeta) do
                if YUZI_KITS[string.lower(tostring(id))] then return id end
            end
            return nil
        end)
        if not chosen then return end

        local accepted = ask(function()
            return bedwars.Client:Get('BedwarsActivateKit'):CallServer({kit = chosen})
        end)
        if accepted then
            run_.equipped = true
            status(nil, 'Equipped the Yuzi kit', '')
        end
    end

    -- Buy the next dao up. AutoBuy only swaps its sword ladder to daos for one of the two kit ids,
    -- so with Dao priority on this asks for them explicitly and the dash is always on the best
    -- blade we can afford.
    local function buyDao(shopId)
        if not DaoPriority or not DaoPriority.Enabled then return end
        local owned = 0
        for index, name in ipairs(DAO_TIERS) do
            if ask(getItem, name) then owned = index end
        end
        for index = owned + 1, #DAO_TIERS do
            local item = ask(function()
                return bedwars.Shop.getShopItem(DAO_TIERS[index], lplr, shopId and {shopId = shopId} or nil)
            end)
            if item then
                local currency = ask(getItem, item.currency)
                if (currency and currency.amount or 0) >= (item.price or math.huge) then
                    safe(function()
                        bedwars.Client:Get('BedwarsPurchaseItem'):CallServerAsync({shopItem = item, shopId = shopId})
                    end)
                    task.wait(0.25)
                end
            end
        end
    end

    ----------------------------------------------------------------------------------------------
    -- Generators, shops and drops.
    ----------------------------------------------------------------------------------------------
    local function isIronGen(entry)
        local iron = ask(function()
            local app = entry.RoactTree and entry.RoactTree:FindFirstChild('TeamOreGeneratorApp')
            return app ~= nil and (app:FindFirstChild('GlobalOreGenerator') or app:FindFirstChild('TeamGenMain')) ~= nil
        end)
        if iron then return true end
        local id = entry:GetAttribute('Id')
        return type(id) == 'string' and string.find(id, 'iron') ~= nil
    end

    local function nearestIronGen()
        local root = myRoot()
        if not root then return nil end
        local from, best, bestDist = root.Position, nil, nil
        for _, entry in ipairs(collectionService:GetTagged('Generator')) do
            -- Generators are models on most maps and bare parts on others, so resolving a part from
            -- either shape is what stops the walk to the generator quietly never happening.
            if entry and entry.Parent and isIronGen(entry) then
                local part = partOf(entry)
                if part then
                    local dist = (part.Position - from).Magnitude
                    if not bestDist or dist < bestDist then best, bestDist = part, dist end
                end
            end
        end
        return best
    end

    local function shopPos(entry)
        local pos = ask(function() return entry.RootPart.Position end)
        if not pos then pos = ask(function() return entry.RootPart:GetPivot().Position end) end
        return pos
    end

    local function nearestShop()
        local root = myRoot()
        if not root then return nil end
        local from, bestPos, bestDist = root.Position, nil, nil
        for _, entry in pairs(store.shop or {}) do
            if entry.Shop and entry.RootPart then
                local pos = shopPos(entry)
                if pos then
                    local dist = (pos - from).Magnitude
                    if not bestDist or dist < bestDist then bestPos, bestDist = pos, dist end
                end
            end
        end
        return bestPos
    end

    local function shopIdNear(maxDist)
        local root = myRoot()
        if not root then return nil end
        for _, entry in pairs(store.shop or {}) do
            if entry.Shop and entry.RootPart then
                local pos = shopPos(entry)
                if pos and (pos - root.Position).Magnitude <= (maxDist or 18) then return entry.Id end
            end
        end
        return nil
    end

    -- Sweep up dropped resources in reach. Standing on the generator makes the server hand them
    -- over anyway; asking explicitly just makes it instant.
    local function vacuum(range)
        local root = myRoot()
        if not root then return end
        for _, drop in ipairs(collectionService:GetTagged('ItemDrop')) do
            local part = drop.Parent and partOf(drop)
            if part and (part.Position - root.Position).Magnitude <= range then
                if tick() - (drop:GetAttribute('ClientDropTime') or 0) >= 2 then
                    safe(function()
                        bedwars.Client:Get(remotes.PickupItem):CallServerAsync({itemDrop = drop})
                    end)
                end
            end
        end
    end

    local function woolShopItem(shopId)
        local item = ask(function()
            return bedwars.Shop.getShopItem(WOOL_ITEM, lplr, shopId and {shopId = shopId} or nil)
        end)
        if not item then
            item = ask(function()
                return bedwars.Shop.getShopItem('wool', lplr, shopId and {shopId = shopId} or nil)
            end)
        end
        return item
    end

    ----------------------------------------------------------------------------------------------
    -- Banking and respawning.
    ----------------------------------------------------------------------------------------------
    -- With Take over on this is AutoBank's job and we only make sure it is running. Without it,
    -- deposit directly - the server simply ignores the request when we are nowhere near our chest,
    -- which costs nothing.
    local function bankLoot()
        if not BankLoot or not BankLoot.Enabled then return end
        if takeOver('AutoBank', {}) then return end
        local chest = replicatedStorage:FindFirstChild('Inventories')
        chest = chest and chest:FindFirstChild(lplr.Name .. '_personal')
        if not chest then return end
        local inv = store.inventory and store.inventory.inventory
        if not inv or not inv.items then return end
        local any = false
        for _, entry in pairs(inv.items) do
            if BANKABLE[entry.itemType] and entry.tool then
                any = true
                safe(function()
                    bedwars.Client:GetNamespace('Inventory'):Get('ChestGiveItem'):CallServer(chest, entry.tool)
                end)
            end
        end
        if any then
            status(nil, 'Banking loot', '')
            task.wait(0.3)
        end
    end

    -- Reset to base. Only ever called with our own bed intact, so it is a respawn and not an
    -- elimination.
    local function selfRespawn(gen)
        -- Mark it, so the death this is about to cause is not counted against us as "died on the
        -- way to the bed" and does not send the run shopping for armour it already has.
        run_.selfResetAt = tick()
        local before = lplr.Character
        local sent = ask(function()
            bedwars.Client:Get(remotes.ResetCharacter):SendToServer()
            return true
        end)
        if not sent then
            safe(function() bedwars.Client:Get(remotes.ResetCharacter):SendToServer({}) end)
        end
        local deadline = tick() + 4
        while running(gen) and tick() < deadline do
            if not entitylib.isAlive or lplr.Character ~= before then break end
            task.wait(0.1)
        end
        status('Respawning', 'Waiting to respawn', '')
        deadline = tick() + 20
        while running(gen) and tick() < deadline do
            if alive() then break end
            task.wait(0.2)
        end
        task.wait(0.4)
    end

    -- The only place the run is allowed to reset itself, so the two things that make a reset wrong
    -- are checked once rather than at every call site.
    --
    --   * With our bed gone the respawn IS the elimination. That check existed, but as a bare
    --     ownBedAlive() at each site, and one missed site throws the match.
    --   * A reset while a hitbox swap is in flight is what leaves your body frozen in place.
    --     Anything that parks your real root elsewhere for a moment (GodMode, AntiDeath) sets
    --     store.rootpart, which is the whole script's flag for "somebody owns the hitbox". Wait
    --     for the swap to finish, and skip the reset entirely if it will not clear.
    -- `force` is for the watchdog, whose reset is the last thing standing between a wedged run and
    -- an hour of nothing. It skips the Respawn after bed preference - not the two safety checks.
    local function resetToBase(gen, force)
        if not force and not RespawnAfterBed.Enabled then return false end
        if lastLife() or not ownBedAlive() then return false end
        local deadline = tick() + 2
        while running(gen) and store.rootpart and tick() < deadline do
            task.wait(0.05)
        end
        if not running(gen) or store.rootpart then return false end
        selfRespawn(gen)
        return true
    end

    ----------------------------------------------------------------------------------------------
    -- Actions. Each one is bounded and returns to the brain, which re-decides from scratch.
    ----------------------------------------------------------------------------------------------
    local function gatherIron(gen, target)
        if ironCount() >= target then return true end
        local gen_ = nearestIronGen()
        if gen_ then
            local root = myRoot()
            if root and (gen_.Position - root.Position).Magnitude > 10 then
                status('Resources', 'Walking to the generator', '')
                travel(gen, function()
                    return gen_.Parent and gen_.Position or nil
                end, 8, false, 'Walking to the generator', 40)
            end
        end

        -- Wait at the generator, but only while iron is actually arriving. Standing somewhere with
        -- no generator in reach used to burn minutes of a run doing nothing at all.
        local deadline = tick() + 60
        local held, sinceGain = ironCount(), tick()
        while running(gen) and alive() and ironCount() < target and tick() < deadline do
            status('Resources', 'Collecting iron', ironCount() .. '/' .. target)
            vacuum(18)
            if ironCount() > held then
                held, sinceGain = ironCount(), tick()
                run_.lastProgress = tick()
            elseif tick() - sinceGain > 15 then
                break
            end
            task.wait(0.35)
        end
        return ironCount() >= target
    end

    -- AutoBuy, with the toggles the run depends on actually asked for.
    --
    -- Buy Armor ships on and Buy Sword ships off, and neither was being requested - so whether a
    -- run bought armour came down to how the user last left AutoBuy, and one switched off there
    -- meant standing at the counter with the iron for a chestplate and buying nothing at all. Take
    -- over records and restores every option it changes, so asking for them is not a change to
    -- anybody's config. Still gated on the Take over toggle, because buyArmour and buyDao below
    -- cover the same ground when it is off.
    local function driveAutoBuy()
        return takeOver('AutoBuy', {
            ['GUI check'] = false,
            ['Only Bedwars'] = false,
            ['Buy Armor'] = true,
            ['Buy Sword'] = true
        })
    end

    -- Walk the armour ladder ourselves. With Take over on, driveAutoBuy above already covers this
    -- and these calls simply find nothing left to buy; without it nothing else would, and a run in
    -- its underwear is the thing this exists to stop. Same shape as buyDao.
    local function buyArmour(shopId)
        local owned = armourTier()
        for index = owned + 1, #ARMOUR_TIERS do
            local item = ask(function()
                return bedwars.Shop.getShopItem(ARMOUR_TIERS[index], lplr, shopId and {shopId = shopId} or nil)
            end)
            if item then
                local currency = ask(getItem, item.currency)
                if (currency and currency.amount or 0) >= (item.price or math.huge) then
                    safe(function()
                        bedwars.Client:Get('BedwarsPurchaseItem'):CallServerAsync({shopItem = item, shopId = shopId})
                    end)
                    task.wait(0.25)
                end
            end
        end
    end

    -- Time to go shopping for armour?
    --
    -- The second trigger is the one that matters. The first is just "we have none" - crossing the
    -- map unarmoured is a bad trade at any point in a match. The second is dying: a run that keeps
    -- dying before it reaches the bed is a run whose gear is not up to the crossing, and setting
    -- off again on exactly the same gear is the loop being reported. Each death buys one trip to
    -- the shop; gearUp clears the count, so this can never turn into shuttling back and forth.
    local function needsGear()
        if tick() - (run_.lastGear or 0) < 20 then return false end
        local tier = armourTier()
        if tier <= 0 then return true end
        if (run_.deaths or 0) > 0 and tier < #ARMOUR_TIERS then return true end
        -- Last life: our bed is gone, so this is the crossing that decides the match.
        if lastLife() and tier < 2 then return true end
        return false
    end

    -- Go to a shop and come back dressed.
    --
    -- AutoBuy is what buys armour, and AutoBuy only buys while you are stood beside a shop NPC.
    -- Nothing in the old run ever took us there for that reason - the one shop trip was the wool
    -- trip inside stockUp, so a run that already had wool, or was dashing (which skipped stockUp
    -- entirely), never visited a shop at all and fought the whole match in what it spawned in.
    local function gearUp(gen, label)
        label = label or 'Going for armour'
        -- Every give-up path stamps the clock too. Without that, a map with no shop we can find
        -- would answer "yes, go shopping" on every single tick and re-ask the question forever.
        if not shopIdNear(18) then
            local pos = nearestShop()
            if not pos then
                run_.lastGear = tick()
                return false
            end
            status('Resources', label, '')
            travel(gen, function() return pos end, 8, false, label, 45)
            if not running(gen) or not alive() then return false end
        end
        local shopId = shopIdNear(22)
        if not shopId then
            run_.lastGear = tick()
            return false
        end

        local waitShop = tick() + 6
        while running(gen) and not store.shopLoaded and tick() < waitShop do task.wait(0.1) end

        status('Resources', label, armourTier() .. '/' .. #ARMOUR_TIERS .. ' armour')
        driveAutoBuy()
        buyArmour(shopId)
        buyDao(shopId)

        -- AutoBuy spends on its own loop, so give it a beat at the counter rather than walking off
        -- the moment we arrive. Stops early as soon as something lands.
        local before = armourTier()
        local deadline = tick() + 3
        while running(gen) and alive() and tick() < deadline do
            if armourTier() > before then break end
            task.wait(0.2)
        end

        -- One trip per death, whether or not we could afford anything. Without this a run that has
        -- run out of iron would walk back to the shop after every single death for the rest of the
        -- match and never get anything else done.
        run_.lastGear = tick()
        run_.deaths = 0
        return armourTier() > 0
    end

    local function goShopping(gen, wantBlocks)
        if not shopIdNear(18) then
            local pos = nearestShop()
            if not pos then return blockCount() > 0 end
            status('Resources', 'Walking to the shop', '')
            travel(gen, function() return pos end, 8, false, 'Walking to the shop', 45)
        end
        local shopId = shopIdNear(22)
        if not shopId then return blockCount() > 0 end

        local waitShop = tick() + 6
        while running(gen) and not store.shopLoaded and tick() < waitShop do task.wait(0.1) end

        -- Armour, a sword and tools are AutoBuy's job and it is already standing here with us; all
        -- this has to do is the things AutoBuy will not - the dao ladder, the armour ladder when
        -- AutoBuy is not available to walk it, and enough wool for the crossing we measured.
        driveAutoBuy()
        buyDao(shopId)
        buyArmour(shopId)

        for _ = 1, 40 do
            if not running(gen) or not alive() then break end
            if blockCount() >= wantBlocks then break end
            local item = woolShopItem(shopId)
            if not item then break end
            local price = item.price or WOOL_PRICE
            if ironCount() < price then break end
            status('Resources', 'Buying wool', blockCount() .. '/' .. wantBlocks)
            local sent = ask(function()
                bedwars.Client:Get('BedwarsPurchaseItem'):CallServerAsync({shopItem = item, shopId = shopId})
                return true
            end)
            if not sent then break end
            task.wait(0.25)
        end
        return blockCount() > 0
    end

    -- Level first, then the steps down a bridge takes, then one step up. Down before up so a wall
    -- beside the route is never mistaken for the floor of it.
    local PROBE = {0, -1, -2, -3, 1}

    -- Follow the ground along a straight X/Z line and count the columns with nothing under them.
    -- The height is carried from column to column instead of being pinned to the one we set off at,
    -- because a bridge climbs, dips and is often built a level off ours - measured at a single fixed
    -- height, an existing bridge reads as open air for its whole length.
    local function straightLineCost(from, to)
        local steps = math.min(math.abs(to.X - from.X) + math.abs(to.Z - from.Z), 300)
        local cursor, need = from, 0
        for _ = 1, steps do
            local dx, dz = to.X - cursor.X, to.Z - cursor.Z
            if dx == 0 and dz == 0 then break end
            if math.abs(dx) >= math.abs(dz) then
                cursor = cursor + Vector3.new(dx > 0 and 1 or -1, 0, 0)
            else
                cursor = cursor + Vector3.new(0, 0, dz > 0 and 1 or -1)
            end
            local found = nil
            for _, dy in ipairs(PROBE) do
                local probe = cursor + Vector3.new(0, dy, 0)
                if solidAt(probe) then
                    found = probe
                    break
                end
            end
            if found then
                cursor = found
            else
                need = need + 1
            end
        end
        return need
    end

    -- What this crossing actually costs us in blocks.
    --
    -- This used to be the straight line above and nothing else, measured at one fixed height, and
    -- it is why the run bought wool with a finished bridge in front of it: a bridge is almost never
    -- at exactly the height you set off at - it climbs, it dips, it was built from the far side,
    -- you are standing on its lip a level up - so a perfectly walkable crossing priced as if
    -- nothing was there at all, and the run went off for iron and a stack of wool it did not need.
    --
    -- Ask the router instead. It is the same search travel is about to run, so what it says the
    -- route costs is what the crossing will really cost, existing bridge included. The straight
    -- line stays as the fallback for when the search comes back empty.
    local function blocksNeeded(gen, goalPos)
        local root, char = myRoot()
        if not root or not goalPos then return 0 end
        local from = footCell(root, char)
        local to = cellOf(Vector3.new(goalPos.X, goalPos.Y - STAND, goalPos.Z))

        -- Same arguments the crossing itself will use, or the estimate prices a different route to
        -- the one we are about to walk.
        local route = planRoute(from, to, true, true, gen)
        if not running(gen) then return 0 end
        if route and #route > 0 then
            local need = 0
            for _, cell in ipairs(route) do
                if not solidAt(cell) then need = need + 1 end
            end
            -- A route that ran out of search budget only priced the part of the crossing it could
            -- see. Price the rest the cheap way rather than setting off underweight.
            local last = route[#route]
            if (last - to).Magnitude > 2 then
                need = need + straightLineCost(last, to)
            end
            return need
        end
        return straightLineCost(from, to)
    end

    -- Measure the crossing, gather exactly the iron it needs, and buy it.
    local function stockUp(gen, goalPos)
        local root = myRoot()
        if not root then return false end
        local need = blocksNeeded(gen, goalPos)
        if not running(gen) then return false end

        -- The Block amount slider is the floor for a crossing that has to be BUILT. When the route
        -- is already walkable the whole way - a teammate's bridge, our own from the last cycle, a
        -- map that simply connects - there is nothing to build and a full stack is a shopping trip
        -- for nothing. Carry a small reserve for patching a hole and go.
        local reserve = math.min(WoolAmount.Value, 8)
        local want = need > 0 and math.max(WoolAmount.Value, need + 10) or reserve
        if blockCount() >= want then return true end
        local buys = math.ceil(math.max(want - blockCount(), 0) / WOOL_PER_BUY)
        gatherIron(gen, math.max(IronAmount.Value, buys * WOOL_PRICE))
        if not running(gen) then return false end
        return goShopping(gen, want)
    end

    ----------------------------------------------------------------------------------------------
    -- Breaking a bed.
    ----------------------------------------------------------------------------------------------
    local function breakBed(gen, bed)
        local deadline = tick() + 45
        while running(gen) and alive() and bed.Parent and tick() < deadline do
            local part = partOf(bed)
            local root = myRoot()
            if not part or not root then break end
            local dist = (part.Position - root.Position).Magnitude
            if dist > 26 then return false end
            root.CFrame = CFrame.lookAt(root.Position, Vector3.new(part.Position.X, root.Position.Y, part.Position.Z))
            if bedShielded(bed) then
                status('Bed', 'Waiting out the bed shield', '')
                task.wait(0.3)
            else
                status('Bed', 'Breaking ' .. bedName(bed), string.format('%.0f studs', dist))
                safe(bedwars.breakBlock, part, true, true, nil, true, breakmethods.Distance, 360, false)
                run_.lastProgress = tick()
                task.wait(0.22)
            end
        end
        return bed.Parent == nil or partOf(bed) == nil
    end

    ----------------------------------------------------------------------------------------------
    -- Combat.
    --
    -- Killaura does the hitting when it is available - it is a far better aura than anything that
    -- belongs in here, and driving it means one implementation to be right rather than two. The
    -- fallback below only runs when Killaura is missing or Take over is off, so a run is never left
    -- walking up to people and doing nothing.
    ----------------------------------------------------------------------------------------------
    local function swordInHand()
        local sword = store.tools and store.tools.sword
        -- With a dao on us that IS the sword, and it is what the dash needs in hand anyway.
        local dao = getDao()
        if dao and dao.tool then sword = dao end
        if not sword or not sword.tool then return nil end
        if not store.hand or store.hand.tool ~= sword.tool then
            safe(switchItem, sword.tool, 0)
        end
        return sword, bedwars.ItemMeta[sword.tool.Name]
    end

    local function swing(ent)
        local sword, meta = swordInHand()
        if not sword then return end
        local root = myRoot()
        if not root or not ent.RootPart or not ent.RootPart.Parent then return end
        local target = ent.Character and ent.Character.PrimaryPart or ent.RootPart
        local selfPos = root.Position
        local delta = target.Position - selfPos
        if delta.Magnitude > bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE then return end

        local speed = (meta and meta.sword and meta.sword.attackSpeed) or 0.11
        if (tick() - bedwars.SwordController.lastSwing) >= math.max(speed, 0.11) then
            safe(function() bedwars.SwordController:playSwordEffect(meta, false) end)
            bedwars.SwordController.lastSwing = tick()
        end

        local dir = CFrame.lookAt(selfPos, target.Position).LookVector
        local pos = selfPos + dir * math.max(delta.Magnitude - 14.399, 0)
        bedwars.SwordController.lastAttack = workspace:GetServerTimeNow()
        safe(function()
            bedwars.Client:Get(remotes.AttackEntity):SendToServer({
                weapon = sword.tool,
                chargedAttack = {chargeRatio = 0},
                entityInstance = ent.Character,
                validate = {
                    raycast = {
                        cameraPosition = {value = pos},
                        cursorDirection = {value = dir}
                    },
                    targetPosition = {value = target.Position},
                    selfPosition = {value = pos}
                }
            })
        end)
    end

    -- Break off and heal.
    --
    -- Walking away from a fight was not something the run could do at all. With our own bed still
    -- up that hardly matters - a bad trade costs a respawn - but once it is gone the same bad trade
    -- ends the match, and "swing until one of us drops" is how a won game gets handed to whoever
    -- happened to be standing next to the last bed. So on the last life the run puts distance
    -- between itself and whoever is on it, and lets AutoConsume do its job.
    local function disengage(gen)
        local root = myRoot()
        if not root then return false end
        local ent = pickEnemy()
        if not ent or not ent.RootPart or not ent.RootPart.Parent then return false end

        local delta = (root.Position - ent.RootPart.Position) * Vector3.new(1, 0, 1)
        -- Nothing close enough to be worth running from; whatever hurt us is not here any more.
        if delta.Magnitude > 60 then return false end
        local away = delta.Magnitude > 1 and delta.Unit or root.CFrame.LookVector * Vector3.new(1, 0, 1)
        if away.Magnitude < 0.1 then return false end

        takeOver('AutoConsume', {})
        local goal = root.Position + away.Unit * 45
        status('Combat', 'Backing off to heal', string.format('%d%% hp', math.floor(healthFraction() * 100)))
        travel(gen, function() return goal end, 6, true, 'Backing off to heal', 10)

        -- Then hold off until the heal lands or they lose interest, rather than turning straight
        -- round into the same fight on the same health.
        local deadline = tick() + 8
        while running(gen) and alive() and tick() < deadline do
            if healthFraction() >= 0.8 then break end
            local near, now = pickEnemy(), myRoot()
            if not now then break end
            if not near or not near.RootPart or not near.RootPart.Parent then break end
            if (near.RootPart.Position - now.Position).Magnitude > 55 then break end
            status('Combat', 'Backing off to heal', string.format('%d%% hp', math.floor(healthFraction() * 100)))
            task.wait(0.3)
        end
        run_.lastProgress = tick()
        return true
    end

    local function fight(gen, ent)
        local auraDriven = takeOver('Killaura', {
            ['Require mouse down'] = false,
            ['GUI check'] = false
        })
        local deadline = tick() + 25
        while running(gen) and alive() and tick() < deadline do
            if not ent.RootPart or not ent.RootPart.Parent then return true end
            if ent.Health and ent.Health <= 0 then return true end
            local root = myRoot()
            if not root then break end
            -- Last life: a trade we are losing is a trade that ends the match. Hand back to the
            -- brain, which with our bed gone will back off and heal rather than finish the swing.
            if lastLife() and healthFraction() < 0.4 then
                status('Combat', 'Breaking off - too low to trade', '')
                return false
            end
            local dist = (ent.RootPart.Position - root.Position).Magnitude
            if dist > PlayerReach.Value + 10 then return false end
            root.CFrame = CFrame.lookAt(root.Position, Vector3.new(ent.RootPart.Position.X, root.Position.Y, ent.RootPart.Position.Z))
            status('Combat', 'Fighting ' .. (ent.Player and ent.Player.Name or 'a player'),
                string.format('%.0f studs  |  %d hp', dist, math.floor(ent.Health or 0)))
            if not auraDriven then swing(ent) end
            run_.lastProgress = tick()
            task.wait(auraDriven and 0.1 or 0)
        end
        return not (ent.RootPart and ent.RootPart.Parent)
    end

    ----------------------------------------------------------------------------------------------
    -- Escalation. Each rung is a movement module the walker is allowed to lean on; they are all
    -- released the moment the run is moving again, so the blatant ones are only ever on for the few
    -- seconds they are actually needed.
    ----------------------------------------------------------------------------------------------
    function applyTier()
        local tier = math.min(run_.tier, maxTier())
        if tier >= 2 then
            takeOver('Speed', {}, true)
        else
            releaseOne('Speed')
        end
        if tier >= 3 then
            takeOver('Fly', {}, true)
        else
            releaseOne('Fly')
        end
    end

    local function calmDown()
        if run_.tier > 0 and tick() - run_.lastProgress < 4 then
            run_.tier = 0
            applyTier()
        end
    end

    ----------------------------------------------------------------------------------------------
    -- End of match.
    ----------------------------------------------------------------------------------------------
    local function resolveQueue()
        local wanted = Gamemode and Gamemode.Value or 'Current'
        if wanted == 'Current' or wanted == nil then return store.queueType end
        if wanted == 'Random' then
            local modes = {}
            safe(function()
                for id, meta in pairs(bedwars.QueueMeta) do
                    if not meta.disabled and not meta.voiceChatOnly and not meta.rankCategory then
                        table.insert(modes, id)
                    end
                end
            end)
            if #modes > 0 then return modes[math.random(1, #modes)] end
            return store.queueType
        end
        return wanted
    end

    -- Queue for the next match. BedWars only accepts this from the party leader and only when the
    -- party is not already queued, so both are checked rather than fired blind.
    local function joinQueue()
        if not Requeue or not Requeue.Enabled then return end
        if run_.queued then return end
        local ok = ask(function()
            local state = bedwars.Store:getState()
            if state.Game.customMatch then return false end
            if state.Party.leader.userId ~= lplr.UserId then return false end
            if state.Party.queueState ~= 0 then return false end
            return true
        end)
        if not ok then return end
        run_.queued = true
        writeState()
        local mode = resolveQueue()
        status('Done', 'Queueing for ' .. tostring(mode), '')
        safe(function() bedwars.QueueController:joinQueue(mode) end)
        -- One retry a few seconds later: the first call right on the match-end frame is sometimes
        -- swallowed while the end screen is still animating in.
        task.delay(6, function()
            if not running() then return end
            local still = ask(function()
                return bedwars.Store:getState().Party.queueState == 0
            end)
            if still then safe(function() bedwars.QueueController:joinQueue(mode) end) end
        end)
    end

    ----------------------------------------------------------------------------------------------
    -- Staying in the game at all.
    --
    -- A run measured in hours ends the first time the client is disconnected unless something puts
    -- it back. Both the error prompt and the disconnect signal are watched, and the rejoin goes to
    -- the LOBBY place rather than the match: a finished match server is not somewhere to return to,
    -- and the lobby is where AutoQueue picks the run back up.
    ----------------------------------------------------------------------------------------------
    local rejoining = false

    local function rejoin()
        if not AutoRejoin or not AutoRejoin.Enabled then return end
        -- Once only. Both watchers below can fire for the same disconnect, and a second teleport
        -- request on top of one already in flight is how a rejoin turns into a kick.
        if rejoining then return end
        rejoining = true
        writeState()
        safe(function()
            local teleportService = cloneref(game:GetService('TeleportService'))
            teleportService:Teleport(LOBBY_PLACE, lplr)
        end)
    end

    local function watchDisconnects(gen)
        AutoWin:Clean(function() rejoining = false end)
        safe(function()
            AutoWin:Clean(guiService.ErrorMessageChanged:Connect(function(message)
                if not running(gen) then return end
                if type(message) == 'string' and message ~= '' then
                    task.delay(2, rejoin)
                end
            end))
        end)
        safe(function()
            local prompt = coreGui:FindFirstChild('RobloxPromptGui')
            prompt = prompt and prompt:FindFirstChild('promptOverlay')
            if not prompt then return end
            AutoWin:Clean(prompt.ChildAdded:Connect(function(child)
                if not running(gen) then return end
                if string.find(child.Name, 'ErrorPrompt') then
                    task.delay(2, rejoin)
                end
            end))
        end)
    end

    ----------------------------------------------------------------------------------------------
    -- The brain. One decision, one bounded action, repeat. Everything above is a leaf it calls.
    ----------------------------------------------------------------------------------------------
    local function step(gen)
        -- Match over. Nothing left to do but line the next one up.
        if store.matchState == 2 then
            status('Done', 'Match over', '')
            stopMoving()
            joinQueue()
            task.wait(1)
            return
        end

        if store.matchState == 0 then
            -- Back in a pre-game. That is a new match, so the one-shot queue latch has to be armed
            -- again or a second game played without a teleport would never queue a third.
            run_.queued = false
            status('Waiting', 'Waiting for the match', '')
            equipYuzi()
            stopMoving()
            task.wait(0.5)
            return
        end

        if not alive() then
            -- Dead, or somebody else is holding the hitbox. Neither is ours to fight.
            stopMoving()
            if not entitylib.isAlive then
                status('Respawning', 'Waiting to respawn', '')
                if not ownBedAlive() and #playersService:GetPlayers() > 1 then
                    -- Eliminated. The match is finished for us either way, so wait it out and
                    -- queue when it ends rather than spinning here.
                    status('Done', 'Eliminated - waiting for the match to end', '')
                end
            end
            task.wait(0.4)
            return
        end

        calmDown()
        applyTier()
        equipYuzi()

        local root = myRoot()
        if not root then
            task.wait(0.2)
            return
        end

        -- Last life. Our bed is gone, so the next death is not a respawn, it is the match - and
        -- this is where a won game gets thrown away: the run charges the final bed on a sliver of
        -- health with whatever it happened to be carrying, and hands the win to whoever is standing
        -- next to it. Nothing else about the plan changes; it just stops taking the trades that end
        -- it. Healing is AutoConsume's job and it is better at it than anything that belongs here.
        if lastLife() then
            takeOver('AutoConsume', {})
            if healthFraction() < 0.45 and disengage(gen) then return end
        end

        -- Phase one: beds. A bed left standing is a team that keeps coming back, so nothing else
        -- matters until they are all gone.
        local beds = enemyBeds()
        if #beds ~= run_.lastBedCount then
            if run_.lastBedCount >= 0 and #beds < run_.lastBedCount then
                run_.bedFails = {}
            end
            run_.lastBedCount = #beds
        end

        if #beds > 0 then
            local bed = pickBed(root.Position)
            if not bed then
                task.wait(0.3)
                return
            end
            local part = partOf(bed)
            if not part then
                task.wait(0.2)
                return
            end
            local getBedPos = function()
                local live = bed.Parent and partOf(bed)
                return live and live.Position or nil
            end

            -- Dressed before we set off. This is where dying repeatedly on the way out gets
            -- answered: the shop is on the way, and turning up to the same crossing in the same
            -- gear that just got us killed is the loop rather than a plan.
            if needsGear() then
                gearUp(gen, 'Gearing up for ' .. bedName(bed))
                if not running(gen) or not alive() then return end
                root = myRoot()
                if not root then return end
            end

            -- The dash goes first, because when it lands us at the bed the block run was never
            -- needed and that was most of the cycle's time.
            --
            -- What it must NOT do any more is replace the block run. It used to: a dao in the bag
            -- meant stockUp was skipped entirely, so the run set off with zero blocks. The dash has
            -- a cooldown, it refuses to launch over open air or into a wall, and it stops short of
            -- a raised bed - so the moment it could not finish the crossing, travel came straight
            -- back with 'noblocks', that counted as a failed bed, and the run banked, reset to base
            -- and did the whole thing again. That is the walking-around-and-respawning cycle: not a
            -- broken dash, a run that had thrown away its ability to bridge before it started.
            -- Now the dash covers what it can and whatever is left is bridged like anything else.
            if YuziDash.Enabled and getDao() ~= nil then
                status('Yuzi', 'Dashing to ' .. bedName(bed), '')
                dashToward(gen, getBedPos, BedReach.Value, 'Dashing to ' .. bedName(bed))
                if not running(gen) or not alive() then return end
                root = myRoot()
                if not root then return end
            end

            -- Whatever the dash did not cover gets bridged, so stock for what is actually left -
            -- measured from where the dash put us down, not from where we set off.
            local function shortOfBed()
                local now, live = myRoot(), getBedPos()
                if not now or not live then return nil end
                return flatDistance(now.Position, live) > BedReach.Value, live
            end

            local short, live = shortOfBed()
            -- The bed went while we were crossing (a teammate got there first). Nothing to do here;
            -- the next tick re-picks from the beds actually left.
            if short == nil then return end
            if short then
                status('Resources', 'Preparing for ' .. bedName(bed), '')
                stockUp(gen, live)
                if not running(gen) then return end
                short = shortOfBed()
                if short == nil then return end
            end

            if short and blockCount() <= 0 then
                -- Nothing to build with and still short of the bed. A reset is the clean way out of
                -- that - it puts us back at the generator and the shop with a route to everything -
                -- and it is not counted against the bed, because it is our supply that failed and
                -- not the route. When there is no reset to take (our own bed is gone) we go anyway
                -- rather than standing here re-deciding the same thing every tick: the crossing
                -- either partly exists or the bed's own failure count moves us on to another one.
                status('Resources', 'Out of blocks - resetting', '')
                bankLoot()
                if resetToBase(gen) then return end
            end

            status('Bridging', 'Heading for ' .. bedName(bed), '')
            local result = travel(gen, getBedPos, BedReach.Value, true, 'Heading for ' .. bedName(bed), 120)
            if result ~= 'arrived' then
                if result == 'abort' then return end
                run_.bedFails[bed] = (run_.bedFails[bed] or 0) + 1
                status('Bridging', 'Could not reach ' .. bedName(bed), result)
                bankLoot()
                resetToBase(gen)
                return
            end

            if breakBed(gen, bed) then
                run_.bedFails[bed] = nil
                run_.lastProgress = tick()
                status('Bed', 'Bed down', '')
            else
                run_.bedFails[bed] = (run_.bedFails[bed] or 0) + 1
            end
            bankLoot()
            if RespawnAfterBed.Enabled and not lastLife() and ownBedAlive() then
                status('Respawning', 'Back to base', '')
                resetToBase(gen)
            end
            return
        end

        -- Phase two: the survivors.
        if not KillPlayers.Enabled then
            status('Done', 'All beds down - waiting for the match to end', '')
            stopMoving()
            task.wait(1)
            return
        end

        local ent = pickEnemy()
        if not ent then
            status('Done', 'Nobody left to fight', '')
            stopMoving()
            task.wait(1)
            return
        end

        local name = ent.Player and ent.Player.Name or 'a player'
        local getEnemyPos = function()
            if ent.RootPart and ent.RootPart.Parent then return ent.RootPart.Position end
            return nil
        end

        -- Same rule as the bed phase: walk into the last fight of the match dressed. With every bed
        -- down this IS the match, and it is the fight the run used to arrive at in whatever it had.
        if needsGear() then
            gearUp(gen, 'Gearing up before ' .. name)
            if not running(gen) or not alive() then return end
        end

        if blockCount() < 12 then
            stockUp(gen, getEnemyPos())
            if not running(gen) then return end
        end

        if YuziDash.Enabled and getDao() then
            dashToward(gen, getEnemyPos, PlayerReach.Value, 'Dashing to ' .. name)
        end

        status('Combat', 'Closing on ' .. name, '')
        local result = travel(gen, getEnemyPos, PlayerReach.Value, true, 'Closing on ' .. name, 90)
        if result == 'abort' then return end
        if result == 'arrived' then
            if not fight(gen, ent) then
                run_.playerFails[ent.Character] = (run_.playerFails[ent.Character] or 0) + 1
            else
                run_.playerFails[ent.Character] = nil
                run_.lastProgress = tick()
            end
        else
            run_.playerFails[ent.Character] = (run_.playerFails[ent.Character] or 0) + 1
        end
    end

    ----------------------------------------------------------------------------------------------
    -- Supervisor and watchdog.
    ----------------------------------------------------------------------------------------------
    local function brain(gen)
        -- Wait for a match, a map, a body and - critically - a team. The bed phase treats an unknown
        -- team as "no enemy beds" so that it can never smash our own, and starting before the team
        -- resolves would make it skip bed breaking entirely.
        local deadline = tick() + 180
        while running(gen) and tick() < deadline do
            if store.matchState ~= 0 and store.map and entitylib.isAlive and myTeam() ~= nil then break end
            status('Waiting', 'Waiting for the map', '')
            equipYuzi()
            task.wait(0.4)
        end
        if not running(gen) then return end
        task.wait(StartDelay.Value)
        resetRun()

        -- The stack a sweat would already have running before the first tick.
        takeOver('AutoTool', {})
        -- The run is played on Yuzi, so the kit module worth having on is the one that carries
        -- its dash further. It is a no-op on any other kit, so driving it costs nothing when
        -- Auto equip kit is off and something else is equipped.
        takeOver('YuziExtender', {})
        takeOver('NoFallDamage', {})
        takeOver('AntiVoid', {})
        if KeepAwake.Enabled then takeOver('Anti-AFK', {}) end
        -- AutoBuy for the whole run rather than only during the wool trip. It only spends while you
        -- are stood at a shop, so leaving it on costs nothing and means every pass through spawn -
        -- every reset, every respawn - tops the armour up without a special trip for it.
        driveAutoBuy()

        local failures = 0
        while running(gen) do
            local ok, err = pcall(step, gen)
            if ok then
                failures = 0
            else
                -- One broken action must never end the run. Report it once per burst and carry on;
                -- a genuinely broken build will show up as the watchdog resetting instead.
                failures = failures + 1
                if failures <= 3 then
                    warn('[AetherV2] AutoWin tick failed: ' .. tostring(err))
                end
                if failures > 3 then task.wait(1) end
            end
            task.wait(0.1)
        end
        stopMoving()
    end

    -- Outside the brain entirely, so it still fires when the brain is wedged inside something.
    local function watchdog(gen)
        while running(gen) do
            task.wait(5)
            if not running(gen) then break end
            local limit = StuckLimit.Value * 60
            if limit > 0 and store.matchState == 1 and alive() then
                if tick() - run_.lastProgress > limit then
                    status('Watchdog', 'No progress - resetting the run', '')
                    run_.lastProgress = tick()
                    stopMoving()
                    clearGrid()
                    run_.bedFails = {}
                    run_.playerFails = {}
                    run_.tier = 0
                    applyTier()
                    -- A reset to base is the one move that reliably un-wedges a run: it puts us
                    -- back at the generator and the shop with a clean route to everything. Through
                    -- resetToBase like every other reset, so the watchdog cannot be the one path
                    -- that respawns us onto an elimination or into the middle of a hitbox swap.
                    safe(resetToBase, gen, true)
                end
            end
            refreshHUD()
        end
    end

    local function shutdown()
        stopMoving()
        endDashCarry()
        releaseAll()
        run_.phase, run_.action, run_.detail, run_.tier = 'Idle', 'Waiting', '', 0
        refreshHUD()
        writeState()
    end

    ----------------------------------------------------------------------------------------------
    -- Module.
    ----------------------------------------------------------------------------------------------
    AutoWin = vape.Categories.World:CreateModule({
        Name = 'AutoWin',
        Function = function(callback)
            if callback then
                generation = generation + 1
                local gen = generation
                resetRun()
                run_.phase, run_.action, run_.detail = 'Starting', 'Waiting for the map', ''
                refreshHUD()
                writeState()
                -- The GUI already made the HUD frame visible because the module is on; Show HUD is
                -- the user's say over that, so it is applied on top.
                pcall(function()
                    if hudFrame then hudFrame.Visible = ShowHUD.Enabled end
                end)

                -- Order matters. The threads are registered first so a toggle-off cancels them
                -- before shutdown puts every driven module back - otherwise a still-running brain
                -- would switch them straight on again on its way out.
                startDriver(gen)
                AutoWin:Clean(task.spawn(function() brain(gen) end))
                AutoWin:Clean(task.spawn(function() watchdog(gen) end))
                AutoWin:Clean(task.spawn(function()
                    while running(gen) do
                        refreshHUD()
                        task.wait(0.4)
                    end
                end))
                watchDisconnects(gen)
                AutoWin:Clean(vapeEvents.MatchEndEvent.Event:Connect(function()
                    if not running(gen) then return end
                    stopMoving()
                    task.delay(1.5, joinQueue)
                end))
                AutoWin:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(deathTable)
                    if not running(gen) then return end
                    if deathTable.entityInstance ~= lplr.Character then return end
                    stopMoving()
                    endDashCarry()
                    -- Count it, unless it was our own reset - the run resets to base after every
                    -- bed, and counting those as deaths would send it shopping for armour it is
                    -- already wearing after every single cycle.
                    if tick() - (run_.selfResetAt or 0) > 5 then
                        run_.deaths = (run_.deaths or 0) + 1
                    end
                    if deathTable.finalKill then
                        -- Eliminated with nobody left in the party: this match is over for us, so
                        -- line the next one up instead of waiting out the end screen.
                        local alone = ask(function()
                            return #bedwars.Store:getState().Party.members <= 0
                        end)
                        if alone and store.matchState ~= 2 then task.delay(3, joinQueue) end
                    end
                end))
                AutoWin:Clean(shutdown)
            else
                generation = generation + 1
                shutdown()
            end
        end,
        Tooltip = 'Plays the whole match alone - gears up, breaks every bed, hunts survivors and queues the next game',
        Size = UDim2.fromOffset(232, 96)
    })

    -- The HUD lives in the draggable frame the GUI made for us; grab the title bar to move it.
    if AutoWin.Children then
        hudFrame = AutoWin.Children
        if hudFrame.Position == UDim2.new() then
            hudFrame.Position = UDim2.fromOffset(16, 220)
        end
        local bg = Instance.new('Frame')
        bg.Size = UDim2.fromScale(1, 1)
        bg.BackgroundColor3 = Color3.new()
        bg.BackgroundTransparency = 0.35
        bg.BorderSizePixel = 0
        bg.Parent = hudFrame
        local corner = Instance.new('UICorner')
        corner.CornerRadius = UDim.new(0, 5)
        corner.Parent = bg

        local title = Instance.new('TextLabel')
        title.Size = UDim2.new(1, -12, 0, 18)
        title.Position = UDim2.fromOffset(8, 5)
        title.BackgroundTransparency = 1
        title.Font = Enum.Font.GothamBold
        title.TextSize = 13
        title.TextXAlignment = Enum.TextXAlignment.Left
        title.TextColor3 = Color3.new(1, 1, 1)
        title.Text = 'AutoWin'
        title.Parent = bg

        hudPhase = Instance.new('TextLabel')
        hudPhase.Size = UDim2.new(1, -12, 0, 18)
        hudPhase.Position = UDim2.fromOffset(-8, 5)
        hudPhase.BackgroundTransparency = 1
        hudPhase.Font = Enum.Font.GothamBold
        hudPhase.TextSize = 13
        hudPhase.TextXAlignment = Enum.TextXAlignment.Right
        hudPhase.TextColor3 = Color3.fromRGB(120, 220, 170)
        hudPhase.Text = 'Idle'
        hudPhase.Parent = bg

        hudAction = Instance.new('TextLabel')
        hudAction.Size = UDim2.new(1, -16, 0, 18)
        hudAction.Position = UDim2.fromOffset(8, 26)
        hudAction.BackgroundTransparency = 1
        hudAction.Font = Enum.Font.Gotham
        hudAction.TextSize = 13
        hudAction.TextXAlignment = Enum.TextXAlignment.Left
        hudAction.TextTruncate = Enum.TextTruncate.AtEnd
        hudAction.TextColor3 = Color3.new(1, 1, 1)
        hudAction.Text = 'Waiting'
        hudAction.Parent = bg

        hudDetail = Instance.new('TextLabel')
        hudDetail.Size = UDim2.new(1, -16, 0, 16)
        hudDetail.Position = UDim2.fromOffset(8, 45)
        hudDetail.BackgroundTransparency = 1
        hudDetail.Font = Enum.Font.Gotham
        hudDetail.TextSize = 12
        hudDetail.TextXAlignment = Enum.TextXAlignment.Left
        hudDetail.TextTruncate = Enum.TextTruncate.AtEnd
        hudDetail.TextColor3 = Color3.fromRGB(185, 185, 185)
        hudDetail.Text = ''
        hudDetail.Parent = bg

        hudStock = Instance.new('TextLabel')
        hudStock.Size = UDim2.new(1, -16, 0, 16)
        hudStock.Position = UDim2.fromOffset(8, 68)
        hudStock.BackgroundTransparency = 1
        hudStock.Font = Enum.Font.GothamMedium
        hudStock.TextSize = 12
        hudStock.TextXAlignment = Enum.TextXAlignment.Left
        hudStock.TextColor3 = Color3.fromRGB(235, 205, 130)
        hudStock.Text = '0 iron   0 blocks'
        hudStock.Parent = bg
    end

    ----------------------------------------------------------------------------------------------
    -- Options.
    ----------------------------------------------------------------------------------------------
    Aggression = AutoWin:CreateDropdown({
        Name = 'Aggression',
        List = {'Safe', 'Balanced', 'Blatant'},
        Tooltip = 'How far the run may escalate\nSafe - walk and bridge\nBalanced - also Speed\nBlatant - also Fly'
    })
    -- This GUI's dropdowns take their starting value from the first list entry and ignore Default,
    -- so the wanted default is set explicitly. A saved config still overrides it on load.
    pcall(function() Aggression:SetValue('Balanced') end)
    TakeOver = AutoWin:CreateToggle({
        Name = 'Take over modules',
        Default = true,
        Tooltip = 'Drives your other modules during the run and puts every one of them back afterwards'
    })
    KillPlayers = AutoWin:CreateToggle({
        Name = 'Kill players',
        Default = true,
        Tooltip = 'Once every enemy bed is down, hunt the survivors instead of waiting the match out'
    })
    RespawnAfterBed = AutoWin:CreateToggle({
        Name = 'Respawn after bed',
        Default = true,
        Tooltip = 'Reset to base after each bed. Skipped once your own bed is gone, since dying would end you'
    })
    BankLoot = AutoWin:CreateToggle({
        Name = 'Bank loot',
        Default = true,
        Tooltip = 'Deposit resources before every reset so dying never costs the run what it has gathered'
    })
    YuziDash = AutoWin:CreateToggle({
        Name = 'Yuzi dash',
        Default = true,
        Tooltip = 'With a dao in hand, cross by dashing instead of bridging. Anything the dash misses is still bridged'
    })
    AutoEquipKit = AutoWin:CreateToggle({
        Name = 'Auto equip Yuzi',
        Default = true,
        Darker = true,
        Tooltip = 'Select the Yuzi kit before the match starts when the account owns it'
    })
    DaoPriority = AutoWin:CreateToggle({
        Name = 'Dao priority',
        Default = true,
        Darker = true,
        Tooltip = 'Buy the next dao up whenever it is affordable, so the dash is always on the best blade you can carry'
    })
    IronAmount = AutoWin:CreateSlider({
        Name = 'Iron amount',
        Min = 8,
        Max = 64,
        Default = 16,
        Suffix = ' iron',
        Tooltip = 'The least iron to collect before shopping. 8 iron buys 16 wool'
    })
    WoolAmount = AutoWin:CreateSlider({
        Name = 'Block amount',
        Min = 16,
        Max = 128,
        Default = 32,
        Suffix = ' blocks',
        Tooltip = 'Least to set off with when the crossing has to be built. A measured route can ask for more'
    })
    BedReach = AutoWin:CreateSlider({
        Name = 'Bed reach',
        Min = 3,
        Max = 14,
        Default = 8,
        Decimal = 10,
        Suffix = ' studs',
        Tooltip = 'How close to get to a bed before breaking it'
    })
    PlayerReach = AutoWin:CreateSlider({
        Name = 'Player reach',
        Min = 3,
        Max = 14,
        Default = 8,
        Decimal = 10,
        Suffix = ' studs',
        Tooltip = 'How close to get to a player before fighting'
    })
    StartDelay = AutoWin:CreateSlider({
        Name = 'Start delay',
        Min = 0,
        Max = 10,
        Default = 2,
        Decimal = 10,
        Suffix = ' seconds',
        Tooltip = 'How long to settle after the map loads before starting'
    })
    StuckLimit = AutoWin:CreateSlider({
        Name = 'Watchdog',
        Min = 0,
        Max = 10,
        Default = 4,
        Decimal = 10,
        Suffix = ' minutes',
        Tooltip = 'Reset the run when it has made no measurable progress for this long. 0 turns the watchdog off'
    })
    Requeue = AutoWin:CreateToggle({
        Name = 'Auto queue',
        Default = true,
        Tooltip = 'Queue the next match as soon as this one ends, or as soon as you are eliminated from it'
    })
    Gamemode = AutoWin:CreateDropdown({
        Name = 'Gamemode',
        List = (function()
            local list = {'Current', 'Random'}
            pcall(function()
                local ids = {}
                for id, meta in pairs(bedwars.QueueMeta) do
                    if not meta.disabled and not meta.voiceChatOnly then
                        table.insert(ids, id)
                    end
                end
                table.sort(ids)
                for _, id in ipairs(ids) do table.insert(list, id) end
            end)
            return list
        end)(),
        Darker = true,
        Tooltip = 'Which queue to join. Current re-queues whatever you were just playing',
        Function = function()
            writeState()
        end
    })
    ResumeInLobby = AutoWin:CreateToggle({
        Name = 'Resume in lobby',
        Default = true,
        Darker = true,
        Tooltip = 'Leaves a note the lobby AutoQueue picks up, so you are put straight back into a match',
        Function = function()
            writeState()
        end
    })
    AutoRejoin = AutoWin:CreateToggle({
        Name = 'Auto rejoin',
        Default = true,
        Tooltip = 'Teleport back to the BedWars lobby on a disconnect or an error prompt, so one network blip does not end an overnight run'
    })
    KeepAwake = AutoWin:CreateToggle({
        Name = 'Keep awake',
        Default = true,
        Tooltip = 'Run Anti-AFK for the duration, so Roblox\'s twenty minute idle kick never fires'
    })
    ShowHUD = AutoWin:CreateToggle({
        Name = 'Show HUD',
        Default = true,
        Tooltip = 'Show the progress HUD while the run is on',
        Function = function(callback)
            pcall(function()
                if hudFrame then hudFrame.Visible = callback and AutoWin.Enabled end
            end)
        end
    })
    Notify = AutoWin:CreateToggle({
        Name = 'Notifications',
        Tooltip = 'Also notify on each action change. Off by default - the HUD already says what it is doing'
    })
end)

run(function()
    -- EntityAnalyser
    --
    -- Works out how good each player actually is from what they do in front of us, and nothing
    -- else. Every input below is something the game already hands every client: damage and death
    -- events, block placements and breaks, bed breaks, replicated inventories, replicated
    -- animations, character attributes and the positions of entities that are streamed in. There
    -- is no stat page, no leaderboard and no rank lookup anywhere in here, and kills and gear are
    -- two signals out of forty-odd - neither can carry a rating on its own.
    --
    -- Six categories are scored separately (Combat, Movement, GameSense, Objectives, Resources,
    -- Teamwork) and each is built the same way: a fixed list of named signals, each reporting a
    -- deviation from -1 (as bad as it gets) to +1 (as good as it gets) together with a confidence
    -- saying how much evidence is behind it. A signal we have never observed is still declared, at
    -- confidence zero - which is what makes incomplete data cost confidence instead of quietly
    -- reweighting whatever happened to survive. The overall skill is a confidence-weighted blend
    -- of the categories, re-weighted for the role the player is actually playing, so a Support or
    -- an Economy player is not marked down against a Fighter's yardstick.
    --
    -- Things that would make a number a lie are handled where they happen rather than averaged
    -- over: kills on AFK, trapped, out-geared or repeatedly-respawning players are discounted at
    -- the moment of the kill; fights taken against equal or better gear count for more; samples
    -- taken across a teleport or a streaming gap are thrown away instead of read as movement;
    -- time we could not see the player is not counted as time observed.
    --
    -- This module is a read-out. It never touches another module's settings. What it knows is
    -- published on getgenv().EntityAnalyser and vapeEvents.EntityAnalysed for anything that wants
    -- to act on it - Killaura's 'Target skilled' is the first consumer.
    local EntityAnalyser
    local SweatAt
    local SkilledAt
    local AboveAt
    local BeginnerBelow
    local NewBelow
    local MinConfidence
    local SampleRange
    local Labels
    local ShowScore
    local ShowRole
    local ShowConfidence
    local ShowSweat
    local ShowSkilled
    local ShowAbove
    local ShowAverage
    local ShowBeginner
    local ShowNew
    local ShowUnknown
    local Teammates
    local Notify

    ----------------------------------------------------------------------------
    -- Constants.
    ----------------------------------------------------------------------------
    local COMBO_WINDOW = 1.6      -- hits inside this gap are one combo
    local FIGHT_MEMORY = 6        -- still "in a fight" this long after a hit either way
    local ENGAGE_MEMORY = 14      -- an engagement stays resolvable this long after its last hit
    local ASSIST_WINDOW = 8       -- damage this recent counts toward someone else's kill
    local SWING_WINDOW = 0.28     -- a swing this soon before damage is the swing that landed
    local AFK_TIME = 12           -- no movement and no action for this long reads as AFK
    local TELEPORT_JUMP = 90      -- a position step bigger than this is lag, not movement
    local EVENT_LIMIT = 12        -- RecentEvents ring size
    local RESCORE_INTERVAL = 0.5  -- a profile is rebuilt at most this often
    local FAR_INTERVAL = 0.5      -- sampling period outside the near radius
    local AFK_INTERVAL = 2        -- sampling period for someone who is not doing anything
    local PROBE_INTERVAL = 0.1    -- terrain probe period for near players
    local PROBE_BUDGET = 4        -- terrain probes allowed per frame, across everyone
    local WORLD_INTERVAL = 0.5    -- bed/generator/roster snapshot rebuild period
    local HEAVY_INTERVAL = 0.5    -- period for the per-player checks that allocate
    local BED_NEAR = 30           -- "at a bed" radius
    local GEN_NEAR = 16           -- "at a generator" radius
    local THREAT_NEAR = 35        -- an enemy this close is a threat to have noticed
    local MATE_NEAR = 45          -- a teammate this close is one you could have helped
    local VOID_WINDOW = 4         -- knockback to void death has to land inside this
    local SEEN_TIMEOUT = 2        -- no sample for this long is a streaming gap, not idling

    local ratingColor = {
        Sweat = Color3.fromRGB(255, 105, 180),
        Skilled = Color3.fromRGB(85, 220, 130),
        ['Above Average'] = Color3.fromRGB(170, 225, 110),
        Average = Color3.fromRGB(235, 205, 90),
        Beginner = Color3.fromRGB(235, 95, 95),
        New = Color3.fromRGB(170, 115, 115),
        Unknown = Color3.fromRGB(150, 150, 158)
    }

    local ROLES = {'Rusher', 'Defender', 'Fighter', 'Support', 'Economy', 'ResourceControl'}
    local CATEGORIES = {'Combat', 'Movement', 'GameSense', 'Objectives', 'Resources', 'Teamwork'}

    -- How much each category counts toward the overall score, per role. A Defender who never
    -- rushes is not a worse player for it, so Objectives weighs less for them and the job they
    -- are actually doing weighs more. Mixed is the neutral profile everyone starts on.
    local ROLE_WEIGHTS = {
        Mixed           = {Combat = 1.00, Movement = 0.75, GameSense = 1.00, Objectives = 0.85, Resources = 0.55, Teamwork = 0.60},
        Rusher          = {Combat = 1.00, Movement = 0.95, GameSense = 0.85, Objectives = 1.20, Resources = 0.45, Teamwork = 0.50},
        Defender        = {Combat = 0.95, Movement = 0.70, GameSense = 1.20, Objectives = 0.70, Resources = 0.60, Teamwork = 0.90},
        Fighter         = {Combat = 1.30, Movement = 0.90, GameSense = 0.95, Objectives = 0.60, Resources = 0.40, Teamwork = 0.55},
        Support         = {Combat = 0.70, Movement = 0.70, GameSense = 1.05, Objectives = 0.65, Resources = 0.70, Teamwork = 1.35},
        Economy         = {Combat = 0.60, Movement = 0.70, GameSense = 0.95, Objectives = 0.70, Resources = 1.35, Teamwork = 0.85},
        ResourceControl = {Combat = 0.85, Movement = 0.75, GameSense = 1.10, Objectives = 0.75, Resources = 1.15, Teamwork = 0.90}
    }

    ----------------------------------------------------------------------------
    -- Rolling statistics.
    ----------------------------------------------------------------------------
    -- A mean that converges fast while there is little evidence and settles as more arrives, so an
    -- early read is usable and a late one is stable. `n` is the evidence weight behind it, which
    -- is what every count-based confidence term in the module is built from.
    local function meter(initial)
        return {v = initial or 0, n = 0}
    end

    local function observe(m, value, weight)
        weight = weight or 1
        if weight <= 0 or value ~= value then return end
        m.n = m.n + weight
        m.v = m.v + (value - m.v) * math.clamp(weight / math.min(m.n, 24), 0.04, 1)
    end

    -- Confidence a meter has earned. `full` is the observation weight at which the signal counts
    -- as properly evidenced; below that it is scaled down rather than dropped off a cliff.
    local function evidence(m, full)
        return math.clamp(m.n / (full or 8), 0, 1)
    end

    local function countConf(count, full)
        return math.clamp(count / (full or 6), 0, 1)
    end

    local function safeDiv(a, b)
        return b > 0 and (a / b) or 0
    end

    -- Maps a measurement onto the -1..+1 the blender wants, given the value a weak player produces
    -- and the value a strong one does. Used where both ends mean something - an accuracy of zero
    -- really is bad, not merely unremarkable.
    local function scale(value, low, high)
        if low == high then return 0 end
        return math.clamp((value - low) / (high - low), 0, 1) * 2 - 1
    end

    -- Counting signals where doing none of it is unremarkable rather than bad. Most players never
    -- break a bed; that is not a flaw, so zero has to land on neutral and not on -1.
    local function reward(value, good)
        if good <= 0 then return 0 end
        return math.clamp(value / good, 0, 1)
    end

    -- Signals where both extremes are wrong and the middle is right - target switching, time spent
    -- on a generator.
    local function bell(value, ideal, spread)
        if spread <= 0 then return 0 end
        return math.clamp(1 - (math.abs(value - ideal) / spread), -1, 1)
    end

    ----------------------------------------------------------------------------
    -- The blender.
    ----------------------------------------------------------------------------
    -- Every category is a bag of named signals. `total` accumulates the weight of every signal the
    -- category declares, `conf` the weight actually backed by evidence - so a category we can only
    -- half observe reports a middling confidence and a score pulled toward 50, rather than a
    -- confident-looking score assembled from whichever three signals happened to have data.
    local function blender()
        return {sum = 0, weight = 0, conf = 0, total = 0, named = {}}
    end

    local function signal(b, name, deviation, weight, confidence)
        weight = weight or 1
        confidence = math.clamp(confidence or 0, 0, 1)
        deviation = math.clamp(deviation or 0, -1, 1)
        b.total = b.total + weight
        b.conf = b.conf + weight * confidence
        local w = weight * confidence
        if w > 0 then
            b.sum = b.sum + deviation * w
            b.weight = b.weight + w
            b.named[name] = {Deviation = deviation, Confidence = confidence, Weight = weight}
        end
    end

    local function resolve(b)
        if b.total <= 0 then return 50, 0, b end
        local conf = b.conf / b.total
        if b.weight <= 0 then return 50, conf, b end
        local mean = b.sum / b.weight
        -- Low confidence holds the score near Average, so one well-evidenced signal in an
        -- otherwise unobserved category cannot swing it to an extreme.
        return math.clamp(50 + mean * 50 * (0.4 + 0.6 * conf), 0, 100), conf, b
    end

    ----------------------------------------------------------------------------
    -- State.
    ----------------------------------------------------------------------------
    local profiles, engagements, pendingVoid, tags, seen = {}, {}, {}, {}, {}
    local folder
    local running = false
    local probeBudget = 0
    local matchStart, bedsAtStart, lastMatchState = tick(), 0, -1

    -- Bed, generator and player positions are rebuilt a couple of times a second and shared by
    -- everyone, so the per-frame sampling never walks CollectionService or re-reads a position
    -- once per player per player.
    local world = {
        At = 0,
        Beds = {},
        Generators = {},
        Roster = {},
        Stage = 'Early',
        Elapsed = 0,
        TeamSize = 1
    }

    local function newProfile(plr)
        local now = tick()
        return {
            Player = plr,
            FirstSeen = now,
            LastSeen = now,
            LastSample = 0,
            LastProbe = 0,
            LastHeavy = 0,
            Observed = 0,       -- seconds we have actually had eyes on them
            Dirty = true,
            NextScore = 0,
            Cache = nil,
            Events = {},

            Combat = {
                Swings = 0, SwingHits = 0, SwingIds = {}, PendingSwing = 0, PendingSwingId = nil,
                Hits = 0, MeleeHits = 0,
                Projectiles = 0, ProjectileHits = 0,
                DamageDealt = 0, DamageTaken = 0,
                Kills = 0, Deaths = 0, FinalKills = 0,
                FightsWon = 0, FightsLost = 0,
                UphillFights = 0, UphillWins = 0,
                Combo = 0, BestCombo = 0, ComboCount = 0, ComboHits = 0,
                LastVictim = nil, LastHit = 0,
                LastHurt = 0, LastHurtBy = nil,
                FirstHits = 0, FirstHitChances = 0,
                VoidKills = 0,
                Switches = 0, SwitchSeen = {}, SwitchAt = 0,
                Reaction = meter(0),
                Strafe = meter(0),
                Tracking = meter(0),
                KillQuality = meter(1)
            },

            Movement = {
                Blocks = 0, BridgeRun = 0, BridgeTime = 0, BridgeAt = 0,
                Distance = 0, Pauses = 0, PauseAt = 0,
                Falls = 0, UnforcedFalls = 0, Saves = 0, Parkour = 0, Jumps = 0,
                Clutches = 0,
                KnockbackAt = 0, KnockbackFrom = nil,
                EdgeApproaches = 0, EdgeStops = 0, EdgeAt = 0,
                LastPos = nil, LastDir = nil, LastVel = nil,
                Ground = nil, OverVoid = false,
                FallFrom = nil, Airborne = false,
                BridgeSpeed = meter(0),
                Recovery = meter(0),
                Positioning = meter(0)
            },

            Sense = {
                Threats = 0, ThreatReactions = 0, ThreatFrom = nil, ThreatAt = 0, ThreatAnswered = false,
                BedAlerts = 0, BedResponses = 0, BedAlert = false, LastAlert = 0,
                Retreats = 0, RetreatFrom = nil, RetreatAt = 0,
                Chases = 0, PointlessChases = 0, ChaseAt = 0,
                SafeTime = 0, ExposedTime = 0,
                ToolSwaps = 0, LastHand = nil,
                LowHealthDeaths = 0, LowHealthEscapes = 0,
                SaveChanceAt = 0,
                BedResponseTime = meter(0)
            },

            Objectives = {
                BedApproaches = 0, BedApproachAt = 0,
                DefenceBroken = 0,
                Rushes = 0, RushWins = 0,
                Beds = 0,
                FinalKills = 0, Assists = 0, Escapes = 0,
                Pressure = 0,
                BedBreakTime = meter(0)
            },

            Resources = {
                GenTime = 0, GenAt = 0, GenVisits = 0,
                Iron = 0, Diamond = 0, Emerald = 0,
                IronSpent = 0, DiamondSpent = 0, EmeraldSpent = 0,
                Lost = 0, LostEvents = 0,
                Purchases = 0, Upgrades = 0,
                BestGear = 0,
                LastInventory = nil, InventoryAt = 0,
                Prepared = meter(0),
                GearTier = meter(0)
            },

            Teamwork = {
                Assists = 0,
                Saves = 0, SaveChances = 0, SaveAt = 0,
                Shared = 0,
                Defends = 0,
                PushWindow = 0,
                ControlTime = 0
            },

            Context = {
                Kit = nil, Team = nil,
                AFK = false,
                LastMove = now, LastAction = now,
                Alive = true, Respawns = 0, LastDeath = 0,
                Trapped = false,
                Lagged = 0, Samples = 0,
                Gaps = 0, GapTime = 0,
                Health = 1, Gear = 0, Armour = 0
            }
        }
    end

    local function profileFor(plr)
        if not plr then return nil end
        local record = profiles[plr]
        if not record then
            record = newProfile(plr)
            profiles[plr] = record
        end
        return record
    end

    -- Read path only, so asking about a player never allocates them a profile.
    local function peek(plr)
        return plr and profiles[plr] or nil
    end

    local function touch(record)
        record.Dirty = true
    end

    local function addEvent(record, kind, confidence, detail)
        local events = record.Events
        table.insert(events, {Type = kind, Time = tick(), Confidence = math.clamp(confidence or 1, 0, 1), Detail = detail})
        while #events > EVENT_LIMIT do
            table.remove(events, 1)
        end
        record.Dirty = true
    end

    ----------------------------------------------------------------------------
    -- Match context.
    ----------------------------------------------------------------------------
    local function teamOf(plr)
        if not plr then return nil end
        local team = plr:GetAttribute('Team')
        if team == nil and plr.Character then
            team = plr.Character:GetAttribute('Team')
        end
        return team
    end

    local function sameTeam(a, b)
        local ta, tb = teamOf(a), teamOf(b)
        return ta ~= nil and tb ~= nil and ta == tb
    end

    -- 0 = warmup, 1 = playing, 2 = over. Only a live match is worth judging anyone on, so the
    -- event handlers gate on this while the labels keep rendering whatever we already know.
    local function playing()
        return store.matchState == 1
    end

    local function bedPartOf(bed)
        return bed:IsA('BasePart') and bed or bed:FindFirstChildWhichIsA('BasePart')
    end

    local function refreshWorld(now)
        if now - world.At < WORLD_INTERVAL then return end
        world.At = now

        table.clear(world.Beds)
        local standing = 0
        for _, bed in collectionService:GetTagged('bed') do
            if bed.Parent then
                local part = bedPartOf(bed)
                if part then
                    standing = standing + 1
                    table.insert(world.Beds, {Position = part.Position, Object = bed})
                end
            end
        end

        table.clear(world.Generators)
        for _, gen in collectionService:GetTagged('Generator') do
            local part = gen:IsA('BasePart') and gen or gen:FindFirstChildWhichIsA('BasePart')
            if part then
                local id = tostring(gen:GetAttribute('Id') or ''):lower()
                table.insert(world.Generators, {
                    Position = part.Position,
                    Kind = id:find('emerald') and 'emerald' or id:find('diamond') and 'diamond' or 'iron'
                })
            end
        end

        -- One pass for the roster: positions, teams and the biggest team in the lobby, which is
        -- the only honest read on whether this is solos or squads. We are in it too, because we
        -- are a threat to stand on somebody's bed like anyone else.
        table.clear(world.Roster)
        local sizes, biggest = {}, 1
        local function addToRoster(plr, root)
            if not plr or not root or not root.Parent then return end
            local team = teamOf(plr)
            table.insert(world.Roster, {Player = plr, Position = root.Position, Team = team})
            if team ~= nil then
                sizes[team] = (sizes[team] or 0) + 1
                biggest = math.max(biggest, sizes[team])
            end
        end
        for _, ent in entitylib.List do
            addToRoster(ent.Player, ent.RootPart)
        end
        if entitylib.isAlive then
            addToRoster(lplr, entitylib.character.RootPart)
        end
        world.TeamSize = biggest

        -- Early / mid / late, from the clock and from how many beds are left. Rushing is worth far
        -- more in the first two minutes, and what counts as impressive gear moves with the match.
        local elapsed = now - matchStart
        local fraction = safeDiv(standing, math.max(bedsAtStart, standing, 1))
        world.Elapsed = elapsed
        if elapsed < 150 and fraction > 0.7 then
            world.Stage = 'Early'
        elseif elapsed > 480 or fraction < 0.35 then
            world.Stage = 'Late'
        else
            world.Stage = 'Mid'
        end
    end

    -- The bed belonging to this player's team, and the nearest bed that does not - the two things
    -- every objective, defence and positioning signal is measured against.
    local function bedsFor(plr, position)
        local team = teamOf(plr)
        local own, ownDist, enemy, enemyDist = nil, math.huge, nil, math.huge
        for _, bed in world.Beds do
            local mine = team ~= nil and bed.Object:GetAttribute('Team' .. team .. 'NoBreak') and true or false
            local dist = position and (bed.Position - position).Magnitude or math.huge
            if mine then
                -- Their own bed is theirs whether or not we were given a position to measure to.
                if own == nil or dist < ownDist then
                    own, ownDist = bed, dist
                end
            elseif dist < enemyDist then
                enemy, enemyDist = bed, dist
            end
        end
        return own, ownDist, enemy, enemyDist
    end

    local function nearestGenerator(position)
        local bestDist, bestKind = math.huge, nil
        for _, gen in world.Generators do
            local dist = (gen.Position - position).Magnitude
            if dist < bestDist then
                bestDist, bestKind = dist, gen.Kind
            end
        end
        return bestDist, bestKind
    end

    ----------------------------------------------------------------------------
    -- Gear, health and kits.
    ----------------------------------------------------------------------------
    local function inventoryOf(plr)
        return store.inventories[plr]
    end

    local function swordDamage(inv)
        local best = 0
        for _, item in (inv and inv.items or {}) do
            local meta = bedwars.ItemMeta[item.itemType]
            if meta and meta.sword and (meta.sword.damage or 0) > best then
                best = meta.sword.damage
            end
        end
        return best
    end

    local function armourValue(inv)
        local total = 0
        for _, item in (inv and inv.armor or {}) do
            local meta = item and bedwars.ItemMeta[item.itemType]
            if meta and meta.armor then
                total = total + (meta.armor.damageReductionMultiplier or 0)
            end
        end
        return total
    end

    local function resourceCount(inv, kind)
        local total = 0
        for _, item in (inv and inv.items or {}) do
            if item.itemType == kind then
                total = total + (item.amount or 0)
            end
        end
        return total
    end

    -- One number for "how well equipped are they", weapon and armour together, so comparing two
    -- players' gear is a single subtraction. nil when their inventory has not replicated to us -
    -- which is a missing input, not a player with nothing.
    local function gearOf(plr)
        local inv = inventoryOf(plr)
        if not inv then return nil end
        return swordDamage(inv) + armourValue(inv) * 30
    end

    local function healthFraction(plr)
        local char = plr.Character
        if not char then return 1 end
        local health, maximum = char:GetAttribute('Health'), char:GetAttribute('MaxHealth')
        if not health or not maximum or maximum <= 0 then return 1 end
        return math.clamp(health / maximum, 0, 1)
    end

    local function kitOf(plr)
        return plr:GetAttribute('PlayingAsKits') or plr:GetAttribute('PlayingAsKit') or nil
    end

    -- Kits change what a signal is worth. A kit that hands out mobility makes bridging and parkour
    -- cheaper to look good at; a kit with a combat ability does the same for damage. These only
    -- soften the confidence of the affected signals, never the score itself, so a kit we do not
    -- recognise costs nobody anything.
    local KIT_MOVEMENT = {dasher = 0.7, angel = 0.65, void_dragon = 0.6, owl = 0.7, dragonslayer = 0.8, yuzi = 0.8, melody = 0.85, cyber = 0.8}
    local KIT_COMBAT = {barbarian = 0.8, vulcan = 0.75, ember = 0.8, ice_queen = 0.85, mage = 0.85, ranger = 0.85, pyro = 0.85}

    -- Status effects replicate as character attributes. Being trapped or frozen is not a skill
    -- failure, and killing somebody who is is not a skill success.
    local function statusTrapped(plr)
        local char = plr.Character
        if not char then return false end
        for name, value in char:GetAttributes() do
            if type(name) == 'string' and name:find('StatusEffect_') and value ~= false and value ~= 0 then
                local lowered = name:lower()
                if lowered:find('trap') or lowered:find('stun') or lowered:find('freeze') or lowered:find('root') or lowered:find('web') then
                    return true
                end
            end
        end
        return false
    end

    ----------------------------------------------------------------------------
    -- Data quality.
    ----------------------------------------------------------------------------
    local function localPing()
        local ping = 0
        pcall(function()
            ping = lplr:GetNetworkPing()
        end)
        return ping
    end

    -- Everything timing-sensitive - reaction time, first hits, aim tracking - is measured through
    -- our own connection, so our own ping is a hard ceiling on how far any of it can be trusted.
    local function timingConfidence()
        return math.clamp(1 - (localPing() / 0.35), 0.15, 1)
    end

    -- How much of what we think we know is actually ours to know. Time streamed out, samples
    -- thrown away as lag and a missing replicated inventory all land here, and all of them cost
    -- confidence rather than quietly changing the score.
    local function dataQuality(record)
        local context = record.Context
        local watched = math.max(record.Observed, 0.01)
        local coverage = math.clamp(watched / math.max(tick() - record.FirstSeen, watched), 0.2, 1)
        local clean = 1 - math.clamp(safeDiv(context.Lagged, math.max(context.Samples, 1)), 0, 0.6)
        return math.clamp(coverage * clean * (inventoryOf(record.Player) and 1 or 0.75), 0.1, 1)
    end

    -- A player nobody should be scored against. Returns 0..1, where 1 is somebody in a fair state
    -- to be fighting. This is the number that stops farming reading as skill.
    local function playerQuality(record)
        if not record then return 0.5 end
        local context = record.Context
        local quality = 1
        if context.AFK then
            quality = quality * 0.15
        end
        if context.Trapped then
            quality = quality * 0.4
        end
        -- Repeatedly respawning into the same fight. Every death inside the last minute makes the
        -- next one worth less to whoever takes it.
        local rate = safeDiv(context.Respawns, math.max((tick() - record.FirstSeen) / 60, 0.5))
        if rate > 1.5 then
            quality = quality * math.clamp(1 - (rate - 1.5) * 0.3, 0.3, 1)
        end
        if context.Health < 0.35 then
            quality = quality * 0.7
        end
        return math.clamp(quality, 0.05, 1)
    end

    ----------------------------------------------------------------------------
    -- Engagements.
    ----------------------------------------------------------------------------
    -- A fight is a pair of players trading damage. Tracking it as an object rather than as two
    -- separate hit counters is what makes first-hit rate, fight wins, escapes, assists and
    -- gear-relative performance answerable at all.
    local function engagementFor(attacker, victim)
        local key, flipped
        if attacker.UserId < victim.UserId then
            key, flipped = attacker.UserId .. ':' .. victim.UserId, false
        else
            key, flipped = victim.UserId .. ':' .. attacker.UserId, true
        end

        local now = tick()
        local fight = engagements[key]
        if fight and now - fight.Last > ENGAGE_MEMORY then
            engagements[key] = nil
            fight = nil
        end
        if not fight then
            fight = {
                A = flipped and victim or attacker,
                B = flipped and attacker or victim,
                Start = now,
                Opener = attacker,
                Damage = {},
                Counted = false,
                Resolved = false,
                -- Gear as it stood when the fight opened. The winner may well be holding the
                -- loser's kit by the time it ends, so reading it later would invert the signal.
                GearA = gearOf(flipped and victim or attacker),
                GearB = gearOf(flipped and attacker or victim)
            }
            engagements[key] = fight
        end
        fight.Last = now
        return fight
    end

    local function engagementsInvolving(plr, into)
        table.clear(into)
        for _, fight in engagements do
            if fight.A == plr or fight.B == plr then
                table.insert(into, fight)
            end
        end
        return into
    end

    ----------------------------------------------------------------------------
    -- Event ingestion: swings.
    ----------------------------------------------------------------------------
    -- Swing animations replicate, so misses are countable - but only once we know which of a
    -- player's animations is their swing. The first animation id that keeps coinciding with their
    -- damage output becomes their swing id, and only then do misses start counting, so a kit
    -- ability is never mistaken for a whiffed hit. Until an id is confirmed nothing is scored.
    local function noteSwing(plr, animationId)
        local record = peek(plr)
        if not record then return end
        local combat = record.Combat
        local entry = combat.SwingIds[animationId]
        if not entry then
            entry = {Seen = 0, Hits = 0, Confirmed = false}
            combat.SwingIds[animationId] = entry
        end
        entry.Seen = entry.Seen + 1
        if entry.Confirmed then
            combat.Swings = combat.Swings + 1
        end
        combat.PendingSwing = tick()
        combat.PendingSwingId = animationId
        record.Context.LastAction = tick()
    end

    local function confirmSwing(record)
        local combat = record.Combat
        local id = combat.PendingSwingId
        if not id or tick() - combat.PendingSwing > SWING_WINDOW then return end
        local entry = combat.SwingIds[id]
        if not entry then return end
        entry.Hits = entry.Hits + 1
        if entry.Confirmed then
            combat.SwingHits = combat.SwingHits + 1
        elseif entry.Hits >= 3 and entry.Hits / math.max(entry.Seen, 1) > 0.3 then
            -- Recognised. Everything already seen for this id was a swing, so accuracy does not
            -- restart from zero the moment we work out what we have been watching.
            entry.Confirmed = true
            combat.Swings = combat.Swings + entry.Seen
            combat.SwingHits = combat.SwingHits + entry.Hits
        end
        combat.PendingSwingId = nil
    end

    ----------------------------------------------------------------------------
    -- Event ingestion: damage.
    ----------------------------------------------------------------------------
    local function noteTargetSwitch(record, victim)
        local combat = record.Combat
        local now = tick()
        if now - combat.SwitchAt > FIGHT_MEMORY then
            table.clear(combat.SwitchSeen)
            combat.SwitchAt = now
        end
        if victim and not combat.SwitchSeen[victim] then
            combat.SwitchSeen[victim] = true
            local count = 0
            for _ in combat.SwitchSeen do
                count = count + 1
            end
            if count > 1 then
                combat.Switches = combat.Switches + 1
            end
        end
    end

    local fightScratch = {}

    local function onDamage(damageTable)
        if not running or not playing() then return end
        local amount = damageTable.damage or 0
        if amount <= 0 then return end

        local attacker = damageTable.fromEntity and playersService:GetPlayerFromCharacter(damageTable.fromEntity)
        local victim = damageTable.entityInstance and playersService:GetPlayerFromCharacter(damageTable.entityInstance)
        if attacker == victim then return end
        if not attacker and not victim then return end

        local now = tick()
        local melee = damageTable.damageType == 0
        local attackerRecord = attacker and attacker ~= lplr and profileFor(attacker) or nil
        local victimRecord = victim and victim ~= lplr and profileFor(victim) or nil

        if victimRecord then
            local combat = victimRecord.Combat
            combat.DamageTaken = combat.DamageTaken + amount
            combat.LastHurt = now
            combat.LastHurtBy = attacker
            victimRecord.Context.LastAction = now
            -- Knockback is what actually kills people over a gap, so remember who applied it and
            -- whether the victim was over open air when it landed.
            local knockback = damageTable.knockbackMultiplier
            if knockback and not knockback.disabled and attacker then
                victimRecord.Movement.KnockbackAt = now
                victimRecord.Movement.KnockbackFrom = attacker
                if victimRecord.Movement.OverVoid then
                    pendingVoid[victim] = {From = attacker, At = now}
                end
            end
            touch(victimRecord)
        end

        -- The engagement is tracked from whichever side we can profile, including fights against
        -- us. A player who spends the whole match on the local player would otherwise finish it
        -- with no fight wins, no first hits and no gear-relative record at all - there is simply
        -- nobody to award the other half of each fight to.
        if attacker and victim then
            local fight = engagementFor(attacker, victim)
            fight.Damage[attacker] = (fight.Damage[attacker] or 0) + amount

            -- First hit. Only the opener gets the credit, and only once per fight, so a long
            -- scrap cannot inflate it.
            if not fight.Counted then
                fight.Counted = true
                if attackerRecord then
                    attackerRecord.Combat.FirstHitChances = attackerRecord.Combat.FirstHitChances + 1
                    if fight.Opener == attacker then
                        attackerRecord.Combat.FirstHits = attackerRecord.Combat.FirstHits + 1
                    end
                end
                if victimRecord then
                    victimRecord.Combat.FirstHitChances = victimRecord.Combat.FirstHitChances + 1
                end
            end
        end

        if not attackerRecord then return end
        local combat = attackerRecord.Combat
        combat.DamageDealt = combat.DamageDealt + amount
        combat.Hits = combat.Hits + 1
        attackerRecord.Context.LastAction = now
        if melee then
            combat.MeleeHits = combat.MeleeHits + 1
            confirmSwing(attackerRecord)
        else
            combat.ProjectileHits = combat.ProjectileHits + 1
        end

        -- Combo: hits that keep landing on the same person without a gap. Any pause or a change of
        -- victim ends it, so two people trading singles never adds up into one long combo.
        if combat.LastVictim == victim and now - combat.LastHit <= COMBO_WINDOW then
            combat.Combo = combat.Combo + 1
            combat.ComboHits = combat.ComboHits + 1
            if combat.Combo == 3 then
                combat.ComboCount = combat.ComboCount + 1
                addEvent(attackerRecord, 'Combo', 1, victim and victim.Name or nil)
            end
        else
            combat.Combo = 1
        end
        combat.BestCombo = math.max(combat.BestCombo, combat.Combo)
        combat.LastVictim, combat.LastHit = victim, now
        noteTargetSwitch(attackerRecord, victim)

        -- Reaction time: how quickly they answer being hit themselves.
        if combat.LastHurt > 0 and now - combat.LastHurt < 2 then
            observe(combat.Reaction, math.clamp(now - combat.LastHurt, 0.05, 2))
        end

        if not victim then
            touch(attackerRecord)
            return
        end

        -- Protecting a teammate: hitting somebody who is at that moment in a fight with one of
        -- your own. Rate limited so holding an angle on one attacker is one save, not thirty.
        if now - attackerRecord.Teamwork.SaveAt > 3 then
            for _, other in engagementsInvolving(victim, fightScratch) do
                local partner = other.A == victim and other.B or other.A
                if partner ~= attacker and sameTeam(partner, attacker) and now - other.Last <= FIGHT_MEMORY then
                    attackerRecord.Teamwork.Saves = attackerRecord.Teamwork.Saves + 1
                    attackerRecord.Teamwork.SaveAt = now
                    break
                end
            end
        end

        touch(attackerRecord)
    end

    ----------------------------------------------------------------------------
    -- Event ingestion: deaths.
    ----------------------------------------------------------------------------
    local function resolveEngagements(victim, killer)
        local now = tick()
        local fights = engagementsInvolving(victim, {})
        for _, fight in fights do
            local other = fight.A == victim and fight.B or fight.A
            local otherRecord = peek(other)

            if not fight.Resolved then
                fight.Resolved = true
                local victimRecord = peek(victim)
                if victimRecord then
                    victimRecord.Combat.FightsLost = victimRecord.Combat.FightsLost + 1
                end
                if otherRecord and (killer == other or (fight.Damage[other] or 0) > 0) then
                    otherRecord.Combat.FightsWon = otherRecord.Combat.FightsWon + 1
                    local mine = fight.A == other and fight.GearA or fight.GearB
                    local theirs = fight.A == other and fight.GearB or fight.GearA
                    -- Only counts as a fair test when we actually knew both loadouts.
                    if mine and theirs then
                        otherRecord.Combat.UphillFights = otherRecord.Combat.UphillFights + 1
                        if mine <= theirs + 1 then
                            otherRecord.Combat.UphillWins = otherRecord.Combat.UphillWins + 1
                            addEvent(otherRecord, 'UphillWin', 0.85, victim.Name)
                        end
                    end
                end
            end

            -- Anyone who did real damage inside the assist window and did not land the kill.
            if other ~= killer and (fight.Damage[other] or 0) > 0 and now - fight.Last <= ASSIST_WINDOW then
                if otherRecord and not sameTeam(other, victim) then
                    otherRecord.Objectives.Assists = otherRecord.Objectives.Assists + 1
                    otherRecord.Teamwork.Assists = otherRecord.Teamwork.Assists + 1
                    addEvent(otherRecord, 'Assist', 0.8, victim.Name)
                end
            end
        end
    end

    local function onDeath(deathTable)
        if not running then return end
        local killer = deathTable.fromEntity and playersService:GetPlayerFromCharacter(deathTable.fromEntity)
        local victim = deathTable.entityInstance and playersService:GetPlayerFromCharacter(deathTable.entityInstance)
        if not victim then return end

        local now = tick()
        local victimRecord = victim ~= lplr and profileFor(victim) or nil
        if victimRecord then
            local context = victimRecord.Context
            context.Alive = false
            context.Respawns = context.Respawns + 1
            context.LastDeath = now
            victimRecord.Combat.Deaths = victimRecord.Combat.Deaths + 1
            victimRecord.Combat.Combo = 0

            -- What the death cost them. The last inventory we saw is the best estimate, and it is
            -- the number that separates a careful player from one who dies holding forty iron.
            local inv = victimRecord.Resources.LastInventory
            if inv then
                local lost = inv.Iron + inv.Diamond * 4 + inv.Emerald * 8
                if lost > 0 then
                    victimRecord.Resources.Lost = victimRecord.Resources.Lost + lost
                    victimRecord.Resources.LostEvents = victimRecord.Resources.LostEvents + 1
                end
            end
            addEvent(victimRecord, deathTable.finalKill and 'Eliminated' or 'Death', 1, killer and killer.Name or nil)
        end

        -- Void kill: somebody knocked them out over open air and the death followed. Inferred, so
        -- it carries a confidence rather than being counted as a clean fact.
        local void = pendingVoid[victim]
        if void and now - void.At <= VOID_WINDOW then
            local voidRecord = peek(void.From)
            if voidRecord and not sameTeam(void.From, victim) then
                voidRecord.Combat.VoidKills = voidRecord.Combat.VoidKills + 1
                addEvent(voidRecord, 'VoidKnockback', 0.7, victim.Name)
            end
        end
        pendingVoid[victim] = nil

        if killer and killer ~= victim and killer ~= lplr and not sameTeam(killer, victim) then
            local killerRecord = profileFor(killer)
            killerRecord.Combat.Kills = killerRecord.Combat.Kills + 1
            killerRecord.Context.LastAction = now

            -- What was this kill actually worth? An AFK, trapped, out-geared or endlessly
            -- respawning victim is not evidence of skill, and the discount is applied here rather
            -- than by trying to unpick it from an aggregate later. Killing us is worth most of a
            -- real kill - we are demonstrably a live human - but we do not profile ourselves, so
            -- it cannot be checked the way everybody else's is.
            local quality = victimRecord and playerQuality(victimRecord) or (victim == lplr and 0.85 or 0.5)
            local killerGear, victimGear = gearOf(killer), gearOf(victim)
            if killerGear and victimGear and killerGear > victimGear + 20 then
                quality = quality * math.clamp(1 - (killerGear - victimGear - 20) / 80, 0.35, 1)
            end
            observe(killerRecord.Combat.KillQuality, quality)

            if deathTable.finalKill then
                killerRecord.Combat.FinalKills = killerRecord.Combat.FinalKills + 1
                killerRecord.Objectives.FinalKills = killerRecord.Objectives.FinalKills + 1
                addEvent(killerRecord, 'FinalKill', 1, victim.Name)
            else
                addEvent(killerRecord, 'Kill', 1, victim.Name)
            end
        end

        resolveEngagements(victim, killer)
    end

    ----------------------------------------------------------------------------
    -- Event ingestion: beds and blocks.
    ----------------------------------------------------------------------------
    -- One place to register "they have turned up at somebody else's bed", so the counters and the
    -- event trail agree however we came to notice. Standing near a bed is weak evidence of intent
    -- and only reads as a rush early on; taking its defence apart is neither, and the confidence
    -- carried by the event says which of the two it was.
    local function noteBedApproach(record, rushing, confidence)
        if record.Objectives.BedApproachAt ~= 0 then return end
        record.Objectives.BedApproachAt = tick()
        record.Objectives.BedApproaches = record.Objectives.BedApproaches + 1
        if rushing then
            record.Objectives.Rushes = record.Objectives.Rushes + 1
        end
        addEvent(record, 'BedApproach', confidence, world.Stage)
    end

    local function onBedBreak(bedTable)
        if not running then return end
        local breaker = bedTable.player
        if not breaker or breaker == lplr then return end
        local record = profileFor(breaker)
        record.Objectives.Beds = record.Objectives.Beds + 1
        record.Context.LastAction = tick()

        -- How long from turning up at that bed to taking it. Short is a clean break; a long one
        -- means they were fought off it and came back, which is a different story - and a better
        -- one, so it is credited as a rush that eventually worked either way.
        if record.Objectives.BedApproachAt > 0 then
            observe(record.Objectives.BedBreakTime, math.clamp(tick() - record.Objectives.BedApproachAt, 1, 120))
            record.Objectives.RushWins = record.Objectives.RushWins + 1
            record.Objectives.BedApproachAt = 0
        end

        addEvent(record, 'BedBreak', 1, world.Stage)
        -- Pressure created for teammates: a bed gone is a team that has to defend instead of push.
        for _, entry in world.Roster do
            if entry.Player ~= breaker and sameTeam(entry.Player, breaker) then
                local mate = peek(entry.Player)
                if mate then
                    mate.Objectives.Pressure = mate.Objectives.Pressure + 1
                    touch(mate)
                end
            end
        end
    end

    local function onPlaceBlock(data)
        if not running or not playing() then return end
        local plr = data.player
        if not plr or plr == lplr then return end
        local record = profileFor(plr)
        local movement, now = record.Movement, tick()
        movement.Blocks = movement.Blocks + 1
        record.Context.LastAction = now

        -- Bridging: blocks laid in an unbroken run. The rate over the run is the speed signal, and
        -- a run that keeps going is what tells bridging apart from panic placing.
        if now - movement.BridgeAt <= 1.2 then
            movement.BridgeRun = movement.BridgeRun + 1
            movement.BridgeTime = movement.BridgeTime + (now - movement.BridgeAt)
            if movement.BridgeRun >= 4 and movement.BridgeTime > 0 then
                observe(movement.BridgeSpeed, movement.BridgeRun / movement.BridgeTime, 0.5)
            end
        else
            movement.BridgeRun, movement.BridgeTime = 1, 0
        end
        movement.BridgeAt = now

        local position = data.blockRef and data.blockRef.blockPosition
        if not position then
            touch(record)
            return
        end
        position = position * 3

        -- A block dropped under their own feet while falling fast is a clutch, not a bridge.
        if movement.LastPos and movement.LastVel and position.Y < movement.LastPos.Y - 2 and movement.LastVel.Y < -35 then
            movement.Clutches = movement.Clutches + 1
            addEvent(record, 'BlockClutch', 0.75)
        end

        local own, ownDist, _, enemyDist = bedsFor(plr, position)
        if own and ownDist <= BED_NEAR then
            record.Teamwork.Defends = record.Teamwork.Defends + 1
            if record.Sense.BedAlert and record.Sense.LastAlert > 0 then
                record.Sense.BedResponses = record.Sense.BedResponses + 1
                observe(record.Sense.BedResponseTime, math.clamp(now - record.Sense.LastAlert, 0.5, 30))
                record.Sense.BedAlert = false
            end
        elseif enemyDist <= BED_NEAR then
            -- Blocks at somebody else's bed are a push being consolidated, not defence.
            record.Objectives.Pressure = record.Objectives.Pressure + 0.5
        end
        touch(record)
    end

    local function onBreakBlock(data)
        if not running or not playing() then return end
        local plr = data.player
        if not plr or plr == lplr then return end
        local position = data.blockRef and data.blockRef.blockPosition
        if not position then return end
        local record = profileFor(plr)
        record.Context.LastAction = tick()
        position = position * 3

        local _, _, _, enemyDist = bedsFor(plr, position)
        if enemyDist <= BED_NEAR then
            -- Defence broken: blocks coming off the shell around a bed that is not theirs. Digging
            -- into someone's base is a push at any stage of the match, not just an early rush.
            record.Objectives.DefenceBroken = record.Objectives.DefenceBroken + 1
            noteBedApproach(record, true, 0.85)
        end
        touch(record)
    end

    ----------------------------------------------------------------------------
    -- Event ingestion: projectiles.
    ----------------------------------------------------------------------------
    -- Every projectile in the game replicates as a workspace child carrying the shooter's UserId,
    -- so launches are countable for everyone and not just for us. Hits come from the damage
    -- stream, and the two together are the only honest read on projectile accuracy.
    local function onProjectile(object)
        if not running then return end
        local shooter = object:GetAttribute('ProjectileShooter')
        if not shooter then return end
        local plr = playersService:GetPlayerByUserId(shooter)
        if not plr or plr == lplr then return end
        local record = peek(plr)
        if not record then return end
        record.Combat.Projectiles = record.Combat.Projectiles + 1
        record.Context.LastAction = tick()
        touch(record)
    end

    ----------------------------------------------------------------------------
    -- Sampling.
    ----------------------------------------------------------------------------
    local function sampleEntity(ent, record, dt, near)
        local root = ent.RootPart
        if not root or not root.Parent then return end
        local now = tick()
        local movement, context = record.Movement, record.Context
        local position = root.Position
        local velocity = root.AssemblyLinearVelocity
        local horizontal = Vector3.new(velocity.X, 0, velocity.Z)

        -- A streaming gap. Nothing measured across one means anything, so the movement history is
        -- dropped rather than read as a very fast trip across the map.
        if now - record.LastSeen > SEEN_TIMEOUT then
            context.Gaps = context.Gaps + 1
            context.GapTime = context.GapTime + (now - record.LastSeen)
            movement.LastPos, movement.LastDir, movement.LastVel = nil, nil, nil
        end
        record.LastSeen = now
        context.Samples = context.Samples + 1
        record.Observed = record.Observed + math.min(dt, 1)

        local previous = movement.LastPos
        if previous then
            local step = (position - previous).Magnitude
            if step > TELEPORT_JUMP then
                -- A teleport, a respawn or a lag spike, not movement.
                context.Lagged = context.Lagged + 1
                movement.LastPos, movement.LastDir, movement.LastVel = position, nil, velocity
                touch(record)
                return
            end
            movement.Distance = movement.Distance + step
            if step > 0.6 then
                context.LastMove = now
            end
        end

        local fighting = now - record.Combat.LastHit <= FIGHT_MEMORY or now - record.Combat.LastHurt <= FIGHT_MEMORY
        local sampleWeight = math.min(dt * 4, 1)

        -- Strafing. Direction changes frame to frame while fighting, never while walking the map.
        if fighting and movement.LastDir and horizontal.Magnitude > 4 then
            local change = 1 - math.clamp(horizontal.Unit:Dot(movement.LastDir), -1, 1)
            observe(record.Combat.Strafe, math.clamp(change / 1.2, 0, 1), sampleWeight)
        end
        if horizontal.Magnitude > 1 then
            movement.LastDir = horizontal.Unit
        end

        -- Aim tracking. How well they keep facing whoever they are actually fighting.
        local opponent = record.Combat.LastVictim or record.Combat.LastHurtBy
        if fighting and opponent and opponent.Character then
            local theirRoot = opponent.Character:FindFirstChild('HumanoidRootPart')
            if theirRoot then
                local toward = (theirRoot.Position - position) * Vector3.new(1, 0, 1)
                local facing = root.CFrame.LookVector * Vector3.new(1, 0, 1)
                if toward.Magnitude > 1 and facing.Magnitude > 0.01 then
                    observe(record.Combat.Tracking, math.clamp(facing.Unit:Dot(toward.Unit), 0, 1), sampleWeight)
                end
            end
        end

        -- Pauses. Standing still mid-fight is hesitation; standing still out of one is not.
        if fighting and horizontal.Magnitude < 1.5 then
            if movement.PauseAt == 0 then
                movement.PauseAt = now
            elseif now - movement.PauseAt > 0.8 then
                movement.Pauses = movement.Pauses + 1
                movement.PauseAt = now
            end
        else
            movement.PauseAt = 0
        end

        -- Knockback recovery: how fast they get back to moving under their own power after a hit -
        -- the difference between eating a combo and walking out of one.
        if movement.KnockbackAt > 0 and now - movement.KnockbackAt < 3 then
            if horizontal.Magnitude > 12 and math.abs(velocity.Y) < 12 then
                observe(movement.Recovery, math.clamp(now - movement.KnockbackAt, 0.05, 3))
                movement.KnockbackAt = 0
            end
        end

        if ent.Jumping then
            movement.Jumps = movement.Jumps + 1
        end

        -- Falls. Falling after being hit is somebody else's doing; falling with nothing on the
        -- clock is their own, and a big drop they walk away from was a save.
        local wasAirborne = movement.Airborne
        movement.Airborne = velocity.Y < -12
        if movement.Airborne and not wasAirborne then
            movement.FallFrom = position
        elseif wasAirborne and not movement.Airborne and movement.FallFrom then
            local drop = movement.FallFrom.Y - position.Y
            if drop > 12 then
                movement.Falls = movement.Falls + 1
                if now - record.Combat.LastHurt > FIGHT_MEMORY then
                    movement.UnforcedFalls = movement.UnforcedFalls + 1
                    addEvent(record, 'UnforcedFall', 0.6)
                elseif drop > 25 then
                    movement.Saves = movement.Saves + 1
                end
            elseif drop > 4 then
                movement.Parkour = movement.Parkour + 1
            end
            movement.FallFrom = nil
        end

        movement.LastPos, movement.LastVel = position, velocity

        -- Generator camping and resource control. Time on a generator is economy; time on a
        -- diamond or emerald generator is map control, whoever owns it.
        local genDist, genKind = nearestGenerator(position)
        if genDist <= GEN_NEAR then
            record.Resources.GenTime = record.Resources.GenTime + dt
            if record.Resources.GenAt == 0 or now - record.Resources.GenAt > 5 then
                record.Resources.GenVisits = record.Resources.GenVisits + 1
            end
            record.Resources.GenAt = now
            if genKind == 'diamond' or genKind == 'emerald' then
                record.Teamwork.ControlTime = record.Teamwork.ControlTime + dt
            end
        end

        -- Positioning. Home ground is safe; deep in enemy territory with no teammate in reach is
        -- not. Kept as a running fraction so one bad push does not erase an hour of good sense,
        -- and one good stretch does not hide a habit of overextending.
        local plr = record.Player
        local own, ownDist, _, enemyDist = bedsFor(plr, position)
        local nearOwn = own ~= nil and ownDist <= BED_NEAR
        if nearOwn then
            record.Sense.SafeTime = record.Sense.SafeTime + dt
        end
        if enemyDist <= BED_NEAR * 2 then
            record.Sense.ExposedTime = record.Sense.ExposedTime + dt
            noteBedApproach(record, world.Stage == 'Early', 0.5)
        elseif record.Objectives.BedApproachAt ~= 0
            and enemyDist > BED_NEAR * 4
            and now - record.Objectives.BedApproachAt > 20
        then
            -- Broken off and gone. The next time they come back is a fresh approach, and the one
            -- they gave up on stays on the books as a rush that did not work.
            record.Objectives.BedApproachAt = 0
        end

        -- Teammate and enemy proximity, read off the shared roster rather than by walking the
        -- entity list once per player per frame.
        local mateNear, enemyNear = false, false
        for _, entry in world.Roster do
            if entry.Player ~= plr then
                if (entry.Position - position).Magnitude <= MATE_NEAR then
                    if entry.Team ~= nil and entry.Team == context.Team then
                        mateNear = true
                    else
                        enemyNear = true
                    end
                end
            end
        end
        if mateNear and enemyNear then
            record.Teamwork.PushWindow = record.Teamwork.PushWindow + dt
        end
        observe(movement.Positioning, (nearOwn or mateNear or not enemyNear) and 1 or 0, math.min(dt, 0.5))

        -- A teammate in trouble within reach is a chance to help. Whether they took it is answered
        -- by the damage they then put on whoever was doing it, over in onDamage.
        if near and now - record.Sense.SaveChanceAt > 3 then
            for _, entry in world.Roster do
                if entry.Player ~= plr and entry.Team ~= nil and entry.Team == context.Team then
                    local mate = peek(entry.Player)
                    if mate and now - mate.Combat.LastHurt <= 2 and (entry.Position - position).Magnitude <= MATE_NEAR then
                        record.Sense.SaveChanceAt = now
                        record.Teamwork.SaveChances = record.Teamwork.SaveChances + 1
                        break
                    end
                end
            end
        end

        touch(record)
    end

    ----------------------------------------------------------------------------
    -- Terrain probes.
    ----------------------------------------------------------------------------
    -- Two rays: straight down, and down from a stride along the direction of travel. Between them
    -- they answer "are they over the void", "how far above the floor are they" and "are they
    -- walking at an edge", which is every terrain question the movement signals ask. Budgeted per
    -- frame so a full lobby can never turn edge awareness into a raycast storm.
    local probeParams = RaycastParams.new()
    probeParams.RespectCanCollide = true
    probeParams.FilterType = Enum.RaycastFilterType.Exclude
    local probeIgnore = {}

    local function probeGround(origin)
        probeParams.FilterDescendantsInstances = probeIgnore
        local hit = workspace:Raycast(origin, Vector3.new(0, -400, 0), probeParams)
        return hit and hit.Position.Y or nil
    end

    local function probeEntity(ent, record)
        if probeBudget <= 0 then return end
        local root = ent.RootPart
        if not root or not root.Parent then return end
        probeBudget = probeBudget - 1

        table.clear(probeIgnore)
        table.insert(probeIgnore, ent.Character)
        table.insert(probeIgnore, gameCamera)
        if AntiFallPart then
            table.insert(probeIgnore, AntiFallPart)
        end

        local movement = record.Movement
        local position = root.Position
        local ground = probeGround(position)
        movement.Ground = ground
        movement.OverVoid = ground == nil

        -- Edge awareness: is there floor a stride ahead of where they are heading? If not, and
        -- they slow or turn instead of walking off it, that is a read rather than luck.
        local direction = movement.LastDir
        if direction and ground then
            if probeGround(position + direction * 5) then
                if movement.EdgeAt > 0 and tick() - movement.EdgeAt < 1 then
                    movement.EdgeStops = movement.EdgeStops + 1
                    movement.EdgeAt = 0
                end
            else
                movement.EdgeApproaches = movement.EdgeApproaches + 1
                movement.EdgeAt = tick()
            end
        end
    end

    ----------------------------------------------------------------------------
    -- Inventory deltas.
    ----------------------------------------------------------------------------
    -- Purchases, resource spend, tool preparation and gear progression all fall out of watching
    -- what the replicated inventory does between two looks at it.
    local function sampleInventory(record)
        local inv = inventoryOf(record.Player)
        if not inv then return end
        local now = tick()
        local resources = record.Resources
        if now - resources.InventoryAt < 1 then return end
        resources.InventoryAt = now

        local items = 0
        for _ in (inv.items or {}) do
            items = items + 1
        end
        local snapshot = {
            Iron = resourceCount(inv, 'iron'),
            Diamond = resourceCount(inv, 'diamond'),
            Emerald = resourceCount(inv, 'emerald'),
            Gear = swordDamage(inv) + armourValue(inv) * 30,
            Items = items
        }

        local previous = resources.LastInventory
        resources.LastInventory = snapshot
        record.Context.Gear = snapshot.Gear
        record.Context.Armour = armourValue(inv)
        if snapshot.Gear > resources.BestGear then
            resources.BestGear = snapshot.Gear
            observe(resources.GearTier, math.clamp(snapshot.Gear / 90, 0, 1))
        end

        -- Tool preparation: holding the right thing for what is about to happen. Swapping to a
        -- sword before contact, or to blocks over a gap, is reading a moment ahead.
        local hand = inv.hand
        local handType = hand and hand.itemType or nil
        if handType and handType ~= record.Sense.LastHand then
            record.Sense.LastHand = handType
            record.Sense.ToolSwaps = record.Sense.ToolSwaps + 1
            local meta = bedwars.ItemMeta[handType]
            if meta then
                local fighting = now - record.Combat.LastHit <= FIGHT_MEMORY or now - record.Combat.LastHurt <= FIGHT_MEMORY
                local right = (fighting and meta.sword ~= nil) or (not fighting and record.Movement.OverVoid and meta.block ~= nil)
                observe(resources.Prepared, right and 1 or 0)
            end
        end

        if not previous then return end
        -- Resources going up is collection; going down is spending, and whether the item count
        -- went with them says whether it was bought for themselves or given away.
        resources.Iron = resources.Iron + math.max(snapshot.Iron - previous.Iron, 0)
        resources.Diamond = resources.Diamond + math.max(snapshot.Diamond - previous.Diamond, 0)
        resources.Emerald = resources.Emerald + math.max(snapshot.Emerald - previous.Emerald, 0)

        local ironSpent = math.max(previous.Iron - snapshot.Iron, 0)
        local diamondSpent = math.max(previous.Diamond - snapshot.Diamond, 0)
        local emeraldSpent = math.max(previous.Emerald - snapshot.Emerald, 0)
        resources.IronSpent = resources.IronSpent + ironSpent
        resources.DiamondSpent = resources.DiamondSpent + diamondSpent
        resources.EmeraldSpent = resources.EmeraldSpent + emeraldSpent

        local spent = ironSpent + diamondSpent + emeraldSpent
        if spent > 0 then
            record.Context.LastAction = now
            if snapshot.Items >= previous.Items then
                resources.Purchases = resources.Purchases + 1
                if snapshot.Gear > previous.Gear then
                    addEvent(record, 'Upgrade', 0.8)
                end
            else
                -- Resources gone and items gone with them: handed to a teammate, or spent at the
                -- upgrade shop. Both are contributions rather than losses, and we cannot tell
                -- which from here - so the event says how sure we are.
                resources.Upgrades = resources.Upgrades + 1
                record.Teamwork.Shared = record.Teamwork.Shared + 1
                addEvent(record, 'TeamSpend', 0.45)
            end
        end
    end

    ----------------------------------------------------------------------------
    -- Context, threats and decisions.
    ----------------------------------------------------------------------------
    local function updateContext(record, ent)
        local plr = record.Player
        local context = record.Context
        local now = tick()
        context.Health = healthFraction(plr)
        context.Alive = ent ~= nil and ent.Health > 0

        -- The allocating reads are throttled; the cheap attribute reads above are not.
        if now - record.LastHeavy >= HEAVY_INTERVAL then
            record.LastHeavy = now
            context.Kit = kitOf(plr)
            context.Team = teamOf(plr)
            context.Trapped = statusTrapped(plr)
        end

        -- AFK is only decidable while we can actually see them: a streamed-out player is not
        -- standing still, we just are not looking. An AFK player is not playing badly, they are
        -- not playing, so this freezes the claim rather than grinding them toward New.
        local afk = context.Alive and (now - math.max(context.LastMove, context.LastAction)) > AFK_TIME
        if afk ~= context.AFK then
            context.AFK = afk
            addEvent(record, afk and 'AFK' or 'Active', 0.7)
        end
    end

    local function updateThreats(record, ent)
        local root = ent.RootPart
        if not root or not root.Parent then return end
        local plr = record.Player
        local position = root.Position
        local sense = record.Sense
        local now = tick()

        -- Threat awareness: an enemy inside striking distance. Whether they answered it - turned,
        -- moved off, or hit back - inside a couple of seconds is the read.
        local threat = nil
        for _, entry in world.Roster do
            if entry.Player ~= plr and not (entry.Team ~= nil and entry.Team == record.Context.Team) then
                if (entry.Position - position).Magnitude <= THREAT_NEAR then
                    threat = entry.Player
                    break
                end
            end
        end

        if threat and not sense.ThreatFrom then
            sense.ThreatFrom, sense.ThreatAt, sense.ThreatAnswered = threat, now, false
            sense.Threats = sense.Threats + 1
        elseif not threat then
            sense.ThreatFrom, sense.ThreatAnswered = nil, false
        end

        if sense.ThreatFrom and not sense.ThreatAnswered and now - sense.ThreatAt <= 2.5 then
            local moving = record.Movement.LastVel ~= nil
                and Vector3.new(record.Movement.LastVel.X, 0, record.Movement.LastVel.Z).Magnitude > 8
            if moving or now - record.Combat.LastHit <= 2.5 then
                sense.ThreatReactions = sense.ThreatReactions + 1
                sense.ThreatAnswered = true
            end
        end

        -- Bed under attack. Whether they turn up at all is the defence reaction; the block-place
        -- handler closes the loop when they get there and start walling it back up.
        local own = select(1, bedsFor(plr, position))
        if own then
            local underThreat = false
            for _, entry in world.Roster do
                if not (entry.Team ~= nil and entry.Team == record.Context.Team) then
                    if (entry.Position - own.Position).Magnitude <= BED_NEAR then
                        underThreat = true
                        break
                    end
                end
            end
            if underThreat and not sense.BedAlert then
                sense.BedAlert, sense.LastAlert = true, now
                sense.BedAlerts = sense.BedAlerts + 1
            elseif not underThreat and sense.BedAlert then
                if sense.LastAlert > 0 and (own.Position - position).Magnitude <= BED_NEAR then
                    sense.BedResponses = sense.BedResponses + 1
                    observe(sense.BedResponseTime, math.clamp(now - sense.LastAlert, 0.5, 30))
                end
                sense.BedAlert = false
            end
        end

        -- Retreating. Breaking off a losing fight and living is one of the clearest game-sense
        -- reads there is; dying on the spot at the same health is the other side of it.
        if now - record.Combat.LastHurt <= FIGHT_MEMORY and record.Context.Health < 0.35 then
            if not sense.RetreatFrom then
                sense.RetreatFrom, sense.RetreatAt = position, now
            end
        elseif sense.RetreatFrom then
            if now - sense.RetreatAt < 8 then
                if not record.Context.Alive then
                    sense.LowHealthDeaths = sense.LowHealthDeaths + 1
                elseif (position - sense.RetreatFrom).Magnitude > 40 then
                    sense.Retreats = sense.Retreats + 1
                    sense.LowHealthEscapes = sense.LowHealthEscapes + 1
                    record.Objectives.Escapes = record.Objectives.Escapes + 1
                    addEvent(record, 'Escape', 0.7)
                end
            end
            sense.RetreatFrom = nil
        end

        -- Chases. Running somebody down across the map, landing nothing, while the objective is
        -- somewhere else, is time nobody got anything out of.
        local victim = record.Combat.LastVictim
        local theirRoot = victim and victim.Character and victim.Character:FindFirstChild('HumanoidRootPart')
        if theirRoot and now - record.Combat.LastHit < 6 and (theirRoot.Position - position).Magnitude > 60 then
            if sense.ChaseAt == 0 then
                sense.ChaseAt = now
                sense.Chases = sense.Chases + 1
            elseif now - sense.ChaseAt > 6 then
                sense.PointlessChases = sense.PointlessChases + 1
                sense.ChaseAt = 0
            end
        else
            sense.ChaseAt = 0
        end
    end

    ----------------------------------------------------------------------------
    -- Category scoring.
    ----------------------------------------------------------------------------
    -- A note on confidence, because it is the whole design. Where absence means something - they
    -- have been on a generator for four minutes and have no diamonds - confidence comes from how
    -- long we watched, so a zero is a confident zero. Where absence means nothing - they have
    -- never fired an arrow, so we cannot say whether they can aim one - confidence comes from the
    -- count, and stays at zero until there is something to judge.
    local function watchConf(record, seconds)
        return math.clamp(record.Observed / (seconds or 90), 0, 1)
    end

    local function scoreCombat(record)
        local b = blender()
        local combat = record.Combat
        local timing = timingConfidence()
        local kitFactor = KIT_COMBAT[record.Context.Kit or ''] or 1
        local fights = combat.Kills + combat.Deaths
        local damage = combat.DamageDealt + combat.DamageTaken
        -- Kills against nobody are worth nothing. This multiplies every trade-shaped signal, and
        -- it is what keeps farming from reading as skill.
        local honesty = math.clamp(combat.KillQuality.v, 0.15, 1)

        signal(b, 'Trades',
            scale(safeDiv(combat.Kills - combat.Deaths, math.max(fights, 1)) * honesty, -0.6, 0.6),
            1.4, countConf(fights, 8))

        signal(b, 'Fight wins',
            scale(safeDiv(combat.FightsWon, combat.FightsWon + combat.FightsLost), 0.25, 0.75),
            1.2, countConf(combat.FightsWon + combat.FightsLost, 6))

        signal(b, 'Hit accuracy',
            scale(safeDiv(combat.SwingHits, combat.Swings), 0.3, 0.8),
            1.1, combat.Swings >= 8 and math.min(countConf(combat.Swings, 25), 0.55) or 0)

        signal(b, 'First hits',
            scale(safeDiv(combat.FirstHits, combat.FirstHitChances), 0.3, 0.75),
            1.0, countConf(combat.FirstHitChances, 6) * timing)

        signal(b, 'Combo consistency',
            scale(safeDiv(combat.ComboHits, math.max(combat.MeleeHits, 1)), 0.1, 0.5),
            1.0, countConf(combat.MeleeHits, 20))

        signal(b, 'Best combo',
            reward(combat.BestCombo - 2, 5),
            0.6, countConf(combat.MeleeHits, 20))

        signal(b, 'Damage traded',
            scale(safeDiv(combat.DamageDealt - combat.DamageTaken, math.max(damage, 1)), -0.4, 0.4),
            1.2, math.clamp(damage / 400, 0, 1))

        signal(b, 'Reaction time',
            -scale(combat.Reaction.v, 0.25, 1.1),
            0.9, evidence(combat.Reaction, 6) * timing)

        signal(b, 'Strafing',
            scale(combat.Strafe.v, 0.15, 0.65),
            0.8, evidence(combat.Strafe, 25) * kitFactor)

        signal(b, 'Aim tracking',
            scale(combat.Tracking.v, 0.45, 0.9),
            1.0, evidence(combat.Tracking, 25) * timing)

        signal(b, 'Target switching',
            bell(safeDiv(combat.Switches, math.max(fights, 1)), 0.8, 1.6),
            0.5, countConf(combat.Switches, 4))

        signal(b, 'Projectile accuracy',
            scale(safeDiv(combat.ProjectileHits, combat.Projectiles), 0.15, 0.6),
            0.9, combat.Projectiles >= 4 and countConf(combat.Projectiles, 12) or 0)

        signal(b, 'Void knockbacks',
            reward(combat.VoidKills, 3),
            0.6, watchConf(record, 120) * 0.7)

        signal(b, 'Against better gear',
            scale(safeDiv(combat.UphillWins, combat.UphillFights), 0.2, 0.7),
            1.3, countConf(combat.UphillFights, 5))

        return resolve(b)
    end

    local function scoreMovement(record)
        local b = blender()
        local movement = record.Movement
        local kitFactor = KIT_MOVEMENT[record.Context.Kit or ''] or 1

        signal(b, 'Bridging speed',
            scale(movement.BridgeSpeed.v, 1.2, 3.2),
            1.2, evidence(movement.BridgeSpeed, 5) * kitFactor)

        signal(b, 'Block efficiency',
            scale(safeDiv(movement.Distance, math.max(movement.Blocks, 1)), 1.5, 5),
            0.9, countConf(movement.Blocks, 25))

        signal(b, 'Hesitation',
            -scale(safeDiv(movement.Pauses, math.max(record.Observed / 60, 0.2)), 1, 8),
            0.7, watchConf(record, 90))

        signal(b, 'Unforced falls',
            -reward(movement.UnforcedFalls, 4),
            1.1, watchConf(record, 90))

        signal(b, 'Parkour',
            reward(movement.Parkour, 12),
            0.6, watchConf(record, 120) * kitFactor)

        signal(b, 'Pathing',
            scale(safeDiv(movement.Distance, math.max(record.Observed, 1)), 4, 13),
            0.7, watchConf(record, 60))

        signal(b, 'Edge awareness',
            scale(safeDiv(movement.EdgeStops, math.max(movement.EdgeApproaches, 1)), 0.2, 0.8),
            1.0, countConf(movement.EdgeApproaches, 8))

        signal(b, 'Combat positioning',
            scale(movement.Positioning.v, 0.35, 0.85),
            0.9, evidence(movement.Positioning, 20))

        signal(b, 'Knockback recovery',
            -scale(movement.Recovery.v, 0.3, 1.6),
            1.0, evidence(movement.Recovery, 5))

        signal(b, 'Block clutches',
            reward(movement.Clutches + movement.Saves, 4),
            1.1, watchConf(record, 120) * 0.8)

        return resolve(b)
    end

    local function scoreSense(record)
        local b = blender()
        local sense = record.Sense
        local exposure = sense.SafeTime + sense.ExposedTime

        signal(b, 'Threat awareness',
            scale(safeDiv(sense.ThreatReactions, math.max(sense.Threats, 1)), 0.3, 0.85),
            1.3, countConf(sense.Threats, 6))

        signal(b, 'Bed defence',
            scale(safeDiv(sense.BedResponses, math.max(sense.BedAlerts, 1)), 0.2, 0.8),
            1.2, countConf(sense.BedAlerts, 3))

        signal(b, 'Defence speed',
            -scale(sense.BedResponseTime.v, 3, 18),
            0.8, evidence(sense.BedResponseTime, 3))

        signal(b, 'Retreating',
            scale(safeDiv(sense.LowHealthEscapes, math.max(sense.LowHealthEscapes + sense.LowHealthDeaths, 1)), 0.2, 0.8),
            1.1, countConf(sense.LowHealthEscapes + sense.LowHealthDeaths, 4))

        signal(b, 'Fight selection',
            scale(safeDiv(record.Combat.FightsWon, math.max(record.Combat.FightsWon + record.Combat.FightsLost, 1)), 0.3, 0.9),
            1.0, countConf(record.Combat.FightsWon + record.Combat.FightsLost, 6))

        signal(b, 'Pointless chases',
            -scale(safeDiv(sense.PointlessChases, math.max(sense.Chases, 1)), 0.1, 0.7),
            0.8, countConf(sense.Chases, 4))

        signal(b, 'Safe positioning',
            scale(safeDiv(sense.SafeTime, math.max(exposure, 1)), 0.15, 0.6),
            0.6, math.clamp(exposure / 60, 0, 1))

        signal(b, 'Adapting tools',
            scale(record.Resources.Prepared.v, 0.3, 0.85),
            0.9, evidence(record.Resources.Prepared, 8))

        -- Adapting after failure: coming back at a bed they were pushed off, or changing the way
        -- in, rather than feeding the same approach until the match ends.
        signal(b, 'Adapting after failure',
            scale(safeDiv(record.Objectives.RushWins, math.max(record.Objectives.Rushes, 1)), 0.15, 0.7),
            1.0, countConf(record.Objectives.Rushes, 3))

        return resolve(b)
    end

    local function scoreObjectives(record)
        local b = blender()
        local objectives = record.Objectives
        local minutes = math.max(record.Observed / 60, 0.5)

        signal(b, 'Beds broken',
            reward(objectives.Beds, 2),
            1.5, watchConf(record, 150))

        signal(b, 'Bed approaches',
            scale(safeDiv(objectives.BedApproaches, minutes), 0.1, 1.2),
            0.9, watchConf(record, 120))

        signal(b, 'Rush success',
            scale(safeDiv(objectives.RushWins, math.max(objectives.Rushes, 1)), 0.1, 0.7),
            1.2, countConf(objectives.Rushes, 3))

        signal(b, 'Bed break speed',
            -scale(objectives.BedBreakTime.v, 8, 60),
            0.9, evidence(objectives.BedBreakTime, 2))

        signal(b, 'Defence broken',
            reward(objectives.DefenceBroken, 25),
            0.7, watchConf(record, 120))

        signal(b, 'Final kills',
            reward(objectives.FinalKills, 3),
            1.2, watchConf(record, 150))

        signal(b, 'Assists',
            reward(objectives.Assists, 5),
            0.7, watchConf(record, 120) * (world.TeamSize > 1 and 1 or 0))

        signal(b, 'Escapes',
            reward(objectives.Escapes, 3),
            0.6, watchConf(record, 120))

        signal(b, 'Pressure created',
            reward(objectives.Pressure, 4),
            0.8, watchConf(record, 120))

        return resolve(b)
    end

    local function scoreResources(record)
        local b = blender()
        local resources = record.Resources
        local minutes = math.max(record.Observed / 60, 0.3)
        -- Every resource read comes from the replicated inventory. Without it there is nothing
        -- here to say, and saying so is the point.
        local replicated = inventoryOf(record.Player) and 1 or 0

        signal(b, 'Generator time',
            bell(safeDiv(resources.GenTime, math.max(record.Observed, 1)), 0.25, 0.25),
            0.9, watchConf(record, 90))

        signal(b, 'Iron income',
            scale(safeDiv(resources.Iron, minutes), 4, 30),
            0.8, watchConf(record, 120) * replicated)

        signal(b, 'Diamond income',
            scale(safeDiv(resources.Diamond, minutes), 0.2, 2.5),
            1.0, watchConf(record, 150) * replicated)

        signal(b, 'Emerald income',
            scale(safeDiv(resources.Emerald, minutes), 0.05, 1.2),
            0.9, watchConf(record, 180) * replicated)

        signal(b, 'Spending',
            scale(safeDiv(resources.IronSpent + resources.DiamondSpent * 4 + resources.EmeraldSpent * 8,
                math.max(resources.Iron + resources.Diamond * 4 + resources.Emerald * 8, 1)), 0.25, 0.85),
            1.0, watchConf(record, 120) * replicated)

        signal(b, 'Resources lost on death',
            -scale(safeDiv(resources.Lost, math.max(resources.LostEvents, 1)), 5, 45),
            1.0, countConf(resources.LostEvents, 2))

        signal(b, 'Purchases',
            scale(safeDiv(resources.Purchases, minutes), 0.3, 3),
            0.7, watchConf(record, 120) * replicated)

        signal(b, 'Tool preparation',
            scale(resources.Prepared.v, 0.3, 0.85),
            0.8, evidence(resources.Prepared, 8))

        signal(b, 'Gear progression',
            scale(resources.GearTier.v, 0.15, 0.8),
            1.1, evidence(resources.GearTier, 3) * replicated)

        signal(b, 'Team upgrades',
            reward(resources.Upgrades, 3),
            0.7, watchConf(record, 150) * replicated * 0.5)

        return resolve(b)
    end

    local function scoreTeamwork(record)
        local b = blender()
        local team = record.Teamwork
        -- In a solo mode there is nobody to help. Rather than mark a solo player down for it, the
        -- whole category simply has no confidence and drops out of their overall score.
        local solo = world.TeamSize > 1 and 1 or 0
        local watched = watchConf(record, 120) * solo

        signal(b, 'Assists', reward(team.Assists, 4), 1.2, watched)

        signal(b, 'Protecting teammates',
            scale(safeDiv(team.Saves, math.max(team.SaveChances, 1)), 0.1, 0.6),
            1.1, countConf(team.SaveChances, 3) * solo)

        signal(b, 'Sharing resources', reward(team.Shared, 3), 0.8, watched * 0.6)

        signal(b, 'Defending', reward(team.Defends, 10), 1.0, watched)

        signal(b, 'Coordinated pushes',
            scale(safeDiv(team.PushWindow, math.max(record.Observed, 1)), 0.05, 0.4),
            1.0, watched)

        signal(b, 'Diamond and emerald control',
            scale(safeDiv(team.ControlTime, math.max(record.Observed, 1)), 0.03, 0.3),
            0.9, watchConf(record, 120))

        return resolve(b)
    end

    ----------------------------------------------------------------------------
    -- Roles.
    ----------------------------------------------------------------------------
    -- Each role is scored on its own evidence, and the winner has to be clearly ahead of the
    -- runner-up to be claimed. Anything else is Mixed, which is a real answer rather than a
    -- fallback: most players genuinely do a bit of everything.
    local function roleOf(record)
        local combat, sense = record.Combat, record.Sense
        local objectives, resources, team = record.Objectives, record.Resources, record.Teamwork
        local watched = math.max(record.Observed, 1)
        local minutes = math.max(watched / 60, 0.3)

        local scores = {
            Rusher = math.clamp(
                safeDiv(objectives.BedApproaches, minutes) * 0.5
                + objectives.Beds * 0.5
                + reward(objectives.DefenceBroken, 20) * 0.3
                + safeDiv(sense.ExposedTime, watched) * 0.6, 0, 2),
            Defender = math.clamp(
                safeDiv(sense.SafeTime, watched) * 1.1
                + reward(team.Defends, 10) * 0.6
                + safeDiv(sense.BedResponses, math.max(sense.BedAlerts, 1)) * 0.5, 0, 2),
            Fighter = math.clamp(
                safeDiv(combat.Kills + combat.FightsWon, minutes) * 0.35
                + reward(combat.DamageDealt, 400) * 0.4
                + reward(combat.MeleeHits, 40) * 0.3, 0, 2),
            Support = math.clamp(
                reward(team.Assists, 3) * 0.7
                + safeDiv(team.PushWindow, watched) * 0.9
                + reward(team.Shared, 4) * 0.25, 0, 2),
            Economy = math.clamp(
                safeDiv(resources.GenTime, watched) * 1.2
                + reward(resources.Purchases, 5) * 0.5
                + reward(resources.Iron, 60) * 0.4, 0, 2),
            ResourceControl = math.clamp(
                safeDiv(team.ControlTime, watched) * 1.6
                + reward(resources.Diamond + resources.Emerald * 2, 8) * 0.6, 0, 2)
        }

        local best, bestScore, second = 'Mixed', 0, 0
        for _, role in ROLES do
            local value = scores[role] or 0
            if value > bestScore then
                best, second, bestScore = role, bestScore, value
            elseif value > second then
                second = value
            end
        end

        if bestScore < 0.35 or bestScore < second * 1.35 then
            return 'Mixed', scores
        end
        return best, scores
    end

    ----------------------------------------------------------------------------
    -- Rating bands.
    ----------------------------------------------------------------------------
    -- Sliders can be dragged into any order. Read them back as a strictly descending set so a band
    -- can never swallow the one above it and every rating stays reachable.
    local function bands()
        local sweat = SweatAt.Value
        local skilled = math.min(SkilledAt.Value, sweat - 1)
        local above = math.min(AboveAt.Value, skilled - 1)
        local beginner = math.min(BeginnerBelow.Value, above - 1)
        return sweat, skilled, above, beginner, math.min(NewBelow.Value, beginner - 1)
    end

    local function ratingOf(score, confidence)
        if confidence < (MinConfidence.Value / 100) then return 'Unknown' end
        local sweat, skilled, above, beginner, fresh = bands()
        if score >= sweat then return 'Sweat' end
        if score >= skilled then return 'Skilled' end
        if score >= above then return 'Above Average' end
        if score > beginner then return 'Average' end
        if score > fresh then return 'Beginner' end
        return 'New'
    end

    ----------------------------------------------------------------------------
    -- Building the answer.
    ----------------------------------------------------------------------------
    local function blankAnalysis()
        return {
            OverallSkill = 0,
            Confidence = 0,
            Rating = 'Unknown',
            Role = 'Mixed',
            Categories = {
                Combat = 0,
                Movement = 0,
                GameSense = 0,
                Objectives = 0,
                Resources = 0,
                Teamwork = 0
            },
            Strengths = {},
            Weaknesses = {},
            RecentEvents = {}
        }
    end

    -- Strengths and weaknesses come from the named signals rather than the category totals, so the
    -- answer is "their bridging is quick" and not "movement: 71".
    local function highlights(blends)
        local pool = {}
        for _, entry in blends do
            for name, data in entry.named do
                if data.Confidence >= 0.35 and math.abs(data.Deviation) >= 0.3 then
                    table.insert(pool, {Name = name, Score = data.Deviation * data.Confidence * data.Weight})
                end
            end
        end
        table.sort(pool, function(a, b)
            return a.Score > b.Score
        end)

        local strengths, weaknesses = {}, {}
        for _, entry in pool do
            if entry.Score > 0.25 and #strengths < 4 then
                table.insert(strengths, entry.Name)
            end
        end
        for index = #pool, 1, -1 do
            if pool[index].Score < -0.25 and #weaknesses < 4 then
                table.insert(weaknesses, pool[index].Name)
            end
        end
        return strengths, weaknesses
    end

    local function round(value, places)
        local factor = 10 ^ (places or 1)
        return math.floor(value * factor + 0.5) / factor
    end

    local function rebuild(record)
        local now = tick()
        record.Dirty = false
        record.NextScore = now + RESCORE_INTERVAL

        local scores, confs, blends = {}, {}, {}
        scores.Combat, confs.Combat, blends[1] = scoreCombat(record)
        scores.Movement, confs.Movement, blends[2] = scoreMovement(record)
        scores.GameSense, confs.GameSense, blends[3] = scoreSense(record)
        scores.Objectives, confs.Objectives, blends[4] = scoreObjectives(record)
        scores.Resources, confs.Resources, blends[5] = scoreResources(record)
        scores.Teamwork, confs.Teamwork, blends[6] = scoreTeamwork(record)

        local role, roleScores = roleOf(record)
        local weights = ROLE_WEIGHTS[role] or ROLE_WEIGHTS.Mixed

        -- Overall is a confidence-weighted blend: a category we have barely observed cannot drag
        -- the answer around, and one we have watched thoroughly is what the answer is made of.
        local sum, weight, confSum, confWeight = 0, 0, 0, 0
        for _, name in CATEGORIES do
            local categoryWeight = weights[name]
            local w = categoryWeight * confs[name]
            sum = sum + scores[name] * w
            weight = weight + w
            confSum = confSum + confs[name] * categoryWeight
            confWeight = confWeight + categoryWeight
        end

        local quality = dataQuality(record)
        local confidence = math.clamp(safeDiv(confSum, confWeight) * quality, 0, 1)
        if record.Context.AFK then
            confidence = confidence * 0.6
        end
        -- Hold the overall toward Average by however much we do not know, so a thin read never
        -- comes out as a confident claim.
        local overall = math.clamp(50 + ((weight > 0 and (sum / weight) or 50) - 50) * (0.35 + 0.65 * confidence), 0, 100)
        local rating = ratingOf(overall, confidence)
        local strengths, weaknesses = highlights(blends)

        local events = {}
        for index = #record.Events, 1, -1 do
            local entry = record.Events[index]
            table.insert(events, {
                Type = entry.Type,
                Time = entry.Time,
                Age = now - entry.Time,
                Confidence = entry.Confidence,
                Detail = entry.Detail
            })
        end

        local analysis = {
            OverallSkill = round(overall, 1),
            Confidence = round(confidence, 3),
            Rating = rating,
            Role = role,
            Categories = {
                Combat = round(scores.Combat, 1),
                Movement = round(scores.Movement, 1),
                GameSense = round(scores.GameSense, 1),
                Objectives = round(scores.Objectives, 1),
                Resources = round(scores.Resources, 1),
                Teamwork = round(scores.Teamwork, 1)
            },
            Strengths = strengths,
            Weaknesses = weaknesses,
            RecentEvents = events,
            -- Past the shape the contract asks for, for anything that wants to go deeper.
            Player = record.Player,
            CategoryConfidence = confs,
            RoleScores = roleScores,
            Observed = round(record.Observed, 1),
            AFK = record.Context.AFK,
            DataQuality = round(quality, 3)
        }

        local previous = record.Cache
        record.Cache = analysis
        if not previous or previous.Rating ~= analysis.Rating or previous.Role ~= analysis.Role then
            vapeEvents.EntityAnalysed:Fire(record.Player, analysis)
            local wasHigh = previous ~= nil and (previous.Rating == 'Skilled' or previous.Rating == 'Sweat')
            local isHigh = analysis.Rating == 'Skilled' or analysis.Rating == 'Sweat'
            if Notify.Enabled and isHigh and not wasHigh then
                notif('EntityAnalyser', record.Player.Name .. ' is ' .. analysis.Rating .. ' (' .. math.floor(analysis.OverallSkill) .. ', ' .. analysis.Role .. ')', 4)
            end
        end
        return analysis
    end

    local function analysisFor(plr)
        local record = peek(plr)
        if not record then return blankAnalysis() end
        if not record.Cache then return rebuild(record) end
        -- Sampling marks a profile dirty constantly, so the throttle is what actually decides how
        -- often the maths runs. Twice a second is far faster than a rating can meaningfully move.
        if record.Dirty and tick() >= record.NextScore then return rebuild(record) end
        return record.Cache
    end

    ----------------------------------------------------------------------------
    -- Labels.
    ----------------------------------------------------------------------------
    local function removeTag(plr)
        local tag = tags[plr]
        if tag then
            tag:Destroy()
        end
        tags[plr] = nil
    end

    local function ratingShown(rating)
        if rating == 'Sweat' then return ShowSweat.Enabled end
        if rating == 'Skilled' then return ShowSkilled.Enabled end
        if rating == 'Above Average' then return ShowAbove.Enabled end
        if rating == 'Average' then return ShowAverage.Enabled end
        if rating == 'Beginner' then return ShowBeginner.Enabled end
        if rating == 'New' then return ShowNew.Enabled end
        return ShowUnknown.Enabled
    end

    local function updateTag(plr, ent, analysis)
        local adornee = ent.Head or ent.RootPart
        if not folder or not adornee or not adornee.Parent or not ratingShown(analysis.Rating) then
            removeTag(plr)
            return
        end

        local tag = tags[plr]
        if not tag or tag.Adornee ~= adornee or not tag.Parent then
            removeTag(plr)
            tag = Instance.new('BillboardGui')
            tag.Name = 'EntityAnalyser'
            tag.AlwaysOnTop = true
            tag.ClipsDescendants = false
            tag.Size = UDim2.fromOffset(260, 18)
            -- Above the +3 the other overhead tags use, so a nametag and a rating can be on
            -- together without covering each other.
            tag.StudsOffsetWorldSpace = Vector3.new(0, 4.4, 0)
            tag.Adornee = adornee
            tag.Parent = folder

            local label = Instance.new('TextLabel')
            label.Name = 'Label'
            label.Size = UDim2.fromScale(1, 1)
            label.BackgroundTransparency = 1
            label.Font = Enum.Font.GothamBold
            label.TextSize = 13
            label.TextStrokeTransparency = 0.4
            label.Parent = tag
            tags[plr] = tag
        end

        local label = tag:FindFirstChild('Label')
        if label then
            label.TextColor3 = ratingColor[analysis.Rating] or ratingColor.Unknown
            local text = '\u{25CF} ' .. analysis.Rating
            if ShowScore.Enabled and analysis.Rating ~= 'Unknown' then
                text = text .. ' ' .. math.floor(analysis.OverallSkill)
            end
            if ShowRole.Enabled and analysis.Role ~= 'Mixed' then
                text = text .. ' \u{00B7} ' .. analysis.Role
            end
            if ShowConfidence.Enabled then
                text = text .. ' \u{00B7} ' .. math.floor(analysis.Confidence * 100) .. '%'
            end
            if analysis.AFK then
                text = text .. ' \u{00B7} AFK'
            end
            label.Text = text
        end
    end

    local function clearTags()
        for plr in tags do
            removeTag(plr)
        end
        table.clear(tags)
    end

    ----------------------------------------------------------------------------
    -- The pass.
    ----------------------------------------------------------------------------
    local function step()
        -- Each player carries their own sample clock, so the pass itself needs no frame delta -
        -- a player read twice a second must be credited with half a second, not with one frame.
        local now = tick()
        probeBudget = PROBE_BUDGET

        if store.matchState ~= lastMatchState then
            if store.matchState == 1 then
                matchStart = now
                bedsAtStart = #collectionService:GetTagged('bed')
            end
            lastMatchState = store.matchState
        end
        refreshWorld(now)

        for key, fight in engagements do
            if now - fight.Last > ENGAGE_MEMORY then
                engagements[key] = nil
            end
        end

        local origin = entitylib.isAlive and entitylib.character.RootPart and entitylib.character.RootPart.Position or nil
        local nearRange = SampleRange.Value
        local labelsOn = Labels.Enabled

        table.clear(seen)
        for _, ent in entitylib.List do
            local plr = ent.Player
            if plr and plr ~= lplr then
                seen[plr] = true
                local record = profileFor(plr)
                local root = ent.RootPart
                local distance = (origin and root and root.Parent) and (root.Position - origin).Magnitude or math.huge
                local fighting = now - record.Combat.LastHit <= FIGHT_MEMORY or now - record.Combat.LastHurt <= FIGHT_MEMORY
                local near = distance <= nearRange or fighting

                -- Adaptive: every frame for anyone near or fighting, twice a second for everyone
                -- else, and once every couple of seconds for somebody who is not doing anything -
                -- which is still often enough to notice the moment they start again.
                local interval = near and 0 or (record.Context.AFK and AFK_INTERVAL or FAR_INTERVAL)
                if now - record.LastSample >= interval then
                    local sampleDt = math.min(now - record.LastSample, 1)
                    record.LastSample = now
                    sampleEntity(ent, record, sampleDt, near)
                    updateContext(record, ent)
                    sampleInventory(record)
                    if near then
                        updateThreats(record, ent)
                        if now - record.LastProbe >= PROBE_INTERVAL then
                            record.LastProbe = now
                            probeEntity(ent, record)
                        end
                    end
                end

                -- Scored whether or not anything is being drawn: the labels are one consumer of
                -- this, the API and the notifications are others, and the rescore is throttled to
                -- twice a second regardless of how many of them are listening.
                local analysis = analysisFor(plr)
                if labelsOn and (Teammates.Enabled or not sameTeam(plr, lplr)) then
                    updateTag(plr, ent, analysis)
                else
                    removeTag(plr)
                end
            end
        end

        -- Anyone who has left the entity list - died, left, streamed out - loses their label but
        -- keeps their profile, so a rating survives a respawn instead of starting over.
        for plr in tags do
            if not seen[plr] then
                removeTag(plr)
            end
        end
    end

    ----------------------------------------------------------------------------
    -- Public API.
    ----------------------------------------------------------------------------
    local api
    api = {
        Enabled = false,
        -- Always the full shape, even for a player we have never seen: an unknown player is a
        -- zeroed table rated 'Unknown', never nil. The table is rebuilt on each rescore, so treat
        -- what comes back as read-only and re-ask rather than holding onto it.
        Analyse = function(plr)
            if not running or typeof(plr) ~= 'Instance' or not plr:IsA('Player') then
                return blankAnalysis()
            end
            local ok, result = pcall(analysisFor, plr)
            return ok and result or blankAnalysis()
        end,
        GetAll = function()
            local all = {}
            if not running then return all end
            for plr in profiles do
                if plr.Parent then
                    all[plr] = api.Analyse(plr)
                end
            end
            return all
        end,
        Reset = function(plr)
            if plr then
                profiles[plr] = nil
                return
            end
            table.clear(profiles)
            table.clear(engagements)
            table.clear(pendingVoid)
        end,
        Ratings = {'New', 'Beginner', 'Average', 'Above Average', 'Skilled', 'Sweat'},
        Roles = ROLES
    }
    getgenv().EntityAnalyser = api

    EntityAnalyser = vape.Categories.Utility:CreateModule({
        Name = 'EntityAnalyser',
        Function = function(callback)
            running = callback
            api.Enabled = callback
            -- Anything whose UI depends on the analyser being up listens for this rather than
            -- reaching into this module - see Killaura's 'Target skilled'.
            vapeEvents.EntityAnalyserState:Fire(callback)

            if callback then
                matchStart, lastMatchState = tick(), -1
                bedsAtStart = #collectionService:GetTagged('bed')
                folder = Instance.new('Folder')
                folder.Name = 'EntityAnalyser'
                folder.Parent = vape.gui
                EntityAnalyser:Clean(folder)

                EntityAnalyser:Clean(vapeEvents.EntityDamageEvent.Event:Connect(onDamage))
                EntityAnalyser:Clean(vapeEvents.EntityDeathEvent.Event:Connect(onDeath))
                EntityAnalyser:Clean(vapeEvents.BedwarsBedBreak.Event:Connect(onBedBreak))
                EntityAnalyser:Clean(vapeEvents.PlaceBlockEvent.Event:Connect(onPlaceBlock))
                EntityAnalyser:Clean(vapeEvents.BreakBlockEvent.Event:Connect(onBreakBlock))
                EntityAnalyser:Clean(vapeEvents.MatchEndEvent.Event:Connect(function()
                    table.clear(engagements)
                    table.clear(pendingVoid)
                end))
                EntityAnalyser:Clean(entitylib.Events.AnimationPlayed:Connect(function(plr, track)
                    if not running or not plr or plr == lplr then return end
                    local animation = track and track.Animation
                    if animation then
                        noteSwing(plr, animation.AnimationId)
                    end
                end))
                EntityAnalyser:Clean(workspace.ChildAdded:Connect(function(object)
                    -- The shooter attribute is written a frame after the projectile is parented.
                    task.delay(0, function()
                        if object and object.Parent then
                            pcall(onProjectile, object)
                        end
                    end)
                end))
                -- A player leaving takes their profile with them, so a rejoin is judged fresh
                -- rather than inheriting somebody else's match.
                EntityAnalyser:Clean(playersService.PlayerRemoving:Connect(function(plr)
                    profiles[plr] = nil
                    pendingVoid[plr] = nil
                    removeTag(plr)
                end))
                -- Everything above is event driven. This is the only loop, and all it does is the
                -- adaptive sampling and the label refresh - the two things that need a clock.
                EntityAnalyser:Clean(runService.Heartbeat:Connect(function()
                    if not running then return end
                    pcall(step)
                end))
            else
                clearTags()
                table.clear(profiles)
                table.clear(engagements)
                table.clear(pendingVoid)
                folder = nil
            end
        end,
        Tooltip = 'Rates how well each player is playing and marks them overhead. Read-only, it never changes other modules'
    })

    SweatAt = EntityAnalyser:CreateSlider({
        Name = 'Sweat at',
        Min = 60,
        Max = 99,
        Default = 84,
        Tooltip = 'Score needed for the top rating. Getting here takes a spread of categories, sustained - no single thing carries anyone to it'
    })
    SkilledAt = EntityAnalyser:CreateSlider({
        Name = 'Skilled at',
        Min = 50,
        Max = 95,
        Default = 70,
