					local ringY = math.sin(ph) * portalRadius
					local pulse = 0.3 + math.abs(math.sin(t * 1.5 + ph)) * 0.4
					local darkH = (0.75 + (ph / (math.pi * 2)) * 0.15 + t * 0.03) % 1
					pcall(function()
						node.CFrame = CFrame.new(base + Vector3.new(ringX, ringY + 1, -3.5))
