run(function()
	local DaveyAim
	local AimMode, PositionMode, SearchRange, LaunchCannon

	local rayParams = RaycastParams.new()
	rayParams.RespectCanCollide = false

	DaveyAim = kits:CreateModule({
		Name = 'DaveyAim',
		Category = 'Aim',
		Function = function(callback)
			if not callback then return end
			-- One-shot: turns itself straight back off, so it is meant to be used on a keybind.
			DaveyAim:Toggle()
			if not entitylib.isAlive then return end

			local aimPosition
			if PositionMode.Value == 'Camera' then
				rayParams.FilterDescendantsInstances = {lplr.Character, gameCamera}
				local hit = workspace:Raycast(gameCamera.CFrame.Position, gameCamera.CFrame.LookVector * 1000000, rayParams)
				aimPosition = hit and hit.Position
			else
				local unitRay = lplr:GetMouse().UnitRay
				rayParams.FilterDescendantsInstances = {lplr.Character, gameCamera}
				local hit = workspace:Raycast(unitRay.Origin, unitRay.Direction * 1000000, rayParams)
				aimPosition = hit and hit.Position
			end
			if not aimPosition then
				notif('DaveyAim', 'Nothing under the cursor to aim at.', 4)
				return
			end

			-- Nearest cannon inside the search range, rather than the first one the block list
			-- happens to yield.
			local origin = entitylib.character.RootPart.Position
			local cannon, best = nil, SearchRange.Value
			for _, block in store.blocks do
				if block.Name == 'cannon' then
					local distance = (origin - block.Position).Magnitude
					if distance < best then
						cannon, best = block, distance
					end
				end
			end
			if not cannon then
				notif('DaveyAim', 'No cannon within '..SearchRange.Value..' studs.', 4)
				return
			end

			local blockPosition = bedwars.BlockController:getBlockPosition(cannon.Position)

			if AimMode.Value ~= 'Legit' then
				pcall(function()
					bedwars.Client:Get(remotes.CannonAim):SendToServer({
						cannonBlockPos = blockPosition,
						lookVector = CFrame.lookAt(cannon.Position, aimPosition).LookVector * 200
					})
				end)
				task.wait(0.5)
				if LaunchCannon.Enabled then
					pcall(function()
						bedwars.CannonHandController:launchSelf(cannon)
					end)
				end
			else
				-- Legit: drives the game's own aim prompts and turns the camera onto the target,
				-- so what the server sees is the cannon being aimed by hand.
				local aimPrompt = cannon:FindFirstChild('AimPrompt')
				if not aimPrompt then
					notif('DaveyAim', 'That cannon has no aim prompt.', 4)
					return
				end
				aimPrompt:InputHoldBegin()
				task.wait(aimPrompt.HoldDuration)

				local finish = tick() + 0.3
				repeat
					local current = gameCamera.CFrame
					local step = runService.PostSimulation:Wait()
					gameCamera.CFrame = current:Lerp(CFrame.lookAt(current.Position, aimPosition), math.min(22 * step, 1))
					pcall(function()
						bedwars.Client:Get(remotes.CannonAim):SendToServer({
							cannonBlockPos = blockPosition,
							lookVector = gameCamera.CFrame.LookVector
						})
					end)
				until tick() > finish

				local stopPrompt = cannon:FindFirstChild('StopAimingPrompt')
				if stopPrompt then
					stopPrompt:InputHoldBegin()
					task.wait(stopPrompt.HoldDuration)
				end

				if LaunchCannon.Enabled then
					local launchPrompt = cannon:FindFirstChild('LaunchSelfPrompt')
					if launchPrompt then
						launchPrompt:InputHoldBegin()
						task.wait(launchPrompt.HoldDuration)
					end
				end
			end
		end,
		Tooltip = 'Aims the nearest cannon where you are looking. Bind it - it fires once and turns itself off'
	})

	AimMode = DaveyAim:CreateDropdown({
		Name = 'Aim Mode',
		List = {'Fast', 'Legit'},
		Default = 'Fast'
	})
	PositionMode = DaveyAim:CreateDropdown({
		Name = 'Position Mode',
		List = {'Mouse', 'Camera'},
		Default = 'Mouse'
	})
	SearchRange = DaveyAim:CreateSlider({
		Name = 'Search Range',
		Min = 1,
		Max = 30,
		Default = 10,
		Suffix = function(val)
			return val <= 1 and 'stud' or 'studs'
		end
	})
	LaunchCannon = DaveyAim:CreateToggle({Name = 'Launch Cannon'})
end)

-- KrystalDisabler (restored; InfiniteKrystal was folded into it). Krystal - the GlacialSkater
-- kit - skates on momentum: the controller decays it every step and reports the value to the
-- server, and the server correcting a client that disagrees is what reads as a lagback. So we
-- hook the controller's own updateMomentum and keep momentum pinned, re-assert it every
-- PreSimulation step, and suppress the local CFrame/Velocity correction listeners so the skate
-- never snaps back. Fails gracefully (notif + untoggle) if this build has no Krystal controller.
--
-- The hook wraps the original rather than replacing it: updateMomentum also drives the skate
-- itself, so a hook that swallows the call pins a momentum value you never actually move with.
-- We set momentum on both sides of the call instead, which is what stops the original walking
-- it back down. Kept from InfiniteKrystal: the Kits window home beside AutoKrystal, the
-- Enabled check inside the hook, the identity check before restoring, and a momentum figure
-- that is a number the server can plausibly see rather than 9e9.
run(function()
	local KrystalDisabler
	local Momentum
	local SuppressCorrections
	local oldUpdateMomentum, hookedUpdateMomentum
	local patchedSignals = setmetatable({}, {__mode = 'k'})
	local lastRemoteReport = 0

	local function getController()
		return bedwars and bedwars.GlacialSkaterController
	end

	-- The controller throttles its own reports (it keeps a serverMomentumUpdateElapsedTime for
	-- exactly that), so firing the remote on every frame is both wasted and loud. Match a sane
	-- cadence instead. Resolved through Handler, which pcalls and memoises the lookup, so a
	-- build without the remote costs nothing.
	local function reportMomentum(target)
		local handler = bedwars and bedwars.Handler
		if not handler then return end
		local now = tick()
		if now - lastRemoteReport < 0.1 then return end
		lastRemoteReport = now
		pcall(function()
			local remote = handler:Get('MomentumUpdate')
			if remote and remote.Remote then
				remote:Fire('SendToServer', {momentumValue = target})
			end
		end)
	end

	-- lastMomentumReport holds the momentum value last sent to the server - the controller's
	-- fields that hold times are the ones named ...Time - so it has to track momentum. Leaving
	-- the two disagreeing is what invites the correction we are trying to avoid.
	local function setKrystalMomentum(controller, report)
		controller = controller or getController()
		if not controller then return end
		local target = Momentum and Momentum.Value or 1000
		controller.momentum = target
		controller.lastMomentumReport = target
		if report then
			reportMomentum(target)
		end
	end

	local function patchMovementSignal(signal)
		if not signal or not getconnections or not hookfunction then return end
		for _, connection in getconnections(signal) do
			local func = connection and connection.Function
			if func and patchedSignals[func] == nil then
				-- Keep the original hookfunction returns so we can restore it on toggle-off.
				-- Store `false` if the hook itself failed, so cleanup never tries to restore
				-- something we never actually replaced.
				local ok, original = pcall(hookfunction, func, function() end)
				patchedSignals[func] = (ok and original) or false
			end
		end
	end

	-- Undo every movement-signal hook we installed, handing each listener its original
	-- function back so the client's correction listeners work normally again after disable.
	local function restoreSignals()
		for func, original in pairs(patchedSignals) do
			if type(original) == 'function' then
				pcall(hookfunction, func, original)
			end
		end
		table.clear(patchedSignals)
	end

	local function patchCharacter(character)
		if not SuppressCorrections or not SuppressCorrections.Enabled then return end
		local root = character and character.RootPart
		if not root then return end
		patchMovementSignal(root:GetPropertyChangedSignal('CFrame'))
		patchMovementSignal(root:GetPropertyChangedSignal('Velocity'))
		patchMovementSignal(root:GetPropertyChangedSignal('AssemblyLinearVelocity'))
	end

	KrystalDisabler = kits:CreateModule({
		Name = 'KrystalDisabler',
		Category = 'Ability',
		Function = function(callback)
			local controller = getController()
			if callback then
				if not controller or type(controller.updateMomentum) ~= 'function' then
					notif('KrystalDisabler', 'Krystal controller is unavailable.', 5, 'warning')
					KrystalDisabler:Toggle()
					return
				end

				lastRemoteReport = 0
				if not oldUpdateMomentum then
					-- The closure keeps its own reference to the original: toggle-off clears
					-- oldUpdateMomentum, and a hook left installed by a wrapper stacked on top
					-- of ours would then be calling nil.
					local original = controller.updateMomentum
					oldUpdateMomentum = original
					-- The Enabled check means such a hook goes inert instead of still pinning
					-- momentum after the module is off (see the restore below).
					hookedUpdateMomentum = function(self, ...)
						if not KrystalDisabler.Enabled then
							return original(self, ...)
						end
						setKrystalMomentum(self, false)
						local result = original(self, ...)
						setKrystalMomentum(self, true)
						return result
					end
					controller.updateMomentum = hookedUpdateMomentum
				end

				KrystalDisabler:Clean(runService.PreSimulation:Connect(function()
					setKrystalMomentum(nil, true)
				end))

				KrystalDisabler:Clean(entitylib.Events.LocalAdded:Connect(patchCharacter))
				if entitylib.isAlive then
					patchCharacter(entitylib.character)
				end
				setKrystalMomentum(controller, true)
				pcall(controller.updateMomentum, controller)
			else
				-- Only hand back a hook that is still ours: something else may have wrapped
				-- updateMomentum on top of us, and restoring blindly would drop its hook.
				if controller and oldUpdateMomentum and controller.updateMomentum == hookedUpdateMomentum then
					controller.updateMomentum = oldUpdateMomentum
				end
				oldUpdateMomentum, hookedUpdateMomentum = nil, nil
				restoreSignals()
			end
		end,
		Tooltip = 'Removes Krystal lagbacks by keeping momentum maxed and muting the correction listeners'
	})

	Momentum = KrystalDisabler:CreateSlider({
		Name = 'Momentum',
		Min = 100,
		Max = 10000,
		Default = 1000
	})

	SuppressCorrections = KrystalDisabler:CreateToggle({
		Name = 'Suppress corrections',
		Default = true,
		Function = function(callback)
			if callback then
				if KrystalDisabler and KrystalDisabler.Enabled and entitylib.isAlive then
					patchCharacter(entitylib.character)
				end
			else
				restoreSignals()
			end
		end,
		Tooltip = 'Silences the listeners the server corrects you through. Needs getconnections and hookfunction'
	})
end)

run(function()
	local PhaseMine
	local ignored = {}

	local function ignoreCharacter(character)
		if not character then return end
		for _, part in character:GetDescendants() do
			if part:IsA('BasePart') then
				table.insert(ignored, part)
				pcall(function() bedwars.QueryUtil:setQueryIgnored(part, true) end)
			end
		end
		PhaseMine:Clean(character.DescendantAdded:Connect(function(child)
			if child:IsA('BasePart') then
				table.insert(ignored, child)
				pcall(function() bedwars.QueryUtil:setQueryIgnored(child, true) end)
			end
		end))
	end

	PhaseMine = kits:CreateModule({
		Name = 'PhaseMine',
		Category = 'Ability',
		Function = function(callback)
			if not callback then
				for _, part in ignored do
					if part and part.Parent then
						pcall(function() bedwars.QueryUtil:setQueryIgnored(part, false) end)
					end
				end
				table.clear(ignored)
				return
			end

			PhaseMine:Clean(entitylib.Events.EntityAdded:Connect(function(ent)
				if ent.Player then
					task.delay(1, ignoreCharacter, ent.Character)
				end
			end))
			for _, ent in entitylib.List do
				if ent.Character then
					ignoreCharacter(ent.Character)
				end
			end
		end,
		Tooltip = 'Lets your mining raycasts pass through other players'
	})
end)

run(function()
	local AutoCyber
	local DropMode, Whitelist, GeneratorOnly, Visualize, StealSplit, TargetCheck, LimitItem
	local cachedGenerator, generatorExpiry, cachedDrone = nil, 0, nil
	local itemCooldowns = {}

	local function teamGenerator()
		if not cachedGenerator or not cachedGenerator.Parent or os.clock() >= generatorExpiry then
			cachedGenerator = collectionService:GetTagged((lplr:GetAttribute('Team') or -1)..'_TeamOreGenerator')[1]
			generatorExpiry = os.clock() + 5
		end
		return cachedGenerator
	end

	local function getDrone()
		if LimitItem.Enabled then
			local held = store.hand and store.hand.tool
			if not held or held.Name ~= 'drone' then return nil end
		end
		if cachedDrone and cachedDrone.Parent then return cachedDrone end

		for _, drone in collectionService:GetTagged('Drone') do
			if drone:GetAttribute('PlayerUserId') == lplr.UserId then
				-- A drone holding something cannot pick anything else up, so anything it is
				-- carrying is thrown clear before it goes back out.
				local function dropHeld()
					while AutoCyber.Enabled and drone.Parent and drone:GetAttribute('HeldItem') do
						pcall(function()
							bedwars.Handler:Get('DropDroneItem'):Fire('SendToServer', {
								direction = Vector3.new(1000, 10, 0),
								position = drone.PrimaryPart.Position
							})
						end)
						task.wait(0.1)
					end
				end
				AutoCyber:Clean(drone:GetAttributeChangedSignal('HeldItem'):Connect(function()
					task.spawn(dropHeld)
				end))
				cachedDrone = drone
				return cachedDrone
			end
		end

		if LimitItem.Enabled then return nil end
		local drone = getItem('drone')
		if not drone or not drone.tool then return nil end
		switchItem(drone.tool, 0)
		local fired = false
		pcall(function()
			fired = bedwars.Handler:Get('FireGuidedProjectile'):Fire('CallServer', 'drone') and true or false
		end)
		if not fired then return nil end
		task.wait(0.2)
		-- One retry only. Recursing here (as the reference build did) spins forever whenever
		-- the drone never appears.
		for _, spawned in collectionService:GetTagged('Drone') do
			if spawned:GetAttribute('PlayerUserId') == lplr.UserId then
				cachedDrone = spawned
				return cachedDrone
			end
		end
		return nil
	end

	local function findTarget(drone)
		local generator = teamGenerator()
		local generatorPosition = generator and generator.PrimaryPart and generator.PrimaryPart.Position or Vector3.zero
		local position = drone.PrimaryPart.Position

		local drops = workspace.ItemDrops:GetChildren()
		table.sort(drops, function(a, b)
			return (position - a.Position).Magnitude < (position - b.Position).Magnitude
		end)

		for _, drop in drops do
			if (itemCooldowns[drop] or 0) >= os.clock() then continue end
			if not table.find(Whitelist.ListEnabled, drop.Name) then continue end
			-- Still falling, or already underneath the map: not something worth chasing.
			if drop.Position.Y <= 0 or math.abs(drop.Velocity.Y) > 0 then continue end
			if GeneratorOnly.Enabled and (drop.Position - generatorPosition).Magnitude > 20 then continue end
			if StealSplit.Enabled and (drop.Position - generatorPosition).Magnitude <= 20 then continue end

			if TargetCheck.Enabled then
				local blocked = entitylib.EntityPosition({
					Origin = drop.Position,
					Range = 60,
					Part = 'RootPart',
					Players = true
				})
				if blocked then continue end
			end
			return drop
		end
		return nil
	end

	AutoCyber = kits:CreateModule({
		Name = 'AutoCyber',
		Category = 'Auto',
		Function = function(callback)
			if not callback then
				local drone = cachedDrone
				if drone and drone.Parent and drone.PrimaryPart then
					drone.PrimaryPart.CFrame = CFrame.new(drone.PrimaryPart.Position.X, 500, drone.PrimaryPart.Position.Z)
				end
				cachedDrone, cachedGenerator, generatorExpiry = nil, nil, 0
				table.clear(itemCooldowns)
				return
			end

			-- Anything that comes out of a generator split flies sideways at speed. Those are the
			-- drops the drone is for, so they are routed straight to wherever Drop mode says.
			AutoCyber:Clean(workspace.ItemDrops.ChildAdded:Connect(function(drop)
				task.wait()
				if drop.Velocity.X <= 100 then return end
				itemCooldowns[drop] = os.clock() + 5

				local amount = drop:GetAttribute('Amount') or 1
				local parent = drop.Parent

				if DropMode.Value == 'Generator' then
					local generator = teamGenerator()
					if not generator then
						notif('AutoCyber', 'Your team generator was not found', 8, 'alert')
						return
					end
					local started = os.clock()
					repeat
						drop.Velocity = Vector3.zero
						drop.CFrame = generator.PrimaryPart.CFrame
						task.wait()
					until os.clock() - started >= 1 or not drop.Parent or drop.Parent ~= parent
					if Visualize.Enabled then
						notif('AutoCyber', 'Dropped '..formatNumber(amount)..' '..drop.Name, 4)
					end
				else
					repeat
						if not entitylib.isAlive then break end
						drop.Velocity = Vector3.zero
						drop.CFrame = entitylib.character.RootPart.CFrame - Vector3.new(0, 4, 0)
						task.spawn(function()
							pcall(function()
								bedwars.Client:Get(remotes.PickupItem):CallServerAsync({itemDrop = drop})
							end)
						end)
						task.wait(0.02)
					until not drop.Parent or drop.Parent ~= parent
					if Visualize.Enabled then
						notif('AutoCyber', 'Collected '..formatNumber(amount)..' '..drop.Name, 4)
					end
				end
			end))

			repeat
				local drone = getDrone()
				if not drone or not drone.PrimaryPart then
					task.wait(0.5)
					continue
				end

				local target = findTarget(drone)
				if not target then
					-- Parked out of sight rather than left sitting where it can be shot.
					drone.PrimaryPart.AssemblyLinearVelocity = Vector3.zero
					drone.PrimaryPart.CFrame = CFrame.new(drone.PrimaryPart.Position.X, 10000, drone.PrimaryPart.Position.Z)
					task.wait(0.2)
					continue
				end

				task.wait(0.3)
				drone.PrimaryPart.AssemblyLinearVelocity = Vector3.zero
				drone.PrimaryPart.CFrame = CFrame.new(drone.PrimaryPart.Position.X, 10000, drone.PrimaryPart.Position.Z)

				local distance, announced = math.huge, math.huge
				while AutoCyber.Enabled and drone.Parent and target.Parent == workspace.ItemDrops do
					local targetPosition = target.Position
					drone.PrimaryPart.CanCollide = false
					drone.PrimaryPart.AssemblyAngularVelocity = Vector3.zero

					local flatDrone = drone.PrimaryPart.Position * Vector3.new(1, 0, 1)
					local flatTarget = targetPosition * Vector3.new(1, 0, 1)
					if (flatDrone - flatTarget).Magnitude > 0.01 then
						drone.PrimaryPart.AssemblyLinearVelocity = CFrame.lookAt(flatDrone, flatTarget).LookVector * 30
					end
					distance = (flatDrone - flatTarget).Magnitude

					if Visualize.Enabled and announced - distance >= 25 then
						announced = distance
						notif('AutoCyber', 'Drone is '..math.floor(distance)..' studs from '..target.Name, 1)
					end

					task.wait()
					if distance <= 2 then break end
				end

				if AutoCyber.Enabled and target.Parent == workspace.ItemDrops and distance <= 5 then
					local started = os.clock()
					repeat
						if drone.Parent and target.Parent then
							drone.PrimaryPart.AssemblyLinearVelocity = Vector3.zero
							drone.PrimaryPart.AssemblyAngularVelocity = Vector3.new(0, -30, 0)
							drone.PrimaryPart.CFrame = CFrame.new(target.Position - Vector3.new(0, drone.PrimaryPart.Size.Y, 0))
						end
						task.wait(0.02)
					until os.clock() - started >= 1.25 or not AutoCyber.Enabled
				elseif Visualize.Enabled and target.Parent == workspace.ItemDrops then
					notif('AutoCyber', 'Too far to collect '..target.Name, 6)
				end

				task.wait()
			until not AutoCyber.Enabled
		end,
		Tooltip = 'Sends the Cyber drone out to steal resources for you'
	})

	DropMode = AutoCyber:CreateDropdown({
		Name = 'Drop mode',
		List = {'Player', 'Generator'},
		Default = 'Player',
		Tooltip = 'Where a stolen split ends up'
	})
	Whitelist = AutoCyber:CreateTextList({
		Name = 'Whitelist',
		Default = {'emerald', 'diamond'}
	})
	GeneratorOnly = AutoCyber:CreateToggle({
		Name = 'Generator only',
		Tooltip = 'Only picks up whitelisted items that came out of a generator'
	})
	Visualize = AutoCyber:CreateToggle({
		Name = 'Visualize',
		Tooltip = 'Says what the drone is going for and how far away it is'
	})
	StealSplit = AutoCyber:CreateToggle({
		Name = 'Steal split',
		Tooltip = 'Goes for the enemy team\'s generator split instead of loose drops near yours'
	})
	TargetCheck = AutoCyber:CreateToggle({
		Name = 'Target check',
		Tooltip = 'Skips a drop that somebody is standing near'
	})
	LimitItem = AutoCyber:CreateToggle({
		Name = 'Limit to item',
		Tooltip = 'Only works while the drone is held, and never spawns one for you'
	})
end)

run(function()
	local AutoAdetunde
	local Toggles = {}

	-- The upgrade table is read once here and again inside the loop: reading it at registration
	-- is what names the toggles, but a build that has moved it must not cost the whole module.
	local UPGRADES = {}
	pcall(function()
		for name in bedwars.AdetundeUpgradeMeta do
			table.insert(UPGRADES, name)
		end
	end)
	table.sort(UPGRADES)

	AutoAdetunde = kits:CreateModule({
		Name = 'AutoAdetunde',
		Category = 'Auto',
		Function = function(callback)
			if not callback then return end
			repeat
				do
					pcall(function()
						local crystal = getItem('frost_crystal')
						if not crystal then return end

						for name, tier in bedwars.AdetundeUtil.getUpgradesFromHammer(lplr) do
							if not AutoAdetunde.Enabled then break end
							-- Re-read every pass: an upgrade spends crystals, so the amount held
							-- a moment ago is not what is left to spend on the next one.
							crystal = getItem('frost_crystal')
							if not crystal then break end

							local toggle = Toggles[name]
							local meta = bedwars.AdetundeUpgradeMeta[name]
							local wanted = toggle and toggle.Enabled and meta and meta.tiers[tier + 1] or nil
							if wanted and crystal.amount >= wanted.price then
								bedwars.Handler:Get('UpgradeFrostyHammer'):Fire('CallServer', name)
								task.wait(0.1)
							end
						end
					end)
				end
				task.wait(0.5)
			until not AutoAdetunde.Enabled
		end,
		Tooltip = 'Spends frost crystals on the frosty hammer as soon as the next tier is affordable'
	})

	for _, name in UPGRADES do
		Toggles[name] = AutoAdetunde:CreateToggle({
			Name = 'Buy '..name,
			Default = true
		})
	end
end)

run(function()
	local AutoBuilder
	local Animation, BedCheck, LimitItem
	local Blacklist

	-- Nearest bed we are NOT allowed to break, i.e. our own - that is the one worth fortifying
	-- around. Returns nil when there is no such bed, which the caller has to handle: a match
	-- where our bed is already gone used to throw here on the first pass.
	local function ownBed(position)
		local best, bestmag = nil, math.huge
		local team = lplr:GetAttribute('Team') or -1
		for _, bed in collectionService:GetTagged('bed') do
			local mag = (position - bed.Position).Magnitude
			if mag < bestmag and bed:GetAttribute('Team'..team..'NoBreak') then
				best, bestmag = bed, mag
			end
		end
		return best
	end

	AutoBuilder = kits:CreateModule({
		Name = 'AutoBuilder',
		Category = 'Auto',
		Function = function(callback)
			if not callback then return end
			repeat task.wait() until (store.matchState ~= 0 and store.equippedKit == 'builder') or not AutoBuilder.Enabled
			if not AutoBuilder.Enabled then return end

			-- Only blocks somebody placed can be fortified, and the attribute is not set on the
			-- frame the block appears, hence the deferred insert.
			local blocks = collection('block', AutoBuilder, function(tab, obj)
				task.delay(0, function()
					if obj and obj.Parent and not obj:GetAttribute('NoBreak') and obj:GetAttribute('PlacedByUserId') ~= nil then
						table.insert(tab, obj)
					end
				end)
			end)

			repeat
				local hammer = getItem('hammer')
				local holding = store.hand.tool and store.hand.tool.Name == 'hammer'
				if entitylib.isAlive and hammer and (not LimitItem.Enabled or holding) then
					local position = entitylib.character.RootPart.Position
					local bed = BedCheck.Enabled and ownBed(position) or nil

					-- Bed check on with no bed of ours left means there is nothing to fortify
					-- around, so skip the pass rather than fortifying the whole map.
					if not BedCheck.Enabled or bed then
						for _, block in blocks do
							if not AutoBuilder.Enabled then break end
							if block.Parent and (not bed or (bed.Position - block.Position).Magnitude <= 30) then
								local name = block.Name
								if name:find('wool_') then
									name = 'wool'
								end
								if not table.find(Blacklist.ListEnabled, name) and not block:FindFirstChild('BuilderFortify') then
									pcall(function()
										bedwars.Handler:Get('FortifyBlock'):Fire('SendToServer', ({getPlacedBlock(block.Position)})[2])
										if Animation.Enabled then
											bedwars.GameAnimationUtil:playAnimation(lplr, bedwars.GameAnimationUtil:getAssetId(bedwars.AnimationType.BUILDER_HAMMER_HIT), {
												fadeInTime = 0.02
											})
											bedwars.SoundManager:playSound(bedwars.SoundList.FORTIFY_BLOCK, entitylib.character.RootPart.Position)
										end
									end)
								end
							end
						end
					end
				end
				task.wait(0.1)
			until not AutoBuilder.Enabled
		end,
		Tooltip = 'Fortifies placed blocks with the builder hammer'
	})

	BedCheck = AutoBuilder:CreateToggle({
		Name = 'Bed Check',
		Tooltip = 'Only fortifies blocks within 30 studs of your own bed'
	})
	Animation = AutoBuilder:CreateToggle({
		Name = 'Animation',
		Default = true,
		Tooltip = 'Plays the hammer swing and the fortify sound'
	})
	LimitItem = AutoBuilder:CreateToggle({
		Name = 'Limit to items',
		Default = true,
		Tooltip = 'Only fortifies while the hammer is actually held'
	})
	Blacklist = AutoBuilder:CreateTextList({
		Name = 'Blacklists',
		Placeholder = 'block',
		Default = {'cannon', 'wool'}
	})
end)

run(function()
	local AutoCaitlyn
	local Mode, Range, MinHP
	local TargetPriorities
	local activeSession

	local function asEntity(value)
		return typeof(value) == 'Instance' and entitylib.getEntity(value) or nil
	end

	-- Contracts key their target by player, but a rejoin can leave a stale Player object behind,
	-- so a name match is accepted as well.
	local function contractFor(contracts, ent)
		for _, contract in contracts do
			if contract.target == ent.Player or (contract.target and ent.Player and contract.target.Name == ent.Player.Name) then
				return contract
			end
		end
		return nil
	end

	local function reachable(wallcheck)
		local targets = {}
		for _, ent in entitylib.AllPosition({
			Part = 'RootPart',
			Players = true,
			Range = Range.Value,
			Wallcheck = wallcheck
		}) do
			if ent.Player and not (ent.Player.Team and ent.Player.Team.Name == 'Spectators') then
				targets[ent.Player] = ent
				targets[ent.Character] = ent
			end
		end
		return targets
	end

	-- Cached for a second: this is asked once per candidate contract, several times a second.
	local function hasBed(session, plr)
		local ok, team = pcall(bedwars.TeamController.getPlayerTeam, bedwars.TeamController, plr)
		local teamId = (ok and team and team.id) or plr:GetAttribute('Team')
		if teamId == nil then return true end

		local cached = session.beds[teamId]
		if cached and cached[2] > tick() then
			return cached[1]
		end

		local found
		ok, found = pcall(bedwars.BedwarsController.getTeamBed, bedwars.BedwarsController, teamId)
		local result = not ok or (found and found.Parent ~= nil) or false
		session.beds[teamId] = {result, tick() + 1}
		return result
	end

	-- How worth taking a contract is. Reward first, then how close the target is to dying,
	-- then how reachable they are - a contract on somebody across the map is worth less than
	-- one on whoever is hitting you right now.
	local function score(session, contract, targets)
		local ent = targets[contract.target]
		if not ent then return nil end

		local health = ent.Humanoid.Health
		local distance = (entitylib.character.RootPart.Position - ent.RootPart.Position).Magnitude
		local total = 30 + ((tonumber(contract.rewardValue) or 0) * 35)
		total += (1 - math.clamp(health / math.max(ent.Humanoid.MaxHealth, 1), 0, 1)) * 35
		total += math.max(1 - (distance / Range.Value), 0) * 20

		if health <= MinHP.Value then total += 20 end
		if (session.threats[ent.Player] or 0) > tick() then total += 30 end
		if ent.Character:GetAttribute('BleedSource') == lplr.UserId then total += 25 end
		if not hasBed(session, ent.Player) then total += 20 end

		local reward = contract.rewardExplanation
		if type(reward) == 'table' then
			total += (reward.assassin and 10 or 0) + (reward.kitClass and 8 or 0) + (reward.gear and 6 or 0)
		end
		return total, ent
	end

	local function bestContract(session, contracts)
		local bounty = false
		for _, contract in contracts do
			if contract.rewardValue ~= nil or contract.rewardUpgrade ~= nil then
				bounty = true
				break
			end
		end
		if not bounty then return nil, false end

		local targets = reachable(true)
		local current, currentScore
		if session.priorityId ~= nil then
			for _, contract in contracts do
				if contract.id == session.priorityId then
					current, currentScore = contract, score(session, contract, targets)
					break
				end
			end
		end

		local best, bestScore
		for _, contract in contracts do
			local value = score(session, contract, targets)
			if value and (not bestScore or value > bestScore) then
				best, bestScore = contract, value
			end
		end

		-- Hysteresis: a marginally better contract is not worth dropping the one already picked.
		if current and currentScore and best ~= current and bestScore < currentScore + 15 then
			best = current
		end

		session.priorityId = best and best.id or nil
		return best, true
	end

	local function hitContract(session, contracts)
		local hit = session.lastHit
		if hit and hit[2] > tick() then
			local ent = reachable(false)[hit[1].Player]
			if ent == hit[1] then
				if Mode.Value == 'On Low' and ent.Humanoid.Health >= MinHP.Value then
					return nil
				end
				return contractFor(contracts, ent)
			end
		end
		session.lastHit = nil
		return nil
	end

	local function selectContract(session, contract)
		if contract and not (session.pendingId == contract.id and session.pendingUntil > tick()) then
			bedwars.Handler:Get('BloodAssassinSelectContract'):Fire('SendToServer', {
				contractId = contract.id
			})
			session.pendingId = contract.id
			session.pendingUntil = tick() + 1
		end
	end

	local function update(session)
		if not entitylib.isAlive or store.matchState ~= 1 or store.equippedKit ~= 'blood_assassin' then
			session.lastHit, session.pendingId, session.priorityId = nil, nil, nil
			return
		end

		local kit = bedwars.Store:getState().Kit
		if not kit or kit.activeContract then
			session.pendingId = nil
			session.priorityId = kit and kit.activeContract and kit.activeContract.id or nil
			return
		end

		if session.pendingId and session.pendingUntil > tick() then return end
		session.pendingId = nil

		local contracts = kit.availableContracts
		if not contracts or #contracts == 0 then return end

		local contract
		if TargetPriorities.Enabled then
			local available
			contract, available = bestContract(session, contracts)
			if not available then
				contract = hitContract(session, contracts)
			end
		else
			session.priorityId = nil
			contract = hitContract(session, contracts)
		end
		selectContract(session, contract)
	end

	AutoCaitlyn = kits:CreateModule({
		Name = 'AutoCaitlyn',
		Category = 'Auto',
		Function = function(callback)
			if not callback then
				activeSession = nil
				return
			end

			local session = {beds = {}, nextUpdate = 0, pendingUntil = 0, threats = {}}
			activeSession = session

			AutoCaitlyn:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damage)
				if activeSession ~= session then return end
				local source = asEntity(damage.fromEntity)
				if damage.entityInstance == lplr.Character and source and source.Player then
					session.threats[source.Player] = tick() + 3
				elseif damage.fromEntity == lplr.Character or damage.fromEntity == lplr then
					local victim = asEntity(damage.entityInstance)
					if victim then
						session.lastHit = {victim, tick() + 1}
					end
				end
			end))

			AutoCaitlyn:Clean(vapeEvents.BedwarsBedBreak.Event:Connect(function()
				table.clear(session.beds)
			end))
			AutoCaitlyn:Clean(entitylib.Events.LocalAdded:Connect(function()
				session.lastHit, session.pendingId = nil, nil
			end))
			AutoCaitlyn:Clean(entitylib.Events.LocalRemoved:Connect(function()
				session.lastHit, session.pendingId, session.priorityId = nil, nil, nil
			end))

			repeat
				if tick() >= session.nextUpdate then
					session.nextUpdate = tick() + 0.2
					pcall(update, session)
				end
				task.wait(0.05)
			until not AutoCaitlyn.Enabled or activeSession ~= session

			if activeSession == session then
				activeSession = nil
			end
		end,
		Tooltip = 'Takes the blood assassin contract on whoever is worth killing'
	})

	Mode = AutoCaitlyn:CreateDropdown({
		Name = 'Contract mode',
		List = {'On Hit', 'On Low'},
		Default = 'On Low',
		Tooltip = 'On Hit - contracts whoever you start hitting\nOn Low - waits until they are low',
		Function = function(value)
			pcall(function()
				MinHP.Object.Visible = value == 'On Low'
			end)
		end
	})
	MinHP = AutoCaitlyn:CreateSlider({
		Name = 'Minimum Health',
		Min = 1,
		Max = 100,
		Default = 30,
		Darker = true,
		Tooltip = 'How low they have to be before contracting'
	})
	Range = AutoCaitlyn:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 50,
		Default = 50,
		Suffix = function(val)
			return val <= 1 and 'stud' or 'studs'
		end
	})
	TargetPriorities = AutoCaitlyn:CreateToggle({
		Name = 'Target Priorities',
		Tooltip = 'Scores every contract by reward, health, distance and bed state instead of only who you hit',
		Function = function()
			if activeSession then
				activeSession.priorityId = nil
			end
		end
	})
end)

run(function()
	local AutoElder
	local Streamer, Animation
	local Range, Delay
	local cooldowns = {}

	local legit = getFunctionRange(bedwars.EldertreeController and bedwars.EldertreeController.createTreeOrbInteraction) or 10

	local function orbPart(orb)
		return orb:FindFirstChild('Spirit') or orb.PrimaryPart or (orb:IsA('BasePart') and orb) or nil
	end

	AutoElder = kits:CreateModule({
		Name = 'AutoElder',
		Category = 'Auto',
		Function = function(callback)
			if not callback then
				table.clear(cooldowns)
				return
			end

			AutoElder:Clean(proximityPromptService.PromptShown:Connect(function(prompt)
				if Streamer.Enabled and prompt.Name == 'treeOrb' then
					task.delay(0.1, prompt.InputHoldBegin, prompt)
				end
			end))

			repeat
				if not Streamer.Enabled and entitylib.isAlive then
					local position = entitylib.character.RootPart.Position
					for _, orb in collectionService:GetTagged('treeOrb') do
						if not AutoElder.Enabled then break end
						local part = orbPart(orb)
						if part and tick() > (cooldowns[orb] or 0) and (position - part.Position).Magnitude <= Range.Value then
							if Delay.Value > 0 then
								task.wait(Delay.Value)
							end
							-- Re-checked after the wait: the orb can be gone, or we can have
							-- walked away from it, in the time the delay took.
							if orb.Parent and part.Parent and entitylib.isAlive
								and (entitylib.character.RootPart.Position - part.Position).Magnitude <= Range.Value then
								pcall(function()
									if Animation.Enabled then
										bedwars.GameAnimationUtil:playAnimation(lplr.Character, bedwars.AnimationType.PUNCH)
										bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.FP_USE_ITEM)
										bedwars.SoundManager:playSound(bedwars.SoundList.CROP_HARVEST)
									end
									if bedwars.Handler:Get('ConsumeTreeOrb'):Fire('CallServer', {treeOrbSecret = orb:GetAttribute('TreeOrbSecret')}) then
										orb:Destroy()
									end
								end)
								cooldowns[orb] = tick() + 1
